var e=JSON.parse(`[{"sach":"Sáng Thế Ký","ma":"GEN","chuong":1,"cau":1,"loi_kinh_thanh":"Ban đầu Đức Chúa Trời dựng nên trời đất.","bai_hoc":"Trước khi có bất cứ điều gì bạn đang lo lắng, trước khi có thời gian, tiếng ồn và những bộn bề, Đức Chúa Trời đã ở đó. Ngài đã dựng nên trời và đất bằng một lời phán, không vội vàng và không vất vả. Hãy để điều này làm lòng bạn dịu lại: thế giới này không phải ngẫu nhiên, và đời bạn cũng vậy. Bạn không bắt đầu từ hư không, bạn bắt đầu từ bàn tay của một Đấng Tạo Hóa yêu thương. Nếu hôm nay mọi thứ quanh bạn có vẻ rối ren và vô định, hãy nhớ rằng Đấng đã sắp đặt trật tự từ sự trống rỗng vẫn đang cầm lấy câu chuyện của bạn. Hãy bắt đầu ngày mới bằng việc nhìn lên Ngài.","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng có từ ban đầu và đã dựng nên mọi sự. Xin cho con bắt đầu ngày hôm nay bằng cách ngước nhìn Ngài trước, và tin rằng đời con nằm trong tay Ngài. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":1,"cau":3,"loi_kinh_thanh":"Đức Chúa Trời phán rằng: Phải có sự sáng; thì có sự sáng.","bai_hoc":"Chúa chỉ cần phán một lời, và ánh sáng xuất hiện giữa bóng tối. Không cần cố gắng, không cần chuẩn bị. Có những giai đoạn trong đời mà bạn thấy mình ở giữa khoảng tối: mơ hồ, mệt mỏi, không thấy đường phía trước. Hãy nhớ rằng Đấng tạo ra ánh sáng đầu tiên vẫn còn phán, và Lời của Ngài vẫn có quyền soi vào những nơi tối tăm nhất trong lòng bạn. Bạn không cần tự tạo ra ánh sáng cho mình. Bạn chỉ cần mở lòng đón nhận. Hôm nay, hãy đọc một đoạn Lời Chúa thật chậm rãi, và để ánh sáng của Ngài len vào từng góc nhỏ trong tâm hồn bạn.","loi_cau_nguyen":"Chúa ơi, Lời Ngài là ánh sáng giữa bóng tối. Xin cho con có thời gian đọc một đoạn Kinh Thánh hôm nay, và để Lời Ngài soi vào những nơi trong lòng con cần được sáng hơn. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":1,"cau":26,"loi_kinh_thanh":"Đức Chúa Trời phán rằng: Chúng ta hãy làm nên loài người như hình ta và theo tượng ta, đặng quản trị loài cá biển, loài chim trời, loài súc vật, loài côn trùng bò trên mặt đất, và khắp cả đất.","bai_hoc":"Bạn được dựng nên theo hình ảnh của Đức Chúa Trời. Hãy đọc chậm câu ấy một lần nữa. Không phải ai đó xa xôi hay hoàn hảo hơn bạn, mà chính bạn, với mọi điều bạn là. Có những ngày bạn thấy mình nhỏ bé, vụng về, không đáng kể. Nhưng giá trị của bạn không đến từ thành tích hay cái nhìn của người khác, nó đến từ Đấng đã khắc hình ảnh Ngài trong bạn. Mỗi người bạn gặp hôm nay cũng mang hình ảnh ấy. Khi nhìn mình và nhìn người khác bằng đôi mắt này, bạn sẽ thấy dịu dàng hơn, biết trân trọng hơn, và bớt khắt khe với chính mình.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dựng nên con theo hình ảnh của Ngài. Xin giúp con nhìn chính mình và nhìn người khác với sự trân trọng ấy, và biết dịu dàng hơn trong cách đối xử với mọi người. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":1,"cau":27,"loi_kinh_thanh":"Đức Chúa Trời dựng nên loài người như hình Ngài; Ngài dựng nên loài người giống như hình Đức Chúa Trời; Ngài dựng nên người nam cùng người nữ.","bai_hoc":"Nam và nữ, Chúa dựng nên cả hai theo hình ảnh Ngài. Không ai đứng dưới ai, không ai kém giá trị hơn ai. Có thể bạn từng bị coi thường, bị so sánh, hoặc từng tự thấy mình không xứng đáng. Hôm nay, hãy nghe lại sự thật Chúa nói về bạn: bạn là tác phẩm của Ngài, được tạo ra có chủ ý và mang dấu ấn của Ngài. Điều đó không thể bị ai lấy đi. Hãy đặt tay lên ngực, hít một hơi, và thầm cảm ơn Chúa vì Ngài đã nghĩ đến bạn và dựng nên bạn như thế. Từ nơi biết ơn này, lòng bạn sẽ có thêm sức để yêu thương người khác.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dựng nên con có chủ ý và có giá trị. Xin giúp con nhớ rằng giá trị của con đến từ Ngài, không từ lời đánh giá của người khác hay thành tích của con. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":1,"cau":31,"loi_kinh_thanh":"Đức Chúa Trời thấy các việc Ngài đã làm thật rất tốt lành. Vậy, có buổi chiều và buổi mai; ấy là ngày thứ sáu.","bai_hoc":"Sau khi dựng nên mọi sự, Chúa nhìn lại và thấy rất tốt lành. Hãy tưởng tượng ánh mắt hài lòng và vui mừng ấy. Chúa không dựng nên thế giới vì bắt buộc mà vì Ngài yêu thích điều Ngài làm. Và bạn là một phần của điều ấy. Dù hôm nay thế giới có nhiều tổn thương và bạn có những điều chưa như ý, câu Kinh Thánh này nhắc ta rằng khởi đầu của mọi sự là tốt lành, và Chúa vẫn đang làm việc để phục hồi. Hãy nhìn quanh bạn hôm nay: một tia nắng, một nụ cười, một bữa ăn ấm. Hãy tìm điều tốt lành nhỏ bé ấy và nói lời cảm ơn Ngài.","loi_cau_nguyen":"Chúa ơi, Ngài đã nhìn công việc của Ngài và thấy rất tốt lành. Xin mở mắt con để thấy những điều tốt đẹp Ngài đã ban hôm nay, dù nhỏ bé, và cho con lòng biết ơn. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":2,"cau":3,"loi_kinh_thanh":"Rồi, Ngài ban phước cho ngày thứ bảy, đặt là ngày thánh; vì trong ngày đó, Ngài nghỉ các công việc đã dựng nên và đã làm xong rồi.","bai_hoc":"Sau sáu ngày làm việc, Chúa ban phước cho ngày nghỉ và biệt riêng nó ra thánh. Ngài nghỉ không phải vì mệt, mà để chúng ta biết nghỉ ngơi là một món quà. Bạn có đang chạy mãi, lo mãi, làm mãi không? Chúa dịu dàng mời bạn dừng lại. Nghỉ ngơi là cách bạn nói với Ngài: \\"Con tin rằng Chúa vẫn đang cầm mọi sự, con không cần phải tự gánh\\". Hãy dành một khoảng thời gian không điện thoại, không công việc, chỉ ngồi yên với Chúa. Để Ngài nạp lại sức cho bạn, và để tâm hồn bạn thở được một hơi thật sâu.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã ban cho chúng con ngày nghỉ như một món quà. Xin giúp con biết dừng lại, nghỉ ngơi thật sự, và tin rằng Ngài vẫn đang cầm giữ mọi việc. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":2,"cau":7,"loi_kinh_thanh":"Giê-hô-va Đức Chúa Trời bèn lấy bụi đất nắn nên hình người, hà sanh khí vào lỗ mũi; thì người trở nên một loài sanh linh.","bai_hoc":"Chúa lấy bụi đất nắn nên con người, rồi tự mình thổi hơi sự sống vào mũi người ấy. Hãy nghĩ về điều này: mỗi hơi thở của bạn bắt đầu từ chính hơi thở của Chúa. Bạn mỏng manh như đất bụi, nhưng quý giá vì mang sự sống của Ngài. Có những lúc bạn thấy mình yếu đuối, dễ vỡ, dễ mệt. Điều đó không sao cả, vì bạn được tạo ra như vậy, để biết cần dựa vào Ngài. Hôm nay, khi hít thở, hãy nhớ rằng mỗi hơi thở là một món quà, và thầm nói: \\"Cảm ơn Chúa vì đã cho con sự sống\\".","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã thổi sự sống vào con. Mỗi hơi thở của con là món quà từ Ngài. Xin giúp con sống ngày hôm nay như người biết mình được ban sự sống. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":2,"cau":18,"loi_kinh_thanh":"Giê-hô-va Đức Chúa Trời phán rằng: Loài người ở một mình thì không tốt; ta sẽ làm nên một kẻ giúp đỡ giống như nó.","bai_hoc":"Chúa nhìn thấy điều chưa tốt: con người ở một mình. Ngài không muốn bạn đi qua cuộc đời trong cô độc. Nếu hôm nay bạn đang thấy lẻ loi, giữa đám đông mà vẫn cô đơn, hãy biết rằng Chúa hiểu cảm giác đó, và Ngài đã thiết kế chúng ta để sống trong sự kết nối. Đừng ngại mở lòng, gửi một tin nhắn, mời một người bạn đi cà phê, hay bước vào một cộng đoàn đức tin. Và nếu bạn đã có người đồng hành, hãy trân trọng họ như một món quà từ Chúa. Chúa không muốn bạn một mình, và Ngài luôn ở bên bạn qua những con người Ngài đặt vào đời bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dựng nên chúng con để sống trong tình yêu thương và sự kết nối. Xin giúp con trân trọng những người quanh con, và can đảm mở lòng khi con cần người đồng hành. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":2,"cau":24,"loi_kinh_thanh":"Bởi vậy cho nên người nam sẽ lìa cha mẹ mà dính díu cùng vợ mình, và cả hai sẽ trở nên một thịt.","bai_hoc":"Hôn nhân trong Kinh Thánh là một sự kết hiệp sâu sắc: rời khỏi, gắn bó, và nên một. Đó không chỉ là cảm xúc nhất thời, mà là lời hứa chọn nhau mỗi ngày. Nếu bạn đang ở trong một cuộc hôn nhân, hãy dành vài phút hôm nay để nhìn người ấy bằng ánh mắt biết ơn: họ đã chọn đi cùng bạn, qua những ngày vui lẫn những ngày mệt. Nếu bạn đang đợi một người, hãy tin rằng Chúa nhìn thấy tương lai của bạn. Tình yêu bền vững không đến từ sự hoàn hảo, mà từ sự gắn bó và tha thứ. Hãy cầu xin Chúa ban cho bạn một tấm lòng biết giữ lời hứa trong yêu thương.","loi_cau_nguyen":"Chúa ơi, xin giúp con biết giữ lời hứa trong yêu thương và gắn bó. Xin ban cho những người đang sống trong hôn nhân sự tha thứ và biết ơn nhau, và cho những ai đang chờ đợi sự bình an. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":3,"cau":15,"loi_kinh_thanh":"Ta sẽ làm cho mầy cùng người nữ, dòng dõi mầy cùng dòng dõi người nữ nghịch thù nhau. Người sẽ giày đạp đầu mầy, còn mầy sẽ cắn gót chân người.","bai_hoc":"Giữa khung cảnh buồn nhất của loài người, sau khi sa ngã, Chúa không bỏ cuộc. Ngay lúc ấy Ngài đã thắp lên một tia hy vọng: sẽ có Một Đấng đến đánh bại điều ác. Chúa không để câu chuyện kết thúc trong tuyệt vọng. Nếu bạn đang cảm thấy mình đã làm hỏng mọi thứ, hãy nhớ rằng Chúa luôn có một lời hứa dành cho người vấp ngã. Chúa Giê-su là sự ứng nghiệm của lời hứa đó, Ngài chịu tổn thương để chúng ta được chữa lành. Hôm nay, hãy để lời hứa này neo lòng bạn: sự cứu rỗi luôn được chuẩn bị cho những ai biết quay về với Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã hứa ban Đấng Cứu Thế ngay khi con người sa ngã. Xin cho con giữ vững hy vọng nơi Chúa Giê-su, Đấng đã đến để đánh bại điều ác. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":3,"cau":19,"loi_kinh_thanh":"ngươi sẽ làm đổ mồ hôi trán mới có mà ăn, cho đến ngày nào ngươi trở về đất, là nơi mà có ngươi ra; vì ngươi là bụi, ngươi sẽ trở về bụi.","bai_hoc":"Câu Kinh Thánh này nghe nặng nề, nhưng nó nói thật về thân phận con người: \\"ngươi sẽ làm đổ mồ hôi trán mới có mà ăn, cho đến ngày nào ngươi trở về đất, là nơi mà có ngươi ra; vì ngươi là bụi, ngươi sẽ trở về bụi\\" Lao nhọc, mệt mỏi và cái chết là hậu quả của tội lỗi trong thế gian. Nhưng hãy đọc câu ấy bằng đôi mắt đức tin: vì ta nhỏ bé, ta càng cần một Đấng Cứu Chuộc. Bạn không phải tự gánh hết gánh nặng của đời mình. Chúa Giê-su đã bước vào bụi đất của chúng ta, chịu lấy nó và mở một con đường mới. Khi bạn thấy kiệt sức, hãy nhớ rằng Ngài không nhìn bạn bằng sự thất vọng, mà bằng lòng thương xót.","loi_cau_nguyen":"Chúa ơi, con biết mình mỏng manh và hữu hạn. Xin giúp con thôi cố gắng tự gánh tất cả, và nương cậy vào ơn cứu của Chúa Giê-su, Đấng đã chịu lấy gánh nặng cho con. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":4,"cau":9,"loi_kinh_thanh":"Đức Giê-hô-va hỏi Ca-in rằng: A-bên, em ngươi, ở đâu? Thưa rằng: Tôi không biết; tôi là người giữ em tôi sao?","bai_hoc":"Ca-in hỏi: \\"Tôi là người giữ em tôi sao?\\" Đó là câu hỏi của một trái tim đã nguội lạnh. Chúa không trả lời trực tiếp, nhưng cả Kinh Thánh sau này trả lời: có, chúng ta được gọi để quan tâm đến anh chị em mình. Có thể hôm nay có một người đang cần bạn: một người bạn lặng lẽ, một thành viên gia đình đang mệt, một người quen đang ở một mình. Bạn không cần phải làm điều gì to tát. Một cuộc gọi, một lời hỏi thăm, một cái ôm cũng có thể là sự quan tâm Chúa dùng. Hãy để lòng bạn mềm ra, và trở thành người giữ gìn người khác bằng tình yêu.","loi_cau_nguyen":"Chúa ơi, xin làm mềm lòng con để con biết quan tâm đến người khác. Xin chỉ cho con một người cần được hỏi thăm hôm nay, và cho con can đảm làm điều ấy bằng tình yêu. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":6,"cau":8,"loi_kinh_thanh":"Nhưng Nô-ê được ơn trước mặt Đức Giê-hô-va.","bai_hoc":"Giữa một thế hệ đầy bạo lực và hư hoại, Nô-ê được ơn trước mặt Chúa. Câu này không nói ông hoàn hảo, nhưng nói ông nhận được ân điển. Ân điển luôn là điểm khởi đầu: Chúa nhìn bạn với lòng thương, trước cả khi bạn làm điều gì. Có thể bạn đang sống trong một môi trường khiến bạn thấy cô đơn với niềm tin của mình. Hãy nhớ rằng Chúa thấy bạn, như Ngài đã thấy Nô-ê. Ngài không bỏ sót những người âm thầm giữ lòng ngay thẳng. Hôm nay, hãy tin rằng bạn đang được Chúa nhìn bằng ánh mắt ân điển, và bạn không phải chứng minh điều gì với Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài nhìn con bằng ân điển. Xin giúp con giữ lòng ngay thẳng giữa thế gian nhiều điều khó, và nhớ rằng con không phải chứng minh điều gì trước Ngài. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":8,"cau":22,"loi_kinh_thanh":"Hễ đất còn, thì mùa gieo giống cùng mùa gặt hái, lạnh và nóng, mùa hạ cùng mùa đông, ngày và đêm, chẳng bao giờ tuyệt được.","bai_hoc":"Sau cơn hồng thủy, Chúa hứa rằng gieo và gặt, lạnh và nóng, ngày và đêm sẽ không bao giờ ngừng. Bạn có thể thấy sự thành tín của Ngài trong nhịp điệu bình thường nhất: mặt trời mọc mỗi sáng, mùa đông rồi lại xuân. Khi đời sống bạn có những mùa khó khăn, hãy nhớ rằng mùa nào cũng sẽ qua, và Chúa vẫn trung tín. Hôm nay, hãy dành một chút thời gian nhìn ra cửa sổ hay ra ngoài trời. Nghe tiếng chim, cảm nhận làn gió. Mỗi điều bình dị ấy là lời nhắc nhở rằng Đức Chúa Trời của bạn không thay đổi, và Ngài vẫn chăm sóc thế giới này.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã giữ nhịp đều đặn của ngày đêm và các mùa. Xin giúp con tin rằng Ngài thành tín, kể cả khi con đi qua những mùa khó khăn trong đời. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":9,"cau":13,"loi_kinh_thanh":"Ta đặt mống của ta trên từng mây, dùng làm dấu chỉ sự giao ước của ta với đất.","bai_hoc":"Sau cơn bão lớn nhất, Chúa đặt cầu vồng trên mây như một lời hứa. Mỗi lần bạn thấy cầu vồng, đó là tín hiệu dịu dàng của Chúa: Ta nhớ giao ước của Ta. Cuộc đời có những cơn bão, và đôi khi bạn tự hỏi liệu mình có vượt qua nổi không. Hãy nhớ rằng sau những cơn mưa, Chúa vẫn thắp lên những màu sắc của hy vọng. Ngài không quên bạn, không quên lời hứa của Ngài. Hôm nay, nếu bạn đang ở giữa một mùa khó khăn, hãy ngước lên và tìm kiếm những dấu hiệu nhỏ của sự thành tín Ngài. Chúng luôn ở đó, đang chờ bạn nhận ra.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đặt cầu vồng làm dấu giao ước. Xin giúp con nhớ rằng Ngài không quên lời hứa, và cho con nhận ra dấu hiệu của sự thành tín Ngài sau những cơn bão. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":12,"cau":1,"loi_kinh_thanh":"Vả, Đức Giê-hô-va có phán cùng Áp-ram rằng: Ngươi hãy ra khỏi quê hương, vòng bà con và nhà cha ngươi, mà đi đến xứ ta sẽ chỉ cho.","bai_hoc":"Chúa gọi Áp-ram rời khỏi nơi quen thuộc: \\"Vả, Đức Giê-hô-va có phán cùng Áp-ram rằng: Ngươi hãy ra khỏi quê hương, vòng bà con và nhà cha ngươi, mà đi đến xứ ta sẽ chỉ cho\\" Ông được bảo đi đến một nơi mà Chúa sẽ chỉ cho, chứ chưa phải một bản đồ rõ ràng. Có thể bạn cũng đang đứng trước một bước ngoặt: đổi việc, đổi nơi ở, bắt đầu điều mới. Cảm giác lo lắng là bình thường. Nhưng hãy nhớ rằng Chúa không chỉ gọi, Ngài còn đồng hành. Đức tin không phải là biết hết đường đi, mà là tin vào Đấng dẫn đường. Hôm nay, hãy cầu nguyện: \\"Chúa ơi, con sẵn lòng bước đi theo Ngài, dù con chưa thấy hết con đường\\".","loi_cau_nguyen":"Chúa ơi, khi Ngài gọi con bước đi mà con chưa thấy hết đường, xin cho con can đảm bước từng bước nhỏ, vì biết Ngài đi cùng. Xin dẫn dắt con đến nơi Ngài đã chuẩn bị. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":12,"cau":2,"loi_kinh_thanh":"Ta sẽ làm cho ngươi nên một dân lớn; ta sẽ ban phước cho ngươi, cùng làm nổi danh ngươi, và ngươi sẽ thành một nguồn phước.","bai_hoc":"Chúa hứa làm cho Áp-ram thành một dân lớn, ban phước cho ông và làm cho danh ông nên cao trọng. Nhưng hãy chú ý: ngươi sẽ làm một nguồn phước. Phước của Chúa không nhằm dừng lại nơi bạn. Nó được ban để chảy qua bạn đến những người khác. Hôm nay, hãy nghĩ xem Chúa đã ban cho bạn điều gì: thời gian, tài năng, lòng tốt, một mái ấm. Làm sao bạn có thể chia sẻ nó với ai đó? Khi bạn trở thành nguồn phước cho người khác, bạn sẽ khám phá rằng niềm vui sâu nhất là niềm vui khi cho đi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã ban phước cho con. Xin giúp con trở thành nguồn phước cho người khác, bằng thời gian, tài năng hay lòng tốt mà Ngài đã trao cho con. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":12,"cau":3,"loi_kinh_thanh":"Ta sẽ ban phước cho người nào chúc phước ngươi, rủa sả kẻ nào rủa sả ngươi; và các chi tộc nơi thế gian sẽ nhờ ngươi mà được phước.","bai_hoc":"Lời hứa này mở rộng ra tất cả các dân tộc trên đất. Kế hoạch của Chúa luôn lớn hơn bạn tưởng, và bạn là một phần nhỏ nhưng quý giá trong câu chuyện ấy. Đôi khi chúng ta nghĩ cuộc sống chỉ xoay quanh những lo toan hằng ngày. Nhưng Chúa mời bạn nhìn xa hơn: cuộc đời bạn có thể góp phần mang phước lành đến người khác. Dù là việc nhỏ như một lời động viên, một sự giúp đỡ âm thầm, hay một lời cầu nguyện cho ai đó, tất cả đều nằm trong kế hoạch lớn của Ngài. Hôm nay, hãy xin Chúa mở mắt bạn để thấy cơ hội trở thành phước cho một người.","loi_cau_nguyen":"Chúa ơi, kế hoạch của Ngài lớn hơn những gì con thấy. Xin mở mắt con nhận ra cơ hội để làm phước cho một người hôm nay, dù chỉ bằng một lời cầu nguyện hay một việc nhỏ. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":15,"cau":6,"loi_kinh_thanh":"Áp-ram tin Đức Giê-hô-va, thì Ngài kể sự đó là công bình cho người.","bai_hoc":"Áp-ram nhìn lên bầu trời đầy sao và tin lời Chúa hứa dù mọi thứ trông bất khả. Và Chúa kể sự tin ấy là công bình cho ông. Không phải vì ông làm điều gì vĩ đại, mà vì ông tin. Điều này là một sự nhẹ nhõm lớn cho chúng ta: bạn không cần phải hoàn hảo để được Chúa chấp nhận. Bạn chỉ cần tin Ngài, ngay cả khi đức tin còn nhỏ và run rẩy. Hôm nay, nếu bạn đang mệt vì cố gắng chứng minh bản thân, hãy đặt gánh nặng ấy xuống. Hãy ngước nhìn các vì sao, và nói với Chúa: \\"Con tin Ngài\\".","loi_cau_nguyen":"Chúa ơi, con tin Ngài, dù đức tin của con còn nhỏ. Xin giúp con thôi cố gắng chứng minh bản thân, và yên nghỉ trong ơn cứu Ngài ban cho những ai tin Ngài. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":18,"cau":14,"loi_kinh_thanh":"Há có điều chi Đức Giê-hô-va làm không được chăng? Đến kỳ đã định, trong một năm nữa, ta sẽ trở lại cùng ngươi, và Sa-ra sẽ có một con trai.","bai_hoc":"Sa-ra cười thầm khi nghe lời hứa về đứa con, vì mọi thứ dường như đã quá muộn. Nhưng Chúa hỏi nhẹ nhàng: Có việc gì quá khó cho Đức Giê-hô-va chăng? Hãy tự hỏi: điều gì trong đời bạn mà bạn đã ngừng hy vọng? Một mối quan hệ đổ vỡ, một ước mơ bị chôn vùi, một vết thương cũ. Chúa không quở trách bạn vì sự nghi ngờ, Ngài chỉ dịu dàng nhắc: không điều gì là quá khó với Ngài. Hôm nay, hãy mang chính điều tưởng như đã chết ấy đến với Chúa. Ngài có thể làm điều bạn không dám mong.","loi_cau_nguyen":"Chúa ơi, không có việc gì quá khó với Ngài. Xin giúp con dám mang đến Ngài những điều con đã thôi hy vọng, và tin rằng Ngài có thể làm những điều con không dám mong. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":22,"cau":8,"loi_kinh_thanh":"Áp-ra-ham rằng: Con ơi! chính Đức Chúa Trời sẽ sắm sẵn lấy chiên con đặng dùng làm của lễ thiêu; rồi cả hai cha con cứ đồng đi.","bai_hoc":"Trên con đường lên núi, Y-sác hỏi cha: Chiên con để làm của lễ ở đâu? Áp-ra-ham đáp, với một đức tin lặng lẽ: Đức Chúa Trời sẽ tự sắm sẵn. Có những lúc bạn không thấy giải pháp nào, không biết mình sẽ vượt qua thử thách bằng cách nào. Hãy nhớ rằng điều Chúa đòi hỏi nơi bạn, Ngài cũng sẽ cung cấp. Câu chuyện này cuối cùng chỉ về Chúa Giê-su, Chiên Con Chúa đã sắm sẵn cho chúng ta. Hôm nay, hãy trao nỗi lo cho Ngài và tin rằng Đấng đã chuẩn bị mọi sự từ trước sẽ chuẩn bị cả điều bạn cần.","loi_cau_nguyen":"Chúa ơi, xin cho con tin rằng Ngài sẽ chuẩn bị những gì cần thiết. Khi con không thấy giải pháp, xin giúp con kiên nhẫn và tiếp tục tin cậy Chúa Giê-su, Chiên Con Ngài đã ban. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":22,"cau":14,"loi_kinh_thanh":"Áp-ra-ham gọi chỗ đó là Giê-hô-va Di-rê. Bởi cớ ấy, ngày nay có tục ngữ rằng: Trên núi của Đức Giê-hô-va sẽ có sắm sẵn.","bai_hoc":"Áp-ra-ham gọi nơi ấy là Đức Giê-hô-va sẽ thấy trước và lo liệu. Ông đã đi qua thử thách đau đớn nhất, và ở đỉnh núi ông nhận ra Chúa đã sẵn sàng từ trước. Nhiều khi chúng ta chỉ thấy sự chu cấp của Chúa khi nhìn lại. Hãy thử nhìn lại cuộc đời mình: có những lúc bạn tưởng đã hết lối, rồi bất ngờ có một cánh cửa mở ra, một người xuất hiện giúp bạn. Đó là dấu tay của Đấng lo liệu. Hôm nay, hãy tin rằng Ngài cũng đang chuẩn bị điều bạn chưa thấy, và đừng quên nói lời cảm ơn vì những điều Ngài đã làm.","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng thấy trước và lo liệu. Xin giúp con nhìn lại và nhận ra những lần Ngài đã chu cấp cho con, rồi tin rằng Ngài cũng đang chuẩn bị cho những ngày sắp đến. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":28,"cau":15,"loi_kinh_thanh":"Nầy, ta ở cùng ngươi, ngươi đi đâu, sẽ theo gìn giữ đó, và đem ngươi về xứ nầy; vì ta không bao giờ bỏ ngươi cho đến khi ta làm xong những điều ta đã hứa cùng ngươi.","bai_hoc":"Gia-cốp đang chạy trốn, cô đơn và sợ hãi, ngủ ngoài trời với một hòn đá làm gối. Ngay giữa khoảnh khắc ấy, Chúa nói: Này, Ta ở cùng ngươi, sẽ gìn giữ ngươi mọi nơi ngươi đi. Bạn không cần ở trong nhà thờ hay trong lúc bình yên mới gặp được Chúa. Ngài đến ngay nơi bạn đang cảm thấy yếu đuối nhất. Dù hôm nay bạn đang ở một nơi xa lạ, một giai đoạn bất định, hãy nhớ rằng Chúa đi cùng bạn và Ngài không bỏ bạn cho đến khi mọi lời Ngài hứa được trọn. Hãy yên nghỉ trong lời hứa ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa ở cùng và gìn giữ con ở mọi nơi con đi. Dù con ở đâu, xin cho con cảm nhận sự hiện diện của Ngài và biết mình không bao giờ đơn độc. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":31,"cau":49,"loi_kinh_thanh":"Mà cũng gọi là Mích-ba, vì La-ban có nói thêm rằng: Khi chúng ta phân cách nhau, cầu xin Đức Giê-hô-va coi sóc cậu và cháu.","bai_hoc":"Mích-ba là một lời nguyện dịu dàng: Xin Đức Giê-hô-va giám sát giữa hai ta khi chúng ta xa nhau. Có những mối quan hệ khiến ta lo lắng khi phải xa cách, hoặc không còn tin tưởng hoàn toàn. Lời nguyện này mời ta đặt các mối quan hệ dưới ánh mắt của Chúa. Hôm nay, bạn có thể nghĩ đến một người xa cách: một người thân ở xa, một người bạn cũ, một người đã xảy ra hiểu lầm. Hãy trao họ cho Chúa trong lời cầu nguyện, và xin Ngài gìn giữ tình thương giữa hai người, dù khoảng cách địa lý hay cảm xúc.","loi_cau_nguyen":"Chúa ơi, xin đặt những mối quan hệ của con dưới sự gìn giữ của Ngài. Xin giữ gìn tình thương giữa con và những người xa cách, dù khoảng cách địa lý hay khoảng cách trong lòng. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":32,"cau":26,"loi_kinh_thanh":"Người đó bèn nói: Trời đã rạng đông rồi; thôi để cho ta đi; nhưng Gia-cốp đáp rằng: Tôi chẳng cho người đi đâu, nếu người không ban phước cho tôi.","bai_hoc":"Gia-cốp vật lộn với Chúa suốt đêm và nói: Tôi chẳng buông Ngài ra đâu, trừ khi Ngài ban phước cho tôi. Đó là tiếng kêu của một người tuyệt vọng nhưng không buông bỏ. Chúa không chê trách sự kiên trì ấy. Có những đêm cầu nguyện dài, bạn không nhận được câu trả lời ngay. Hãy tiếp tục bám lấy Ngài. Chúa quý trọng những ai đến với Ngài bằng sự thành thật, kể cả khi họ mệt mỏi và đầy thương tích. Hôm nay, nếu bạn đang vật lộn với một câu hỏi, một nỗi đau, đừng buông ra, hãy giữ lấy Chúa, và Ngài sẽ ban phước cho bạn.","loi_cau_nguyen":"Chúa ơi, xin cho con biết bám lấy Ngài trong lúc vật lộn, và không buông ra. Xin ban phước và cho con câu trả lời đúng lúc, và cho con sự kiên nhẫn để chờ đợi Ngài. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":32,"cau":28,"loi_kinh_thanh":"Người lại nói: Tên ngươi sẽ chẳng làm Gia-cốp nữa, nhưng tên là Y-sơ-ra-ên, vì ngươi đã có vật lộn cùng Đức Chúa Trời và người ta; ngươi đều được thắng.","bai_hoc":"Sau đêm vật lộn, Gia-cốp được đổi tên thành Y-sơ-ra-ên. Ông bị thương, đi khập khiễng, nhưng ông có một danh mới. Có khi những vết thương trên đường đức tin lại là nơi Chúa viết nên căn tính mới cho chúng ta. Bạn không còn là người cũ, người của sự lừa dối, nỗi sợ hay thất bại. Trong Chúa, bạn có một danh phận mới. Hôm nay, hãy nhớ rằng Chúa nhìn bạn không bằng những lỗi lầm quá khứ, mà bằng con người Ngài đang xây dựng. Hãy bước tiếp, dù có khập khiễng, với một trái tim mới.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ban cho con một danh phận mới trong Ngài. Xin giúp con sống như người được đổi mới, không còn bị lỗi lầm hay thất bại trong quá khứ định nghĩa. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":39,"cau":9,"loi_kinh_thanh":"trong nhà nầy chẳng ai lớn hơn tôi, và chủ cùng không cấm chi tôi, trừ ra một mình ngươi, vì là vợ của chủ tôi. Thế nào tôi dám làm điều đại ác dường ấy, mà phạm tội cùng Đức Chúa Trời sao?","bai_hoc":"Giô-sép bị cám dỗ khi chẳng ai nhìn thấy, và ông đáp: Làm sao tôi dám phạm tội trọng này mà đắc tội cùng Đức Chúa Trời? Ông nhìn tội lỗi trước hết là một tổn thương trong mối quan hệ với Chúa, không chỉ là một điều luật. Cách nhìn ấy giúp ông đứng vững. Khi bạn đối diện với cám dỗ, đặc biệt những cám dỗ kín đáo, hãy nhớ rằng Chúa luôn ở bên bạn và yêu thương bạn. Bạn không phải chiến đấu một mình. Hôm nay, hãy xin Chúa cho bạn một lòng yêu mến Ngài hơn tất cả, để việc chọn điều đúng không còn là gánh nặng mà là đáp lại tình yêu.","loi_cau_nguyen":"Chúa ơi, xin giữ con khỏi những cám dỗ, kể cả những điều không ai nhìn thấy. Xin cho con yêu mến Ngài hơn tất cả, để việc chọn điều đúng không còn là gánh nặng mà là đáp lại tình yêu Ngài. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":45,"cau":5,"loi_kinh_thanh":"Bây giờ, đừng sầu não, và cũng đừng tiếc chi về điều các anh đã bán tôi đặng bị dẫn đến xứ nầy; vì để giữ gìn sự sống các anh, nên Đức Chúa Trời đã sai tôi đến đây trước các anh.","bai_hoc":"Giô-sép đứng trước những người anh đã bán mình, và thay vì trả thù, ông nói: Đừng buồn, vì Đức Chúa Trời đã sai tôi đi trước để cứu sự sống. Ông đã khóc nhiều, đã đau nhiều, nhưng ông chọn nhìn thấy bàn tay Chúa trong tất cả. Điều đó giúp ông tha thứ. Nếu bạn đang mang một vết thương do người khác gây ra, hãy xin Chúa giúp bạn nhìn thấy điều Ngài đang làm bên trong nỗi đau ấy. Tha thứ không xóa đi nỗi đau, nhưng mở ra sự tự do. Hôm nay, hãy trao nỗi đau cho Chúa, và để Ngài chữa lành từng chút một.","loi_cau_nguyen":"Chúa ơi, xin giúp con thấy bàn tay Ngài trong cả những điều làm con đau. Xin cho con can đảm từng bước tha thứ, và để Ngài chữa lành những vết thương trong lòng con. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":49,"cau":10,"loi_kinh_thanh":"Cây phủ việt chẳng hề dời khỏi Giu-đa, Kẻ lập pháp không dứt khỏi giữa chân nó, Cho đến chừng Đấng Si-lô hiện tới, Và các dân vâng phục Đấng đó.","bai_hoc":"Gia-cốp, ở cuối đời, nói tiên tri về chi phái Giu-đa: cây phủ việt sẽ không dời khỏi nó, cho đến khi Đấng được vâng phục đến. Đó là lời báo trước về Chúa Giê-su, Vua của muôn vua. Ngay từ những trang đầu Kinh Thánh, Chúa đã chuẩn bị cho sự đến của Đấng Cứu Thế. Nghĩa là câu chuyện cứu rỗi không phải là một ý nghĩ chợt nảy ra, mà là kế hoạch từ lâu đời, đầy yêu thương. Hôm nay, hãy biết ơn Chúa vì Ngài đã dành cả lịch sử để đưa Đấng Christ đến với bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã chuẩn bị sự đến của Đấng Cứu Thế từ lâu đời. Xin cho con nhớ rằng câu chuyện cứu rỗi là kế hoạch đầy yêu thương của Ngài dành cho con. A-men."},{"sach":"Sáng Thế Ký","ma":"GEN","chuong":50,"cau":20,"loi_kinh_thanh":"Các anh toan hại tôi, nhưng Đức Chúa Trời lại toan làm điều ích cho tôi, hầu cho cứu sự sống cho nhiều người, y như đã xảy đến ngày nay, và giữ gìn sự sống của dân sự đông đảo.","bai_hoc":"Các anh của Giô-sép đã có ý hại ông, nhưng Giô-sép nói: \\"Các anh toan hại tôi, nhưng Đức Chúa Trời lại toan làm điều ích.\\" Đó là một trong những lời đẹp nhất về sự chữa lành. Không phải điều ác trở thành điều tốt, nhưng Chúa có thể dùng ngay cả những điều đau đớn nhất để mang lại điều tốt đẹp. Có thể bạn đang mang theo một ký ức khó nhọc. Hãy cầu xin Chúa cho bạn niềm hy vọng rằng Ngài sẽ không bỏ phí nỗi đau ấy. Hôm nay, hãy tin rằng bàn tay Ngài vẫn đang dệt nên điều tốt từ những mảnh vỡ.","loi_cau_nguyen":"Chúa ơi, xin dùng cả những điều đau đớn trong đời con để làm nên điều tốt. Xin cho con tin rằng Ngài không bỏ phí nước mắt của con, và cho con hy vọng đến từ Ngài. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":3,"cau":5,"loi_kinh_thanh":"Đức Chúa Trời phán rằng: Chớ lại gần chốn nầy, Hãy cổi giầy ngươi ra, vì chỗ ngươi đang đứng là đất thánh.","bai_hoc":"Môi-se đang chăn chiên như bao ngày, nhưng bỗng thấy một bụi gai cháy mà không tàn. Khi ông tiến lại gần, Chúa phán: Hãy cởi giày ra, vì chỗ ngươi đứng là đất thánh. Chỉ một nơi bình thường, mà vì sự hiện diện của Chúa đã trở nên thánh. Có thể hôm nay bạn đang ở trong chính nơi quen thuộc: căn bếp, văn phòng, chiếc xe buýt. Chúa vẫn có thể đến đó và làm nơi ấy trở nên thiêng liêng. Hãy chậm lại, hạ thấp lòng, và nhận ra Ngài đang ở rất gần. Đôi khi, điều ta cần chỉ là cởi bỏ vội vàng và để Ngài chạm vào lòng mình.","loi_cau_nguyen":"Chúa ơi, xin giúp con chậm lại và nhận ra sự hiện diện của Ngài ở ngay những nơi con thường ngày. Xin cho con đến gần Ngài với lòng kính trọng và biết ơn. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":3,"cau":14,"loi_kinh_thanh":"Đức Chúa Trời phán rằng: Ta là Đấng Tự Hữu Hằng Hữu; rồi Ngài lại rằng: Hãy nói cho dân Y-sơ-ra-ên như vầy: Đấng Tự Hữu đã sai ta đến cùng các ngươi.","bai_hoc":"Môi-se hỏi Chúa phải nói gì với dân sự, và Chúa đáp: \\"Ta là Đấng Tự Hữu.\\" Một cái tên giản dị, nhưng chứa đựng cả sự thành tín. Chúa không đến rồi đi như những điều trong đời. Ngài luôn là Đấng ở đó, hôm qua, hôm nay và mãi mãi. Khi mọi thứ quanh bạn thay đổi, người thân đi xa, công việc xáo trộn, sức khỏe mong manh, hãy nhớ rằng có một Đấng không bao giờ đổi thay. Bạn có thể đặt niềm tin vào Ngài, như đặt chân trên đá thay vì cát. Hôm nay, hãy thì thầm: \\"Chúa ơi, Ngài là nền vững của con.\\"","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng Tự Hữu, không bao giờ đổi thay. Khi mọi thứ quanh con thay đổi, xin làm nền vững chắc cho đức tin con, và giúp con nương cậy Ngài. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":12,"cau":13,"loi_kinh_thanh":"Huyết bôi trên nhà các ngươi ở, sẽ dùng làm dấu hiệu; khi ta hành hại xứ Ê-díp-tô, thấy huyết đó, thì sẽ vượt qua, chẳng có tai nạn hủy diệt các ngươi.","bai_hoc":"Trong đêm Vượt Qua, những gia đình bôi huyết chiên lên cửa nhà. Chúa phán: Khi Ta thấy huyết, Ta sẽ vượt qua. Họ được cứu không phải vì họ giỏi hơn, mà vì tin lời Ngài và nương vào dấu hiệu Ngài đã chỉ. Đây là hình ảnh đẹp về Chúa Giê-su, Chiên Con đổ huyết để chúng ta được cứu. Nếu bạn đang mang cảm giác tội lỗi và sợ hãi, hãy nhớ rằng huyết của Ngài đã bao phủ bạn. Bạn được an toàn, không phải bởi thành tích, mà bởi lòng thương xót đã được trả giá. Hôm nay, hãy nghỉ ngơi trong sự bình an ấy.","loi_cau_nguyen":"Cảm ơn Chúa Giê-su đã đổ huyết để cứu con. Xin giúp con nghỉ ngơi trong sự bình an của ơn cứu ấy, và sống không còn bị ràng buộc bởi sợ hãi hay mặc cảm tội lỗi. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":14,"cau":14,"loi_kinh_thanh":"Đức Giê-hô-va sẽ chiến cự cho, còn các ngươi cứ yên lặng.","bai_hoc":"Dân Y-sơ-ra-ên đứng bên bờ Biển Đỏ, quân Ai Cập đuổi phía sau, không còn đường lui. Môi-se nói: Đức Giê-hô-va sẽ chiến đấu cho các ngươi, còn các ngươi cứ yên lặng. Chúng ta thường nghĩ mình phải làm gì đó, phải xoay xở, phải lo liệu mọi thứ. Nhưng có những lúc điều Chúa mời bạn là bình tĩnh, đứng yên và tin cậy. Nếu hôm nay bạn đang bị dồn vào chân tường, hãy hít thở sâu. Đấng mở biển có thể mở đường cho bạn. Bạn không cần tự gồng mình, hãy để Ngài chiến đấu thay bạn.","loi_cau_nguyen":"Chúa ơi, khi con thấy mình bị dồn ép, xin giúp con bình tĩnh và đứng yên. Xin nhắc con rằng Ngài chiến đấu cho con, và con có thể nghỉ ngơi trong sự tin cậy. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":15,"cau":2,"loi_kinh_thanh":"Đức Giê-hô-va là sức mạnh và sự ca tụng của tôi: Ngài đã trở nên Đấng cứu tôi. Ngài là Đức Chúa Trời tôi, tôi ngợi khen Ngài; Đức Chúa Trời của tổ phụ tôi, tôi tôn kính Ngài.","bai_hoc":"Sau khi qua biển an toàn, Môi-se và dân sự cất tiếng hát: Đức Giê-hô-va là sức mạnh và bài ca của tôi. Khi được cứu, điều đầu tiên họ làm là ca ngợi. Hãy nghĩ về những lần Chúa đã cứu bạn: một cơn bệnh qua đi, một khó khăn được giải quyết, một lúc tưởng như hết hy vọng. Đã bao giờ bạn dừng lại để hát lên lời cảm tạ chưa? Ca ngợi là cách chúng ta nhắc lòng mình nhớ rằng Chúa tốt lành. Hôm nay, dù bạn không có giọng hát hay, hãy cất lên một bài thánh ca nhỏ và để tâm hồn bạn được nâng lên.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là sức mạnh và là Đấng cứu con. Xin giúp con nhớ những điều Ngài đã làm, và dâng một lời ngợi khen cho Ngài, dù chỉ ngắn và đơn sơ. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":15,"cau":26,"loi_kinh_thanh":"Ngài phán rằng: Nếu ngươi chăm chỉ nghe lời Giê-hô-va Đức Chúa Trời ngươi, làm sự ngay thẳng trước mặt Ngài, lắng tai nghe các điều răn và giữ mọi luật lệ Ngài, thì ta chẳng giáng cho ngươi một trong các bịnh nào mà ta đã giáng cho xứ Ê-díp-tô; vì ta là Đức Giê-hô-va, Đấng chữa bịnh cho ngươi.","bai_hoc":"Chúa tự giới thiệu Ngài với dân sự bằng một danh xưng dịu dàng: Ta là Đức Giê-hô-va, Đấng chữa lành ngươi. Ngài quan tâm đến cả thân thể, tâm hồn và tinh thần của bạn. Có thể bạn đang mang một nỗi đau thể xác hay một vết thương không ai thấy. Chúa biết hết. Ngài không xa lạ với đau đớn, và Ngài muốn đến gần để chữa lành. Sự chữa lành có thể đến theo nhiều cách và nhiều thời điểm khác nhau, nhưng Ngài luôn ở đó, không bỏ rơi bạn. Hôm nay, hãy đặt bàn tay lên nơi đau của mình và cầu nguyện: \\"Chúa ơi, xin chạm vào con.\\"","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng chữa lành. Xin chạm vào những nỗi đau trong thân thể và tâm hồn con, và cho con kiên nhẫn tin cậy Ngài theo thời gian và cách của Ngài. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":2,"loi_kinh_thanh":"Ta là Giê-hô-va Đức Chúa Trời ngươi, đã rút ngươi ra khỏi xứ Ê-díp-tô, là nhà nô lệ.","bai_hoc":"Trước khi ban mười điều răn, Chúa nhắc dân Ngài một điều: Ta là Đức Giê-hô-va, Đức Chúa Trời ngươi, đã đem ngươi ra khỏi xứ Ai Cập. Ngài mở đầu bằng ơn cứu, rồi mới ban luật. Điều đó có nghĩa là sự vâng lời của chúng ta không phải để mua lấy tình yêu của Chúa, mà là đáp lại tình yêu đã được ban. Bạn đã được Ngài giải thoát khỏi điều gì? Nỗi sợ hãi, tội lỗi, sự cô đơn? Hãy nhớ lại điều ấy và để lòng biết ơn thúc đẩy bạn sống theo đường lối của Ngài, không phải vì bắt buộc, mà vì yêu mến.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã giải thoát con. Xin giúp con vâng lời Ngài vì lòng biết ơn và yêu mến, không phải vì sợ hãi hay để mua lấy tình yêu của Ngài. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":3,"loi_kinh_thanh":"Trước mặt ta, ngươi chớ có các thần khác.","bai_hoc":"\\"Trước mặt ta, ngươi chớ có các thần khác\\" Điều răn đầu tiên không phải là một lời cấm đoán lạnh lùng, mà là lời của một Đấng yêu thương, mong muốn chúng ta đặt Ngài ở vị trí đầu tiên. Thần tượng ngày nay không nhất thiết là tượng đá, mà có thể là công việc, tiền bạc, sự công nhận, hoặc cả những người ta yêu quý. Khi bất cứ điều gì chiếm chỗ của Chúa trong lòng, ta dần dần mất bình an. Hôm nay, hãy hỏi lòng mình: điều gì đang chiếm nhiều thời gian và tâm trí nhất? Rồi nhẹ nhàng đặt Chúa trở lại vị trí trung tâm.","loi_cau_nguyen":"Chúa ơi, xin chỉ cho con điều gì đang chiếm chỗ của Ngài trong lòng con. Xin giúp con nhẹ nhàng đặt Ngài trở lại ở trung tâm đời sống của con. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":4,"loi_kinh_thanh":"Ngươi chớ làm tượng chạm cho mình, cũng chớ làm tượng nào giống những vật trên trời cao kia, hoặc nơi đất thấp nầy, hoặc trong nước dưới đất.","bai_hoc":"Chúa không muốn chúng ta thu nhỏ Ngài vào bất kỳ hình tượng nào, vì Ngài lớn hơn mọi thứ ta có thể tưởng tượng. Đôi khi chúng ta tự tạo ra một hình ảnh về Chúa: nghiêm khắc, xa cách, hay chỉ phục vụ theo ý mình. Nhưng Chúa thật vừa thánh khiết vừa dịu dàng, vừa vĩ đại vừa gần gũi. Hôm nay, hãy xin Ngài cho bạn biết Ngài đúng như Ngài là, không phải như nỗi sợ hay mong muốn của bạn tưởng tượng. Khi hiểu đúng về Chúa, lòng bạn sẽ được tự do để thờ phượng Ngài một cách chân thật và sâu sắc.","loi_cau_nguyen":"Chúa ơi, xin cho con biết Ngài đúng như Ngài là, không bị giới hạn bởi hình ảnh con tự tưởng tượng. Xin giúp con thờ phượng Ngài một cách chân thật và sâu sắc. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":7,"loi_kinh_thanh":"Ngươi chớ lấy danh Giê-hô-va Đức Chúa Trời ngươi mà làm chơi, vì Đức Giê-hô-va chẳng cầm bằng vô tội kẻ nào lấy danh Ngài mà làm chơi.","bai_hoc":"Danh của Chúa mang trọng lượng của tình yêu và sự thánh khiết. Khi chúng ta dùng danh Ngài một cách vô tâm, thật ra chúng ta đang quên Ngài là ai. Hãy nghĩ đến cách bạn nói về Chúa: trong lời nói, trong lời thề, trong những lúc bực dọc. Danh Chúa là nơi nương náu, là lời kêu cầu trong lúc hoạn nạn, không phải một thói quen bông đùa. Hôm nay, hãy thử nói đến danh Chúa như nói về một người bạn đáng kính, bằng lòng biết ơn và sự trân trọng. Bạn sẽ thấy lòng mình dịu lại mỗi khi gọi tên Ngài.","loi_cau_nguyen":"Chúa ơi, danh Ngài là thánh. Xin giúp con dùng danh Ngài với lòng kính trọng, trong lời nói và trong cả những lúc con bực bội hay vô tâm. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":8,"loi_kinh_thanh":"Hãy nhớ ngày nghỉ đặng làm nên ngày thánh.","bai_hoc":"Chúa ban cho chúng ta một món quà: ngày nghỉ. \\"Hãy nhớ ngày nghỉ đặng làm nên ngày thánh.\\" Ngài biết chúng ta dễ bị cuốn vào guồng quay công việc, cảm thấy giá trị mình phụ thuộc vào năng suất. Ngày nghỉ là lời nhắc dịu dàng rằng bạn quý giá không phải vì bạn làm được nhiều, mà vì bạn thuộc về Ngài. Hãy dành một ngày trong tuần để chậm lại, đến với Chúa, ở bên người thân, nghỉ ngơi thật sự. Đó không phải là lãng phí thời gian, mà là cách bạn nuôi dưỡng linh hồn và nhớ ai đang cầm giữ đời mình.","loi_cau_nguyen":"Chúa ơi, xin giúp con dành thời gian nghỉ ngơi thật sự và ở cùng Ngài. Xin nhắc con rằng giá trị của con không nằm ở việc con làm được bao nhiêu. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":12,"loi_kinh_thanh":"Hãy hiếu kính cha mẹ ngươi, hầu cho ngươi được sống lâu trên đất mà Giê-hô-va Đức Chúa Trời ngươi ban cho.","bai_hoc":"\\"Hãy hiếu kính cha mẹ ngươi, hầu cho ngươi được sống lâu trên đất mà Giê-hô-va Đức Chúa Trời ngươi ban cho\\" Điều răn này đến kèm một lời hứa. Có thể bạn có một mối quan hệ dễ dàng với cha mẹ, hoặc có thể đó là một mối quan hệ nhiều vết thương. Dù thế nào, Chúa mời bạn tìm cách tôn trọng, biết ơn những gì họ đã làm được. Nếu cha mẹ còn, hãy gọi cho họ hôm nay. Nếu họ không còn, hãy thầm cảm ơn Chúa vì họ. Với những ai mang tổn thương, tôn kính không có nghĩa phải che giấu nỗi đau, mà là chọn tha thứ từng chút một. Chúa sẽ đi cùng bạn trong hành trình đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con biết ơn cha mẹ mình. Xin cho con tìm cách tôn trọng họ, và nếu có tổn thương cũ, xin dẫn con từng bước đến sự tha thứ. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":13,"loi_kinh_thanh":"Ngươi chớ giết người.","bai_hoc":"\\"Ngươi chớ giết người.\\" Điều răn này bảo vệ sự sống, vì mỗi con người đều được tạo dựng theo hình ảnh của Chúa. Chúa Giê-su còn đi sâu hơn: Ngài nói cả cơn giận trong lòng cũng cần được chữa lành. Có thể bạn đang giữ sự giận dữ hay cay đắng với ai đó. Hãy đưa nó đến với Chúa. Cơn giận cất giữ lâu ngày sẽ làm tổn thương chính mình trước. Hôm nay, hãy cầu nguyện cho người đã làm bạn đau, dù chỉ một câu ngắn thôi: \\"Chúa ơi, xin ban phước cho họ.\\" Bạn sẽ thấy lòng nhẹ nhàng hơn một chút.","loi_cau_nguyen":"Chúa ơi, xin chữa lành cơn giận trong lòng con. Xin giúp con cầu nguyện điều tốt đẹp cho người đã làm con tổn thương, và giải thoát con khỏi sự cay đắng. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":14,"loi_kinh_thanh":"Ngươi chớ phạm tội tà dâm.","bai_hoc":"Sự trung tín trong hôn nhân là một món quà quý giá cho cả hai người và cho gia đình. Điều răn này không chỉ về hành động, mà về cả những điều trong lòng: ánh mắt, tâm trí, những ý nghĩ thầm kín. Giữ lòng trung tín là một quyết định mỗi ngày, bằng sự biết ơn người bạn đời và bằng sự cẩn trọng trong những điều ta để tâm vào. Nếu bạn từng thất bại, đừng quên Chúa đầy ơn tha thứ. Hôm nay, hãy trân trọng người bạn đồng hành của mình, và xin Chúa giữ gìn tình yêu giữa hai người luôn tươi mới.","loi_cau_nguyen":"Chúa ơi, xin giữ lòng con trung tín, từ ánh mắt đến những suy nghĩ thầm kín. Xin làm mới tình yêu trong gia đình con và ban ơn tha thứ cho những ai đã thất bại. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":15,"loi_kinh_thanh":"Ngươi chớ trộm cướp.","bai_hoc":"\\"Ngươi chớ trộm cướp\\" Điều răn này nhắc ta sống ngay thẳng, kể cả trong những điều nhỏ bé: một món đồ, một khoản tiền, một chút thời gian không thuộc về mình. Chúa muốn chúng ta tin cậy Ngài là Đấng cung cấp, để không cần lấy những điều không phải của mình. Khi sống chân thật với tiền bạc, bạn cũng đang xây dựng sự bình an trong lòng. Hôm nay, hãy nhìn lại cách mình đối xử với của cải và với thời gian của người khác. Nếu cần sửa điều gì, hãy làm với tấm lòng nhẹ nhõm, và biết rằng Chúa luôn đứng về phía người chọn điều ngay thẳng.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống ngay thẳng trong cả những điều nhỏ về tiền bạc và thời gian. Xin giúp con tin rằng Ngài là Đấng cung cấp, để con không cần lấy điều không phải của mình. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":16,"loi_kinh_thanh":"Ngươi chớ nói chứng dối cho kẻ lân cận mình.","bai_hoc":"\\"Ngươi chớ nói chứng dối cho kẻ lân cận mình\\" Lời nói của chúng ta có sức mạnh xây dựng hoặc phá hủy. Một lời không thật, một tin đồn vô tâm có thể làm tổn thương người khác sâu sắc. Chúa mời bạn trở thành người nói sự thật trong tình yêu thương. Hôm nay, trước khi nói về ai đó, hãy tự hỏi: điều này có thật không, có cần thiết không, có tử tế không? Lời nói của bạn có thể là nơi trú ẩn cho người nghe. Hãy xin Chúa đặt một sự canh giữ nơi môi miệng bạn, để mỗi lời bạn nói đều mang theo hơi ấm của Ngài.","loi_cau_nguyen":"Chúa ơi, xin canh giữ môi miệng con. Xin giúp mỗi lời con nói đều thật thà và tử tế, để lời nói của con xây dựng người nghe. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":20,"cau":17,"loi_kinh_thanh":"Ngươi chớ tham nhà kẻ lân cận ngươi, cũng đừng tham vợ người, hoặc tôi trai tớ gái, bò, lừa, hay là vật chi thuộc về kẻ lân cận ngươi.","bai_hoc":"\\"Ngươi chớ tham.\\" Lòng tham thường bắt đầu rất lặng lẽ: một cái nhìn ngưỡng mộ biến thành so sánh, rồi thành bất mãn. Chúa muốn giải thoát bạn khỏi cuộc chạy đua vô tận ấy. Điều Ngài ban cho bạn hôm nay đã là đủ cho ngày hôm nay. Hãy thử viết ra ba điều bạn biết ơn: một người thân, một bữa ăn, một khoảnh khắc yên bình. Khi lòng biết ơn lớn lên, lòng tham sẽ nhỏ lại. Hôm nay, hãy xin Chúa cho bạn một tấm lòng biết đủ và biết vui với những gì mình đang có.","loi_cau_nguyen":"Chúa ơi, xin cho con một lòng biết đủ. Xin giúp con nhìn thấy và cảm ơn những điều Ngài đã ban, để lòng tham và sự so sánh không chiếm chỗ trong con. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":33,"cau":14,"loi_kinh_thanh":"Đức Giê-hô-va đáp rằng: Chính mình ta sẽ đi cùng ngươi, và ta sẽ cho ngươi an nghỉ.","bai_hoc":"Môi-se cầu xin Chúa đừng bắt họ đi nếu Ngài không đi cùng. Và Chúa đáp: Mặt Ta sẽ đi cùng ngươi, và Ta sẽ cho ngươi được an nghỉ. Chỉ cần có Chúa đồng hành là đủ. Có thể bạn đang bước vào một chặng đường mới mà bạn chưa biết điều gì chờ phía trước. Hãy biết rằng sự hiện diện của Chúa là lời hứa lớn nhất. Ngài không chỉ chỉ đường, Ngài đi cùng bạn. Và khi có Ngài, bạn sẽ tìm thấy sự bình yên giữa những bất định. Hôm nay, hãy xin Ngài ở cùng bạn, và nghỉ ngơi trong sự hiện diện ấy.","loi_cau_nguyen":"Chúa ơi, con muốn có sự hiện diện của Ngài hơn mọi điều khác. Xin đi cùng con trong mỗi chặng đường, và ban cho con sự bình an chỉ có được khi ở bên Ngài. A-men."},{"sach":"Xuất Ai-cập Ký","ma":"EXO","chuong":34,"cau":6,"loi_kinh_thanh":"Ngài đi ngang qua mặt người, hô rằng: Giê-hô-va! Giê-hô-va! là Đức Chúa Trời nhân từ, thương xót, chậm giận, đầy dẫy ân huệ và thành thực,","bai_hoc":"Chúa tự giới thiệu bản thân: Đức Giê-hô-va, Đức Giê-hô-va, là Đức Chúa Trời nhân từ, thương xót, chậm nóng giận, đầy dẫy ơn và thành tín. Hãy chậm rãi đọc từng chữ. Đây là Đấng bạn đang cầu nguyện mỗi ngày. Không phải một Đấng khó tính hay xa cách, nhưng là một Đấng nhịn nhục và đầy lòng thương. Khi bạn cảm thấy mình đã làm hỏng việc, khi bạn sợ phải đến cùng Chúa với bao vụng về, hãy nhớ lời này. Ngài chậm giận và nhanh thương xót. Hôm nay, hãy mạnh dạn đến với Ngài như một đứa con đến với cha.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng nhân từ, thương xót, chậm giận và đầy thành tín. Xin giúp con mạnh dạn đến gần Ngài, ngay cả khi con còn nhiều vụng về và thiếu sót. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":11,"cau":44,"loi_kinh_thanh":"Vì ta là Giê-hô-va Đức Chúa Trời của các ngươi; ta là thánh, nên các ngươi phải nên thánh, thì sẽ được thánh. Các ngươi chớ vì một con nào của loài côn trùng trên mặt đất mà làm lây ô uế cho thân mình.","bai_hoc":"\\"Vì ta là Giê-hô-va Đức Chúa Trời của các ngươi; ta là thánh, nên các ngươi phải nên thánh, thì sẽ được thánh. Các ngươi chớ vì một con nào của loài côn trùng trên mặt đất mà làm lây ô uế cho thân mình\\" Sự thánh khiết không phải là sự cứng nhắc hay xa cách, mà là sống thuộc về Chúa, được biệt riêng cho Ngài. Chúa muốn dân Ngài khác biệt vì họ thuộc về một Đấng tuyệt đẹp. Hôm nay, hãy nghĩ đến những việc nhỏ có thể thể hiện sự thuộc về Chúa: lời nói tử tế, sự trung thực, lòng tha thứ. Nên thánh không phải là hoàn hảo, mà là mỗi ngày chọn đi gần Chúa hơn một chút. Và Ngài, Đấng thánh, luôn nâng đỡ bạn trên hành trình ấy bằng ân điển.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống thuộc về Ngài, được biệt riêng cho Ngài. Xin giúp con thể hiện điều đó qua những việc nhỏ hằng ngày, bằng ân điển của Ngài. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":17,"cau":11,"loi_kinh_thanh":"vì sanh mạng của xác thịt ở trong huyết; ta đã cho các ngươi huyết rưới trên bàn thờ đặng làm lễ chuộc tội cho linh hồn mình; vì nhờ sanh mạng mà huyết mới chuộc tội được.","bai_hoc":"\\"vì sanh mạng của xác thịt ở trong huyết; ta đã cho các ngươi huyết rưới trên bàn thờ đặng làm lễ chuộc tội cho linh hồn mình; vì nhờ sanh mạng mà huyết mới chuộc tội được\\" Lê-vi Ký có những phần khó đọc, nhưng đây là trái tim của nó: sự sống quý giá, và Chúa ban huyết để làm của lễ chuộc tội. Tất cả đều chỉ về Chúa Giê-su, Đấng đã hy sinh sự sống mình vì chúng ta. Khi bạn cảm thấy mình không xứng đáng, hãy nhớ rằng giá của bạn đã được trả bằng điều quý nhất. Bạn được yêu đến mức đó. Hôm nay, hãy dừng lại một chút để biết ơn: Chúa không tiếc điều gì để đưa bạn trở về với Ngài.","loi_cau_nguyen":"Cảm ơn Chúa Giê-su đã hy sinh sự sống mình để chuộc tội con. Xin giúp con hiểu sâu hơn mình được yêu đến dường nào, và sống trong sự biết ơn ấy. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":19,"cau":2,"loi_kinh_thanh":"Hãy truyền cho cả hội chúng Y-sơ-ra-ên rằng: Hãy nên thánh, vì ta Giê-hô-va Đức Chúa Trời các người, vốn là thánh.","bai_hoc":"\\"Hãy truyền cho cả hội chúng Y-sơ-ra-ên rằng: Hãy nên thánh, vì ta Giê-hô-va Đức Chúa Trời các người, vốn là thánh\\" Lời kêu gọi này được nói với cả cộng đồng, không chỉ với một vài người đặc biệt. Chúa muốn mỗi người, trong công việc, gia đình, tình bạn, đều sống thuộc về Ngài. Nên thánh nghĩa là để Chúa chạm vào từng phần đời sống của bạn: cách bạn ăn nói, cách bạn làm việc, cách bạn nhìn người khác. Hôm nay, hãy chọn một việc nhỏ và làm nó như dâng cho Chúa. Ngài thấy tấm lòng ấy, và Ngài vui lòng. Bạn không cần làm điều lớn lao, chỉ cần trung tín trong những việc nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống thánh khiết trong mọi mặt đời sống, trong công việc, gia đình và các mối quan hệ. Xin giúp con trung tín trong những việc nhỏ, như làm cho Ngài. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":19,"cau":18,"loi_kinh_thanh":"Chớ toan báo thù, chớ giữ sự báo thù cùng con cháu dân sự mình; nhưng hãy yêu thương kẻ lân cận ngươi như mình: Ta là Đức Giê-hô-va.","bai_hoc":"\\"Chớ toan báo thù, chớ giữ sự báo thù cùng con cháu dân sự mình; nhưng hãy yêu thương kẻ lân cận ngươi như mình: Ta là Đức Giê-hô-va\\" Chúa Giê-su gọi đây là một trong hai điều răn lớn nhất. Yêu người khác như chính mình nghĩa là cũng biết trân trọng bản thân mình như Chúa trân trọng bạn, rồi từ đó tràn ra sự quan tâm đến người khác. Có thể ai đó trong đời bạn đang khó yêu: một đồng nghiệp, một người hàng xóm, một thành viên gia đình. Hôm nay, hãy xin Chúa cho bạn một ánh nhìn mới về người ấy, và chọn làm một điều nhỏ bé tử tế dành cho họ. Tình yêu thương lớn lên từng chút qua những hành động đơn sơ.","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu người lân cận như yêu chính mình. Xin cho con một ánh nhìn mới về những người khó yêu, và cho con làm một việc tử tế dành cho họ. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":25,"cau":10,"loi_kinh_thanh":"Các ngươi phải làm cho năm thứ năm mươi nên thánh, và rao truyền sự tự do cho hết thảy dân trong xứ. Ấy sẽ là năm hân hỉ cho các ngươi; ai nấy đều được nhận lại cơ nghiệp mình, và ai nấy đều trở về gia quyến mình.","bai_hoc":"Năm hân hỷ là năm của tự do: nô lệ được thả, ruộng đất được trả lại, những gánh nợ được xóa. Chúa là Đấng yêu sự giải phóng. Ngài không muốn ai bị trói buộc mãi trong một vòng luẩn quẩn của nghèo khó hay áp bức. Hôm nay, bạn có đang mang một gánh nặng khiến mình không thể ngẩng đầu lên? Một món nợ, một thói quen, một nỗi niềm cũ? Chúa Giê-su đến để công bố năm hân hỷ cho đời bạn. Hãy cầu xin Ngài tháo xiềng xích cho bạn, và bước vào sự tự do mà Ngài đã chuẩn bị.","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng giải phóng. Xin tháo gỡ những xiềng xích đang trói buộc con, và giúp con bước vào sự tự do Ngài đã chuẩn bị cho con trong Chúa Giê-su. A-men."},{"sach":"Lê-vi Ký","ma":"LEV","chuong":26,"cau":12,"loi_kinh_thanh":"Ta sẽ đi giữa các ngươi, làm Đức Chúa Trời các ngươi, và các ngươi sẽ làm dân ta.","bai_hoc":"\\"Ta sẽ đi giữa các ngươi, làm Đức Chúa Trời các ngươi, và các ngươi sẽ làm dân ta\\" Đây là lời hứa đẹp nhất: không chỉ cứu bạn, Chúa còn muốn ở cùng bạn, đi cùng bạn trong từng bước chân. Ngài không muốn là một vị khách thỉnh thoảng ghé qua, mà là Đấng cùng sống với bạn mỗi ngày. Khi bạn nấu cơm, đi làm, chăm sóc con cái, Ngài đều ở đó. Hôm nay, hãy thử trò chuyện với Chúa như với một người bạn đang bước đi bên cạnh bạn. Bạn sẽ khám phá ra rằng cuộc đời không còn cô đơn nữa.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài muốn ở giữa chúng con. Xin giúp con quen trò chuyện với Ngài trong những công việc thường ngày, và nhớ rằng Ngài luôn đi cùng con. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":6,"cau":24,"loi_kinh_thanh":"Cầu xin Đức Giê-hô-va ban phước cho ngươi và phù hộ ngươi!","bai_hoc":"\\"Cầu xin Đức Giê-hô-va ban phước cho ngươi và phù hộ ngươi!\\" Đây là lời chúc phước các thầy tế lễ dành cho dân Chúa. Hãy đọc nó như thể Chúa đang nói riêng với bạn. Gìn giữ nghĩa là bảo vệ, che chở, như người cha canh giấc ngủ cho đứa con nhỏ. Dù hôm nay bạn gặp điều gì, bạn đều nằm trong vòng tay gìn giữ của Ngài. Bạn cũng có thể dùng lời chúc này cho những người bạn yêu thương: con cái, bạn bè, người thân. Hãy cầu nguyện cho họ, và để lời chúc phước ấy trở thành một món quà nhỏ nhưng sâu sắc.","loi_cau_nguyen":"Chúa ơi, xin ban phước và gìn giữ con. Xin giúp con cũng chúc phước cho những người con thương, và cầu nguyện cho họ hôm nay. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":6,"cau":25,"loi_kinh_thanh":"Cầu xin Đức Giê-hô-va chiếu sáng mặt Ngài trên ngươi, và làm ơn cho ngươi!","bai_hoc":"\\"Cầu xin Đức Giê-hô-va chiếu sáng mặt Ngài trên ngươi, và làm ơn cho ngươi!\\" Hãy tưởng tượng khuôn mặt của Chúa chiếu sáng trên bạn, như người mẹ mỉm cười khi nhìn con mình. Đó là cách Ngài nhìn bạn: với niềm vui và sự trìu mến. Nhiều khi chúng ta nghĩ Chúa đang cau mày trước những lỗi lầm của mình. Nhưng lời chúc này cho thấy ngược lại: Ngài muốn ban ơn. Hôm nay, hãy nhắm mắt và hình dung ánh mắt dịu dàng ấy hướng về bạn. Hãy để mình được yêu thương mà không cần chứng minh điều gì.","loi_cau_nguyen":"Chúa ơi, xin cho mặt Ngài rạng soi trên con. Xin giúp con cảm nhận ánh nhìn trìu mến của Ngài, và thôi nghĩ rằng Ngài chỉ nhìn con bằng sự khắt khe. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":6,"cau":26,"loi_kinh_thanh":"Cầu xin Đức Giê-hô-va đoái xem ngươi và ban bình an cho ngươi!","bai_hoc":"\\"Cầu xin Đức Giê-hô-va đoái xem ngươi và ban bình an cho ngươi!\\" Bình an ở đây không chỉ là không có rắc rối, mà là sự trọn vẹn, sự toàn vẹn của lòng, trí và đời sống. Đó là món quà Chúa muốn ban cho bạn. Có thể hôm nay lòng bạn đang xáo động và nhiều lo lắng. Hãy hít một hơi thật sâu, và nhận lời chúc phước này như một cái ôm vô hình. Bình an của Chúa không phụ thuộc hoàn cảnh, nó đến từ việc biết rằng Ngài đoái nhìn bạn. Hãy yên nghỉ trong ánh mắt ấy.","loi_cau_nguyen":"Chúa ơi, xin ban cho con sự bình an trọn vẹn của Ngài, vượt trên mọi hoàn cảnh. Xin giúp lòng con yên nghỉ khi con biết Ngài đoái nhìn con. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":14,"cau":24,"loi_kinh_thanh":"Nhưng vì kẻ tôi tớ Ca-lép ta không đồng lòng cùng chúng nó, theo ta một cách trung tín, thì ta sẽ đem người vào xứ mà người đã có đi, và dòng dõi người sẽ được xứ làm sản nghiệp.","bai_hoc":"Giữa đám đông sợ hãi và than van, Ca-lép có một tâm tình khác. Ông theo Chúa trọn vẹn, và Chúa khen ngợi ông. Đôi khi, tin Chúa nghĩa là đứng lên trong một thế hệ hoài nghi. Có thể bạn đang là người duy nhất trong gia đình, công ty hay nhóm bạn giữ vững đức tin. Hãy nhớ rằng Chúa thấy bạn, như Ngài đã thấy Ca-lép. Sự trung tín của bạn không bị lãng quên. Hôm nay, hãy xin Chúa cho bạn một tinh thần như Ca-lép: kiên định, can đảm và đầy hy vọng, vì bạn biết mình đang theo Đấng đáng tin cậy.","loi_cau_nguyen":"Chúa ơi, xin cho con một tâm tình như Ca-lép, theo Ngài trọn vẹn. Xin giúp con giữ vững đức tin, ngay cả khi những người quanh con không cùng hướng. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":23,"cau":19,"loi_kinh_thanh":"Đức Chúa Trời chẳng phải là người để nói dối, Cũng chẳng phải là con loài người đặng hối cải. Điều Ngài đã nói, Ngài há sẽ chẳng làm ư? Điều Ngài đã phán, Ngài há sẽ chẳng làm ứng nghiệm sao?","bai_hoc":"\\"Đức Chúa Trời chẳng phải là người để nói dối, Cũng chẳng phải là con loài người đặng hối cải. Điều Ngài đã nói, Ngài há sẽ chẳng làm ư? Điều Ngài đã phán, Ngài há sẽ chẳng làm ứng nghiệm sao?\\" Loài người có thể hứa rồi quên, có thể hứa rồi thất hứa. Nhưng Chúa thì không. Điều Ngài đã nói, Ngài sẽ làm. Khi bạn từng bị phản bội hay thất vọng vì lời hứa của ai đó, câu này là sự an ủi nhẹ nhàng: có một Đấng hoàn toàn đáng tin. Hôm nay, hãy chọn một lời hứa của Chúa trong Kinh Thánh và tin vào nó. Hãy để nó là chiếc neo giữ bạn vững vàng giữa những con sóng của cuộc sống.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng không bao giờ nói dối hay thất hứa. Xin giúp con đặt niềm tin vào những lời hứa của Ngài, và để chúng làm chiếc neo cho lòng con. A-men."},{"sach":"Dân Số Ký","ma":"NUM","chuong":32,"cau":23,"loi_kinh_thanh":"Còn nếu không làm như vậy, nầy các ngươi sẽ phạm tội cùng Đức Giê-hô-va, và phải biết rằng tội chắc sẽ đổ lại trên các ngươi.","bai_hoc":"\\"Còn nếu không làm như vậy, nầy các ngươi sẽ phạm tội cùng Đức Giê-hô-va, và phải biết rằng tội chắc sẽ đổ lại trên các ngươi\\" Nghe nặng nề, nhưng đây là một lời nhắc yêu thương. Tội lỗi giấu kín thường làm lòng ta nặng nề, mệt mỏi, mất bình an. Chúa không muốn bạn mang gánh nặng ấy. Ngài mời gọi bạn thật thà bước ra ánh sáng, nhận tội và nhận lấy sự tha thứ. Không có điều gì quá nặng cho lòng thương xót của Ngài. Hôm nay, nếu có điều gì bạn đang giấu trong lòng, hãy thì thầm với Chúa. Sự thật làm bạn tự do, và Ngài luôn sẵn sàng ôm lấy bạn trở lại.","loi_cau_nguyen":"Chúa ơi, xin giúp con thành thật với Ngài về những điều con muốn giấu. Xin tha thứ và giải thoát con khỏi sự mệt mỏi của việc che đậy, để con sống trong ánh sáng. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":4,"cau":29,"loi_kinh_thanh":"Ở đó ngươi sẽ tìm cầu Giê-hô-va Đức Chúa Trời ngươi, và khi nào hết lòng hết ý tìm cầu Ngài thì mới gặp.","bai_hoc":"\\"Ở đó ngươi sẽ tìm cầu Giê-hô-va Đức Chúa Trời ngươi, và khi nào hết lòng hết ý tìm cầu Ngài thì mới gặp\\" Dù bạn đã đi lạc, đã xa cách, Chúa vẫn luôn chờ để bạn tìm về. Ngài không đóng cửa. Điều Ngài cần chỉ là tấm lòng chân thành, không phải sự hoàn hảo. Có thể hôm nay bạn đang thấy mình cách xa Chúa quá, không biết bắt đầu lại từ đâu. Hãy bắt đầu bằng một lời cầu nguyện đơn sơ: \\"Chúa ơi, con ở đây.\\" Ngài đã sẵn sàng đón bạn, như người cha đứng ngoài cổng mong ngóng đứa con trở về.","loi_cau_nguyen":"Chúa ơi, Ngài hứa rằng ai hết lòng tìm kiếm Ngài sẽ gặp Ngài. Xin giúp con tìm kiếm Ngài với lòng chân thành, kể cả khi con thấy mình còn xa, và xin cho con gặp Ngài. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":6,"cau":4,"loi_kinh_thanh":"Hỡi Y-sơ-ra-ên! hãy nghe: Giê-hô-va Đức Chúa Trời chúng ta là Giê-hô-va có một không hai.","bai_hoc":"\\"Hỡi Y-sơ-ra-ên, hãy nghe: Giê-hô-va Đức Chúa Trời chúng ta là Giê-hô-va có một không hai.\\" Đây là lời cầu nguyện mà người Do Thái đọc mỗi sáng và mỗi tối. Chúa là Đấng duy nhất, trọn vẹn, đáng tin cậy. Giữa cuộc sống nhiều tiếng ồn và nhiều lựa chọn, bạn có một Đấng duy nhất để quy hướng. Hôm nay, trước khi lao vào ngày mới, hãy dừng lại một phút, nhắm mắt và thầm nhắc: \\"Chúa là Chúa của con, duy nhất.\\" Lời tuyên xưng ấy sẽ như một chiếc neo, giữ lòng bạn bình an suốt ngày.","loi_cau_nguyen":"Chúa ơi, Ngài là Chúa duy nhất của con. Xin gom lòng con lại hướng về Ngài trước khi con bước vào những việc trong ngày, và giữ con bình an. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":6,"cau":5,"loi_kinh_thanh":"Ngươi phải hết lòng, hết ý, hết sức kính mến Giê-hô-va Đức Chúa Trời ngươi.","bai_hoc":"\\"Ngươi phải hết lòng, hết ý, hết sức kính mến Giê-hô-va Đức Chúa Trời ngươi\\" Chúa không muốn một phần bạn, Ngài muốn cả tấm lòng, vì Ngài yêu bạn trọn vẹn. Yêu Chúa không chỉ là cảm xúc dâng trào mỗi Chúa nhật, mà là từng việc nhỏ trong ngày: cách bạn làm việc, cách bạn nói chuyện, cách bạn chăm sóc người khác. Có những ngày lòng bạn thấy nguội lạnh, đừng vội tự trách. Hãy xin Chúa nhen lại ngọn lửa yêu mến trong bạn. Ngài rất vui khi nghe một lời thì thầm: \\"Chúa ơi, con muốn yêu Chúa nhiều hơn.\\"","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu mến Ngài hết lòng, hết linh hồn và hết sức. Khi lòng con nguội lạnh, xin nhen lại ngọn lửa yêu mến Ngài trong con. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":6,"cau":7,"loi_kinh_thanh":"khá ân cần dạy dỗ điều đó cho con cái ngươi và phải nói đến, hoặc khi ngươi ngồi trong nhà, hoặc khi đi ngoài đường, hoặc lúc ngươi nằm, hay là khi chổi dậy.","bai_hoc":"Chúa dặn cha mẹ phải ân cần dạy con cái Lời Ngài, khi ở nhà, khi đi đường, khi nằm, khi dậy. Đức tin không chỉ được truyền qua những bài giảng, mà qua những khoảnh khắc đời thường: một bữa cơm, một chuyến xe, lời cầu nguyện trước khi ngủ. Nếu bạn là cha mẹ, hãy tin rằng những điều nhỏ bé bạn làm đều gieo hạt giống vào lòng con. Nếu bạn không phải, hãy nghĩ về những người đã dạy bạn biết Chúa và gửi lời cảm ơn. Hôm nay, hãy chia sẻ một lời Kinh Thánh với ai đó bạn thương mến.","loi_cau_nguyen":"Chúa ơi, xin giúp con chia sẻ Lời Ngài một cách tự nhiên với người con thương, trong những cuộc trò chuyện đời thường. Xin cho đức tin được truyền sang thế hệ sau. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":7,"cau":9,"loi_kinh_thanh":"Vậy nên, phải nhận biết rằng Giê-hô-va Đức Chúa Trời ngươi, ấy là Đức Chúa Trời, tức Đức Chúa Trời thành tín, giữ sự giao ước và nhân từ đến ngàn đời cho những người yêu mến Ngài và vâng giữ các điều răn Ngài;","bai_hoc":"\\"Vậy nên, phải nhận biết rằng Giê-hô-va Đức Chúa Trời ngươi, ấy là Đức Chúa Trời, tức Đức Chúa Trời thành tín, giữ sự giao ước và nhân từ đến ngàn đời cho những người yêu mến Ngài và vâng giữ các điều răn Ngài\\" Ngàn đời! Nghĩa là tình yêu của Chúa dành cho gia đình bạn kéo dài vượt xa những gì bạn có thể thấy. Có thể bạn lo lắng cho con cháu, cho người thân chưa biết Chúa. Hãy nhớ rằng Chúa trung tín và Ngài không quên lời hứa. Hôm nay, hãy cầu nguyện cho những người bạn yêu thương, và tin rằng tình yêu thành tín của Ngài sẽ đi theo họ suốt nhiều thế hệ. Bạn đang đặt đời mình vào bàn tay vững chắc.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đức Chúa Trời thành tín, giữ giao ước đến ngàn đời. Con xin trao gia đình và con cháu con cho Ngài, và tin Ngài thành tín qua mọi thế hệ. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":8,"cau":3,"loi_kinh_thanh":"Vậy, Ngài có hạ ngươi xuống, làm cho ngươi bị đói, đoạn cho ăn ma-na mà ngươi và tổ phụ ngươi chưa hề biết, để khiến ngươi biết rằng loài người sống chẳng phải nhờ bánh mà thôi, nhưng loài người sống nhờ mọi lời bởi miệng Đức Giê-hô-va mà ra.","bai_hoc":"Chúa cho dân sự đói trong hoang mạc, rồi nuôi họ bằng ma-na, để họ biết người ta sống không phải chỉ nhờ bánh mà thôi. Có những mùa trong đời ta thấy thiếu thốn, và điều đó có thể là lời mời gọi đến gần Chúa hơn. Bánh nuôi thân thể, nhưng Lời Chúa nuôi linh hồn. Bạn đã bao giờ thấy mệt mỏi dù mọi thứ đều đủ đầy? Có thể linh hồn bạn đang đói. Hôm nay, hãy dành mười phút đọc Kinh Thánh và để Lời Ngài là bữa ăn dịu dàng của bạn. Linh hồn bạn sẽ được no đủ.","loi_cau_nguyen":"Chúa ơi, xin nuôi dưỡng linh hồn con bằng Lời Ngài như con nuôi thân thể bằng bánh. Xin giúp con dành thời gian đọc Kinh Thánh hôm nay và được no đủ. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":10,"cau":12,"loi_kinh_thanh":"Vậy, hỡi Y-sơ-ra-ên, bây giờ Giê-hô-va Đức Chúa Trời ngươi đòi ngươi điều chi? há chẳng phải đòi ngươi kính sợ Giê-hô-va, Đức Chúa Trời ngươi, đi theo các đạo Ngài, hết lòng hết ý kính mến và phục sự Giê-hô-va Đức Chúa Trời ngươi,","bai_hoc":"Giê-hô-va Đức Chúa Trời ngươi đòi hỏi ngươi điều gì? Chỉ kính sợ Ngài, đi theo Ngài, yêu mến Ngài. Chúa không đòi hỏi những điều quá sức. Ngài chỉ muốn tấm lòng của bạn. Có những lúc chúng ta nghĩ phải làm thật nhiều thật giỏi mới làm Chúa vui lòng. Nhưng điều Ngài mong là mối quan hệ gần gũi với bạn. Hôm nay, hãy nhẹ nhõm vì Chúa không cần bạn hoàn hảo. Hãy dành vài phút bên Ngài, nói chuyện với Ngài, và để tình yêu của Ngài bao phủ bạn như một tấm chăn ấm trong ngày lạnh.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài chỉ mong tấm lòng của con. Xin giúp con kính sợ Ngài, bước đi trong đường lối Ngài và yêu mến Ngài, và dành thời gian ở bên Ngài. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":18,"cau":15,"loi_kinh_thanh":"Từ giữa anh em ngươi, Giê-hô-va Đức Chúa Trời ngươi sẽ lập lên một đấng tiên tri như ta; các ngươi khá nghe theo đấng ấy!","bai_hoc":"Môi-se nói với dân sự: Đức Giê-hô-va sẽ dấy lên cho ngươi một Đấng tiên tri như ta. Hàng trăm năm sau, những người tin Chúa Giê-su nhận ra Ngài chính là Đấng ấy. Chúa không để dân Ngài cô độc, Ngài luôn gửi người nói thay cho Ngài, và cuối cùng, chính Con Ngài đến. Điều này cho thấy sự kiên nhẫn của Chúa trong việc dẫn dắt con người. Hôm nay, hãy biết ơn vì bạn không phải tự mò mẫm tìm Chúa trong bóng tối. Chúa Giê-su đã đến, nói với bạn bằng tiếng nói rõ ràng nhất của tình yêu.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã gửi Chúa Giê-su, Đấng tiên tri trọn vẹn, đến với chúng con. Xin giúp con lắng nghe Ngài và đi theo lời dạy của Ngài. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":29,"cau":29,"loi_kinh_thanh":"Những sự bí mật thuộc về Giê-hô-va Đức Chúa Trời chúng ta; song những sự bày tỏ thuộc về chúng ta, và con cháu chúng ta đời đời, để chúng ta làm theo mọi lời của luật pháp nầy.","bai_hoc":"\\"Những sự bí mật thuộc về Giê-hô-va Đức Chúa Trời chúng ta; song những sự bày tỏ thuộc về chúng ta, và con cháu chúng ta đời đời, để chúng ta làm theo mọi lời của luật pháp nầy\\" Có những câu hỏi trong đời bạn mà bạn chưa có câu trả lời: vì sao người thân ra đi sớm, vì sao điều ấy xảy ra. Chúa không bắt bạn phải hiểu mọi thứ. Có những điều thuộc về Ngài, và bạn có thể buông tay. Điều bạn cần làm là sống theo những gì Ngài đã bày tỏ. Hôm nay, hãy trao lại cho Chúa những câu hỏi chưa có lời đáp, và yên nghỉ trong sự tin cậy rằng Ngài biết và Ngài yêu bạn.","loi_cau_nguyen":"Chúa ơi, có những điều con chưa hiểu và thuộc về Ngài. Xin giúp con trao lại những câu hỏi ấy cho Ngài, và sống theo những điều Ngài đã bày tỏ. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":30,"cau":19,"loi_kinh_thanh":"Ngày nay, ta bắt trời và đất làm chứng cho các ngươi rằng ta đã đặt trước mặt ngươi sự sống và sự chết, sự phước lành và sự rủa sả. Vậy, hãy chọn sự sống, hầu cho ngươi và dòng dõi ngươi được sống,","bai_hoc":"\\"Ngày nay, ta bắt trời và đất làm chứng cho các ngươi rằng ta đã đặt trước mặt ngươi sự sống và sự chết, sự phước lành và sự rủa sả. Vậy, hãy chọn sự sống, hầu cho ngươi và dòng dõi ngươi được sống\\" Chúa không ép buộc. Ngài đặt con đường trước mặt bạn, và nhẹ nhàng mời gọi bạn chọn điều tốt lành. Mỗi ngày bạn đều đang chọn: chọn tha thứ hay cay đắng, chọn tin cậy hay lo sợ, chọn bước đến Ngài hay quay đi. Dù hôm qua bạn đã chọn chưa đúng, hôm nay vẫn là một cơ hội mới. Hãy nhắm mắt lại và thì thầm: \\"Chúa ơi, hôm nay con chọn sự sống, con chọn Ngài.\\" Ngài sẽ đi cùng bạn trong lựa chọn ấy.","loi_cau_nguyen":"Chúa ơi, hôm nay con chọn sự sống, con chọn Ngài. Xin giúp con chọn đúng trong những quyết định nhỏ và lớn, và cho con sức mạnh để đi theo lựa chọn ấy. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":31,"cau":6,"loi_kinh_thanh":"Hãy vững lòng bền chí; chớ sợ chi và chớ kinh khủng trước mặt các dân đó; vì Giê-hô-va Đức Chúa Trời ngươi đi cùng ngươi; Ngài chẳng lìa khỏi ngươi, chẳng từ bỏ ngươi đâu.","bai_hoc":"\\"Hãy vững lòng bền chí; chớ sợ chi và chớ kinh khủng trước mặt các dân đó; vì Giê-hô-va Đức Chúa Trời ngươi đi cùng ngươi; Ngài chẳng lìa khỏi ngươi, chẳng từ bỏ ngươi đâu\\" Môi-se nói với dân sự trước khi họ bước vào một vùng đất đầy thách thức. Lời này cũng dành cho bạn hôm nay. Sự can đảm không phải là không sợ, mà là bước đi dù có sợ vì biết Chúa đi cùng. Có thể bạn đang đối diện một điều khiến mình run rẩy: một cuộc phẫu thuật, một quyết định lớn, một mối quan hệ khó khăn. Hãy nắm lấy lời hứa này. Bạn không đi một mình.","loi_cau_nguyen":"Chúa ơi, Ngài hứa không lìa bỏ con. Xin giúp con mạnh mẽ và can đảm, không phải vì con không sợ, mà vì con biết Ngài đi cùng con. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":31,"cau":8,"loi_kinh_thanh":"Chính Đức Giê-hô-va sẽ đi trước ngươi, Ngài sẽ ở cùng ngươi, chẳng lìa khỏi ngươi, chẳng từ bỏ ngươi đâu. Chớ sợ, và chớ kinh khủng.","bai_hoc":"\\"Chính Đức Giê-hô-va sẽ đi trước ngươi, Ngài sẽ ở cùng ngươi, chẳng lìa khỏi ngươi, chẳng từ bỏ ngươi đâu. Chớ sợ, và chớ kinh khủng\\" Chúa đi trước bạn. Điều đó nghĩa là khi bạn đến nơi bạn sợ, Ngài đã ở đó rồi. Ngày mai chưa đến, nhưng Ngài đã có mặt. Hãy để hình ảnh này làm lòng bạn dịu lại: mỗi bước chân ngày mai, Chúa đã đặt dấu chân trước. Những con đường bạn chưa biết đã được Ngài chuẩn bị. Hôm nay, khi lo âu về tương lai, hãy thầm nhắc: \\"Chúa đã ở đó trước con.\\" Và bước tiếp với một chút bình an.","loi_cau_nguyen":"Chúa ơi, Ngài đi trước con trên mọi con đường. Khi con lo lắng về tương lai, xin nhắc con rằng Ngài đã ở đó rồi, và giúp con bình an bước từng bước một. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":32,"cau":4,"loi_kinh_thanh":"Công việc của Hòn Đá là trọn vẹn; Vì các đường lối Ngài là công bình. Ấy là Đức Chúa Trời thành tín và vô tội; Ngài là công bình và chánh trực.","bai_hoc":"\\"Công việc của Hòn Đá là trọn vẹn; Vì các đường lối Ngài là công bình. Ấy là Đức Chúa Trời thành tín và vô tội; Ngài là công bình và chánh trực\\" Hòn đá là hình ảnh của sự vững chắc, một nơi bạn có thể đứng, nương tựa và nghỉ ngơi. Khi mọi thứ khác lung lay, Chúa vẫn là nền. Có thể niềm tin của bạn đang bị thử thách bởi những biến cố. Điều đó rất con người. Hãy nhớ rằng Chúa không hề thay đổi, và đường lối Ngài, dù đôi khi khó hiểu, luôn xuất phát từ tình yêu. Hôm nay, hãy đặt gánh nặng của mình lên hòn đá ấy, và cảm nhận sự vững chãi của Ngài.","loi_cau_nguyen":"Chúa ơi, Ngài là hòn đá vững chắc, công việc Ngài trọn vẹn. Khi mọi thứ lung lay, xin giúp con đứng vững trên Ngài và tin rằng đường lối Ngài đều ngay thẳng. A-men."},{"sach":"Phục Truyền Luật Lệ Ký","ma":"DEU","chuong":33,"cau":27,"loi_kinh_thanh":"Đức Chúa Trời hằng sống là nơi ở của ngươi, Ở dưới có cánh tay đời đời của Ngài, Ngài đuổi kẻ thù nghịch khỏi trước mặt ngươi, Và phán cùng ngươi rằng: Hãy diệt đi!","bai_hoc":"\\"Đức Chúa Trời hằng sống là nơi ở của ngươi, Ở dưới có cánh tay đời đời của Ngài, Ngài đuổi kẻ thù nghịch khỏi trước mặt ngươi, Và phán cùng ngươi rằng: Hãy diệt đi!\\" Hãy hình dung bạn như một đứa trẻ được bế trong vòng tay của cha. Dưới bạn là cánh tay đời đời, không bao giờ mỏi, không bao giờ buông. Bất cứ khi nào bạn thấy mình rơi, bạn sẽ rơi vào tay Ngài. Có thể hôm nay bạn đang rất mệt mỏi, cảm thấy mình không còn sức. Hãy thả lỏng và để Chúa nâng bạn lên. Bạn không phải tự mình giữ lấy mọi thứ. Ngài đang ôm bạn, và Ngài sẽ không bao giờ buông.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là nơi nương náu với cánh tay đời đời đỡ lấy con. Khi con mệt mỏi, xin giúp con thả lỏng và để Ngài nâng đỡ con. A-men."},{"sach":"Giô-suê","ma":"JOS","chuong":1,"cau":5,"loi_kinh_thanh":"Trót đời ngươi sống, thì chẳng sẽ ai được chống cự trước mặt ngươi. Ta sẽ ở cùng ngươi như ta đã ở cùng Môi-se; ta sẽ không lìa ngươi, không bỏ ngươi đâu.","bai_hoc":"Chúa nói với Giô-suê, người kế nhiệm Môi-se: \\"Ta sẽ ở cùng ngươi như Ta đã ở cùng Môi-se; Ta sẽ không lìa ngươi đâu.\\" Giô-suê phải bước vào chỗ của một người lãnh đạo vĩ đại, và có lẽ ông đã thấy mình nhỏ bé. Chúa không bảo ông phải cố gắng trở thành Môi-se. Ngài chỉ hứa ở cùng. Nếu hôm nay bạn đang cảm thấy mình không đủ khả năng cho vai trò mới, hãy nhớ rằng sự hiện diện của Chúa là điều làm nên khác biệt. Bạn không cần phải là ai khác, bạn chỉ cần có Ngài đồng hành.","loi_cau_nguyen":"Chúa ơi, Ngài hứa ở cùng như đã ở cùng người đi trước. Khi con thấy mình chưa đủ cho một vai trò, xin giúp con nhớ rằng sự hiện diện của Ngài là điều làm nên khác biệt. A-men."},{"sach":"Giô-suê","ma":"JOS","chuong":1,"cau":8,"loi_kinh_thanh":"Quyển sách luật pháp này chớ xa miệng ngươi, hãy suy gẫm ngày và đêm, hầu cho cẩn thận làm theo mọi điều đã chép ở trong; vì như vậy ngươi mới được may mắn trong con đường mình, và mới được phước.","bai_hoc":"\\"Quyển sách luật pháp này chớ xa miệng ngươi, hãy suy gẫm ngày và đêm.\\" Suy gẫm là chậm rãi nhai lại Lời Chúa như nhấm nháp một món ăn ngon. Giữa một thế giới nhiều tiếng ồn, việc dành thời gian ở với Lời Chúa là một món quà cho tâm hồn. Bạn không cần đọc nhiều, chỉ cần đọc sâu. Hãy chọn một câu Kinh Thánh hôm nay và mang theo nó suốt ngày: khi đi làm, khi nấu ăn, khi chờ đèn đỏ. Lời Ngài sẽ ngấm dần vào lòng bạn, dẫn dắt bạn đi trong đường lối khôn ngoan.","loi_cau_nguyen":"Chúa ơi, xin giúp con suy gẫm Lời Ngài ngày và đêm. Xin cho con mang theo một câu Kinh Thánh suốt ngày và sống theo đó, để đường lối con được khôn ngoan. A-men."},{"sach":"Giô-suê","ma":"JOS","chuong":1,"cau":9,"loi_kinh_thanh":"Ta há không có phán dặn ngươi sao? Hãy vững lòng bền chí, chớ run sợ, chớ kinh khủng; vì Giê-hô-va Đức Chúa Trời ngươi vẫn ở cùng ngươi trong mọi nơi ngươi đi.","bai_hoc":"\\"Ta há không có phán dặn ngươi sao? Hãy vững lòng bền chí, chớ run sợ, chớ kinh khủng; vì Giê-hô-va Đức Chúa Trời ngươi vẫn ở cùng ngươi trong mọi nơi ngươi đi\\" Lệnh truyền này không phải là lời quát nạt, mà là một lời khích lệ của người cha. Chúa biết Giô-suê đang sợ, và Ngài dịu dàng ở bên ông. Bạn có thể can đảm không phải vì mình mạnh, mà vì Ngài ở cùng. Hôm nay, bất kể bạn đi đâu, đến bệnh viện, đến cuộc họp, về nhà, hãy nhớ rằng Chúa đang bước cạnh bạn. Hãy đứng thẳng, hít sâu, và bước tới.","loi_cau_nguyen":"Chúa ơi, xin cho con vững lòng bền chí vì có Ngài ở cùng con mọi nơi. Xin giúp con bước vào những điều con sợ với sự tin cậy, không phải bằng sức riêng. A-men."},{"sach":"Giô-suê","ma":"JOS","chuong":24,"cau":15,"loi_kinh_thanh":"Nếu chẳng thích cho các ngươi phục sự Đức Giê-hô-va, thì ngày nay hãy chọn ai mà mình muốn phục sự, hoặc các thần mà tổ phụ các ngươi đã hầu việc bên kia sông, hoặc các thần dân A-mô-rít trong xứ mà các ngươi ở; nhưng ta và nhà ta sẽ phục sự Đức Giê-hô-va.","bai_hoc":"\\"Hãy chọn ngày nay ai mà các ngươi muốn phục sự... còn ta và nhà ta, chúng ta sẽ phục sự Đức Giê-hô-va.\\" Giô-suê không chờ ai quyết định giùm. Ông nói rõ về lựa chọn của mình và gia đình. Hôm nay, hãy nghĩ về điều bạn thật sự muốn đặt lên hàng đầu trong cuộc sống. Một quyết định đơn sơ nhưng chân thành: \\"Con chọn đi theo Chúa\\" sẽ thay đổi cách bạn sống, cách bạn đối diện khó khăn, cách bạn yêu thương. Và nếu bạn có gia đình, hãy cầu nguyện để cả nhà cùng tìm đến Ngài. Một quyết định hôm nay có thể gieo phước cho nhiều thế hệ.","loi_cau_nguyen":"Chúa ơi, hôm nay con chọn phục vụ Ngài. Xin giúp con giữ quyết định ấy trong cuộc sống hằng ngày, và dẫn cả gia đình con đến với Ngài. A-men."},{"sach":"Quan Án","ma":"JDG","chuong":6,"cau":12,"loi_kinh_thanh":"Thiên sứ của Đức Giê-hô-va hiện đến cùng người mà rằng: Hỡi người dõng sĩ! Đức Giê-hô-va ở cùng ngươi.","bai_hoc":"Ghê-đê-ôn đang trốn quân thù để đập lúa trong hầm ép rượu, và thiên sứ chào ông: Hỡi người dũng sĩ, Đức Giê-hô-va ở cùng ngươi! Ông chưa cảm thấy mình dũng cảm, nhưng Chúa đã nhìn thấy ông như vậy. Chúa thường nhìn bạn không phải bằng những gì bạn đang là, mà bằng những gì Ngài sẽ làm trong bạn. Nếu bạn thấy mình yếu đuối, sợ hãi, nhỏ bé, hãy nhớ rằng Chúa gọi bạn bằng tên mới. Hôm nay, hãy cho phép Ngài nhìn bạn như vậy: một người được Ngài đồng hành, một người có thể làm điều lớn nhờ có Ngài.","loi_cau_nguyen":"Chúa ơi, xin giúp con nhìn mình như Ngài nhìn, không phải theo nỗi sợ hay những điều con thấy mình thiếu. Xin ban cho con can đảm để làm điều Ngài gọi con làm. A-men."},{"sach":"Quan Án","ma":"JDG","chuong":21,"cau":25,"loi_kinh_thanh":"Đang lúc đó, không có vua trong Y-sơ-ra-ên; ai nấy làm theo ý mình lấy làm phải.","bai_hoc":"\\"Đang lúc đó, không có vua trong Y-sơ-ra-ên; ai nấy làm theo ý mình lấy làm phải\\" Sách Các Quan Xét kết thúc bằng một câu buồn: một dân tộc mất phương hướng khi không còn ai làm vua của lòng mình. Khi chúng ta chỉ làm theo cảm xúc hay ý riêng, chúng ta dần lạc đường. Chúa không muốn bạn mất tự do, Ngài muốn bạn tìm thấy sự bình an trong việc để Ngài làm Vua. Hôm nay, hãy thử cầu nguyện: \\"Chúa ơi, xin ngự trị trong lòng con.\\" Và để Ngài hướng dẫn những quyết định nhỏ bé nhất của bạn.","loi_cau_nguyen":"Chúa ơi, xin ngự trị trong lòng con làm Vua. Xin giúp con hỏi ý Ngài trước khi quyết định, thay vì chỉ làm theo cảm xúc hay ý riêng của con. A-men."},{"sach":"Ru-tơ","ma":"RUT","chuong":1,"cau":16,"loi_kinh_thanh":"Ru-tơ thưa rằng: Xin chớ nài tôi phân rẽ mẹ; vì mẹ đi đâu, tôi sẽ đi đó; mẹ ở nơi nào, tôi sẽ ở nơi đó. Dân sự của mẹ, tức là dân sự của tôi; Đức Chúa Trời của mẹ, tức là Đức Chúa Trời của tôi;","bai_hoc":"\\"Ru-tơ thưa rằng: Xin chớ nài tôi phân rẽ mẹ; vì mẹ đi đâu, tôi sẽ đi đó; mẹ ở nơi nào, tôi sẽ ở nơi đó. Dân sự của mẹ, tức là dân sự của tôi; Đức Chúa Trời của mẹ, tức là Đức Chúa Trời của tôi\\" Ru-tơ, người nữ góa bụa nghèo khó, chọn ở lại với Na-ô-mi khi đáng ra cô có thể quay về quê hương. Đó là một tình yêu thương trung tín, hy sinh và không cần lý do. Có ai trong đời bạn cần lòng trung thành như vậy? Một người bạn đang mệt, một người thân đang buồn? Hôm nay, hãy làm điều Ru-tơ đã làm: ở lại bên họ. Và hãy biết rằng Chúa nhìn thấy mọi hành động tử tế thầm lặng.","loi_cau_nguyen":"Chúa ơi, xin dạy con lòng trung tín như Ru-tơ. Xin giúp con ở lại bên một người đang cần con, và yêu thương họ bằng sự gắn bó và hy sinh. A-men."},{"sach":"Ru-tơ","ma":"RUT","chuong":2,"cau":12,"loi_kinh_thanh":"Nguyện Đức Giê-hô-va báo đáp điều nàng đã làm; nàng đã đến núp dưới cánh Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên; cầu xin Ngài thưởng cho nàng cách trọn vẹn.","bai_hoc":"Bô-ô nói với Ru-tơ: Nguyện Đức Giê-hô-va báo đáp việc làm của nàng... dưới cánh Ngài nàng đã đến nương náu. Ru-tơ đã làm việc vất vả, âm thầm chăm sóc mẹ chồng, và Chúa không quên điều đó. Hôm nay, có thể bạn cũng đang làm những việc lặng lẽ không ai khen: chăm sóc người thân, kiên trì ở một vị trí khó khăn. Hãy tin rằng Chúa thấy từng giọt mồ hôi và từng giọt nước mắt của bạn. Ngài sẽ ban thưởng đúng lúc, và dưới cánh Ngài, bạn luôn có chỗ ẩn náu an toàn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài thấy những việc làm thầm lặng không ai khen. Xin giúp con kiên trì làm điều tốt và nương náu dưới cánh Ngài, tin rằng Ngài sẽ ban thưởng đúng lúc. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":2,"cau":2,"loi_kinh_thanh":"Chẳng ai thánh như Đức Giê-hô-va; Chẳng có Chúa nào khác hơn Ngài! Không có hòn đá nào như Đức Chúa Trời của chúng ta.","bai_hoc":"An-ne cầu nguyện sau khi Chúa ban cho bà đứa con mà bà đã khóc xin nhiều năm: Chẳng ai thánh như Đức Giê-hô-va... chẳng có vầng đá nào như Đức Chúa Trời chúng tôi. Bà trải qua những năm tháng buồn bã, bị chế nhạo, và bây giờ bà ngợi khen. Chúa không quên những giọt nước mắt thầm lặng của bạn. Có thể điều bạn đang chờ đợi vẫn chưa đến, nhưng hãy giữ hy vọng. Ngài là vầng đá không bao giờ rung chuyển. Hôm nay, hãy trao nỗi lòng của bạn cho Ngài như An-ne, với tất cả sự thật thà.","loi_cau_nguyen":"Chúa ơi, không ai thánh như Ngài, và không có vầng đá nào như Ngài. Xin giúp con mang nỗi lòng thật của con đến với Ngài, và đặt lòng tin vào Ngài. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":3,"cau":10,"loi_kinh_thanh":"Đức Giê-hô-va đến đứng tại đó, gọi như các lần trước: Hỡi Sa-mu-ên! hỡi Sa-mu-ên! Sa-mu-ên thưa: Xin hãy phán, kẻ tôi tớ Ngài đang nghe!","bai_hoc":"Cậu bé Sa-mu-ên nằm ngủ trong đền thờ, nghe một tiếng gọi giữa đêm. Lần thứ ba, cậu đáp theo lời thầy dạy: Xin phán, vì kẻ tôi tớ Ngài đương nghe. Chúa vẫn đang nói, nhưng chúng ta thường quá bận để nghe. Hãy tạo cho mình một khoảng yên lặng hôm nay: tắt điện thoại, ngồi một góc yên tĩnh, và thầm nói như Sa-mu-ên. Có thể Chúa nói qua một câu Kinh Thánh, một ý nghĩ nhẹ nhàng, hay một sự bình an trong lòng. Điều quan trọng là bạn sẵn lòng lắng nghe, và Chúa sẽ không để bạn phải chờ đợi vô ích.","loi_cau_nguyen":"Chúa ơi, xin phán, vì con đang lắng nghe. Xin giúp con dành thời gian yên lặng để nghe tiếng Ngài, qua Lời Ngài và qua sự bình an trong lòng. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":7,"cau":12,"loi_kinh_thanh":"Bấy giờ, Sa-mu-ên lấy một hòn đá dựng lên giữa khoảng Mích-ba và Sen, đặt tên là Ê-bên-Ê-xe. Vì người nói rằng: Đức Giê-hô-va đã cứu giúp chúng tôi đến bây giờ.","bai_hoc":"Sau chiến thắng, Sa-mu-ên dựng một hòn đá và đặt tên là Ê-bên-ê-xe, nghĩa là Cho đến bây giờ Đức Giê-hô-va đã giúp đỡ chúng ta. Ông muốn nhắc dân nhớ rằng Chúa đã ở đó. Bạn cũng có thể dựng cho mình một \\"hòn đá\\" kỷ niệm: nhớ lại những lần Chúa đã cứu bạn qua cơn khó khăn. Hãy viết ra ba điều Ngài đã giúp bạn trong năm nay. Khi nhìn lại, bạn sẽ thấy lòng thành tín của Ngài. Và khi lo lắng về ngày mai, bạn sẽ nhớ rằng Đấng đã giúp bạn cho đến bây giờ cũng sẽ tiếp tục giúp bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã giúp đỡ con cho đến bây giờ. Xin giúp con nhớ lại những lần Ngài thành tín, và vững lòng bước tiếp vì biết Ngài vẫn đi cùng con. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":15,"cau":22,"loi_kinh_thanh":"Sa-mu-ên nói: Đức Giê-hô-va há đẹp lòng của lễ thiêu và của lễ thù ân bằng sự vâng theo lời phán của Ngài ư? Vả, sự vâng lời tốt hơn của tế lễ; sự nghe theo tốt hơn mỡ chiên đực;","bai_hoc":"Sau-lơ dâng của lễ thay vì vâng lời, và Sa-mu-ên nói: \\"Vâng lời tốt hơn của lễ.\\" Chúa không muốn những nghi thức bề ngoài khi lòng ta xa cách. Ngài muốn một tấm lòng sẵn sàng lắng nghe và làm theo. Có thể bạn đã dâng nhiều cho Chúa nhưng thấy lòng trống rỗng. Hôm nay, hãy hỏi Ngài: \\"Chúa ơi, Ngài muốn con làm điều gì?\\" Rồi hãy lắng nghe. Sự vâng lời không phải là gánh nặng, mà là cách thể hiện tình yêu và niềm tin. Khi bạn làm điều Chúa chỉ, lòng bạn sẽ thấy bình an hơn bất kỳ của lễ nào.","loi_cau_nguyen":"Chúa ơi, xin cho con một tấm lòng biết vâng lời, hơn là chỉ những nghi thức bên ngoài. Xin dạy con điều Ngài muốn con làm, và cho con lòng sẵn sàng đáp lại. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":16,"cau":7,"loi_kinh_thanh":"Nhưng Đức Giê-hô-va phán cùng Sa-mu-ên rằng; Chớ xem về bộ dạng và hình vóc cao lớn của nó, vì ta đã bỏ nó. Đức Giê-hô-va chẳng xem điều gì loài người xem; loài người xem bề ngoài, nhưng Đức Giê-hô-va nhìn thấy trong lòng.","bai_hoc":"Khi Sa-mu-ên đi chọn vua, ông nhìn vẻ ngoài của các con trai Y-sai. Nhưng Chúa phán: \\"Loài người xem bề ngoài, nhưng Đức Giê-hô-va nhìn thấy trong lòng.\\" Có thể bạn từng bị đánh giá bởi vẻ bề ngoài, bởi thành tích, bởi những gì bạn có hay không. Chúa nhìn bạn khác. Ngài thấy tấm lòng, những nỗ lực thầm lặng, những giọt nước mắt cầu nguyện. Hôm nay, bạn được tự do khỏi áp lực phải chứng minh mình. Hãy chăm sóc tấm lòng bạn hơn là hình ảnh bên ngoài. Và biết rằng bạn được nhìn thấy, được hiểu và được yêu.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài nhìn thấy tấm lòng con. Xin giúp con chăm sóc tấm lòng hơn hình ảnh bên ngoài, và thôi cảm thấy phải chứng minh mình với người khác. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":17,"cau":45,"loi_kinh_thanh":"Đa-vít đáp cùng người Phi-li-tin rằng: Ngươi cầm gươm, giáo, lao mà đến cùng ta; còn ta, ta nhân danh Đức Giê-hô-va vạn binh mà đến, tức là Đức Chúa Trời của đạo binh Y-sơ-ra-ên, mà ngươi đã sỉ nhục.","bai_hoc":"Đa-vít, chàng trai trẻ nhỏ bé, đối mặt với gã khổng lồ Gô-li-át và nói: Ngươi đến cùng ta bằng gươm giáo, còn ta đến cùng ngươi nhân danh Đức Giê-hô-va. Đa-vít không dựa vào sức mình, mà vào Chúa. Có thể hôm nay bạn đang đối diện với một \\"người khổng lồ\\": một khó khăn quá lớn, một nỗi sợ quá nặng. Hãy nhớ rằng bạn không phải đối mặt một mình. Chúa đứng cạnh bạn. Hãy bước ra với lòng tin, như Đa-vít, và nhận ra rằng Ngài lớn hơn mọi điều bạn sợ. Dù viên đá của bạn nhỏ bé đến đâu, trong tay Ngài nó vẫn đủ.","loi_cau_nguyen":"Chúa ơi, khi con đối diện với điều khổng lồ trong đời, xin giúp con đến với Ngài như Đa-vít, không dựa vào sức riêng. Xin nhắc con rằng Ngài lớn hơn mọi điều con sợ. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":17,"cau":47,"loi_kinh_thanh":"Khắp thế gian sẽ biết rằng Y-sơ-ra-ên có một Đức Chúa Trời; và quân lính nầy sẽ thấy rằng Đức Giê-hô-va không giải cứu bằng gươm, hoặc bằng giáo; vì Đức Giê-hô-va là Chúa của chiến trận, và Ngài sẽ phó các ngươi vào tay chúng ta.","bai_hoc":"Vì trận chiến thuộc về Đức Giê-hô-va. Đa-vít nói với sự bình tĩnh lạ lùng. Có những cuộc chiến trong đời mà bạn không thể thắng bằng sức mình: một căn bệnh, một mối quan hệ đổ vỡ, một nỗi lo kéo dài. Chúa nhắc bạn rằng bạn không cần gánh cuộc chiến ấy một mình. Hãy làm phần của bạn, cầu nguyện, kiên nhẫn, hành động tử tế, rồi để Ngài làm phần của Ngài. Hôm nay, hãy trao trận chiến của bạn cho Chúa, và để tâm hồn được nghỉ ngơi trong sự chắc chắn rằng Ngài đang chiến đấu cho bạn.","loi_cau_nguyen":"Chúa ơi, có những cuộc chiến vượt quá sức con. Xin giúp con làm phần của mình, rồi trao trận chiến cho Ngài và nghỉ ngơi trong sự tin cậy. A-men."},{"sach":"I Sa-mu-ên","ma":"1SA","chuong":30,"cau":6,"loi_kinh_thanh":"Đa-vít bị sự hoạn nạn lớn, vì dân sự toan ném đá người, bởi hết thảy đều có tâm hồn đầy cay đắng, vì cớ mất con trai và con gái mình. Nhưng Đa-vít được sức mạnh nơi Giê-hô-va Đức Chúa Trời mình.","bai_hoc":"Đa-vít bị dồn vào đường cùng: thành bị đốt, gia đình bị bắt, quân lính muốn ném đá ông. Nhưng câu Kinh Thánh nói: Đa-vít cậy Giê-hô-va Đức Chúa Trời mình mà tự làm cho mình mạnh mẽ. Khi không còn ai để dựa vào, ông tìm đến Chúa. Có những lúc bạn cảm thấy hoàn toàn một mình, không ai hiểu. Đó là lúc bạn có thể làm như Đa-vít: hướng lòng lên Chúa. Hôm nay, nếu bạn thấy kiệt sức, hãy thì thầm: \\"Chúa ơi, xin cho con sức mạnh.\\" Ngài sẽ nâng đỡ bạn, từng chút một.","loi_cau_nguyen":"Chúa ơi, khi con thấy mình đơn độc và không ai khích lệ, xin giúp con tìm sức mạnh nơi Ngài như Đa-vít. Xin nâng đỡ con và làm vững lòng con. A-men."},{"sach":"II Sa-mu-ên","ma":"2SA","chuong":1,"cau":19,"loi_kinh_thanh":"Ôi! Y-sơ-ra-ên! kẻ danh vọng của ngươi đã thác trên gò nỗng ngươi! Nhân sao các kẻ anh hùng nầy bị ngã chết?","bai_hoc":"Đa-vít viết một bài ca than khóc khi Sau-lơ và Giô-na-than ngã xuống: Hỡi Y-sơ-ra-ên, sự vinh hiển ngươi đã bị giết trên các nơi cao ngươi! Các anh hùng ngã xuống dường nào! Giữa nỗi đau mất người thân, ông không giấu giếm. Ông khóc và viết thành bài thơ. Bạn cũng được phép đau buồn khi mất đi người mình yêu. Chúa không bắt bạn phải mạnh mẽ ngay lập tức. Ngài ngồi bên bạn trong nước mắt. Hôm nay, nếu bạn đang mang nỗi đau mất mát, hãy cho mình thời gian để khóc, và biết rằng Chúa đang ôm lấy bạn.","loi_cau_nguyen":"Chúa ơi, xin ôm lấy con trong những lúc đau buồn vì mất mát. Xin cho con thời gian để khóc mà không tự trách, và an ủi con bằng sự hiện diện của Ngài. A-men."},{"sach":"II Sa-mu-ên","ma":"2SA","chuong":7,"cau":16,"loi_kinh_thanh":"Như vậy, nhà ngươi và nước ngươi được bền đổ trước mặt ngươi đời đời; ngôi ngươi sẽ được vững lập đến mãi mãi.","bai_hoc":"Chúa hứa với Đa-vít: Nhà ngươi và nước ngươi sẽ vững bền mãi mãi trước mặt ngươi. Lời hứa này vượt quá thời đại của Đa-vít, nó chỉ về Chúa Giê-su, Vua đời đời. Chúa luôn có kế hoạch lớn hơn những gì chúng ta có thể thấy. Có thể bạn đang lo lắng về tương lai, về những điều chưa chắc chắn. Hãy nhớ rằng Chúa đã dệt nên một câu chuyện lớn lao, và bạn là một phần của nó. Ngài giữ lời hứa qua nhiều thế hệ. Hôm nay, hãy tin rằng nước Ngài vững bền, và bạn thuộc về nước ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã hứa một Vua đời đời trong Chúa Giê-su. Xin giúp con yên lòng trong kế hoạch lớn lao của Ngài, và tin rằng con thuộc về nước Ngài. A-men."},{"sach":"II Sa-mu-ên","ma":"2SA","chuong":12,"cau":7,"loi_kinh_thanh":"Bấy giờ, Na-than nói cùng Đa-vít rằng: Vua là người đó! Giê-hô-va Đức Chúa Trời của Y-sơ-ra-ên có phán như vầy: Ta đã xức dầu lập ngươi làm vua Y-sơ-ra-ên, ta đã giải cứu ngươi khỏi tay Sau-lơ.","bai_hoc":"Tiên tri Na-than đến gặp Đa-vít và nói: Ngươi chính là người đó. Một câu nói thẳng và đau, nhưng được nói bằng tình yêu để đưa vua trở về. Đa-vít đã phạm tội nặng, và Chúa không bỏ mặc ông. Ngài gửi một người bạn can đảm đến để nói sự thật. Nếu hôm nay lương tâm bạn đang bất an, hãy coi đó là tiếng gọi dịu dàng của Chúa. Đừng chạy trốn. Hãy trở về với Ngài như Đa-vít đã làm. Và nếu bạn có người bạn dám nói thật với bạn, hãy biết ơn họ như một món quà quý giá.","loi_cau_nguyen":"Chúa ơi, xin cho con nghe tiếng Ngài qua lương tâm và qua những người bạn dám nói thật với con. Xin giúp con trở về với Ngài thay vì chạy trốn. A-men."},{"sach":"II Sa-mu-ên","ma":"2SA","chuong":22,"cau":2,"loi_kinh_thanh":"rằng: Đức Giê-hô-va là hòn đá và đồn lũy tôi, Đấng giải cứu tôi.","bai_hoc":"\\"rằng: Đức Giê-hô-va là hòn đá và đồn lũy tôi, Đấng giải cứu tôi\\" Đa-vít dùng nhiều hình ảnh vì ông đã trải qua nhiều hoàn cảnh: hang động, chiến trận, sự phản bội. Mỗi hình ảnh nói lên một nhu cầu: nơi vững vàng, nơi che chở, Đấng cứu giúp. Hôm nay, bạn cần Chúa là ai? Hòn đá cho tâm trí chao đảo? Đồn lũy cho lòng sợ hãi? Đấng giải cứu cho điều bạn không thể tự gỡ? Hãy gọi Ngài bằng đúng điều bạn cần, và để Ngài trở nên điều ấy cho bạn. Ngài sẵn sàng.","loi_cau_nguyen":"Chúa ơi, Ngài là hòn đá, đồn lũy và Đấng giải cứu của con. Xin trở nên điều con cần nhất hôm nay, và giúp con nương náu nơi Ngài. A-men."},{"sach":"I Các Vua","ma":"1KI","chuong":3,"cau":9,"loi_kinh_thanh":"Vậy, xin ban cho kẻ tôi tớ Chúa tấm lòng khôn sáng, để đoán xét dân sự Ngài và phân biệt điều lành điều dữ; vì ai có thể đoán xét dân rất lớn này của Chúa?","bai_hoc":"Khi Chúa hỏi Sa-lô-môn muốn xin điều gì, ông không xin giàu sang hay quyền lực, mà xin một tấm lòng khôn sáng để biết phân biệt phải trái. Lời cầu xin ấy làm Chúa vui lòng. Có thể bạn đang phải đưa ra một quyết định khó: về công việc, gia đình, hay một mối quan hệ. Đừng lo vì không biết chọn đúng. Hãy xin Chúa như Sa-lô-môn: Xin ban cho con lòng khôn ngoan. Ngài rất vui lòng ban điều ấy cho người khiêm nhường. Khôn ngoan không phải là biết mọi thứ, mà là biết dựa vào Đấng biết mọi sự.","loi_cau_nguyen":"Chúa ơi, xin ban cho con một tấm lòng khôn ngoan để phân biệt phải trái. Khi con phải quyết định điều khó, xin hướng dẫn con và cho con sự khiêm nhường để nghe Ngài. A-men."},{"sach":"I Các Vua","ma":"1KI","chuong":8,"cau":56,"loi_kinh_thanh":"Đáng khen ngợi Đức Giê-hô-va, là Đấng đã ban sự bình yên cho dân Y-sơ-ra-ên của Ngài, tùy theo các lời Ngài đã hứa! Về các lời tốt lành mà Ngài đã cậy miệng Môi-se, kẻ tôi tớ Ngài, phán ra, chẳng có một lời nào không ứng nghiệm.","bai_hoc":"Sa-lô-môn dâng đền thờ và tuyên bố: Đáng ngợi khen Đức Giê-hô-va, vì Ngài đã ban sự bình an cho dân Ngài... chẳng có một lời nào sai lạc trong mọi lời lành Ngài đã phán. Không một lời nào. Sau bao nhiêu thế kỷ chờ đợi, ông có thể nhìn lại và khẳng định như vậy. Có những lời hứa của Chúa mà bạn đang chờ ứng nghiệm. Hãy kiên nhẫn. Chúa không quên, Ngài chỉ đang làm theo thời gian của Ngài. Hôm nay, hãy nhớ lại một lời hứa Chúa đã giữ trong đời bạn, và để nó nuôi dưỡng niềm hy vọng cho điều đang chờ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng giữ trọn mọi lời hứa. Khi con chờ đợi, xin giúp con kiên nhẫn và tin rằng không một lời nào của Ngài bị bỏ sót. A-men."},{"sach":"I Các Vua","ma":"1KI","chuong":18,"cau":21,"loi_kinh_thanh":"Đoạn Ê-li đến trước mặt dân sự mà nói rằng: Các ngươi đi giẹo hai bên cho đến chừng nào? Nếu Giê-hô-va là Đức Chúa Trời, khá theo Ngài; nếu Ba-anh là Đức Chúa Trời, hãy theo hắn. Song dân sự không đáp một lời.","bai_hoc":"Ê-li đứng giữa đám đông trên núi Cạt-mên và hỏi: Các ngươi đi khập khiễng hai bên cho đến chừng nào? Dân sự đã không thể quyết định giữa Chúa và những thần khác. Có thể bạn cũng đang sống lưng chừng: một chân trong đức tin, một chân trong sự lo lắng của thế gian. Chúa không lên án, nhưng Ngài dịu dàng mời gọi bạn chọn Ngài một cách trọn vẹn. Khi bạn dứt khoát đặt lòng tin vào Chúa, bạn sẽ thấy bình an hơn, vì không còn bị giằng co. Hôm nay, hãy nói với Ngài: \\"Chúa ơi, con chọn Ngài.\\"","loi_cau_nguyen":"Chúa ơi, xin giúp con không sống lưng chừng. Hôm nay con chọn Ngài trọn vẹn, xin củng cố quyết định ấy trong lòng con và dẫn dắt con đi theo Ngài. A-men."},{"sach":"I Các Vua","ma":"1KI","chuong":19,"cau":12,"loi_kinh_thanh":"Sau cơn động đất có đám lửa; nhưng không có Đức Giê-hô-va trong đám lửa. Sau đám lửa, có một tiếng êm dịu nhỏ nhẹ.","bai_hoc":"Sau chiến thắng lớn, Ê-li kiệt sức, sợ hãi, muốn chết. Chúa không đến trong gió bão, động đất hay lửa, mà trong \\"tiếng êm dịu nhỏ nhẹ.\\" Có những lúc bạn kiệt sức, và điều bạn cần không phải tiếng ồn lớn mà là sự dịu dàng của Chúa. Ngài không quát tháo, không thúc giục. Ngài đến gần và thì thầm. Hôm nay, nếu bạn mệt mỏi, hãy tìm một nơi yên tĩnh, lắng nghe bằng cả tấm lòng. Có thể Ngài sẽ nói với bạn một lời bình an nhẹ nhàng đủ để bạn đứng dậy và tiếp tục.","loi_cau_nguyen":"Chúa ơi, khi con kiệt sức, xin cho con nghe tiếng Ngài nhẹ nhàng như tiếng êm dịu nhỏ nhẹ. Xin nâng con dậy và cho con sức để tiếp tục. A-men."},{"sach":"II Các Vua","ma":"2KI","chuong":2,"cau":11,"loi_kinh_thanh":"Hai người cứ vừa đi vừa nói với nhau, kìa, có một cái xe lửa và ngựa lửa phân rẽ hai người; Ê-li lên trời trong một cơn gió lốc.","bai_hoc":"Ê-li không chết như người thường, ông được cất lên trời trong một cỗ xe lửa. Đối với Ê-li-sê, đó là khoảnh khắc đau buồn vì mất đi người thầy, nhưng cũng là khoảnh khắc ông thấy sự vinh hiển của Chúa. Chúa có kế hoạch cho những người trung tín với Ngài, vượt ngoài những gì chúng ta hình dung. Khi bạn tiễn một người thân yêu, hãy nhớ rằng Chúa không bỏ quên họ. Hôm nay, hãy biết ơn về những người đã dẫn dắt bạn trong đức tin, và xin Chúa cho bạn tiếp nối điều tốt đẹp họ để lại.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì những người đã dẫn con đến với Ngài. Xin giúp con tiếp nối điều tốt đẹp họ để lại, và an ủi con khi con nhớ họ. A-men."},{"sach":"II Các Vua","ma":"2KI","chuong":6,"cau":16,"loi_kinh_thanh":"Ê-li-sê đáp rằng: Chớ sợ, những người ở với chúng ta đông hơn những người ở với chúng nó.","bai_hoc":"Ê-li-sê bình tĩnh nói với người đầy tớ đang hoảng sợ vì bị quân thù bao vây: Đừng sợ, vì những kẻ ở cùng chúng ta nhiều hơn những kẻ ở với chúng nó. Rồi ông cầu xin, và đôi mắt người đầy tớ mở ra, thấy núi đầy ngựa và xe lửa của Chúa. Có những lúc điều bạn thấy chỉ là khó khăn, nhưng đằng sau đó, Chúa đang bảo vệ bạn theo cách bạn chưa nhìn ra. Hôm nay, hãy cầu xin: \\"Chúa ơi, xin mở mắt đức tin của con.\\" Bạn sẽ ngạc nhiên khi thấy Ngài đã ở quanh bạn từ lâu.","loi_cau_nguyen":"Chúa ơi, xin mở mắt đức tin của con để thấy rằng những kẻ ở cùng chúng con nhiều hơn những kẻ chống lại. Xin giúp con bớt sợ hãi và tin cậy sự bảo vệ của Ngài. A-men."},{"sach":"I Lịch Sử","ma":"1CH","chuong":4,"cau":10,"loi_kinh_thanh":"Gia-bê khấn nguyện với Đức Chúa Trời của Y-sơ-ra-ên rằng: Chớ chi Chúa ban phước cho tôi, mở bờ cõi tôi rộng lớn; nguyện tay Chúa phù giúp tôi, giữ tôi được khỏi sự dữ, hầu cho tôi chẳng buồn rầu! Đức Chúa Trời bèn ban cho y như sự người cầu nguyện.","bai_hoc":"Gia-bê cầu nguyện: Ôi, chớ gì Chúa ban phước cho tôi, mở rộng địa phận tôi, tay Chúa phù hộ tôi, giữ tôi khỏi tai nạn. Một lời cầu xin đơn giản và thật thà. Và Chúa đã nhậm lời. Bạn cũng có thể cầu nguyện cách cụ thể và mạnh dạn như vậy. Chúa không chê bạn xin nhiều, Ngài vui khi con cái đến với Ngài bằng sự tin cậy. Hôm nay, hãy nói với Chúa những điều bạn mong muốn: sức khỏe, công việc, bình an cho gia đình. Ngài là Cha yêu thương, và Ngài muốn nghe tiếng bạn.","loi_cau_nguyen":"Chúa ơi, xin ban phước và bảo vệ con. Con xin Ngài một cách thật thà những điều con mong muốn, và con tin cậy ân điển của Ngài. A-men."},{"sach":"I Lịch Sử","ma":"1CH","chuong":16,"cau":11,"loi_kinh_thanh":"Phải tìm cầu Đức Giê-hô-va và sức mạnh Ngài, Phải tìm mặt Ngài luôn luôn.","bai_hoc":"\\"Phải tìm cầu Đức Giê-hô-va và sức mạnh Ngài, Phải tìm mặt Ngài luôn luôn\\" Tìm kiếm Chúa không phải là một sự kiện một lần, mà là thói quen mỗi ngày, như hít thở. Có những ngày bạn bận rộn đến mức quên mất, và có những ngày bạn thấy lòng khô khan. Nhưng chỉ cần quay đầu lại, Ngài vẫn ở đó. Hôm nay, hãy đặt một nhắc nhở nhỏ: buổi sáng, trước bữa ăn, hay trước khi ngủ, dành một phút tìm kiếm Chúa. Dần dần, thói quen ấy sẽ nuôi dưỡng tâm hồn bạn, và bạn sẽ thấy sức mạnh của Ngài.","loi_cau_nguyen":"Chúa ơi, xin cho con thói quen tìm kiếm Ngài và sức mạnh Ngài mỗi ngày. Xin giúp con dành một khoảnh khắc buổi sáng cho Ngài, dù ngắn. A-men."},{"sach":"I Lịch Sử","ma":"1CH","chuong":16,"cau":34,"loi_kinh_thanh":"Hãy cảm tạ Đức Giê-hô-va, vì Ngài là nhân từ; Sự thương xót Ngài còn đến đời đời.","bai_hoc":"\\"Hãy cảm tạ Đức Giê-hô-va, vì Ngài là nhân từ; sự thương xót Ngài còn đến đời đời.\\" Cảm tạ không đòi hỏi mọi thứ phải hoàn hảo. Nó bắt đầu khi bạn nhìn thấy sự nhân từ của Chúa, ngay cả trong những điều nhỏ bé: một bữa cơm, một giấc ngủ yên, một lời hỏi thăm. Lòng biết ơn biến những ngày bình thường thành những ngày ý nghĩa. Hôm nay, hãy viết ra ba điều bạn cảm tạ Chúa, dù chỉ là rất nhỏ. Khi bạn đếm những ơn phước, nỗi lo sẽ nhỏ lại, và niềm vui sẽ dần lớn lên.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng nhân từ, và sự thương xót Ngài còn đến đời đời. Xin giúp con thấy những điều nhỏ bé đáng biết ơn hôm nay, và nói lời cảm tạ Ngài. A-men."},{"sach":"I Lịch Sử","ma":"1CH","chuong":29,"cau":11,"loi_kinh_thanh":"Hỡi Đức Giê-hô-va sự cao cả, quyền năng, vinh quang, toàn thắng, và oai nghi đáng qui về Ngài; vì muôn vật trên các từng trời và dưới đất đều thuộc về Ngài. Đức Giê-hô-va ôi! nước thuộc về Ngài; Ngài được tôn cao làm Chúa tể của muôn vật.","bai_hoc":"Đa-vít cầu nguyện trước khi dâng của cho đền thờ: Hỡi Đức Giê-hô-va, sự cao cả, quyền năng, vinh hiển, thắng lợi và oai nghi đều thuộc về Ngài, vì mọi vật trên trời dưới đất đều thuộc về Ngài. Đây là lời nhắc nhở khiêm nhường: mọi thứ ta có đều đến từ Chúa. Khi bạn cảm thấy áp lực phải giữ chặt mọi thứ, hãy nhớ rằng tất cả đều thuộc về Ngài. Bạn chỉ là người quản lý được tin cậy. Hôm nay, hãy nới lỏng bàn tay, thở nhẹ nhàng, và dâng lại mọi điều cho Chúa.","loi_cau_nguyen":"Chúa ơi, mọi sự đều thuộc về Ngài. Xin giúp con nới lỏng bàn tay, quản lý tốt những gì Ngài giao, và sống khiêm nhường trước sự vĩ đại của Ngài. A-men."},{"sach":"II Lịch Sử","ma":"2CH","chuong":7,"cau":14,"loi_kinh_thanh":"và nhược bằng dân sự ta, là dân gọi bằng danh ta, hạ mình xuống, cầu nguyện, tìm kiếm mặt ta, và trở lại, bỏ con đường tà, thì ta ở trên trời sẽ nghe, tha thứ tội chúng nó, và cứu xứ họ khỏi tai vạ.","bai_hoc":"Chúa hứa: Nếu dân Ta, là dân được xưng bằng danh Ta, hạ mình xuống, cầu nguyện, tìm kiếm mặt Ta, và trở lại khỏi đường xấu, thì Ta sẽ nghe từ trên trời, tha tội và chữa lành đất họ. Lời hứa này bắt đầu từ chính dân Chúa, nghĩa là từ chính chúng ta. Sự đổi thay không đến từ người khác trước, mà từ tấm lòng hạ mình của chúng ta. Hôm nay, hãy cầu nguyện cho gia đình, cộng đồng và đất nước bạn. Chúa lắng nghe từng lời cầu nguyện chân thành và Ngài sẽ chữa lành.","loi_cau_nguyen":"Chúa ơi, xin giúp con hạ mình, cầu nguyện và tìm kiếm Ngài. Xin chữa lành gia đình, cộng đồng và đất nước con, bắt đầu từ chính lòng con. A-men."},{"sach":"II Lịch Sử","ma":"2CH","chuong":15,"cau":7,"loi_kinh_thanh":"Song các ngươi hãy mạnh lòng, tay các ngươi chớ nhát sợ, vì việc các ngươi làm sẽ được phần thưởng.","bai_hoc":"Tiên tri A-xa-ria nhắc vua A-sa: Còn các ngươi, hãy vững lòng, chớ để tay mình yếu đuối, vì công việc các ngươi sẽ có phần thưởng. Có những lúc bạn làm điều tốt mà không thấy kết quả: nuôi dạy con cái, phục vụ trong hội thánh, kiên nhẫn với người khó tính. Bạn thấy mệt và muốn buông bỏ. Hãy nghe lời này: đừng buông tay. Chúa thấy từng nỗ lực của bạn, và mùa gặt sẽ đến. Hôm nay, hãy hít một hơi thật sâu, nắm chặt lấy tay Chúa, và tiếp tục làm điều đúng với niềm tin rằng không điều tốt nào bị uổng phí.","loi_cau_nguyen":"Chúa ơi, khi con muốn buông tay vì mệt, xin giúp con kiên trì làm điều tốt. Xin nhắc con rằng Ngài thấy mọi nỗ lực, và mùa gặt sẽ đến đúng lúc. A-men."},{"sach":"II Lịch Sử","ma":"2CH","chuong":16,"cau":9,"loi_kinh_thanh":"Vì con mắt của Đức Giê-hô-va soi xét khắp thế gian, đặng giúp sức cho kẻ nào có lòng trọn thành đối với Ngài. Trong việc này vua có cư xử cách dại dột, nên từ này về sau vua sẽ có giặc giã.","bai_hoc":"\\"Vì con mắt của Đức Giê-hô-va soi xét khắp thế gian, đặng giúp sức cho kẻ nào có lòng trọn thành đối với Ngài. Trong việc này vua có cư xử cách dại dột, nên từ này về sau vua sẽ có giặc giã\\" Hãy hình dung đôi mắt của Chúa không đang soi xét để bắt lỗi, mà đang tìm kiếm cơ hội để giúp đỡ bạn. Ngài nhìn khắp thế gian, và Ngài dừng lại ở bạn. Bạn không phải gây sự chú ý của Ngài. Ngài luôn dõi theo bạn với tình yêu. Có thể hôm nay bạn thấy mình bé nhỏ và bị lãng quên, nhưng hãy tin rằng Chúa đang nhìn bạn và sẵn sàng nâng đỡ. Hãy mở lòng nhận lấy sự giúp đỡ của Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì mắt Ngài đang tìm cách nâng đỡ những ai có lòng trọn vẹn với Ngài. Xin giúp con mở lòng nhận sự giúp đỡ của Ngài. A-men."},{"sach":"II Lịch Sử","ma":"2CH","chuong":20,"cau":15,"loi_kinh_thanh":"mà phán rằng: Hỡi các người Giu-đa và dân cư thành Giê-ru-sa-lem, cùng vua Giô-sa-phát, hãy nghe! Đức Giê-hô-va phán cho các ngươi như vầy: Chớ sợ, chớ kinh hãi bởi cớ đám quân đông đảo này: vì trận giặc này chẳng phải của các ngươi đâu, bèn là của Đức Chúa Trời.","bai_hoc":"Vua Giê-hô-sa-phát bị ba đạo quân bao vây, ông chỉ biết cầu nguyện: Chúng tôi không biết làm sao, nhưng mắt chúng tôi ngửa trông Chúa. Và Chúa đáp qua một tiên tri: Đừng sợ hãi, vì trận này chẳng phải của các ngươi, bèn là của Đức Chúa Trời. Có những trận chiến lớn hơn khả năng của bạn. Hãy thành thật thưa với Chúa: \\"Con không biết phải làm sao.\\" Đó là lời cầu nguyện đẹp lòng Ngài. Rồi hãy tin rằng Ngài sẽ chiến đấu, và bạn có thể yên nghỉ. Hãy hát lên lời ngợi khen trước cả khi thấy kết quả, như dân sự ngày xưa đã làm.","loi_cau_nguyen":"Chúa ơi, có những lúc con không biết phải làm gì, và mắt con ngửa trông Ngài. Xin giúp con nhớ rằng trận chiến thuộc về Ngài, và chiến đấu thay con. A-men."},{"sach":"E-xơ-ra","ma":"EZR","chuong":7,"cau":10,"loi_kinh_thanh":"Vì E-xơ-ra đã định chí tra xét luật pháp của Đức Giê-hô-va, giữ làm theo, và dạy cho dân Y-sơ-ra-ên biết những luật pháp và giới mạng.","bai_hoc":"\\"Vì E-xơ-ra đã định chí tra xét luật pháp của Đức Giê-hô-va, giữ làm theo, và dạy cho dân Y-sơ-ra-ên biết những luật pháp và giới mạng\\" Hãy chú ý thứ tự: tra xét, làm theo, rồi mới dạy. Ông sống với Lời Chúa trước khi chia sẻ với người khác. Nếu bạn muốn ảnh hưởng người khác bằng đức tin, hãy bắt đầu bằng chính đời sống của mình. Không cần phải hoàn hảo, chỉ cần chân thành. Hôm nay, hãy chọn một câu Kinh Thánh và hỏi: \\"Chúa ơi, Ngài muốn con sống điều này như thế nào?\\" Rồi để Lời Ngài âm thầm thay đổi bạn từ bên trong.","loi_cau_nguyen":"Chúa ơi, xin giúp con học Lời Ngài, sống theo Lời ấy, rồi mới dạy người khác. Xin cho con bắt đầu bằng một câu Kinh Thánh và sống theo nó hôm nay. A-men."},{"sach":"Nê-hê-mi","ma":"NEH","chuong":2,"cau":18,"loi_kinh_thanh":"Tôi cũng thuật cho chúng làm sao tay nhân từ của Đức Chúa Trời tôi đã giúp đỡ tôi, và các lời vua đã nói cùng tôi. Chúng nói: Hè, ta hãy chổi dậy và xây sửa lại! Vậy, chúng được vững chắc trong ý nhất định làm công việc tốt lành này.","bai_hoc":"Khi Nê-hê-mi kể cho dân sự nghe về bàn tay nhân từ của Chúa, họ đáp: Chúng ta hãy đứng dậy và xây cất. Họ nhìn thấy những bức tường đổ nát, nhưng họ chọn bắt đầu. Có thể trong đời bạn có những \\"bức tường\\" đã đổ: một mối quan hệ, một thói quen tốt, một niềm hy vọng. Đừng nghĩ công việc quá lớn. Chúa đang ở cùng bạn, và mọi sự xây dựng đều bắt đầu từ một viên gạch nhỏ. Hôm nay, hãy chọn một việc nhỏ để bắt đầu sửa chữa, và để Chúa củng cố đôi tay bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con can đảm bắt đầu sửa chữa những điều đã đổ vỡ, dù chỉ bằng một việc nhỏ. Xin củng cố đôi tay con và đi cùng con trong công việc ấy. A-men."},{"sach":"Nê-hê-mi","ma":"NEH","chuong":8,"cau":10,"loi_kinh_thanh":"Nê-hê-mi nói với chúng rằng: Hãy đi ăn vật gì béo, uống đồ gì ngọt, và hãy gởi phần cho những người không có sắm sửa gì hết; vì ngày nay là thánh, biệt riêng ra cho Chúa của chúng ta. Chớ buồn thảm, vì sự vui vẻ của Đức Giê-hô-va là sức lực của các ngươi.","bai_hoc":"Dân sự khóc khi nghe Lời Chúa, và Nê-hê-mi dịu dàng nói: Chớ buồn rầu, vì sự vui mừng của Đức Giê-hô-va là sức mạnh của các ngươi. Niềm vui của Chúa không phải cảm xúc thoáng qua, mà là một nguồn sức lực sâu xa, vì bạn biết mình được yêu. Có những lúc bạn buồn, và điều đó không sao cả. Nhưng giữa nỗi buồn, hãy để một tia vui từ Chúa chạm vào. Hôm nay, hãy nhớ lại một ân phước Chúa đã ban, và để niềm vui ấy tiếp thêm sức cho bạn. Niềm vui ấy có thể sống cùng nước mắt, và chính nó sẽ giữ bạn đứng vững.","loi_cau_nguyen":"Chúa ơi, xin cho con niềm vui của Ngài làm sức mạnh, ngay cả khi lòng con có nỗi buồn. Xin giúp niềm vui ấy sống cùng nước mắt và giữ con đứng vững. A-men."},{"sach":"Nê-hê-mi","ma":"NEH","chuong":9,"cau":6,"loi_kinh_thanh":"Ôi! chỉ một mình Chúa là Đức Giê-hô-va có một không hai; Chúa đã dựng nên các từng trời, và trời của các từng trời, cùng toàn cơ binh của nó, trái đất và các vật ở trên nó, biển và muôn vật ở dưới nó Chúa bảo tồn những vật ấy, và cơ binh của các từng trời đều thờ lạy Chúa.","bai_hoc":"Chỉ một mình Ngài là Đức Giê-hô-va; Ngài đã làm ra các từng trời... trái đất... và Ngài gìn giữ tất cả. Khi dân sự trở về từ lưu đày, họ cầu nguyện bắt đầu bằng cách nhớ Chúa là ai. Khi tâm hồn bạn rối bời, hãy làm điều tương tự: bắt đầu bằng cách nhìn lên Ngài. Đấng dựng nên bầu trời bao la cũng chăm sóc từng chi tiết trong đời bạn. Ngài lớn hơn mọi vấn đề của bạn. Hôm nay, hãy ngước lên nhìn bầu trời, và để sự vĩ đại của Chúa làm lòng bạn nhẹ nhàng hơn.","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng dựng nên trời đất và gìn giữ tất cả. Khi lòng con rối bời, xin giúp con nhìn lên Ngài, và nhắc con rằng Ngài lớn hơn mọi vấn đề. A-men."},{"sach":"Ê-xơ-tê","ma":"EST","chuong":4,"cau":14,"loi_kinh_thanh":"vì nếu ngươi làm thinh trong lúc nầy đây, dân Giu-đa hẳn sẽ được tiếp trợ và giải cứu bởi cách khác, còn ngươi và nhà cha ngươi đều sẽ bị hư mất; song nào ai biết rằng chẳng phải vì cớ cơ hội hiện lúc nầy mà ngươi được vị hoàng hậu sao?","bai_hoc":"Mạc-đô-chê nói với Ê-xơ-tê: Biết đâu ngươi được vào ngôi hoàng hậu chính vì lúc nầy? Ê-xơ-tê sợ hãi, vì nói lên sự thật có thể phải trả giá bằng mạng sống. Nhưng ông gợi ý rằng bà ở đó vì một mục đích. Có thể bạn đang ở một vị trí nào đó, công ty, gia đình, trường học, không phải ngẫu nhiên. Chúa đặt bạn ở đó \\"vì lúc nầy.\\" Hôm nay, hãy hỏi Ngài: \\"Con ở đây để làm điều gì?\\" Và xin Ngài ban can đảm để thực hiện điều Ngài đặt trong lòng bạn. Bạn không cần thấy toàn bộ kế hoạch, chỉ cần bước đi bước đầu tiên.","loi_cau_nguyen":"Chúa ơi, xin cho con biết mình đang ở vị trí này vì mục đích gì. Xin ban cho con can đảm để làm điều Ngài đặt trong lòng con vào đúng lúc. A-men."},{"sach":"Ê-xơ-tê","ma":"EST","chuong":4,"cau":16,"loi_kinh_thanh":"Hãy đi nhóm hiệp các người Giu-đa ở tại Su-sơ, rồi hãy vì tôi mà kiêng cữ ăn trong ba ngày và đêm, chớ ăn hay uống gì hết; tôi và các nàng hầu tôi cũng sẽ kiêng cữ ăn nữa; như vậy, tôi sẽ vào cùng vua, là việc trái luật pháp; nếu tôi phải chết thì tôi chết.","bai_hoc":"Ê-xơ-tê kêu gọi mọi người cùng kiêng ăn cầu nguyện, rồi nói: \\"Nếu tôi phải chết thì tôi chết.\\" Đó không phải sự liều lĩnh, mà là lòng dũng cảm đến từ việc phó thác. Bà đã chuẩn bị bằng cầu nguyện, rồi bước ra. Đôi khi Chúa mời chúng ta làm điều khiến lòng run sợ: nói lời xin lỗi, nói sự thật, bước vào một cuộc nói chuyện khó. Hãy cầu nguyện trước, rồi tin cậy Chúa mà bước tới. Dù kết quả thế nào, bạn không bao giờ đơn độc. Hôm nay, hãy xin Ngài cho bạn lòng can đảm của Ê-xơ-tê.","loi_cau_nguyen":"Chúa ơi, khi Ngài mời con làm điều khiến con run sợ, xin giúp con cầu nguyện trước, rồi can đảm bước ra. Xin đi cùng con và ban cho con sức mạnh. A-men."},{"sach":"Gióp","ma":"JOB","chuong":1,"cau":21,"loi_kinh_thanh":"và nói rằng: Tôi trần truồng lọt khỏi lòng mẹ, và tôi cũng sẽ trần truồng mà về; Đức Giê-hô-va đã ban cho, Đức Giê-hô-va lại cất đi; đáng ngợi khen danh Đức Giê-hô-va!","bai_hoc":"Gióp mất con cái, mất của cải, mất sức khỏe, nhưng ông quỳ xuống nói: \\"Đức Giê-hô-va đã ban cho, Đức Giê-hô-va lại cất đi; đáng ngợi khen danh Đức Giê-hô-va.\\" Đây không phải sự cam chịu lạnh lùng. Đó là lời của một người đang gục ngã nhưng vẫn tìm đến Chúa. Nếu bạn đang đau buồn vì mất mát, đừng ép mình phải mạnh mẽ. Hãy cứ khóc, và hãy mang nỗi đau đến với Chúa. Ngài không bao giờ chê tiếng khóc của bạn. Hôm nay, hãy để Ngài ôm lấy bạn trong sự mất mát đó.","loi_cau_nguyen":"Chúa ơi, xin ôm lấy con trong những lúc con mất mát và đau buồn. Dù con không hiểu, xin giúp con đến với Ngài, và nhận lấy sự an ủi của Ngài. A-men."},{"sach":"Gióp","ma":"JOB","chuong":2,"cau":10,"loi_kinh_thanh":"Người đáp lại rằng: Ngươi nói như một người đàn bà ngu muội. Ủa sao! Sự phước mà tay Đức Chúa Trời ban cho chúng ta, chúng ta lãnh lấy, còn sự tai họa mà tay Ngài giáng trên chúng ta, lại chẳng lãnh lấy sao? Trong mọi việc đó, Gióp không phạm tội bởi môi miệng mình.","bai_hoc":"Vợ Gióp khuyên ông nguyền rủa Chúa rồi chết đi, nhưng Gióp đáp: Chúng ta đã nhận phước từ Đức Chúa Trời, lại không nhận lấy tai họa sao? Ông không hiểu vì sao đau khổ, nhưng ông chọn không bỏ Chúa. Đức tin chân thật không phải là đức tin chỉ vững khi mọi sự tốt đẹp. Nó là khi bạn nắm tay Chúa trong đêm tối dù chưa thấy ánh sáng. Nếu hôm nay bạn đang trải qua điều không hiểu nổi, hãy thành thật thưa với Chúa, và đừng buông tay Ngài. Ngài vẫn đang nắm tay bạn.","loi_cau_nguyen":"Chúa ơi, khi con không hiểu điều xảy ra, xin giúp con không buông tay Ngài. Xin giữ con vững vàng trong đức tin, và ở bên con cả trong đêm tối. A-men."},{"sach":"Gióp","ma":"JOB","chuong":13,"cau":15,"loi_kinh_thanh":"Dẫu Chúa giết ta, ta cũng còn nhờ cậy nơi Ngài; Nhưng ta sẽ binh vực tánh hạnh ta trước mặt Ngài.","bai_hoc":"\\"Dẫu Chúa giết ta, ta cũng còn nhờ cậy nơi Ngài; Nhưng ta sẽ binh vực tánh hạnh ta trước mặt Ngài\\" Đây là lời của một người đau đớn, bối rối, và vẫn chọn tin. Gióp không giả vờ ổn. Ông còn tranh luận, thắc mắc với Chúa. Nhưng niềm tin của ông giống như sợi dây không đứt. Có thể hôm nay bạn không hiểu vì sao điều ấy xảy ra, và lòng bạn đầy câu hỏi. Chúa không giận bạn vì những câu hỏi đó. Hãy cứ hỏi, cứ bày tỏ, nhưng đừng buông tay Ngài. Có những lúc đức tin chỉ là nói: \\"Chúa ơi, con vẫn trông cậy Ngài.\\"","loi_cau_nguyen":"Chúa ơi, khi lòng con đầy câu hỏi, xin giúp con vẫn chọn tin cậy Ngài. Con có thể thành thật nói với Ngài mọi điều, xin lắng nghe và giữ đức tin con không đứt. A-men."},{"sach":"Gióp","ma":"JOB","chuong":14,"cau":1,"loi_kinh_thanh":"Loài người bởi người nữ sanh ra, sống tạm ít ngày, Bị đầy dẫy sự khốn khổ.","bai_hoc":"\\"Loài người bởi người nữ sanh ra, sống tạm ít ngày, Bị đầy dẫy sự khốn khổ\\" Gióp nói thẳng thắn về sự mong manh của kiếp người, không tô vẽ gì cả. Kinh Thánh cho phép chúng ta thành thật về nỗi buồn và sự mệt mỏi của cuộc sống. Chúa không bắt bạn phải luôn lạc quan. Ngài mời bạn mang cả những tiếng thở dài đến với Ngài. Nếu hôm nay bạn thấy cuộc sống quá nặng nề, hãy nói thật với Chúa. Ngài lắng nghe, và Ngài hiểu. Sự thành thật là bước đầu tiên của sự chữa lành, và Chúa luôn dang tay đón bạn.","loi_cau_nguyen":"Chúa ơi, khi cuộc sống quá nặng nề, xin giúp con thành thật nói với Ngài. Xin lắng nghe, hiểu và nâng đỡ con, và cho con sức mạnh để tiếp tục. A-men."},{"sach":"Gióp","ma":"JOB","chuong":19,"cau":25,"loi_kinh_thanh":"Còn tôi, tôi biết rằng Đấng cứu chuộc tôi vẫn sống, Đến lúc cuối cùng Ngài sẽ đứng trên đất.","bai_hoc":"Giữa lúc mọi thứ sụp đổ, Gióp thốt lên một lời đầy hy vọng: \\"Tôi biết rằng Đấng Cứu Chuộc tôi vẫn sống.\\" Từ đáy sâu của đau khổ, ông nhìn thấy một tia sáng: sẽ có một Đấng bênh vực ông, và cái chết không phải là kết thúc. Lời này ngày nay chỉ về Chúa Giê-su, Đấng sống lại, Đấng cứu chuộc chúng ta. Dù bạn đang đi qua thung lũng nào, hãy nhớ rằng bạn có một Đấng Cứu Chuộc hằng sống. Ngài đang ở đó, và Ngài sẽ có tiếng nói cuối cùng. Hãy giữ lấy hy vọng ấy hôm nay.","loi_cau_nguyen":"Chúa ơi, con tin Ngài là Đấng Cứu Chuộc hằng sống. Xin giữ hy vọng ấy trong lòng con, kể cả khi mọi thứ xung quanh tối tăm. A-men."},{"sach":"Gióp","ma":"JOB","chuong":23,"cau":10,"loi_kinh_thanh":"Nhưng Chúa biết con đường tôi đi; Khi Ngài đã thử rèn tôi, tôi sẽ ra như vàng.","bai_hoc":"\\"Nhưng Chúa biết con đường tôi đi; Khi Ngài đã thử rèn tôi, tôi sẽ ra như vàng\\" Gióp không thấy Chúa, nhưng ông tin rằng Chúa thấy ông. Giống như người thợ vàng đặt kim loại vào lửa để làm sạch tạp chất, Chúa có thể dùng những thử thách để làm cho đức tin bạn tinh khiết hơn. Điều đó không làm nỗi đau bớt thật, nhưng cho nó một ý nghĩa. Nếu bạn đang ở trong \\"lò lửa\\", hãy nhớ rằng Chúa ngồi canh bên cạnh, và Ngài sẽ không để lửa cháy quá mức cần thiết. Bạn sẽ ra khỏi đó, trong sáng như vàng.","loi_cau_nguyen":"Chúa ơi, xin ở bên con trong những thử thách, và dùng chúng để làm đức tin con tinh khiết như vàng. Xin giữ con khỏi nản lòng, vì Ngài biết đường con đi. A-men."},{"sach":"Gióp","ma":"JOB","chuong":28,"cau":28,"loi_kinh_thanh":"Đoạn, phán với loài người rằng: Kính sợ Chúa, ấy là sự khôn ngoan; Tránh khỏi điều ác, ấy là sự thông sáng.","bai_hoc":"\\"Đoạn, phán với loài người rằng: Kính sợ Chúa, ấy là sự khôn ngoan; Tránh khỏi điều ác, ấy là sự thông sáng\\" Sau một bài thơ dài về việc con người không thể tìm ra sự khôn ngoan bằng sức mình, Gióp kết luận: khôn ngoan bắt đầu từ việc kính sợ Chúa. Không phải sợ hãi, mà là yêu mến và tôn trọng Ngài. Khi bạn đặt Chúa ở vị trí đúng trong lòng, những quyết định của bạn sẽ có nền tảng vững chắc. Hôm nay, trước khi chọn làm điều gì, hãy dừng lại một chút và hỏi: \\"Chúa ơi, điều này có làm Ngài vui lòng không?\\" Đó là khởi đầu của sự khôn ngoan.","loi_cau_nguyen":"Chúa ơi, xin cho con lòng kính sợ Ngài là khởi đầu của sự khôn ngoan. Xin giúp con hỏi ý Ngài trước khi quyết định, và tránh xa điều ác. A-men."},{"sach":"Gióp","ma":"JOB","chuong":38,"cau":4,"loi_kinh_thanh":"Khi ta đặt nền trái đất, thì ngươi ở đâu? Nếu ngươi thông sáng, hãy tỏ bày đi.","bai_hoc":"Sau nhiều chương chờ đợi, Chúa lên tiếng từ cơn gió lốc và hỏi Gióp: Khi Ta đặt nền trái đất, ngươi ở đâu? Chúa không giải thích lý do đau khổ, nhưng Ngài mời Gióp ngước nhìn sự vĩ đại của Ngài. Đôi khi, câu trả lời cho nỗi đau không phải là một lời giải thích, mà là sự hiện diện của Chúa. Bạn không cần hiểu hết, chỉ cần biết Ai đang cầm giữ mọi sự. Hôm nay, hãy ngước nhìn bầu trời và nhắc lòng mình: Đấng dựng nên tất cả này cũng đang quan tâm đến bạn.","loi_cau_nguyen":"Chúa ơi, Ngài lớn hơn mọi điều con không hiểu. Xin giúp con ngước nhìn sự vĩ đại của Ngài, và yên lòng khi con nhớ rằng Ngài đang cầm giữ mọi sự. A-men."},{"sach":"Gióp","ma":"JOB","chuong":42,"cau":2,"loi_kinh_thanh":"Tôi biết rằng Chúa có thể làm được mọi sự, Chẳng có ý chỉ nào Chúa lấy làm khó lắm.","bai_hoc":"Sau khi gặp Chúa, Gióp nói: \\"Tôi biết Chúa có thể làm mọi sự, và không có ý chỉ nào Ngài làm không được.\\" Sau tất cả đau khổ, kết luận của ông không phải là câu trả lời cho mọi thắc mắc, mà là lòng tin rằng Chúa lớn hơn mọi điều ông gặp phải. Khi bạn không còn chịu đựng nổi, hãy nhớ rằng không có điều gì ngoài khả năng của Ngài. Hôm nay, hãy trao cho Chúa điều bạn không thể giải quyết, và nghỉ ngơi. Ngài vẫn đang làm việc, dù bạn không thấy. Hãy để lòng mình thôi cố gắng kiểm soát, và tin rằng chương cuối của câu chuyện đang ở trong bàn tay yêu thương.","loi_cau_nguyen":"Chúa ơi, con tin Ngài làm được mọi sự. Xin giúp con trao lại cho Ngài những điều con không giải quyết nổi, và nghỉ ngơi trong sự tin cậy. A-men."},{"sach":"Gióp","ma":"JOB","chuong":42,"cau":5,"loi_kinh_thanh":"Trước lỗ tai tôi có nghe đồn về Chúa, Nhưng bây giờ, mắt tôi đã thấy Ngài:","bai_hoc":"\\"Trước lỗ tai tôi có nghe đồn về Chúa, Nhưng bây giờ, mắt tôi đã thấy Ngài\\" Sau cơn đau dài, Gióp không chỉ biết về Chúa, mà ông đã gặp Chúa. Đôi khi, những mùa khó khăn nhất lại là lúc chúng ta biết Chúa sâu nhất. Không phải vì đau khổ là tốt, nhưng vì Ngài ở đó với chúng ta. Nếu bạn đang đi qua một mùa tối tăm, hãy giữ lòng mở. Có thể Chúa đang chuẩn bị cho bạn một cuộc gặp gỡ riêng, nơi bạn không chỉ nghe về Ngài, mà thật sự thấy và biết Ngài.","loi_cau_nguyen":"Chúa ơi, con không chỉ muốn nghe về Ngài, con muốn gặp Ngài. Xin tỏ mình ra cho con, kể cả trong những mùa khó khăn, để đức tin con trở nên sâu sắc hơn. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":1,"cau":1,"loi_kinh_thanh":"Phước cho người nào chẳng theo mưu kế của kẻ dữ, Chẳng đứng trong đường tội nhân, Không ngồi chỗ của kẻ nhạo báng;","bai_hoc":"\\"Phước cho người nào chẳng theo mưu kế của kẻ dữ, Chẳng đứng trong đường tội nhân, Không ngồi chỗ của kẻ nhạo báng\\" Thi Thiên mở đầu bằng một lời chúc phước, không phải một lời cảnh cáo. Chúa muốn bạn được hạnh phúc, và Ngài chỉ cho bạn con đường dẫn đến đó. Những lời bạn nghe mỗi ngày, những người bạn dành thời gian ở cùng, đều đang định hình tấm lòng bạn. Hãy chọn những tiếng nói nuôi dưỡng đức tin, và chọn những người cùng bạn đi gần Chúa hơn. Không phải để xa lánh ai, mà để giữ cho tâm hồn mình được bình yên. Hôm nay, hãy tự hỏi: ai và điều gì đang ảnh hưởng đến tôi nhiều nhất?","loi_cau_nguyen":"Chúa ơi, xin giúp con chọn những lời nói và những người nuôi dưỡng đức tin con. Xin cho con biết tránh xa điều làm lòng con xa Ngài, và dẫn con vào đường lối của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":1,"cau":3,"loi_kinh_thanh":"Người ấy sẽ như cây trồng gần dòng nước, Sanh bông trái theo thì tiết, Lá nó cũng chẳng tàn héo; Mọi sự người làm đều sẽ thạnh vượng.","bai_hoc":"\\"Người ấy sẽ như cây trồng gần dòng nước, Sanh bông trái theo thì tiết, Lá nó cũng chẳng tàn héo; Mọi sự người làm đều sẽ thạnh vượng\\" Hãy hình dung một cây xanh tốt bên dòng suối, không lo hạn hán, không sợ nắng nóng, vì rễ nó luôn tìm thấy nước. Lời Chúa là dòng nước ấy cho linh hồn bạn. Có những mùa bạn thấy chưa kết trái, đừng nản lòng, vì cây cần thời gian để lớn. Điều quan trọng là rễ của bạn có đang ở nơi nguồn sống không. Hôm nay, hãy dành vài phút ngồi bên dòng nước của Lời Ngài, và để rễ đức tin của bạn thấm sâu hơn một chút.","loi_cau_nguyen":"Chúa ơi, xin cho rễ đức tin con ăn sâu vào Lời Ngài như cây bên dòng nước. Xin giúp con dành thời gian đọc Kinh Thánh, và kết quả trong mùa Ngài định. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":4,"cau":8,"loi_kinh_thanh":"Hỡi Đức Giê-hô-va, tôi sẽ nằm và ngủ bình an; Vì chỉ một mình Ngài làm cho tôi được ở yên ổn.","bai_hoc":"\\"Hỡi Đức Giê-hô-va, tôi sẽ nằm và ngủ bình an; Vì chỉ một mình Ngài làm cho tôi được ở yên ổn\\" Đa-vít viết những lời này giữa lúc bị truy đuổi, nhưng ông vẫn ngủ yên. Bạn có những đêm trằn trọc, đầu óc không ngừng nghĩ về ngày mai? Chúa mời bạn đặt mọi lo lắng xuống trước khi nhắm mắt. Hãy nói với Ngài từng điều khiến bạn bất an, rồi tin rằng Ngài thức canh giữ bạn. Bạn không cần tự giữ cho cả thế giới này. Tối nay, hãy ngủ với bàn tay Chúa trên vai bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con đặt mọi lo lắng xuống trước khi ngủ. Xin giữ con bình an và cho con tin rằng chỉ mình Ngài khiến con ở yên ổn. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":8,"cau":4,"loi_kinh_thanh":"Loài người là gì, mà Chúa nhớ đến? Con loài người là chi, mà Chúa thăm viếng nó?","bai_hoc":"\\"Loài người là gì, mà Chúa nhớ đến? Con loài người là chi, mà Chúa thăm viếng nó?\\" Đa-vít ngước nhìn bầu trời đầy sao và thấy mình thật nhỏ bé. Nhưng điều làm ông kinh ngạc là: Đấng tạo ra những vì sao ấy lại nhớ đến ông. Hôm nay, có thể bạn thấy mình không quan trọng, như một hạt cát giữa muôn vàn điều lớn lao. Hãy nhớ rằng bạn nằm trong tâm trí của Đức Chúa Trời. Ngài biết tên bạn, biết nỗi lo của bạn, và Ngài yêu bạn. Nhỏ bé không có nghĩa là bị lãng quên. Tối nay, hãy ngước nhìn bầu trời và nói lời cảm ơn.","loi_cau_nguyen":"Chúa ơi, con nhỏ bé nhưng Ngài vẫn nhớ đến con. Xin giúp con tin rằng mình luôn nằm trong tâm trí của Ngài, và thôi nghĩ rằng mình bị lãng quên. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":16,"cau":11,"loi_kinh_thanh":"Chúa sẽ chỉ cho tôi biết con đường sự sống; Trước mặt Chúa có trọn sự khoái lạc, Tại bên hữu Chúa có điều vui sướng vô cùng.","bai_hoc":"\\"Chúa sẽ chỉ cho tôi biết con đường sự sống; Trước mặt Chúa có trọn sự khoái lạc, Tại bên hữu Chúa có điều vui sướng vô cùng\\" Niềm vui sâu xa không đến từ việc có mọi thứ, mà từ việc ở gần Chúa. Có những ngày bạn tìm niềm vui ở nhiều nơi: điện thoại, công việc, mua sắm, và rồi vẫn thấy trống trải. Hãy thử chuyển hướng đến Chúa, dù chỉ năm phút yên lặng. Ở đó có một niềm vui khác, bền hơn, dịu dàng hơn. Ngài không chỉ chỉ đường, Ngài ở cùng bạn trên con đường ấy. Hôm nay, hãy tìm một khoảnh khắc ở bên Chúa, và để niềm vui của Ngài thấm vào lòng bạn.","loi_cau_nguyen":"Chúa ơi, xin chỉ cho con đường sự sống. Xin giúp con tìm niềm vui trong sự hiện diện của Ngài, và dành thời gian yên lặng bên Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":18,"cau":2,"loi_kinh_thanh":"Đức Giê-hô-va là hòn đá tôi, đồn lũy tôi, Đấng giải cứu tôi; Đức Chúa Trời là hòn đá tôi, nơi Ngài tôi sẽ nương náu mình; Ngài cũng là cái khiên tôi, sừng cứu rỗi tôi, và là nơi náu ẩn cao của tôi.","bai_hoc":"\\"Đức Giê-hô-va là hòn đá tôi, đồn lũy tôi, Đấng giải cứu tôi; Đức Chúa Trời là hòn đá tôi, nơi Ngài tôi sẽ nương náu mình; Ngài cũng là cái khiên tôi, sừng cứu rỗi tôi, và là nơi náu ẩn cao của tôi\\" Đa-vít dùng nhiều hình ảnh vì ông biết mỗi hoàn cảnh cần một nơi nương náu khác nhau. Khi lo sợ, Chúa là đồn lũy. Khi chao đảo, Chúa là hòn đá. Khi bị dồn ép, Chúa là Đấng giải cứu. Hôm nay, bạn cần Chúa là điều gì? Hãy gọi Ngài bằng chính nhu cầu đó, và để Ngài trở thành điều ấy cho bạn. Bạn không cần phải mạnh mẽ, vì bạn có một nơi trú ẩn luôn mở cửa chờ bạn.","loi_cau_nguyen":"Chúa ơi, Ngài là hòn đá, đồn lũy và Đấng giải cứu của con. Xin giúp con nương náu nơi Ngài trong những lúc cần, và trở nên điều con cần nhất lúc này. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":19,"cau":1,"loi_kinh_thanh":"Các từng trời rao truyền sự vinh hiển của Đức Chúa Trời, Bầu trời giải tỏ công việc tay Ngài làm.","bai_hoc":"\\"Các từng trời rao truyền sự vinh hiển của Đức Chúa Trời, Bầu trời giải tỏ công việc tay Ngài làm\\" Mỗi buổi sáng, bình minh là một lời nói thầm của Chúa dành cho bạn. Bạn không cần nghe bằng tai, chỉ cần dừng lại và nhìn. Có khi chúng ta quá bận rộn để ngước lên. Hôm nay, hãy dành một chút thời gian đứng trước cửa sổ, hoặc bước ra ngoài, nhìn bầu trời. Hãy để vẻ đẹp ấy nhắc bạn rằng có một Đấng đang yêu thương thế giới này, và bạn là một phần quý giá của nó. Lòng bạn sẽ dịu lại ngay.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về vẻ đẹp của tạo vật. Xin giúp con dừng lại, ngước nhìn bầu trời và để lòng con thờ phượng Ngài vì sự vĩ đại của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":19,"cau":14,"loi_kinh_thanh":"Hỡi Đức Giê-hô-va là hòn đá tôi, và là Đấng cứu chuộc tôi, Nguyện lời nói của miệng tôi, Sự suy gẫm của lòng tôi được đẹp ý Ngài!","bai_hoc":"\\"Hỡi Đức Giê-hô-va là hòn đá tôi, và là Đấng cứu chuộc tôi, Nguyện lời nói của miệng tôi, Sự suy gẫm của lòng tôi được đẹp ý Ngài!\\" Đây là lời cầu nguyện đẹp nhất để bắt đầu một ngày. Nó xin Chúa trông coi cả lời nói và những suy nghĩ thầm kín của bạn. Có những ngày bạn nói điều không nên nói, nghĩ điều không muốn nghĩ. Hãy xin Ngài giúp bạn. Chúa không đòi bạn hoàn hảo, nhưng Ngài sẵn lòng làm mới tấm lòng bạn. Hôm nay, hãy thì thầm lời cầu nguyện này trước khi bước ra khỏi nhà.","loi_cau_nguyen":"Chúa ơi, xin canh giữ lời nói và những suy nghĩ của con hôm nay. Xin giúp con nói và nghĩ điều đẹp lòng Ngài, vì Ngài là hòn đá và Đấng cứu chuộc con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":20,"cau":7,"loi_kinh_thanh":"Kẻ nầy nhờ cậy xe cộ, kẻ khác nhờ cậy ngựa, Nhưng chúng tôi nhờ cậy danh Giê-hô-va, là Đức Chúa Trời chúng tôi.","bai_hoc":"\\"Kẻ nầy nhờ cậy xe cộ, kẻ khác nhờ cậy ngựa, Nhưng chúng tôi nhờ cậy danh Giê-hô-va, là Đức Chúa Trời chúng tôi\\" Mỗi người đều có điều mình dựa vào: tiền bạc, bằng cấp, các mối quan hệ, sức khỏe. Những điều ấy không xấu, nhưng chúng có thể lung lay. Chúa mời bạn đặt niềm tin sâu nhất ở nơi Ngài, là Đấng không bao giờ đổi thay. Hôm nay, hãy hỏi lòng mình: tôi đang thật sự nhờ cậy điều gì? Rồi dịu dàng chuyển lòng tin của bạn về phía Chúa. Khi chiếc xe và con ngựa lung lay, tên của Ngài vẫn đứng vững.","loi_cau_nguyen":"Chúa ơi, xin giúp con đặt lòng tin vào danh Ngài, hơn là vào tiền bạc, bằng cấp hay người khác. Khi những điều ấy lung lay, xin giữ con vững trong Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":22,"cau":1,"loi_kinh_thanh":"Đức Chúa Trời tôi ôi! Đức Chúa Trời tôi ôi! sao Ngài lìa bỏ tôi? Nhân sao Ngài đứng xa, không giúp đỡ tôi, và chẳng nghe lời rên siếc tôi?","bai_hoc":"\\"Đức Chúa Trời tôi ôi! Đức Chúa Trời tôi ôi! sao Ngài lìa bỏ tôi? Nhân sao Ngài đứng xa, không giúp đỡ tôi, và chẳng nghe lời rên siếc tôi?\\" Chúa Giê-su đã thốt lên lời này trên thập tự giá. Điều đó có nghĩa là Chúa hiểu cảm giác bị bỏ rơi, hiểu nỗi đau tận cùng. Bạn không cần giả vờ ổn khi cầu nguyện. Kinh Thánh cho phép bạn kêu lên, hỏi, than thở. Nếu hôm nay bạn đang cảm thấy Chúa xa cách, hãy nhớ rằng chính Con Ngài đã đi qua nơi đó vì bạn. Và bài Thi Thiên này kết thúc trong hy vọng. Đêm tối không kéo dài mãi, Chúa vẫn ở gần.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì Chúa Giê-su đã đi qua nỗi đau bị bỏ rơi vì con. Khi con thấy Ngài xa cách, xin nhắc con rằng Ngài hiểu con, và ở gần con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":1,"loi_kinh_thanh":"Đức Giê-hô-va là Đấng chăn giữ tôi: tôi sẽ chẳng thiếu thốn gì.","bai_hoc":"\\"Đức Giê-hô-va là Đấng chăn giữ tôi, tôi sẽ chẳng thiếu thốn gì.\\" Hãy chậm rãi đọc câu này. Chiên không phải tự tìm cỏ, tự canh sói, tự tìm đường về. Chúng chỉ cần đi theo người chăn. Bạn cũng vậy. Có những ngày bạn thấy mình phải lo cho tất cả, và quên mất rằng mình có một Người Chăn Hiền Lành. Ngài biết bạn cần gì trước khi bạn xin. Hôm nay, hãy buông bớt gánh lo, thả lỏng đôi vai, và nhớ rằng bạn là chiên của Ngài, được yêu thương, được dẫn dắt, và không thiếu thốn điều cần thiết.","loi_cau_nguyen":"Chúa ơi, Ngài là Đấng chăn dắt con. Xin giúp con buông bớt gánh lo, và tin rằng Ngài biết con cần gì trước khi con xin. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":2,"loi_kinh_thanh":"Ngài khiến tôi an nghỉ nơi đồng cỏ xanh tươi, Dẫn tôi đến mé nước bình tịnh.","bai_hoc":"\\"Ngài khiến tôi an nghỉ nơi đồng cỏ xanh tươi, Dẫn tôi đến mé nước bình tịnh\\" Người chăn dẫn chiên đến nơi nghỉ ngơi. Chúa cũng biết bạn cần những khoảng lặng, những lúc nghỉ ngơi cho thân và hồn. Có thể bạn đang chạy hết tốc lực, cảm thấy không dám dừng lại. Hãy nghe tiếng Chúa nhẹ nhàng: \\"Con hãy nằm xuống.\\" Nghỉ ngơi không phải là yếu đuối, mà là một cách tin cậy. Hôm nay, hãy tìm cho mình một khoảng lặng bên dòng nước bình tịnh của Chúa: năm phút, mười phút, nhắm mắt lại và thở. Ngài đang ở đó.","loi_cau_nguyen":"Chúa ơi, xin dẫn con đến chỗ nghỉ ngơi bên mé nước bình tịnh. Xin giúp con dừng lại, hít thở, và nhận lấy sự nghỉ ngơi Ngài ban cho. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":3,"loi_kinh_thanh":"Ngài bổ lại linh hồn tôi, Dẫn tôi vào các lối công bình, vì cớ danh Ngài.","bai_hoc":"\\"Ngài bổ lại linh hồn tôi, Dẫn tôi vào các lối công bình, vì cớ danh Ngài\\" Linh hồn cũng cần được chữa lành, như thân thể sau cơn bệnh. Có thể bạn đã mệt mỏi, kiệt quệ, bị tổn thương. Chúa không bảo bạn phải tự chữa. Chính Ngài đến bổ lại, từng chút một, bằng sự dịu dàng và kiên nhẫn. Ngài cũng dẫn bạn đi, không để bạn lạc lối. Hôm nay, nếu bạn thấy lòng mình mỏi mệt, hãy thì thầm: \\"Chúa ơi, xin phục hồi linh hồn con.\\" Ngài sẽ làm điều ấy, không vội vàng, nhưng chắc chắn, bằng tình yêu của một Đấng Chăn Hiền Lành.","loi_cau_nguyen":"Chúa ơi, xin phục hồi linh hồn con. Xin dẫn con vào đường công bình, và chữa lành con từng chút một bằng sự dịu dàng và kiên nhẫn của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":4,"loi_kinh_thanh":"Dầu khi tôi đi trong trũng bóng chết, Tôi sẽ chẳng sợ tai họa nào; vì Chúa ở cùng tôi; Cây trượng và cây gậy của Chúa an ủi tôi.","bai_hoc":"\\"Dầu khi tôi đi trong trũng bóng chết, Tôi sẽ chẳng sợ tai họa nào; vì Chúa ở cùng tôi; Cây trượng và cây gậy của Chúa an ủi tôi\\" Chú ý nhé: Chúa không hứa bạn sẽ không đi qua thung lũng. Ngài hứa Ngài ở cùng bạn khi đi qua. Có thể bạn đang ở một thung lũng: bệnh tật, mất mát, tuyệt vọng. Bạn không cô đơn. Cây gậy và cây trượng của Ngài ở bên bạn, vừa để dẫn dắt vừa để bảo vệ. Khi bóng tối bao quanh, hãy nắm lấy tay Chúa. Hôm nay, hãy thì thầm: \\"Con không sợ, vì Chúa ở cùng con.\\" Dần dần, bạn sẽ thấy ánh sáng ở cuối đường.","loi_cau_nguyen":"Chúa ơi, khi con đi qua những thung lũng tối, xin nhắc con rằng Ngài ở cùng con. Xin cho gậy và trượng của Ngài dẫn dắt và an ủi con, để con không sợ hãi. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":5,"loi_kinh_thanh":"Chúa dọn bàn cho tôi Trước mặt kẻ thù nghịch tôi; Chúa xức dầu cho đầu tôi, Chén tôi đầy tràn.","bai_hoc":"\\"Chúa dọn bàn cho tôi Trước mặt kẻ thù nghịch tôi; Chúa xức dầu cho đầu tôi, Chén tôi đầy tràn\\" Ngay giữa chiến trận, Chúa dọn một bàn tiệc cho bạn. Không phải sau khi mọi thứ kết thúc, mà ngay lúc này. Dù bạn đang đối diện với những điều làm lòng lo sợ, Chúa vẫn muốn đãi bạn bằng sự ân cần và dư dật. Chén của bạn đầy tràn, nghĩa là Ngài ban nhiều hơn bạn cần. Hôm nay, hãy dừng lại và thật sự nhận lấy: một bữa ăn ấm, một lời tử tế, một khoảnh khắc bình yên. Đó là bàn tiệc Chúa dọn cho bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài dọn bàn cho con ngay cả giữa khó khăn. Xin giúp con nhận lấy sự ân cần và dư dật Ngài ban, và thôi để nỗi sợ chiếm hết tâm trí con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":23,"cau":6,"loi_kinh_thanh":"Quả thật, trọn đời tôi Phước hạnh và sự thương xót sẽ theo tôi; Tôi sẽ ở trong nhà Đức Giê-hô-va Cho đến lâu dài.","bai_hoc":"\\"Quả thật, trọn đời tôi Phước hạnh và sự thương xót sẽ theo tôi; Tôi sẽ ở trong nhà Đức Giê-hô-va Cho đến lâu dài\\" Hãy tưởng tượng sự nhân từ và lòng thương xót của Chúa đi theo sau bạn như hai người bạn trung thành, không rời, bất kể bạn đi đâu. Ngay cả khi bạn không nhận ra, họ vẫn ở đó. Cuối đường, bạn sẽ ở trong nhà Chúa mãi mãi. Đó là kết thúc đẹp của câu chuyện đời bạn. Dù hôm nay bạn gặp điều gì, hãy nhớ rằng bạn không bước đi trong đơn độc. Hãy để lòng bạn nhẹ nhàng đón nhận lời hứa này, và cảm ơn Chúa vì tình thương đi theo bạn từng ngày.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì nhân từ và thương xót luôn theo con. Xin giúp con nhớ điều ấy khi con lo âu, và hướng lòng con về nhà Ngài đời đời. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":24,"cau":1,"loi_kinh_thanh":"Đất và muôn vật trên đất, Thế gian và những kẻ ở trong đó, đều thuộc về Đức Giê-hô-va.","bai_hoc":"\\"Đất và muôn vật trên đất, Thế gian và những kẻ ở trong đó, đều thuộc về Đức Giê-hô-va\\" Mọi thứ đều thuộc về Chúa, kể cả những điều bạn đang giữ chặt. Điều đó có thể làm lòng bạn nhẹ đi: bạn không phải là chủ sở hữu, mà là người quản lý. Những lo lắng về tiền bạc, tương lai, con cái, đều có thể được trao cho Chủ thật của mọi sự. Hôm nay, hãy nhìn quanh những gì bạn có, nhà cửa, người thân, công việc, và thầm nói: \\"Tất cả là của Chúa.\\" Bạn sẽ thấy lòng mình bớt căng thẳng, và biết ơn nhiều hơn.","loi_cau_nguyen":"Chúa ơi, đất và mọi vật trong đó đều thuộc về Ngài. Xin giúp con buông bớt sự lo lắng về những điều con đang giữ chặt, và quản lý chúng như người được Ngài giao phó. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":27,"cau":1,"loi_kinh_thanh":"Đức Giê-hô-va là ánh sáng và là sự cứu rỗi tôi: Tôi sẽ sợ ai? Đức Giê-hô-va là đồn lũy của mạng sống tôi: Tôi sẽ hãi hùng ai?","bai_hoc":"\\"Đức Giê-hô-va là ánh sáng và là sự cứu rỗi tôi: Tôi sẽ sợ ai? Đức Giê-hô-va là đồn lũy của mạng sống tôi: Tôi sẽ hãi hùng ai?\\" Nỗi sợ thường lớn nhất khi chúng ta ở trong bóng tối. Nhưng khi ánh sáng bật lên, mọi thứ trở nên rõ ràng và bớt đáng sợ. Chúa là ánh sáng ấy cho bạn. Có thể bạn đang sợ một kết quả, một cuộc gặp, một tương lai chưa biết. Hãy để ánh sáng của Ngài chiếu vào nỗi sợ ấy. Bạn sẽ nhận ra mình không đơn độc. Hôm nay, khi nỗi sợ trỗi dậy, hãy lặp lại lời này thật chậm, như một lời ru dịu dàng cho trái tim đang run rẩy.","loi_cau_nguyen":"Chúa ơi, Ngài là ánh sáng và sự cứu rỗi của con. Xin soi vào nỗi sợ trong lòng con để nó nhỏ lại, và giúp con tin cậy Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":27,"cau":14,"loi_kinh_thanh":"Hãy trông đợi Đức Giê-hô-va; Hãy vững lòng bền chí! Phải, hãy trông đợi Đức Giê-hô-va.","bai_hoc":"\\"Hãy trông đợi Đức Giê-hô-va; Hãy vững lòng bền chí! Phải, hãy trông đợi Đức Giê-hô-va\\" Chờ đợi là một trong những điều khó nhất của đức tin. Có thể bạn đang chờ một lời đáp, một sự chữa lành, một cánh cửa mở ra. Chúa không bảo bạn đứng yên vô vọng, mà mời bạn chờ đợi với lòng vững vàng. Chờ đợi Chúa nghĩa là tin rằng Ngài đang làm việc dù bạn chưa thấy. Hôm nay, nếu bạn mệt mỏi vì chờ đợi, hãy nói với Chúa điều đó. Ngài hiểu. Và Ngài sẽ ban cho bạn sức mạnh để tiếp tục chờ, với hy vọng.","loi_cau_nguyen":"Chúa ơi, khi con phải chờ đợi, xin giúp con kiên nhẫn và vững lòng. Xin giúp con tin rằng Ngài đang làm việc, dù con chưa thấy kết quả. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":28,"cau":7,"loi_kinh_thanh":"Đức Giê-hô-va là sức mạnh và là cái khiên của tôi; Lòng tôi đã nhờ cậy nơi Ngài, và tôi được cứu tiếp; Vì vậy, lòng tôi rất mừng rỡ, Tôi sẽ lấy bài ca mà ngợi khen Ngài.","bai_hoc":"\\"Đức Giê-hô-va là sức mạnh và là cái khiên của tôi; Lòng tôi đã nhờ cậy nơi Ngài, và tôi được cứu tiếp; Vì vậy, lòng tôi rất mừng rỡ, Tôi sẽ lấy bài ca mà ngợi khen Ngài\\" Ở đây Đa-vít không chỉ nói về điều ông cần, mà nói về điều ông đã nhận. Ông được giúp đỡ, và lòng ông nhảy mừng. Có những lần Chúa đã giúp bạn mà bạn gần như quên mất. Hôm nay, hãy nhớ lại một lần Ngài là cái khiên che chở bạn. Hãy để lòng biết ơn trào lên và hát cho Ngài một bài ca nhỏ. Khi bạn nhớ lại sự thành tín của Chúa, đức tin của bạn sẽ được tiếp thêm sức mạnh cho những ngày còn lại.","loi_cau_nguyen":"Chúa ơi, Ngài là sức mạnh và cái khiên của con. Xin giúp con nhớ những lần Ngài đã giúp đỡ con, và để lòng biết ơn nâng đỡ con hôm nay. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":30,"cau":5,"loi_kinh_thanh":"Vì sự giận Ngài chỉ trong một lúc, Còn ơn của Ngài có trọn một đời: Sự khóc lóc đến trọ ban đêm, Nhưng buổi sáng bèn có sự vui mừng.","bai_hoc":"\\"Vì sự giận Ngài chỉ trong một lúc, Còn ơn của Ngài có trọn một đời: Sự khóc lóc đến trọ ban đêm, Nhưng buổi sáng bèn có sự vui mừng\\" Cơn đau có thể kéo dài qua nhiều đêm, nhưng nó không ở lại mãi. Chúa hứa buổi sáng sẽ đến. Nếu hôm nay bạn đang khóc, bạn không cần phải vội vui. Hãy cho phép mình khóc, vì nước mắt là một ngôn ngữ mà Chúa hiểu rất rõ. Nhưng đồng thời, hãy nắm lấy lời hứa này: sự vui mừng đang đến. Ngài sẽ biến sự than khóc thành điệu múa, cất bao gai và thắt lưng bằng niềm vui. Hôm nay, hãy giữ vững hy vọng, dù chỉ nhỏ như một đốm sáng đầu ngày.","loi_cau_nguyen":"Chúa ơi, khi nước mắt con rơi, xin giúp con giữ hy vọng rằng sự vui mừng sẽ đến vào buổi sáng. Xin ở bên con trong đêm dài, và an ủi con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":32,"cau":8,"loi_kinh_thanh":"Ta sẽ dạy dỗ ngươi, chỉ cho ngươi con đường phải đi; Mắt ta sẽ chăm chú ngươi mà khuyên dạy ngươi.","bai_hoc":"\\"Ta sẽ dạy dỗ ngươi, chỉ cho ngươi con đường phải đi; Mắt ta sẽ chăm chú ngươi mà khuyên dạy ngươi\\" Chúa không ném bạn vào cuộc đời rồi bỏ mặc. Ngài ở bên, dõi nhìn, hướng dẫn. Hãy hình dung ánh mắt dịu dàng ấy, giống như người cha nhìn con tập đi. Có thể bạn đang không biết phải chọn con đường nào. Hãy nói thật với Ngài, và hãy lắng nghe. Chúa có thể hướng dẫn qua Lời Ngài, qua một người bạn khôn ngoan, qua sự bình an trong lòng. Hôm nay, hãy xin: \\"Chúa ơi, xin chỉ cho con biết bước tiếp theo.\\" Ngài sẽ không để bạn bơ vơ.","loi_cau_nguyen":"Chúa ơi, xin chỉ dạy và dẫn dắt con trong con đường nên đi. Xin giúp con sẵn lòng lắng nghe, và tin rằng mắt Ngài luôn dõi theo con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":33,"cau":12,"loi_kinh_thanh":"Nước nào có Giê-hô-va làm Đức Chúa Trời mình, Dân tộc nào được Ngài chọn làm cơ nghiệp mình có phước thay!","bai_hoc":"\\"Nước nào có Giê-hô-va làm Đức Chúa Trời mình, Dân tộc nào được Ngài chọn làm cơ nghiệp mình có phước thay!\\" Một dân tộc được phước không phải vì giàu có hay hùng mạnh, mà vì có Chúa là trung tâm. Bạn có thể bắt đầu từ gia đình nhỏ của mình: một gia đình có Chúa ở giữa là một nơi được phước. Hôm nay, hãy cầu nguyện cho đất nước bạn, cho những người lãnh đạo, cho cộng đồng nơi bạn sống. Và hãy làm điều nhỏ bé: một việc tử tế, một lời cầu nguyện chung với người thân. Mỗi hành động nhỏ ấy là một hạt giống của phước lành mà Chúa có thể làm lớn lên.","loi_cau_nguyen":"Chúa ơi, xin ban phước cho gia đình, cộng đồng và đất nước con. Xin giúp chúng con lấy Ngài làm trung tâm, và bắt đầu từ chính nhà con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":34,"cau":8,"loi_kinh_thanh":"Khá nếm thử xem Đức Giê-hô-va tốt lành dường bao! Phước cho người nào nương náu mình nơi Ngài!","bai_hoc":"\\"Khá nếm thử xem Đức Giê-hô-va tốt lành dường bao! Phước cho người nào nương náu mình nơi Ngài.\\" Chúa không bắt bạn tin mù quáng, Ngài mời bạn nếm thử. Giống như một món ăn ngon, bạn phải trải nghiệm mới biết. Hãy thử tin cậy Ngài trong một việc nhỏ hôm nay: giao nỗi lo cho Ngài, tha thứ cho một người, cảm tạ Ngài trong khó khăn. Rồi nhìn xem điều gì xảy ra. Bạn sẽ khám phá ra rằng Ngài thật sự tốt lành, và lòng bạn sẽ ngày càng tin cậy Ngài nhiều hơn. Hãy nếm thử, và thấy.","loi_cau_nguyen":"Chúa ơi, con muốn nếm thử sự tốt lành của Ngài. Xin giúp con tin cậy Ngài trong những việc nhỏ hằng ngày, và nhận ra Ngài thật sự tốt lành. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":34,"cau":18,"loi_kinh_thanh":"Đức Giê-hô-va ở gần những người có lòng đau thương, Và cứu kẻ nào có tâm hồn thống-hối.","bai_hoc":"Có những đêm lòng bạn nặng trĩu đến mức không thể thốt thành lời cầu nguyện. Bạn không biết phải nói gì với Chúa, và đôi khi còn tự trách mình thiếu đức tin. Nhưng hãy nghe lời hứa dịu dàng này: Chúa ở gần những người có lòng đau thương. Ngài không đứng xa chờ bạn bình tĩnh trở lại, cũng không đòi bạn phải mạnh mẽ trước mặt Ngài. Ngài đến ngồi cạnh bạn ngay trong chỗ tan vỡ nhất. Nước mắt của bạn không làm Ngài quay đi, vì chúng quý giá trước mặt Ngài. Hôm nay, nếu lòng bạn đang rạn nứt, hãy chỉ cần thì thầm: \\"Chúa ơi, con đau lắm\\". Ngài đang ở rất gần, và Ngài nghe thấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ở gần những ai có lòng tan vỡ. Khi con đau và không biết nói gì, xin ở lại với con, và nhận lấy tiếng thở dài của con như lời cầu nguyện. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":37,"cau":4,"loi_kinh_thanh":"Cũng hãy khoái lạc nơi Đức Giê-hô-va, Thì Ngài sẽ ban cho ngươi điều lòng mình ao ước.","bai_hoc":"\\"Hãy khoái lạc nơi Đức Giê-hô-va, thì Ngài sẽ ban cho ngươi điều lòng ao ước.\\" Khi bạn vui thích trong Chúa, những điều bạn thật sự mong ước dần được định hình theo lòng Ngài. Đây không phải là một công thức để đạt mọi điều bạn muốn, mà là lời hứa rằng khi Chúa trở thành niềm vui của bạn, lòng bạn sẽ được thỏa thích hơn bất kỳ điều gì khác. Hôm nay, hãy làm điều gì đó giúp bạn vui thích trong Chúa: một bài hát, một bản thánh ca, một lời cảm tạ, một cuộc dạo chơi. Hãy để lòng bạn tận hưởng sự hiện diện của Ngài.","loi_cau_nguyen":"Chúa ơi, xin cho con vui thích nơi Ngài. Xin uốn nắn những ước muốn của con theo lòng Ngài, để con tìm thấy sự thỏa lòng thật sự trong Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":37,"cau":5,"loi_kinh_thanh":"Hãy phó thác đường lối mình cho Đức Giê-hô-va, Và nhờ cậy nơi Ngài, thì Ngài sẽ làm thành việc ấy.","bai_hoc":"\\"Hãy phó thác đường lối mình cho Đức Giê-hô-va, và nhờ cậy nơi Ngài, thì Ngài sẽ làm thành việc ấy.\\" Phó thác nghĩa là trao điều bạn đang ôm chặt cho một Đấng đáng tin cậy hơn. Có thể bạn đang lo lắng cho một kế hoạch, một đứa con, một quyết định. Hãy thử nói điều ấy với Chúa, thật cụ thể và chân thành, rồi buông tay ra. Khó lắm, vì chúng ta quen kiểm soát. Nhưng khi bạn buông tay, bạn mở chỗ cho Chúa làm việc. Hôm nay, hãy chọn một điều và phó thác cho Ngài, rồi nghỉ ngơi trong niềm tin rằng Ngài sẽ làm thành.","loi_cau_nguyen":"Chúa ơi, xin giúp con phó thác đường lối của con cho Ngài. Xin giúp con buông tay khỏi những điều con không kiểm soát được, và tin Ngài làm thành. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":37,"cau":7,"loi_kinh_thanh":"Hãy yên tịnh trước mặt Đức Giê-hô-va, và chờ đợi Ngài. Chớ phiền lòng vì cớ kẻ được may mắn trong con đường mình, Hoặc vì cớ người làm thành những mưu ác.","bai_hoc":"\\"Hãy yên tịnh trước mặt Đức Giê-hô-va, và chờ đợi Ngài. Chớ phiền lòng vì cớ kẻ được may mắn trong con đường mình, Hoặc vì cớ người làm thành những mưu ác\\" Giữa một thế giới ồn ào, điều này nghe thật khó. Chúng ta muốn hành động ngay, muốn giải quyết ngay, muốn thấy kết quả ngay. Nhưng Chúa mời bạn yên lặng, và đừng tức tối khi thấy người khác có vẻ thuận lợi hơn mình. Sự yên lặng trước mặt Ngài là nơi lòng ta được thanh lọc khỏi ganh tị và lo âu. Hôm nay, hãy dành năm phút không làm gì cả, chỉ ngồi yên với Chúa. Hãy để Ngài làm dịu những xáo động bên trong bạn.","loi_cau_nguyen":"Chúa ơi, xin làm dịu những xáo động và sự ganh tị trong lòng con. Xin giúp con yên lặng trước mặt Ngài, và kiên nhẫn chờ đợi Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":42,"cau":1,"loi_kinh_thanh":"Đức Chúa Trời ôi! linh hồn tôi mơ ước Chúa, Như con nai cái thèm khát khe nước.","bai_hoc":"\\"Đức Chúa Trời ôi! linh hồn tôi mơ ước Chúa, Như con nai cái thèm khát khe nước\\" Hãy hình dung một con nai giữa mùa khô, khát đến cháy cổ. Đó là cách linh hồn chúng ta cần Chúa. Đôi khi bạn thấy lòng trống rỗng mà không biết vì sao: có thể là vì bạn đang khát Ngài. Cơn khát ấy không phải là điều xấu, nó là dấu hiệu cho thấy bạn được tạo ra để ở cùng Chúa. Hôm nay, hãy đến với Ngài như con nai đến với dòng suối: không cần nói hay, chỉ cần uống. Ngài luôn sẵn sàng làm no lòng bạn.","loi_cau_nguyen":"Chúa ơi, linh hồn con khao khát Ngài như nai khát nước. Xin làm no lòng con, và giúp con đến với Ngài mỗi ngày. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":46,"cau":1,"loi_kinh_thanh":"Đức Chúa Trời là nơi nương náu và sức lực của chúng tôi, Ngài sẵn giúp đỡ trong cơn gian truân.","bai_hoc":"\\"Đức Chúa Trời là nơi nương náu và sức lực của chúng tôi, Ngài sẵn giúp đỡ trong cơn gian truân.\\" Chữ \\"sẵn\\" thật đẹp: Chúa không phải đi tìm ta khi ta gặp nạn, Ngài đã ở đó. Khi cơn bão ập đến, bạn không phải chạy xa để tìm sự giúp đỡ. Ngài ở ngay bên cạnh. Có thể hôm nay bạn đang đối diện với một cơn khủng hoảng, và mọi thứ như đang rung chuyển. Hãy ẩn mình trong Ngài. Bạn không cần phải mạnh mẽ hơn cơn bão, bạn chỉ cần ở trong nơi nương náu của Chúa. Hãy hít thở chậm, và để Ngài giữ bạn.","loi_cau_nguyen":"Chúa ơi, Ngài là nơi nương náu và sức lực của con, sẵn giúp đỡ trong cơn gian truân. Khi con thấy mọi thứ rung chuyển, xin giữ con trong Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":46,"cau":10,"loi_kinh_thanh":"Hãy yên lặng và biết rằng ta là Đức Chúa Trời; Ta sẽ được tôn cao trong các nước, cũng sẽ được tôn cao trên đất.","bai_hoc":"\\"Hãy yên lặng và biết rằng Ta là Đức Chúa Trời.\\" Đây không phải là lời quở trách, mà là lời mời dịu dàng của một Đấng muốn bạn nghỉ ngơi. Khi mọi thứ xung quanh rung chuyển, điều đầu tiên Chúa nhắc không phải là làm gì, mà là dừng lại. Có thể bạn đang cố gắng giải quyết mọi thứ cùng lúc, đầu óc không ngừng quay. Hãy ngừng lại một chút. Hít vào, thở ra, và nhắc lòng mình: Ngài là Đức Chúa Trời, còn tôi không phải. Không cần phải kiểm soát tất cả. Trong yên lặng ấy, bạn sẽ nhận ra Ngài đang ở rất gần.","loi_cau_nguyen":"Chúa ơi, xin giúp lòng con yên lặng và nhớ rằng Ngài là Đức Chúa Trời. Xin nhắc con rằng con không cần kiểm soát mọi thứ, vì Ngài đang nắm quyền. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":51,"cau":1,"loi_kinh_thanh":"Đức Chúa Trời ôi! xin hãy thương xót tôi tùy lòng nhân từ của Chúa; Xin hãy xóa các sự vi phạm tôi theo sự từ bi rất lớn của Chúa.","bai_hoc":"Đa-vít viết lời này sau khi phạm tội nặng, và ông không biện hộ. Ông chỉ nói: Đức Chúa Trời ơi, xin thương xót tôi theo sự nhân từ của Ngài. Ông không dựa vào việc mình tốt, mà dựa vào lòng nhân từ của Chúa. Nếu bạn từng làm điều khiến mình xấu hổ và nặng nề, hãy cầu nguyện như Đa-vít. Chúa không quay đi khi bạn thành thật. Ngài chờ đợi để ban sự thương xót. Hôm nay, đừng giấu điều gì trong lòng, hãy mang tất cả đến với Ngài. Bạn sẽ ngạc nhiên về sự dịu dàng mà Ngài dành cho người biết ăn năn.","loi_cau_nguyen":"Chúa ơi, con thành thật đến với Ngài và xin thương xót con theo lòng nhân từ của Ngài. Xin tha thứ những lỗi lầm của con, và ban cho con sự bình an. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":51,"cau":10,"loi_kinh_thanh":"Đức Chúa Trời ôi! xin hãy dựng nên trong tôi một lòng trong sạch, Và làm cho mới lại trong tôi một thần linh ngay thẳng.","bai_hoc":"\\"Đức Chúa Trời ôi! xin hãy dựng nên trong tôi một lòng trong sạch, Và làm cho mới lại trong tôi một thần linh ngay thẳng\\" Đa-vít biết mình không thể tự làm sạch lòng mình, ông cần Chúa làm điều ấy. Có những thói quen, những cay đắng, những vết thương mà bạn không thể tự gỡ ra. Hãy xin Chúa. \\"Dựng nên\\" nghĩa là tạo ra điều mới từ nơi trống không, và Chúa làm được điều ấy. Hôm nay, hãy cầu nguyện lời này thật chậm rãi, và để Ngài bắt đầu công việc làm mới trong bạn, từng ngày, từng chút một.","loi_cau_nguyen":"Chúa ơi, xin dựng nên trong con một tấm lòng trong sạch. Con không thể tự làm điều ấy, xin Ngài bắt đầu công việc làm mới trong con, từng ngày. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":55,"cau":22,"loi_kinh_thanh":"Hãy trao gánh nặng ngươi cho Đức Giê-hô-va, Ngài sẽ nâng đỡ ngươi; Ngài sẽ chẳng hề cho người công bình bị rúng động.","bai_hoc":"\\"Hãy trao gánh nặng ngươi cho Đức Giê-hô-va, Ngài sẽ nâng đỡ ngươi; Ngài sẽ chẳng hề cho người công bình bị rúng động\\" Gánh nặng của bạn có thể là lo âu về tài chính, sức khỏe, con cái, công việc. Chúa không bảo bạn đừng có gánh nặng, Ngài bảo bạn trao nó cho Ngài. Hãy hình dung bạn đang đặt từng điều xuống trước mặt Ngài, như đặt chiếc ba lô nặng sau một chặng đường dài. Ngài không bao giờ để người công bình bị rúng động. Hôm nay, hãy làm một điều đơn giản: nói với Chúa từng điều khiến bạn nặng lòng, rồi hít một hơi thật sâu. Bạn không đang cầm một mình nữa.","loi_cau_nguyen":"Chúa ơi, con trao gánh nặng của con cho Ngài. Xin nâng đỡ con, và giúp con nhớ rằng con không phải gánh một mình. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":56,"cau":3,"loi_kinh_thanh":"Trong ngày sợ hãi, Tôi sẽ để lòng nhờ cậy nơi Chúa.","bai_hoc":"\\"Trong ngày sợ hãi, Tôi sẽ để lòng nhờ cậy nơi Chúa\\" Đa-vít không nói ông không sợ. Ông nói khi sợ, ông chọn tin cậy. Nỗi sợ là điều rất người, và Chúa không chê trách nó. Điều Ngài mời bạn là đem nỗi sợ đến với Ngài, thay vì để nó nuốt chửng bạn. Có thể hôm nay bạn đang có tim đập nhanh, lòng thắt lại. Hãy nói thầm: \\"Chúa ơi, con sợ, nhưng con tin cậy Ngài.\\" Lời cầu nguyện chân thật ấy, dù ngắn, là đủ để Chúa tiến đến gần và đặt bàn tay bình an lên bạn.","loi_cau_nguyen":"Chúa ơi, khi con sợ hãi, xin giúp con chọn tin cậy Ngài. Xin đặt bình an của Ngài vào lòng con, và nắm lấy tay con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":63,"cau":1,"loi_kinh_thanh":"Hỡi Đức Chúa Trời, Chúa là Đức Chúa Trời tôi, vừa sáng tôi tìm cầu Chúa; Trong một đất khô khan, cực nhọc, chẳng nước, Linh hồn tôi khát khao Chúa, thân thể tôi mong mỏi về Chúa,","bai_hoc":"\\"Hỡi Đức Chúa Trời, Chúa là Đức Chúa Trời tôi, vừa sáng tôi tìm cầu Chúa; Trong một đất khô khan, cực nhọc, chẳng nước, Linh hồn tôi khát khao Chúa, thân thể tôi mong mỏi về Chúa\\" Đa-vít viết lời này khi ở trong hoang mạc, khô cằn và mệt mỏi. Nhưng chính nơi ấy, lòng ông khát khao Chúa mãnh liệt. Có những mùa trong đời, khi mọi thứ khô khan, lại là lúc chúng ta nhận ra mình cần Ngài đến mức nào. Đừng sợ cơn khát ấy. Hôm nay, ngay từ buổi sáng, hãy dành một khoảnh khắc nói với Chúa: \\"Con cần Ngài.\\" Ngài sẽ đến, như một dòng nước mát giữa sa mạc, làm no lòng bạn.","loi_cau_nguyen":"Chúa ơi, xin cho con khao khát tìm kiếm Ngài từ sáng sớm. Xin làm no lòng con như dòng nước giữa sa mạc, và ở gần con hôm nay. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":73,"cau":26,"loi_kinh_thanh":"Thịt và lòng tôi bị tiêu hao; Nhưng Đức Chúa Trời là sức lực của lòng tôi, và là phần tôi đến đời đời.","bai_hoc":"\\"Thịt và lòng tôi bị tiêu hao; Nhưng Đức Chúa Trời là sức lực của lòng tôi, và là phần tôi đến đời đời\\" Có những lúc cơ thể và tinh thần bạn yếu đi, và bạn cảm thấy mình không thể tiếp tục. Tác giả cũng từng như vậy, thậm chí ông từng ganh tị với người khác. Nhưng cuối cùng ông tìm thấy: Chúa là điều duy nhất không bao giờ phai nhạt. Khi mọi thứ khác phai tàn, Ngài vẫn ở lại. Hôm nay, nếu bạn thấy mình yếu, hãy nhớ rằng bạn có một nguồn sức lực không bao giờ cạn. Hãy dựa vào Ngài.","loi_cau_nguyen":"Chúa ơi, khi thân thể và lòng con yếu đi, xin là sức lực và phần của con. Xin giúp con nhớ rằng Ngài không bao giờ phai nhạt, khi mọi thứ khác đổi thay. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":84,"cau":10,"loi_kinh_thanh":"Vì một ngày trong hành lang Chúa đáng hơn một ngàn ngày khác. Thà tôi làm kẻ giữ cửa trong nhà Đức Chúa Trời tôi, Hơn là ở trong trại kẻ dữ.","bai_hoc":"\\"Vì một ngày trong hành lang Chúa đáng hơn một ngàn ngày khác. Thà tôi làm kẻ giữ cửa trong nhà Đức Chúa Trời tôi, Hơn là ở trong trại kẻ dữ\\" Người viết Thi Thiên này khao khát được ở gần Chúa đến mức chỉ cần một ngày bên Ngài cũng quý hơn cả ngàn ngày ở nơi khác. Có thể bạn đã quen sống mà không còn dành thời gian cho Ngài, và lòng cảm thấy hơi xa. Hôm nay, hãy thử trải nghiệm lại niềm vui ấy: dành thời gian ngồi bên Chúa, không vì bổn phận, mà vì khao khát. Có thể chỉ mười phút, nhưng nó sẽ làm lòng bạn ấm lên, vì không nơi nào bình an bằng ở trong sự hiện diện của Ngài.","loi_cau_nguyen":"Chúa ơi, xin cho con khao khát được ở gần Ngài. Xin giúp con dành thời gian bên Ngài vì tình yêu, và nhận ra rằng không nơi nào bình an bằng ở trong sự hiện diện của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":90,"cau":12,"loi_kinh_thanh":"Cầu xin Chúa dạy chúng tôi biết đếm các ngày chúng tôi, Hầu cho chúng tôi được lòng khôn ngoan.","bai_hoc":"\\"Cầu xin Chúa dạy chúng tôi biết đếm các ngày chúng tôi, Hầu cho chúng tôi được lòng khôn ngoan\\" Cuộc đời ngắn ngủi hơn ta tưởng, và mỗi ngày là một món quà. Lời cầu nguyện này không nhằm làm bạn lo sợ, mà để giúp bạn sống có ý nghĩa. Hãy tự hỏi: nếu hôm nay là một ngày quý giá, tôi sẽ sống thế nào? Có thể bạn muốn gọi cho một người thân, nói lời xin lỗi, hay đơn giản là dành thời gian cho Chúa. Hôm nay, hãy chọn một điều quan trọng và làm nó. Đừng đợi đến mai, vì hôm nay là món quà của bạn.","loi_cau_nguyen":"Chúa ơi, xin dạy con đếm các ngày của mình để được lòng khôn ngoan. Xin giúp con sống có ý nghĩa, và làm điều quan trọng mà con vẫn trì hoãn. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":91,"cau":1,"loi_kinh_thanh":"Người nào ở nơi kín đáo của Đấng Chí cao, Sẽ được hằng ở dưới bóng của Đấng Toàn năng.","bai_hoc":"\\"Người nào ở nơi kín đáo của Đấng Chí Cao sẽ được hằng ở dưới bóng của Đấng Toàn Năng.\\" Hãy tưởng tượng một nơi trú ẩn an toàn nhất mà bạn có thể nghĩ đến: một chiếc chăn ấm, một căn phòng yên tĩnh, vòng tay của người thương. Chúa mời bạn đến một nơi còn an toàn hơn thế. \\"Ở\\" nghĩa là ở lại, không chỉ ghé thăm. Có thể hôm nay lòng bạn lo âu và mệt mỏi. Hãy dành vài phút ở lại trong sự hiện diện của Ngài, như đứa trẻ ngồi trong lòng cha. Dưới bóng của Ngài, bạn thật sự được bảo vệ và yên ổn.","loi_cau_nguyen":"Chúa ơi, xin cho con ở lại nơi kín đáo của Ngài và dưới bóng của Ngài. Xin che chở con, và giúp con nhớ rằng con luôn có nơi nương náu. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":91,"cau":2,"loi_kinh_thanh":"Tôi nói về Đức Giê-hô-va rằng: Ngài là nơi nương náu tôi, và là đồn lũy tôi; Cũng là Đức Chúa Trời tôi, tôi tin cậy nơi Ngài.","bai_hoc":"\\"Tôi nói về Đức Giê-hô-va rằng: Ngài là nơi nương náu tôi, và là đồn lũy tôi; Cũng là Đức Chúa Trời tôi, tôi tin cậy nơi Ngài\\" Có điều gì đó rất mạnh trong việc nói ra thành lời. Khi bạn nói thành tiếng Chúa là nơi nương náu của con, lòng bạn cũng được củng cố. Hôm nay, nếu lòng bạn bất an, hãy thử nói lời này thành tiếng, thật chậm và thật chân thành. Không cần phải cảm thấy mạnh mẽ, chỉ cần tuyên bố. Dần dần, lời nói ấy sẽ thấm vào tâm trí bạn, như một chiếc neo giữ bạn vững vàng giữa những con sóng của lo âu.","loi_cau_nguyen":"Chúa ơi, con tuyên bố Ngài là nơi nương náu và đồn lũy của con, là Đức Chúa Trời con tin cậy. Xin củng cố lòng con khi con lo âu. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":91,"cau":11,"loi_kinh_thanh":"Vì Ngài sẽ ban lịnh cho thiên sứ Ngài, Bảo gìn giữ ngươi trong các đường lối ngươi.","bai_hoc":"\\"Vì Ngài sẽ ban lịnh cho thiên sứ Ngài, Bảo gìn giữ ngươi trong các đường lối ngươi\\" Lời hứa này làm ấm lòng: bạn đang được che chở bởi những sự bảo vệ mà bạn không thấy. Tuy nhiên, hãy nhớ rằng đây là lời hứa dành cho người nương náu nơi Chúa, không phải để bạn thử thách Ngài bằng những điều liều lĩnh. Hôm nay, hãy sống khôn ngoan, đi trong đường lối của Chúa, và tin rằng Ngài gìn giữ bạn. Khi bạn thấy lo cho người thân đang ở xa hoặc đang đi đường, hãy cầu nguyện lời này cho họ. Chúa nghe và đáp lại.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về sự gìn giữ của Ngài. Xin bảo vệ con và những người con thương, và giúp con sống khôn ngoan trong đường lối Ngài, không thử thách Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":100,"cau":4,"loi_kinh_thanh":"Hãy cảm tạ mà vào các cửa Ngài, Hãy ngợi khen mà vào hành lang Ngài. Khá cảm tạ Ngài, chúc tụng danh của Ngài.","bai_hoc":"\\"Hãy cảm tạ mà vào các cửa Ngài, Hãy ngợi khen mà vào hành lang Ngài. Khá cảm tạ Ngài, chúc tụng danh của Ngài\\" Cảm tạ là chiếc chìa khóa mở cửa vào sự hiện diện của Chúa. Có những lúc bạn đến với Ngài chỉ để xin, chỉ để than phiền, và điều đó cũng không sao. Nhưng thử bắt đầu bằng lòng biết ơn xem. Khi bạn nói cảm ơn Chúa vì hôm nay, lòng bạn thay đổi. Bạn nhìn thấy điều tốt đẹp thay vì chỉ thiếu thốn. Hôm nay, trước khi xin điều gì, hãy dành một phút cảm tạ Chúa vì ba điều. Bạn sẽ cảm nhận được cánh cửa lòng mở rộng hơn.","loi_cau_nguyen":"Chúa ơi, xin giúp con bước vào sự hiện diện của Ngài với lòng cảm tạ và ngợi khen. Trước khi xin điều gì, xin cho con nói lời cảm ơn Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":103,"cau":1,"loi_kinh_thanh":"Hỡi linh hồn ta, khá ngợi khen Đức Giê-hô-va! Mọi điều gì ở trong ta hãy ca tụng danh thánh của Ngài!","bai_hoc":"\\"Hỡi linh hồn ta, khá ngợi khen Đức Giê-hô-va! Mọi điều gì ở trong ta hãy ca tụng danh thánh của Ngài!\\" Đa-vít nói với chính linh hồn mình, như thể ông cần nhắc nhở lòng mình. Có những ngày bạn không có cảm hứng để ngợi khen, tâm hồn như ngủ quên. Đó là lúc bạn có thể làm như Đa-vít: nhẹ nhàng đánh thức linh hồn mình. Hãy nói: Linh hồn ơi, hãy nhớ những điều Chúa đã làm cho ta. Rồi kể ra từng điều. Dần dần, lòng bạn sẽ ấm lên, và một bài ca ngợi khen sẽ tự nhiên trào dâng, dù chỉ nhỏ nhẹ như một tiếng thì thầm.","loi_cau_nguyen":"Linh hồn con ơi, hãy ngợi khen Chúa. Chúa ơi, xin đánh thức lòng biết ơn trong con, và giúp con nhớ những điều Ngài đã làm. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":103,"cau":12,"loi_kinh_thanh":"Phương đông xa cách phương tây bao nhiêu, Thì Ngài đã đem sự vi phạm chúng tôi khỏi xa chúng tôi bấy nhiêu.","bai_hoc":"\\"Phương đông xa cách phương tây bao nhiêu, Thì Ngài đã đem sự vi phạm chúng tôi khỏi xa chúng tôi bấy nhiêu\\" Hãy nghĩ về khoảng cách đó: không bao giờ gặp nhau. Chúa đã đặt tội lỗi bạn xa như vậy. Ngài không giữ danh sách, không nhắc lại, không quay về chuyện cũ. Có những điều trong quá khứ vẫn làm bạn xấu hổ và mặc cảm. Hôm nay, hãy nhớ rằng Chúa đã tha thứ hoàn toàn. Nếu Ngài đã quên, bạn cũng được phép tha thứ cho chính mình. Hãy thở phào, đặt gánh nặng cũ xuống, và bước đi nhẹ nhàng hơn trong sự tự do của ân điển.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đem tội lỗi con ra xa như đông xa tây. Xin giúp con tin điều ấy và tha thứ cho chính mình, để con bước đi nhẹ nhàng hơn. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":107,"cau":1,"loi_kinh_thanh":"Hãy ngợi khen Đức Giê-hô-va, vì Ngài là thiện; Sự nhân từ Ngài còn đến đời đời.","bai_hoc":"\\"Hãy ngợi khen Đức Giê-hô-va, vì Ngài là thiện; Sự nhân từ Ngài còn đến đời đời\\" Cảm tạ không đến từ việc mọi sự tốt đẹp, mà từ việc biết Chúa là ai. Ngài nhân từ và lòng thương xót của Ngài không có hồi kết. Dù đời bạn có đi qua những mùa sóng gió hay bình yên, sự thương xót ấy luôn ở đó. Có thể hôm nay bạn đang không cảm thấy mình có nhiều điều để cảm tạ. Hãy bắt đầu từ điều nhỏ nhất: hơi thở, một bữa ăn, một người bạn. Lòng biết ơn là hạt giống nhỏ, nhưng nó có thể làm nở hoa trong tâm hồn mệt mỏi.","loi_cau_nguyen":"Chúa ơi, Ngài nhân từ và sự thương xót Ngài còn đến đời đời. Xin giúp con thấy những điều nhỏ bé đáng biết ơn hôm nay, và nói lời cảm tạ Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":118,"cau":24,"loi_kinh_thanh":"Nầy là ngày Đức Giê-hô-va làm nên, Chúng tôi sẽ mừng rỡ và vui vẻ trong ngày ấy.","bai_hoc":"\\"Nầy là ngày Đức Giê-hô-va làm nên, Chúng tôi sẽ mừng rỡ và vui vẻ trong ngày ấy\\" Hôm nay là một ngày chưa từng có và sẽ không bao giờ lặp lại. Dù nó mang theo điều gì, Chúa đã làm nên ngày này, và Ngài ở trong nó. Có những buổi sáng bạn thức dậy với nặng nề, nhưng lời này mời bạn chọn niềm vui, không phải vì hoàn cảnh dễ dàng, mà vì Chúa ở cùng. Hôm nay, hãy thử mỉm cười khi mở mắt, và nói: \\"Cảm ơn Chúa vì ngày mới.\\" Hãy tìm một điều nhỏ để vui, và tận hưởng nó như một món quà từ Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về ngày hôm nay. Xin giúp con chọn niềm vui trong Ngài, tìm một điều nhỏ để vui, và sống ngày này như món quà từ Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":119,"cau":11,"loi_kinh_thanh":"Tôi đã giấu lời Chúa trong lòng tôi, Để tôi không phạm tội cùng Chúa.","bai_hoc":"\\"Tôi đã giấu lời Chúa trong lòng tôi, để tôi không phạm tội cùng Ngài.\\" Lời Chúa trong lòng bạn giống như một ngọn đèn nhỏ giữ bạn khỏi vấp ngã trong bóng tối. Khi bạn đối diện với cám dỗ hay sự nản lòng, những câu Kinh Thánh bạn đã ghi nhớ sẽ trở về trong tâm trí, nhẹ nhàng nhắc nhở và nâng đỡ. Hôm nay, hãy chọn một câu Kinh Thánh ngắn và học thuộc. Chép ra, dán ở nơi bạn thường nhìn thấy, lặp lại khi đi bộ hay nấu ăn. Hãy giấu lời Chúa vào tận trong lòng, nơi nó sẽ âm thầm bảo vệ bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con ghi nhớ Lời Ngài trong lòng, để Lời ấy bảo vệ con khỏi tội lỗi và nâng đỡ con khi cám dỗ hay nản lòng đến. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":119,"cau":105,"loi_kinh_thanh":"Lời Chúa là ngọn đèn cho chân tôi, Ánh sáng cho đường lối tôi.","bai_hoc":"\\"Lời Chúa là ngọn đèn cho chân tôi, ánh sáng cho đường lối tôi.\\" Hãy chú ý: ngọn đèn cho chân, không phải đèn pha chiếu sáng cả quãng đường. Chúa thường chỉ cho bạn đủ ánh sáng để bước một bước. Có thể bạn muốn biết toàn bộ kế hoạch của mình nhưng chưa thấy. Hãy tin rằng ánh sáng sẽ đủ cho bước tiếp theo. Khi bạn bước đi, ánh đèn sẽ di chuyển cùng bạn. Hôm nay, nếu bạn đang phân vân, hãy mở Lời Chúa và đọc chậm rãi. Bạn sẽ thấy ánh sáng soi vào đúng nơi bạn cần, vừa đủ để đi tiếp một cách an toàn.","loi_cau_nguyen":"Chúa ơi, Lời Ngài là ngọn đèn cho chân con. Xin soi sáng bước chân tiếp theo của con, và giúp con tin rằng Ngài cho con đủ ánh sáng để bước đi. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":121,"cau":1,"loi_kinh_thanh":"Tôi ngước mắt lên trên núi: Sự tiếp trợ tôi đến từ đâu?","bai_hoc":"\\"Tôi ngước mắt lên trên núi: Sự tiếp trợ tôi đến từ đâu?\\" Người hành hương đi trên đường dài, nhìn lên những ngọn núi hiểm trở và tự hỏi liệu có ai giúp mình. Câu hỏi ấy cũng là câu hỏi của bạn khi đối mặt với những ngọn núi trong đời: bệnh tật, nợ nần, mất mát. Điều đẹp là câu trả lời đến ngay sau đó. Hôm nay, khi bạn thấy những khó khăn cao như núi, đừng chỉ nhìn vào chúng. Hãy ngước lên nhìn xa hơn: có một Đấng lớn hơn tất cả đang dõi theo và sẵn sàng giúp bạn.","loi_cau_nguyen":"Chúa ơi, khi con thấy những ngọn núi khó khăn trước mặt, xin giúp con ngước nhìn Ngài, Đấng lớn hơn tất cả. Xin giúp con nhớ rằng sự giúp đỡ của con đến từ Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":121,"cau":2,"loi_kinh_thanh":"Sự tiếp trợ tôi đến từ Đức Giê-hô-va, Là Đấng đã dựng nên trời và đất.","bai_hoc":"\\"Sự tiếp trợ tôi đến từ Đức Giê-hô-va, Là Đấng đã dựng nên trời và đất\\" Đấng nâng đỡ bạn không phải là một người yếu đuối, mà là Đấng dựng nên cả trời đất. Không có vấn đề nào của bạn quá lớn với Ngài. Và điều lạ lùng nhất: Ngài quan tâm đến bạn một cách riêng tư và gần gũi. Hôm nay, nếu bạn thấy mình cần sự giúp đỡ nhưng không biết tìm ở đâu, hãy bắt đầu từ chỗ này. Hãy nói thật với Ngài điều bạn cần. Ngài sẽ giúp, có thể qua cách bạn không ngờ tới, nhưng luôn vào đúng lúc.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng dựng nên trời đất và là Đấng giúp đỡ con. Xin giúp con nói thật với Ngài điều con cần, và tin Ngài giúp đúng lúc. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":122,"cau":1,"loi_kinh_thanh":"Tôi vui mừng khi người ta nói với tôi rằng: Ta hãy đi đến nhà Đức Giê-hô-va.","bai_hoc":"\\"Tôi vui mừng khi người ta nói với tôi rằng: Ta hãy đi đến nhà Đức Giê-hô-va\\" Có một niềm vui đặc biệt khi cùng nhau đến nhà Chúa: tiếng hát chung, những lời chào hỏi, cảm giác thuộc về. Hôm nay, hãy nhớ rằng cộng đoàn đức tin là món quà. Nếu bạn đã lâu không đến, hãy thử quay lại. Nếu bạn đang ở đó, hãy trân trọng những người anh chị em ngồi cạnh bạn. Và có thể mời một người bạn cùng đi, như lời mời trong câu Kinh Thánh này. Một lời mời đơn giản có thể là khởi đầu của điều tuyệt vời cho người ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về cộng đoàn đức tin. Xin giúp con trân trọng anh chị em, vui mừng khi được ở nhà Ngài, và mời một người cùng đến với Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":127,"cau":1,"loi_kinh_thanh":"Nếu Đức Giê-hô-va không cất nhà, Thì những thợ xây cất làm uổng công. Nhược bằng Đức Giê-hô-va không coi-giữ thành, Thì người canh thức canh luống công.","bai_hoc":"\\"Nếu Đức Giê-hô-va không cất nhà, Thì những thợ xây cất làm uổng công. Nhược bằng Đức Giê-hô-va không coi-giữ thành, Thì người canh thức canh luống công\\" Bạn có thể đã làm việc rất nhiều cho gia đình, sự nghiệp, ước mơ của mình. Lời này không bảo bạn đừng cố gắng, mà nhắc bạn mời Chúa vào trong công việc ấy. Có những lúc chúng ta làm việc đến kiệt sức mà vẫn lo lắng, vì quên rằng Chúa là Đấng xây dựng thật sự. Hôm nay, hãy cầu nguyện cho ngôi nhà của bạn, cho gia đình và công việc của bạn. Hãy làm phần của mình, và để Chúa làm phần của Ngài.","loi_cau_nguyen":"Chúa ơi, xin xây dựng ngôi nhà và công việc của con. Xin giúp con làm phần mình với lòng tin cậy, và để Ngài làm phần của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":133,"cau":1,"loi_kinh_thanh":"Kìa, anh em ăn ở hòa thuận nhau Thật tốt đẹp thay!","bai_hoc":"\\"Kìa, anh em ăn ở hòa thuận nhau Thật tốt đẹp thay!\\" Sự hòa thuận giữa những người thân yêu là một trong những niềm vui đẹp nhất. Có thể gia đình bạn đang có những căng thẳng, hoặc một mối quan hệ nào đó đang lạnh nhạt. Hôm nay, hãy làm một bước nhỏ hướng tới hòa thuận: một lời xin lỗi, một tin nhắn thăm hỏi, một bữa cơm chung. Hòa thuận không phải lúc nào cũng dễ dàng, nhưng Chúa chúc phước cho những ai gìn giữ nó. Hãy xin Ngài ban cho bạn lòng nhẫn nại và sự khiêm nhường để làm người xây dựng hòa bình.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm người xây dựng hòa thuận. Xin cho con một bước nhỏ hôm nay, như lời xin lỗi hay tin nhắn thăm hỏi, và ban cho con lòng nhẫn nại. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":139,"cau":14,"loi_kinh_thanh":"Tôi cảm tạ Chúa, vì tôi được dựng nên cách đáng sợ lạ lùng. Công việc Chúa thật lạ lùng, lòng tôi biết rõ lắm.","bai_hoc":"\\"Tôi cảm tạ Chúa, vì tôi được dựng nên cách đáng sợ lạ lùng.\\" Hãy đứng trước gương và nhìn chính mình bằng ánh mắt của Chúa. Mỗi chi tiết nơi bạn, hình dáng, giọng nói, tính cách, đều được Ngài dày công nắn nên. Có thể bạn từng không hài lòng với một điều nào đó nơi mình, hoặc bị người khác làm bạn cảm thấy không đủ. Nhưng Chúa nói bạn được dựng nên một cách lạ lùng. Hôm nay, hãy thử nói lời cảm ơn Ngài vì đã dựng nên bạn, và hãy đối xử với bản thân như một tác phẩm quý giá của Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dựng nên con cách lạ lùng. Xin giúp con trân trọng chính mình như tác phẩm của Ngài, và biết ơn về con người mà Ngài đã tạo nên. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":139,"cau":23,"loi_kinh_thanh":"Đức Chúa Trời ơi, xin hãy tra xét tôi, và biết lòng tôi; Hãy thử thách tôi, và biết tư tưởng tôi;","bai_hoc":"\\"Đức Chúa Trời ơi, xin hãy tra xét tôi, và biết lòng tôi; hãy thử thách tôi, và biết tư tưởng tôi.\\" Đây là một lời cầu nguyện can đảm: mời Chúa nhìn thấy những điều sâu kín nhất trong lòng mình. Nhưng bạn không cần sợ, vì Ngài không soi xét để lên án, mà để chữa lành. Có những lo lắng và đau đớn mà ngay cả bạn cũng chưa nhận ra. Hôm nay, hãy ngồi yên và mời Chúa đến soi sáng. Hãy để Ngài chạm vào những điều bạn chưa dám nhìn, và nhẹ nhàng dẫn bạn trong con đường đời đời của Ngài.","loi_cau_nguyen":"Chúa ơi, xin dò xét lòng con và biết tư tưởng con. Xin soi sáng những điều con chưa nhận ra, và dẫn con trong con đường đời đời của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":145,"cau":18,"loi_kinh_thanh":"Đức Giê-hô-va ở gần mọi người cầu khẩn Ngài. Tức ở gần mọi người có lòng thành thực cầu khẩn Ngài.","bai_hoc":"\\"Đức Giê-hô-va ở gần mọi người cầu khẩn Ngài. Tức ở gần mọi người có lòng thành thực cầu khẩn Ngài\\" Chúa không ở xa. Ngài không cần bạn nói những lời hay ho, chỉ cần chân thành. Có những lúc bạn thấy mình chỉ biết thốt lên \\"Chúa ơi\\" và không biết nói gì thêm. Điều ấy cũng đủ để Ngài đến gần. Hôm nay, nếu lòng bạn nặng nề, hãy kêu cầu Ngài như một đứa trẻ gọi cha. Bạn sẽ nhận ra rằng Ngài đã ở bên cạnh từ lâu, đang chờ nghe tiếng bạn gọi. Sự chân thật là ngôn ngữ mà Chúa hiểu rõ nhất.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ở gần mọi người kêu cầu Ngài cách thành thật. Xin giúp con đến với Ngài chân thành, ngay cả khi con chỉ biết nói: Chúa ơi, xin ở gần con. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":147,"cau":3,"loi_kinh_thanh":"Chữa lành người có lòng đau thương, Và bó vít của họ.","bai_hoc":"\\"Chữa lành người có lòng đau thương, Và bó vít của họ\\" Hãy hình dung Chúa như một người cẩn thận băng bó vết thương, nhẹ nhàng, kiên nhẫn, không vội vã. Có những vết thương không ai nhìn thấy: sự mất mát, lời nói làm tổn thương, những năm tháng cô đơn. Chúa thấy tất cả. Ngài không đòi bạn phải quên đi hay mạnh mẽ ngay lập tức. Ngài chăm sóc từng chút một. Hôm nay, hãy để Ngài chạm vào nơi đau nhất của bạn. Bạn không cần nói nhiều, chỉ cần mở lòng và để Ngài chữa lành bằng tình yêu của Ngài.","loi_cau_nguyen":"Chúa ơi, xin chữa lành những nỗi đau trong lòng con và băng bó vết thương của con. Xin chạm vào những nơi con khó nói thành lời, bằng sự dịu dàng của Ngài. A-men."},{"sach":"Thi Thiên","ma":"PSA","chuong":150,"cau":6,"loi_kinh_thanh":"Phàm vật chi thở, hãy ngợi khen Đức Giê-hô-va! Ha-lê-lu-gia!","bai_hoc":"\\"Phàm vật chi thở hãy ngợi khen Đức Giê-hô-va.\\" Đây là câu cuối của sách Thi Thiên, và nó nói rất đơn giản: nếu bạn còn thở, bạn có lý do để ngợi khen. Mỗi hơi thở là một món quà. Có những ngày bạn không có gì đặc biệt để vui, nhưng bạn vẫn thở, vẫn ở đây, vẫn được Chúa yêu thương. Hôm nay, hãy thử dừng lại giữa ngày, hít một hơi thật sâu và thầm nói: \\"Cảm ơn Chúa.\\" Chỉ đơn giản thế thôi. Đó là một bài ca ngợi khen, và Chúa rất vui khi nghe nó từ bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về từng hơi thở của con. Xin giúp con dâng một lời ngợi khen cho Ngài hôm nay, và sống như người có lý do để tạ ơn. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":1,"cau":7,"loi_kinh_thanh":"Sự kính sợ Đức Giê-hô-va là khởi đầu sự tri thức; Còn kẻ ngu muội khinh bỉ sự khôn ngoan và lời khuyên dạy.","bai_hoc":"\\"Sự kính sợ Đức Giê-hô-va là khởi đầu sự tri thức; Còn kẻ ngu muội khinh bỉ sự khôn ngoan và lời khuyên dạy\\" Kính sợ ở đây không phải là run rẩy trước một vị chủ khắt khe, mà là sự tôn trọng sâu xa dành cho Đấng vĩ đại và yêu thương. Khôn ngoan không bắt đầu từ việc biết nhiều điều, mà từ việc đứng đúng chỗ trước mặt Chúa. Khi bạn nhận ra Ngài lớn hơn mình, nhiều áp lực phải biết hết mọi thứ sẽ nhẹ đi. Bạn có thể học hỏi, hỏi han, và vẫn yên lòng vì có Ngài dẫn dắt. Hôm nay, trước khi bước vào một quyết định, hãy dừng lại và hỏi: điều này có đặt Chúa ở đúng vị trí trong lòng tôi không?","loi_cau_nguyen":"Chúa ơi, xin cho con lòng kính sợ Ngài là khởi đầu của sự khôn ngoan. Xin giúp con hỏi ý Ngài trước khi quyết định, và khiêm nhường học hỏi mỗi ngày. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":3,"cau":5,"loi_kinh_thanh":"Hãy hết lòng tin cậy Đức Giê-hô-va, Chớ nương cậy nơi sự thông sáng của con;","bai_hoc":"\\"Hãy hết lòng tin cậy Đức Giê-hô-va, chớ nương cậy nơi sự thông sáng của con.\\" Có những lúc chúng ta muốn tính toán mọi thứ cho chắc chắn: kế hoạch, tiền bạc, tương lai. Kinh Thánh không bảo bạn đừng suy nghĩ, mà bảo bạn đừng chỉ dựa vào sự hiểu biết giới hạn của mình. Có những điều bạn không thể thấy hết, nhưng Chúa thấy. Tin cậy Ngài là một hành động của lòng, như đứa trẻ nắm tay cha khi băng qua đường đông. Hôm nay, nếu có một điều khiến bạn trăn trở, hãy thử nói với Chúa: \\"Con trao điều này cho Ngài,\\" rồi tiếp tục bước đi với lòng nhẹ hơn.","loi_cau_nguyen":"Chúa ơi, con muốn hết lòng tin cậy Ngài. Khi con cố tự tính toán mọi thứ, xin nhắc con rằng Ngài thấy điều con không thấy, và giúp con buông bớt sự lo lắng. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":3,"cau":6,"loi_kinh_thanh":"Phàm trong các việc làm của con, khá nhận biết Ngài, Thì Ngài sẽ chỉ dẫn các nẻo của con.","bai_hoc":"\\"Phàm trong các việc làm của con, khá nhận biết Ngài, thì Ngài sẽ chỉ dẫn các nẻo của con.\\" Nhận biết Chúa trong mọi việc nghĩa là mời Ngài vào cả những điều nhỏ nhặt: một cuộc trò chuyện, một lựa chọn công việc, một buổi chiều bình thường. Ngài không chỉ quan tâm đến những quyết định lớn. Khi bạn đưa Chúa vào từng việc, bạn dần học cách nghe tiếng Ngài và đi theo hướng Ngài chỉ. Con đường có thể không thẳng tắp, nhưng bạn không đi một mình. Hôm nay, hãy chọn một việc bạn sắp làm và thầm nói: \\"Chúa ơi, xin đi cùng con trong việc này.\\"","loi_cau_nguyen":"Chúa ơi, xin giúp con nhận biết Ngài trong mọi việc, lớn và nhỏ. Xin chỉ dẫn các nẻo của con, và cho con nhạy bén để nghe tiếng Ngài trong ngày hôm nay. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":4,"cau":23,"loi_kinh_thanh":"Khá cẩn thận giữ tấm lòng của con hơn hết, Vì các nguồn sự sống do nơi nó mà ra.","bai_hoc":"\\"Khá cẩn thận giữ tấm lòng của con hơn hết, Vì các nguồn sự sống do nơi nó mà ra\\" Lòng như một mạch nước: nếu nguồn trong thì dòng nước trong, nếu nguồn đục thì cả dòng đều đục. Những gì bạn nhìn, nghe, nghĩ và nuôi dưỡng mỗi ngày đang chảy vào đó. Giữ lòng không có nghĩa là khép kín, mà là cẩn thận chọn điều gì được vào. Có những nội dung, những cuộc trò chuyện, những thói quen làm lòng ta nặng nề; cũng có những điều làm ta bình an. Hôm nay, hãy chọn một điều nuôi dưỡng lòng mình: một bản thánh ca, một đoạn Kinh Thánh, một cuộc trò chuyện chân thành.","loi_cau_nguyen":"Chúa ơi, xin giúp con gìn giữ lòng mình hơn mọi điều. Xin cho con biết chọn những điều nuôi dưỡng đức tin và bình an, và xin Ngài thanh tẩy những gì làm lòng con đục. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":6,"cau":6,"loi_kinh_thanh":"Hỡi kẻ biếng nhác, hãy đi đến loài kiến; Khá xem xét cách ăn ở nó mà học khôn ngoan.","bai_hoc":"\\"Hỡi kẻ biếng nhác, hãy đi đến loài kiến; khá xem xét cách ăn ở nó mà học khôn ngoan.\\" Câu này dùng hình ảnh con kiến nhỏ bé để nói về sự siêng năng và biết chuẩn bị, không cần ai thúc giục. Đó không phải lời trách mắng nặng nề, mà là lời mời học từ thiên nhiên. Siêng năng không có nghĩa là làm việc đến kiệt sức, mà là kiên trì làm những việc nhỏ đúng lúc. Có thể có một việc bạn vẫn trì hoãn: một cuộc gọi, một bài học, một thói quen tốt. Hôm nay, hãy làm một bước nhỏ như con kiến mang một hạt: nhỏ thôi, nhưng đều đặn và có hướng.","loi_cau_nguyen":"Chúa ơi, xin giúp con siêng năng và biết chuẩn bị. Xin cho con can đảm bắt đầu một việc con vẫn trì hoãn, từng bước nhỏ và kiên nhẫn. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":9,"cau":10,"loi_kinh_thanh":"Kính sợ Đức Giê-hô-va, ấy là khởi đầu sự khôn ngoan; Sự nhìn biết Đấng Thánh, đó là sự thông sáng.","bai_hoc":"\\"Kính sợ Đức Giê-hô-va, ấy là khởi đầu sự khôn ngoan; Sự nhìn biết Đấng Thánh, đó là sự thông sáng\\" Khôn ngoan thật không chỉ là kiến thức, mà là biết Ai đang ở trung tâm của mọi sự. Khi bạn dần biết Chúa sâu sắc hơn, cách bạn nhìn công việc, tiền bạc, các mối quan hệ cũng được sắp xếp lại. Sự thông sáng đến từ việc ở gần Ngài. Bạn không cần phải là người thông minh nhất để khôn ngoan, chỉ cần là người biết Chúa. Hôm nay, hãy dành vài phút để biết Ngài hơn: đọc một đoạn Kinh Thánh, ngồi yên cầu nguyện, hoặc nhớ lại điều Ngài đã làm.","loi_cau_nguyen":"Chúa ơi, xin cho con biết Ngài sâu sắc hơn. Xin giúp con kính sợ Ngài, và để sự nhận biết Ngài mang lại cho con sự thông sáng trong mọi quyết định. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":10,"cau":12,"loi_kinh_thanh":"Sự ghen ghét xui điều cãi lộn; Song lòng thương yêu lấp hết các tội phạm.","bai_hoc":"\\"Sự ghen ghét xui điều cãi lộn; Song lòng thương yêu lấp hết các tội phạm\\" Một cuộc cãi vã thường bắt đầu từ một vết thương cũ chưa lành, từ sự ghen tị hay giận dữ âm ỉ. Còn tình yêu thương có sức mạnh lạ lùng: nó không bỏ qua cái sai, nhưng sẵn lòng tha thứ và không phô bày lỗi lầm của người khác. Yêu thương không có nghĩa là im lặng cam chịu, mà là chọn cách cư xử xây dựng thay vì làm tổn thương. Hôm nay, nếu có một mối quan hệ đang căng thẳng, hãy thử bắt đầu bằng một lời dịu dàng, thay vì một lời trách móc.","loi_cau_nguyen":"Chúa ơi, xin làm lòng con mềm ra. Xin giúp con chọn yêu thương thay vì ghen ghét hay giận hờn, và cho con can đảm làm hòa trong những mối quan hệ căng thẳng. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":11,"cau":25,"loi_kinh_thanh":"Lòng rộng rãi sẽ được no nê; Còn ai nhuần gội, chính người sẽ được nhuần gội.","bai_hoc":"Ai ban phước cho kẻ khác sẽ được no đủ, và ai tưới nước cho kẻ khác chính mình cũng được tưới nước. Có một điều kỳ lạ trong nước Chúa: khi bạn cho đi, bạn không nghèo đi mà thường lại được làm giàu theo cách bạn không ngờ. Không phải lúc nào cũng bằng tiền bạc, mà bằng niềm vui, bằng tình bạn, bằng sự bình an. Cho đi không cần phải lớn lao: một bữa ăn, một lời động viên, một khoảng thời gian lắng nghe. Hôm nay, hãy tìm một cơ hội nhỏ để tưới nước cho ai đó, và để ý xem lòng mình thay đổi thế nào.","loi_cau_nguyen":"Chúa ơi, xin cho con một tấm lòng rộng rãi. Xin chỉ cho con một người con có thể giúp đỡ hôm nay, và giúp con cho đi với niềm vui, không toan tính. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":13,"cau":12,"loi_kinh_thanh":"Sự trông cậy trì hoãn khiến lòng bị đau đớn; Nhưng khi sự ước ao được thành, thì giống như một cây sự sống.","bai_hoc":"\\"Sự trông cậy trì hoãn khiến lòng bị đau đớn; Nhưng khi sự ước ao được thành, thì giống như một cây sự sống\\" Chờ đợi mà không thấy kết quả làm lòng ta mệt mỏi, và Kinh Thánh thừa nhận điều đó thật thà. Chúa không bảo bạn rằng chờ đợi là dễ. Nhưng Ngài cũng hứa rằng khi điều mong ước được thành, nó đem lại sự sống mới. Giữa thời gian chờ, hãy cho phép mình mệt, rồi hãy trở lại với Chúa. Ngài không bao giờ xem thường niềm hy vọng của bạn. Hôm nay, nếu bạn đang chờ một điều gì, hãy nói thật với Ngài về cảm giác ấy, và xin Ngài giữ lòng bạn khỏi chai sạn.","loi_cau_nguyen":"Chúa ơi, có những điều con đang chờ đợi và lòng con mỏi mệt. Xin giữ hy vọng trong con khỏi tàn lụi, và giúp con kiên nhẫn tin cậy thời điểm của Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":14,"cau":12,"loi_kinh_thanh":"Có một con đường coi dường chánh đáng cho loài người; Nhưng đến cuối cùng nó thành ra nẻo sự chết.","bai_hoc":"\\"Có một con đường coi dường chánh đáng cho loài người; Nhưng đến cuối cùng nó thành ra nẻo sự chết\\" Cảm giác chắc chắn không phải lúc nào cũng đáng tin. Có những lựa chọn trông hợp lý, nhiều người cùng làm, mình cũng thấy ổn, nhưng cuối cùng lại dẫn đến đau đớn. Lời này không nhằm làm bạn sợ hãi, mà nhắc bạn khiêm nhường: hãy xem xét ý Chúa thay vì chỉ dựa vào cảm xúc hay số đông. Khi bạn dành thời gian cầu nguyện và tìm lời khuyên khôn ngoan, bạn đang bảo vệ chính mình. Hôm nay, trước một quyết định quan trọng, hãy hỏi Chúa và một người bạn đáng tin.","loi_cau_nguyen":"Chúa ơi, xin giúp con không chỉ dựa vào cảm giác của mình. Xin dẫn con vào con đường thật sự ngay thẳng, và cho con khiêm nhường nghe lời khuyên khôn ngoan. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":14,"cau":34,"loi_kinh_thanh":"Sự công bình làm cho nước cao trọng; Song tội lỗi là sự hổ thẹn cho các dân tộc.","bai_hoc":"\\"Sự công bình làm cho nước cao trọng; Song tội lỗi là sự hổ thẹn cho các dân tộc\\" Một đất nước mạnh không chỉ nhờ kinh tế hay quân đội, mà nhờ những con người sống ngay thẳng, trung thực và tử tế. Điều đó bắt đầu từ từng gia đình, từng nơi làm việc, từng người. Bạn có thể nghĩ mình nhỏ bé, nhưng những lựa chọn ngay thẳng hằng ngày của bạn góp phần xây dựng điều lớn lao. Sự công bình là gieo hạt giống cho tương lai. Hôm nay, hãy chọn sự trung thực trong một việc nhỏ, và cầu nguyện cho đất nước, cho những người lãnh đạo.","loi_cau_nguyen":"Chúa ơi, xin ban sự công bình và lòng ngay thẳng cho đất nước chúng con. Xin giúp con sống trung thực và tử tế trong gia đình, công việc và cộng đồng. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":15,"cau":1,"loi_kinh_thanh":"Lời đáp êm nhẹ làm nguôi cơn giận; Còn lời xẳng xớm trêu thạnh nộ thêm.","bai_hoc":"\\"Lời đáp êm nhẹ làm nguôi cơn giận; Còn lời xẳng xớm trêu thạnh nộ thêm\\" Có những lúc cuộc trò chuyện sắp bùng cháy, và chỉ cần một câu nhẹ nhàng cũng đủ làm nguội đi. Dịu dàng không phải là yếu đuối, mà là sức mạnh biết kiềm chế. Một giọng nói bình tĩnh có thể thay đổi cả bầu không khí trong gia đình hay nơi làm việc. Khi bạn thấy mình sắp phản ứng gay gắt, hãy dừng lại một nhịp, hít một hơi, rồi chọn lời. Chúa hiểu việc ấy khó, và Ngài sẵn sàng giúp bạn. Hôm nay, hãy thử đáp lại bằng sự dịu dàng, đặc biệt khi bạn thấy mình bị khích động.","loi_cau_nguyen":"Chúa ơi, xin đặt sự dịu dàng vào môi miệng con. Khi con sắp nói lời gay gắt, xin giúp con dừng lại, hít thở, và chọn lời làm nguôi giận thay vì thêm lửa. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":16,"cau":3,"loi_kinh_thanh":"Hãy phó các việc mình cho Đức Giê-hô-va, Thì những mưu ý mình sẽ được thành công.","bai_hoc":"\\"Hãy phó các việc mình cho Đức Giê-hô-va, Thì những mưu ý mình sẽ được thành công\\" Phó thác không phải là ngồi chờ phép lạ, mà là làm việc với lòng dâng cho Chúa. Khi bạn bắt đầu một dự định bằng cách trao nó cho Ngài, bạn đang mời Ngài định hướng, chỉnh sửa và chúc phước cho nó. Có những kế hoạch của bạn sẽ thay đổi, và đó cũng là một cách Chúa dẫn dắt. Điều quan trọng là lòng bạn yên nghỉ trong Ngài, dù kết quả thế nào. Hôm nay, hãy chọn một công việc hay kế hoạch, thầm cầu nguyện dâng nó cho Chúa, rồi bắt tay làm với sự bình an.","loi_cau_nguyen":"Chúa ơi, con dâng công việc và những dự định của con cho Ngài. Xin hướng dẫn và chỉnh sửa chúng theo ý Ngài, và giúp lòng con yên nghỉ dù kết quả ra sao. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":16,"cau":9,"loi_kinh_thanh":"Lòng người toan định đường lối mình; Song Đức Giê-hô-va chỉ dẫn các bước của người.","bai_hoc":"\\"Lòng người toan định đường lối mình; Song Đức Giê-hô-va chỉ dẫn các bước của người\\" Chúng ta được phép lập kế hoạch, mơ ước, tính toán. Nhưng cuối cùng, chính Chúa là Đấng chỉ dẫn từng bước đi. Điều này vừa làm lòng nhẹ nhõm, vừa mời gọi sự khiêm nhường: kế hoạch của bạn không phải điều quyết định tất cả. Khi mọi việc không đi đúng như dự định, đừng vội thất vọng, có thể Chúa đang dẫn bạn đi một con đường khác tốt hơn. Hôm nay, hãy làm phần mình với tâm trí sẵn sàng thay đổi, và tin rằng Ngài đang dẫn bước chân bạn.","loi_cau_nguyen":"Chúa ơi, con có thể lập kế hoạch, nhưng chính Ngài chỉ dẫn các bước chân con. Xin giúp con sẵn lòng thay đổi khi Ngài dẫn con đi hướng khác, và tin cậy Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":16,"cau":18,"loi_kinh_thanh":"Sự kiêu ngạo đi trước, sự bại hoại theo sau, Và tánh tự cao đi trước sự sa ngã.","bai_hoc":"\\"Sự kiêu ngạo đi trước, sự bại hoại theo sau, Và tánh tự cao đi trước sự sa ngã\\" Đây là lời cảnh báo nhẹ nhàng nhưng thật. Kiêu ngạo thường len lỏi rất âm thầm: ta nghĩ mình không cần ai, mình luôn đúng, mình không cần học hỏi. Khiêm nhường không có nghĩa là tự hạ thấp mình, mà là nhận ra mình cần Chúa và cần người khác. Người khiêm nhường dễ được dạy dỗ, và vì thế dễ trưởng thành. Hôm nay, hãy thử nói một lời cảm ơn hay thừa nhận một sai sót nhỏ. Sự khiêm nhường ấy giúp bạn đứng vững hơn nhiều so với sự kiêu hãnh.","loi_cau_nguyen":"Chúa ơi, xin giữ con khỏi sự kiêu ngạo. Xin cho con lòng khiêm nhường, biết thừa nhận mình cần Ngài và cần người khác, và sẵn sàng học hỏi. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":17,"cau":17,"loi_kinh_thanh":"Bằng hữu thương mến nhau luôn luôn; Và anh em sanh ra để giúp đỡ trong lúc hoạn nạn.","bai_hoc":"\\"Bằng hữu thương mến nhau luôn luôn; Và anh em sanh ra để giúp đỡ trong lúc hoạn nạn\\" Tình bạn thật không chỉ hiện ra lúc vui vẻ, mà càng rõ hơn khi khó khăn. Có thể bạn có một người bạn đã ở bên bạn qua nhiều giai đoạn, hãy trân trọng họ. Cũng có thể bạn đang là người đồng hành cho ai đó trong lúc họ khó khăn. Dù ít lời, sự có mặt của bạn có giá trị rất lớn. Hôm nay, hãy nhắn tin hoặc gọi cho một người bạn, hỏi thăm họ thật lòng, hoặc nói lời cảm ơn vì sự đồng hành của họ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về những người bạn trung tín. Xin giúp con trở thành người bạn đáng tin cậy, ở bên người khác cả lúc khó khăn, và biết trân trọng họ. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":17,"cau":22,"loi_kinh_thanh":"Lòng vui mừng vốn một phương thuốc hay; Còn trí nao sờn làm xương cốt khô héo.","bai_hoc":"\\"Lòng vui mừng vốn một phương thuốc hay; Còn trí nao sờn làm xương cốt khô héo\\" Niềm vui ảnh hưởng đến cả thân thể. Điều đó không có nghĩa là bạn phải luôn vui, hay phải che giấu nỗi buồn. Nhưng lòng biết ơn, tiếng cười và những khoảnh khắc nhẹ nhàng thật sự là một món thuốc Chúa ban. Ngay cả trong thời gian khó khăn, bạn vẫn có thể tìm thấy một chút niềm vui: một ly trà ấm, một bản nhạc hay, một câu chuyện vui cùng người thân. Hôm nay, hãy cho phép mình có một khoảnh khắc nhẹ nhàng, và đón nhận nó như món quà từ Chúa.","loi_cau_nguyen":"Chúa ơi, xin ban cho con một tấm lòng vui mừng, ngay cả giữa những ngày khó khăn. Xin giúp con tìm thấy niềm vui trong những điều nhỏ bé Ngài ban hôm nay. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":18,"cau":10,"loi_kinh_thanh":"Danh Đức Giê-hô-va vốn một ngọn tháp kiên cố; Kẻ công bình chạy đến đó, gặp được nơi ẩn trú cao.","bai_hoc":"\\"Danh Đức Giê-hô-va vốn một ngọn tháp kiên cố; Kẻ công bình chạy đến đó, gặp được nơi ẩn trú cao\\" Khi gặp nguy hiểm, người ta chạy về nơi an toàn nhất. Đối với người tin, nơi ấy là danh Chúa. Gọi danh Ngài không phải là một câu thần chú, mà là bước chạy đến với một Đấng đáng tin cậy. Khi nỗi sợ hay lo âu ập đến, bạn không cần phải tự xây tường bảo vệ, chỉ cần chạy về phía Ngài. Hôm nay, nếu lòng bạn bất an, hãy thầm gọi danh Chúa Giê-su thật chậm rãi, và để lòng bạn nghỉ ngơi trong sự bảo vệ của Ngài.","loi_cau_nguyen":"Chúa ơi, danh Ngài là ngọn tháp vững bền của con. Khi lo sợ ập đến, xin giúp con chạy đến với Ngài ngay, và tìm thấy sự yên ổn nơi Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":18,"cau":21,"loi_kinh_thanh":"Sống chết ở nơi quyền của lưỡi; Kẻ ái mộ nó sẽ ăn bông trái của nó.","bai_hoc":"\\"Sống chết ở nơi quyền của lưỡi; Kẻ ái mộ nó sẽ ăn bông trái của nó\\" Lời nói có sức mạnh lớn: một câu có thể nâng người ta lên hoặc đè người ta xuống. Có những lời bạn từng nghe vẫn còn theo bạn nhiều năm, và có những lời bạn nói ra cũng vậy. Hôm nay, hãy chọn dùng lời nói để mang sự sống: một lời khen chân thành, một lời cảm ơn, một lời động viên. Cũng đừng quên cách bạn nói với chính mình. Hãy nói với bản thân bằng sự dịu dàng, như Chúa nói với bạn. Lời nói tử tế là một hạt giống nhỏ có thể nở hoa trong lòng người khác.","loi_cau_nguyen":"Chúa ơi, xin canh giữ lưỡi con. Xin giúp con dùng lời nói để mang lại sự sống, nâng đỡ người khác, và biết nói với chính mình bằng sự dịu dàng như Ngài nói với con. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":18,"cau":24,"loi_kinh_thanh":"Người nào được nhiều bằng hữu sẽ làm hại cho mình; Nhưng có một bạn tríu mến hơn anh em ruột.","bai_hoc":"\\"Người nào được nhiều bằng hữu sẽ làm hại cho mình; Nhưng có một bạn tríu mến hơn anh em ruột\\" Không phải ai ở bên bạn cũng là người bạn thật. Có những mối quan hệ thoáng qua, và có những người gắn bó sâu sắc hơn cả anh em. Hãy trân trọng những người như vậy và cũng hãy cố gắng trở thành người bạn như vậy. Tình bạn keo sơn cần thời gian, sự thật thà và lòng trung tín. Chúa Giê-su cũng gọi các môn đồ là bạn. Hôm nay, hãy nghĩ đến một người bạn đáng quý và làm điều gì đó nhỏ để nói với họ: bạn có ý nghĩa với tôi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Người Bạn trung tín nhất của con. Xin giúp con biết trân trọng những người bạn thật, và trở thành người bạn gắn bó, chân thành với người khác. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":19,"cau":21,"loi_kinh_thanh":"Trong lòng loài người có nhiều mưu kế; Song ý chỉ của Đức Giê-hô-va sẽ thành được.","bai_hoc":"\\"Trong lòng loài người có nhiều mưu kế; Song ý chỉ của Đức Giê-hô-va sẽ thành được\\" Chúng ta có nhiều ý định, kế hoạch và ước mơ, và đó không phải điều xấu. Nhưng cuối cùng điều đứng vững là điều hợp ý Chúa. Điều này nhắc ta cầu nguyện không chỉ để xin Chúa chúc phước cho kế hoạch mình, mà để hỏi Ngài muốn gì. Khi bạn đặt ý muốn của Chúa lên trên, lòng bạn nhẹ hơn, vì bạn không phải gánh trách nhiệm làm mọi thứ thành công. Hôm nay, hãy thử cầu nguyện: \\"Chúa ơi, ý Ngài muốn con làm gì?\\" và lắng nghe.","loi_cau_nguyen":"Chúa ơi, con có nhiều dự định, nhưng con muốn điều Ngài muốn. Xin giúp con hiểu ý Ngài, và có lòng sẵn sàng đi theo, dù có khác với kế hoạch của con. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":22,"cau":1,"loi_kinh_thanh":"Danh tiếng tốt còn hơn tiền của nhiều; Và ơn nghĩa quí hơn bạc và vàng.","bai_hoc":"\\"Danh tiếng tốt còn hơn tiền của nhiều; Và ơn nghĩa quí hơn bạc và vàng\\" Danh tiếng ở đây không phải là nổi tiếng, mà là uy tín: người ta biết bạn đáng tin, ngay thẳng, tử tế. Điều đó được xây nên từ những việc nhỏ hằng ngày: giữ lời hứa, nói thật, đối xử công bằng. Uy tín mất nhiều năm để xây và có thể mất nhanh chóng. Nhưng nó quý hơn bất kỳ khoản tiền nào. Hôm nay, hãy thử giữ một lời hứa nhỏ hoặc làm một việc đúng dù không ai nhìn thấy. Đó là cách bạn dần xây dựng điều quý giá hơn vàng bạc.","loi_cau_nguyen":"Chúa ơi, xin giúp con giữ danh tiếng tốt bằng cách sống ngay thẳng và đáng tin. Xin cho con trung thực trong những việc nhỏ, ngay cả khi không ai nhìn thấy. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":22,"cau":6,"loi_kinh_thanh":"Hãy dạy cho trẻ thơ con đường nó phải theo; Dầu khi nó trở về già, cũng không hề lìa khỏi đó.","bai_hoc":"\\"Hãy dạy cho trẻ thơ con đường nó phải theo; Dầu khi nó trở về già, cũng không hề lìa khỏi đó\\" Đây là một nguyên tắc khôn ngoan về việc nuôi dạy, không phải lời hứa tuyệt đối mà bạn có thể dùng để tự trách. Con cái có ý chí riêng, và có những đứa trẻ đi lạc dù được dạy dỗ rất cẩn thận. Điều Kinh Thánh khuyến khích là kiên nhẫn gieo hạt giống đúng đắn bằng lời nói và bằng chính tấm gương của mình. Phần còn lại, hãy trao cho Chúa. Hôm nay, hãy làm một điều nhỏ để chỉ đường cho một đứa trẻ trong đời bạn, bằng sự dịu dàng, và cầu nguyện cho em.","loi_cau_nguyen":"Chúa ơi, xin giúp con dạy dỗ trẻ nhỏ bằng lời nói và tấm gương sống của con. Con trao phần con không kiểm soát được cho Ngài, và xin Ngài giữ gìn các em. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":27,"cau":1,"loi_kinh_thanh":"Chớ khoe khoang về ngày mai; Vì con chẳng biết ngày mai sẽ sanh ra điều gì.","bai_hoc":"\\"Chớ khoe khoang về ngày mai; Vì con chẳng biết ngày mai sẽ sanh ra điều gì\\" Chúng ta thường lập kế hoạch như thể có thể điều khiển tương lai, nhưng ngày mai thuộc về Chúa. Lời này không bảo bạn đừng lập kế hoạch, mà mời bạn sống khiêm nhường và biết ơn hôm nay. Có những điều bạn muốn làm, muốn nói, muốn sửa, đừng đợi đến mai. Và cũng đừng lo lắng quá về ngày mai, vì Chúa đang cầm giữ nó. Hôm nay, hãy làm một điều quan trọng mà bạn vẫn để dành cho sau này, và nói với Chúa: Tương lai thuộc về Ngài.","loi_cau_nguyen":"Chúa ơi, ngày mai thuộc về Ngài. Xin giúp con sống khiêm nhường và biết ơn hôm nay, làm điều cần làm ngay, và để tương lai trong tay Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":27,"cau":17,"loi_kinh_thanh":"Sắt mài nhọn sắt. Cũng vậy người bổ dưỡng diện mạo bạn hữu mình.","bai_hoc":"\\"Sắt mài nhọn sắt. Cũng vậy người bổ dưỡng diện mạo bạn hữu mình\\" Bạn bè tốt không chỉ làm ta vui, mà còn giúp ta trưởng thành. Đôi khi họ nói điều khó nghe, nhắc ta điều ta quên, hoặc thách thức ta nhìn khác đi. Điều đó có thể khó chịu, nhưng là dấu hiệu của tình bạn thật. Hãy trân trọng người dám nói thẳng với bạn bằng tình yêu thương, và cũng đừng ngại làm điều đó với bạn bè mình, bằng sự dịu dàng và chân thành. Hôm nay, hãy hỏi một người bạn đáng tin: tôi có thể làm tốt hơn ở điểm nào?","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về những người giúp con trưởng thành. Xin cho con lòng khiêm nhường để nghe lời khuyên, và sự khôn ngoan để giúp bạn bè con bằng tình yêu. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":28,"cau":13,"loi_kinh_thanh":"Người nào giấu tội lỗi mình sẽ không được may mắn; Nhưng ai xưng nó ra và lìa bỏ nó sẽ được thương xót.","bai_hoc":"\\"Người nào giấu tội lỗi mình sẽ không được may mắn; Nhưng ai xưng nó ra và lìa bỏ nó sẽ được thương xót\\" Giấu giếm là một gánh nặng. Điều gì đó bạn đang che đậy, cho dù nhỏ, cũng chiếm một góc trong tâm trí và làm lòng bạn không yên. Chúa không muốn bạn mang gánh ấy. Ngài mời bạn nói thật, vì Ngài muốn tha thứ và chữa lành. Xưng tội không phải để bị phán xét, mà để được tự do. Hôm nay, nếu có điều gì bạn đang giấu, hãy thì thầm với Chúa. Ngài đón nhận bạn bằng lòng thương xót, và bạn sẽ thấy lòng nhẹ đi.","loi_cau_nguyen":"Chúa ơi, con thành thật với Ngài về những điều con đã giấu. Xin tha thứ, ban cho con sức mạnh để từ bỏ điều sai, và cho con nhận lấy lòng thương xót của Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":29,"cau":18,"loi_kinh_thanh":"Đâu thiếu sự mặc thị, dân sự bèn phóng tứ; Nhưng ai giữ gìn luật pháp lấy làm có phước thay!","bai_hoc":"Ở đâu không có khải tượng, dân sự phải phóng túng; nhưng ai giữ luật pháp có phước thay. Khải tượng là sự nhìn thấy hướng đi và mục đích Chúa dành cho mình. Khi không có phương hướng, con người dễ trôi dạt, chạy theo cảm xúc và cám dỗ. Bạn không cần biết toàn bộ đời mình, nhưng hãy hỏi Chúa: tôi sống để làm gì? Ngài sẽ dần cho bạn thấy. Lời Ngài là ngọn đèn giúp bạn giữ hướng. Hôm nay, hãy dành vài phút viết ra điều bạn thấy Chúa đang kêu gọi mình trong mùa này, dù chỉ là một điều nhỏ, và cầu nguyện cho điều đó.","loi_cau_nguyen":"Chúa ơi, xin ban cho con khải tượng và hướng đi trong cuộc đời. Xin giúp con giữ Lời Ngài làm kim chỉ nam, và sống với mục đích rõ ràng, theo ý Ngài. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":31,"cau":10,"loi_kinh_thanh":"Một người nữ tài đức ai sẽ tìm được? Giá trị nàng trổi hơn châu ngọc.","bai_hoc":"\\"Một người nữ tài đức ai sẽ tìm được? Giá trị nàng trổi hơn châu ngọc\\" Câu này mở đầu một bài thơ ngợi ca người phụ nữ đức hạnh, không phải vì vẻ đẹp, mà vì sự khôn ngoan, siêng năng, tử tế và trung tín. Cả bài thơ cho thấy giá trị thật nằm ở tính cách chứ không ở vẻ bề ngoài hay thành tích. Dù bạn là ai, nam hay nữ, đây là lời nhắc: hãy đầu tư vào những phẩm chất bền lâu. Hôm nay, hãy cảm ơn một người phụ nữ đã làm gương cho bạn bằng sự tử tế và trung tín, bằng một lời nói hay một cử chỉ nhỏ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về những người phụ nữ đức hạnh đã ảnh hưởng đến đời con. Xin giúp con trân trọng họ, và xây dựng tính cách bền vững, khôn ngoan và tử tế. A-men."},{"sach":"Châm Ngôn","ma":"PRO","chuong":31,"cau":30,"loi_kinh_thanh":"Duyên là giả dối, sắc lại hư không; Nhưng người nữ nào kính sợ Đức Giê-hô-va sẽ được khen ngợi.","bai_hoc":"\\"Duyên là giả dối, sắc lại hư không; Nhưng người nữ nào kính sợ Đức Giê-hô-va sẽ được khen ngợi\\" Vẻ ngoài sẽ phai nhạt theo thời gian, nhưng một tấm lòng kính sợ Chúa thì ngày càng đẹp hơn. Lời này giải thoát chúng ta khỏi áp lực phải luôn hoàn hảo về ngoại hình hay hình ảnh. Giá trị thật của một người nằm ở đức tin, lòng tử tế và sự khôn ngoan. Hôm nay, nếu bạn thấy mình bị cuốn vào việc so sánh vẻ bề ngoài, hãy nhớ rằng điều Chúa quý nhất là tấm lòng. Hãy chăm sóc nó hôm nay bằng một lời cầu nguyện hay một việc tốt.","loi_cau_nguyen":"Chúa ơi, xin giúp con không đặt giá trị mình vào vẻ bề ngoài. Xin cho con chăm sóc tấm lòng kính sợ Ngài, vì đó là điều đẹp nhất và bền lâu nhất. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":1,"cau":9,"loi_kinh_thanh":"Điều chi đã có, ấy là điều sẽ có; điều gì đã làm, ấy là điều sẽ làm nữa; chẳng có điều gì mới ở dưới mặt trời.","bai_hoc":"\\"Điều chi đã có, ấy là điều sẽ có; điều gì đã làm, ấy là điều sẽ làm nữa; chẳng có điều gì mới ở dưới mặt trời\\" Người viết sách Truyền Đạo nhìn đời sống bằng đôi mắt đã trải nhiều và thấy những vòng lặp quen thuộc: ngày nối ngày, người đến rồi đi. Lời này nghe hơi buồn, nhưng nó có một món quà: nó giải thoát ta khỏi ảo tưởng rằng thành tựu hay sự mới lạ sẽ lấp đầy lòng mình. Chỉ có Chúa mới làm lòng ta thỏa nguyện thật sự. Hôm nay, nếu bạn thấy ngày tháng trôi qua giống nhau, hãy thử tìm Chúa trong sự bình thường ấy, và để Ngài làm cho nó có ý nghĩa.","loi_cau_nguyen":"Chúa ơi, khi đời sống có vẻ lặp đi lặp lại, xin giúp con đừng tìm sự thỏa lòng ở những điều phù du. Xin cho con tìm thấy ý nghĩa và niềm vui trong Ngài. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":3,"cau":1,"loi_kinh_thanh":"Phàm sự gì có thì tiết; mọi việc dưới trời có kỳ định.","bai_hoc":"\\"Phàm sự gì có thì tiết; mọi việc dưới trời có kỳ định\\" Có thì khóc và thì cười, thì gieo và thì gặt, thì ôm ấp và thì buông tay. Câu Kinh Thánh này nhắc rằng mình không cần phải ở một mùa nào mãi mãi, và cũng không cần ép mình sống mùa này như thể nó là mùa khác. Nếu bạn đang ở trong mùa khó khăn, nó sẽ có lúc qua. Nếu bạn đang ở mùa vui, hãy trân trọng nó. Chúa ở trong mọi mùa với bạn. Hôm nay, hãy hỏi mình: tôi đang ở mùa nào? Và xin Chúa giúp bạn sống trọn vẹn mùa ấy, với sự biết ơn và kiên nhẫn.","loi_cau_nguyen":"Chúa ơi, xin giúp con nhận biết mùa mình đang sống và sống trọn vẹn trong đó. Xin ở cùng con trong mọi mùa, và cho con kiên nhẫn chờ mùa mới theo thời Ngài. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":3,"cau":11,"loi_kinh_thanh":"Phàm vật Đức Chúa Trời đã làm nên đều là tốt lành trong thì nó. Lại, Ngài khiến cho sự đời đời ở nơi lòng loài người; dầu vậy, công việc Đức Chúa Trời làm từ ban đầu đến cuối cùng, người không thế hiểu được.","bai_hoc":"\\"Phàm vật Đức Chúa Trời đã làm nên đều là tốt lành trong thì nó. Lại, Ngài khiến cho sự đời đời ở nơi lòng loài người; dầu vậy, công việc Đức Chúa Trời làm từ ban đầu đến cuối cùng, người không thế hiểu được\\" Có một khao khát sâu xa trong lòng người: muốn điều gì đó vượt qua thời gian, muốn một ý nghĩa lớn hơn những việc hằng ngày. Đó không phải sự bất mãn vô cớ, mà là dấu ấn Chúa đặt trong ta để chúng ta tìm đến Ngài. Khi bạn cảm thấy có điều gì đó còn thiếu dù mọi thứ có vẻ ổn, có thể đó là tiếng gọi của sự đời đời. Hôm nay, hãy lắng nghe khao khát ấy và mang nó đến với Chúa. Ngài làm mọi sự đẹp đẽ đúng thời.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đặt khao khát đời đời trong lòng con. Xin giúp con tìm thấy sự thỏa lòng trong Ngài, và tin rằng Ngài làm mọi sự đẹp đẽ đúng thời của nó. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":4,"cau":9,"loi_kinh_thanh":"Hai người hơn một, vì họ sẽ được công giá tốt về công việc mình.","bai_hoc":"\\"Hai người hơn một, vì họ sẽ được công giá tốt về công việc mình\\" Cuộc sống đức tin không phải là hành trình đơn độc. Có người đồng hành, bạn có thêm sức khi mệt, có thêm sự khôn ngoan khi bối rối, và có thêm niềm vui khi chia sẻ. Có thể bạn đang làm một việc một mình quá lâu. Hãy mời ai đó cùng làm, hoặc ít nhất kể cho họ nghe. Và cũng hãy để ý xem ai đang cần bạn đồng hành. Hôm nay, hãy làm một việc nhỏ cùng một người khác, hoặc đơn giản là dành thời gian ở cùng họ, để cả hai cùng được nâng đỡ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã không để con đi một mình. Xin giúp con biết nhờ cậy và đồng hành với người khác, và cho con tìm được những người cùng bước đi với con. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":4,"cau":12,"loi_kinh_thanh":"Lại nếu kẻ ở một mình bị người khác thắng, thì hai người có thế chống cự nó; một sợi dây đánh ba tao lấy làm khó đứt.","bai_hoc":"\\"Lại nếu kẻ ở một mình bị người khác thắng, thì hai người có thế chống cự nó; một sợi dây đánh ba tao lấy làm khó đứt\\" Sợi dây thứ ba trong hôn nhân, tình bạn hay gia đình chính là Chúa. Khi hai người cùng đặt Chúa ở giữa, mối quan hệ có thêm sức để vượt qua sóng gió. Bạn không cần mối quan hệ hoàn hảo, chỉ cần để Chúa dệt nó lại khi nó sờn. Có thể có một mối quan hệ mong manh trong đời bạn. Hãy mời Chúa vào đó. Hôm nay, hãy cùng ai đó cầu nguyện, dù chỉ hai câu ngắn, và để sợi dây của Ngài làm mối quan hệ ấy vững chắc hơn.","loi_cau_nguyen":"Chúa ơi, xin ở giữa những mối quan hệ của con như sợi dây thứ ba. Xin bện chặt tình yêu, sự tha thứ và niềm tin giữa chúng con, để không dễ đứt trong sóng gió. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":9,"cau":10,"loi_kinh_thanh":"Mọi việc tay ngươi làm được, hãy làm hết sức mình; vì dưới âm phủ, là nơi ngươi đi đến, chẳng có việc làm, chẳng có mưu kế, cũng chẳng có tri thức, hay là sự khôn ngoan.","bai_hoc":"\\"Mọi việc tay ngươi làm được, hãy làm hết sức mình; vì dưới âm phủ, là nơi ngươi đi đến, chẳng có việc làm, chẳng có mưu kế, cũng chẳng có tri thức, hay là sự khôn ngoan\\" Công việc, dù nhỏ hay lớn, đều có thể là cách bạn dâng lên Chúa. Làm hết sức không có nghĩa là làm đến kiệt quệ, mà là làm với tấm lòng trọn vẹn thay vì qua loa. Khi bạn dồn tâm trí vào việc mình đang làm, dù là nấu ăn, chăm sóc con, hay một báo cáo công việc, bạn đang nói với Chúa rằng bạn trân trọng món quà thời gian Ngài ban. Hôm nay, hãy chọn một việc bạn thường làm vội, và thử làm nó chậm rãi và tận tâm như dâng cho Ngài.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm những việc trong tay con với trọn tấm lòng, không qua loa. Xin cho con trân trọng thời gian và cơ hội Ngài ban, và làm mọi việc như làm cho Ngài. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":11,"cau":1,"loi_kinh_thanh":"Hãy liệng bánh ngươi nơi mặt nước, vì khỏi lâu ngày ngươi sẽ tìm nó lại.","bai_hoc":"\\"Hãy ném bánh mình trên mặt nước, vì sau nhiều ngày con sẽ tìm lại được.\\" Đây là lời mời hào phóng: hãy cho đi mà không tính toán quá chặt chẽ. Có những điều tốt bạn làm hôm nay có thể không thấy kết quả ngay, nhưng không bao giờ uổng phí. Sự tử tế, lời cầu nguyện, sự giúp đỡ âm thầm của bạn đều được Chúa ghi nhớ và có thể trở lại theo những cách bạn không ngờ. Hôm nay, hãy làm một việc tốt mà không mong được đáp lại, và để Chúa lo phần còn lại.","loi_cau_nguyen":"Chúa ơi, xin cho con một tấm lòng rộng rãi, biết cho đi mà không tính toán. Xin giúp con tin rằng không điều tốt nào bị uổng phí, và Ngài sẽ lo phần kết quả. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":12,"cau":1,"loi_kinh_thanh":"Trong buổi còn thơ ấu hãy tưởng nhớ Đấng Tạo hóa ngươi, trước khi những ngày gian nan chưa đến, trước khi những năm tới mà ngươi nói rằng: Ta không lấy làm vui lòng;","bai_hoc":"\\"Trong buổi còn thơ ấu hãy tưởng nhớ Đấng Tạo hóa ngươi, trước khi những ngày gian nan chưa đến, trước khi những năm tới mà ngươi nói rằng: Ta không lấy làm vui lòng\\" Nhớ đến Chúa sớm là một món quà cho cả cuộc đời. Dù bạn đang ở tuổi nào, hôm nay vẫn là ngày trẻ nhất của phần đời còn lại. Đừng đợi đến khi mọi thứ ổn định, hay đến khi có thời gian rảnh, mới bắt đầu tìm Chúa. Ngài chờ đón bạn ngay bây giờ. Và nếu bạn là người trẻ, đây là lời khích lệ: dâng những năm tháng quý giá nhất cho Ngài là điều không bao giờ phí. Hôm nay, hãy dành một khoảnh khắc nhớ đến Đấng đã tạo nên bạn và nói lời cảm ơn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng Tạo Hóa của con. Xin giúp con nhớ đến Ngài sớm và mỗi ngày, và dâng những năm tháng của con cho Ngài với lòng biết ơn. A-men."},{"sach":"Giáo Huấn","ma":"ECC","chuong":12,"cau":13,"loi_kinh_thanh":"Chúng ta hãy nghe lời kết của lý thuyết nầy: Khá kính sợ Đức Chúa Trời và giữ các điều răn Ngài; ấy là trọn phận sự của ngươi.","bai_hoc":"\\"Chúng ta hãy nghe lời kết của lý thuyết nầy: Khá kính sợ Đức Chúa Trời và giữ các điều răn Ngài; ấy là trọn phận sự của ngươi\\" Sau tất cả những suy tư về đời sống, người viết rút ra một kết luận giản dị: sống kính sợ Chúa và vâng theo Ngài. Không cần phức tạp hóa. Khi mọi thứ dường như mơ hồ, bạn vẫn có thể tự hỏi: hôm nay tôi có đang sống đẹp lòng Chúa không? Điều đó đủ để định hướng cho bạn. Hôm nay, hãy chọn một điều Chúa mong bạn làm và làm điều ấy với lòng yêu mến.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống kính sợ Ngài và vâng theo đường lối Ngài. Khi mọi thứ phức tạp, xin cho con nhớ điều giản dị nhất: yêu mến Ngài và làm điều đẹp lòng Ngài. A-men."},{"sach":"Tình Ca","ma":"SNG","chuong":2,"cau":1,"loi_kinh_thanh":"Ta là hoa tường vi của Sa-rôn, Bông huệ của trũng.","bai_hoc":"\\"Ta là hoa tường vi của Sa-rôn, Bông huệ của trũng\\" Bài ca này kể về một tình yêu say đắm giữa hai người, và có thể được đọc cả như hình ảnh tình yêu của Chúa dành cho dân Ngài. Dù bạn đang ở trong một mối tình hay đang chờ đợi, hãy nhớ rằng bạn quý giá trước mắt Ngài. Có những lúc chúng ta thấy mình bình thường, nhưng người yêu thương thật thấy vẻ đẹp nơi ta. Hôm nay, hãy nhìn một người bạn yêu thương bằng ánh mắt trân trọng và nói với họ điều bạn thấy đẹp nơi họ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dạy con yêu và được yêu. Xin giúp con nhìn thấy vẻ đẹp nơi những người con thương, và trân trọng họ bằng lời nói chân thành. A-men."},{"sach":"Tình Ca","ma":"SNG","chuong":2,"cau":4,"loi_kinh_thanh":"Người đưa tôi vào phòng yến tiệc, Ngọn cờ người phất trên tôi ấy là ái tình.","bai_hoc":"\\"Người đưa tôi vào phòng yến tiệc, Ngọn cờ người phất trên tôi ấy là ái tình\\" Ngọn cờ là dấu hiệu công khai: người yêu tuyên bố rằng người ấy thuộc về mình, được bảo vệ và được yêu thương. Chúa cũng nhìn bạn như vậy. Ngài không giấu giếm tình yêu của Ngài dành cho bạn. Trong hôn nhân, đây là lời nhắc về tình yêu công khai, trân trọng và che chở. Hôm nay, hãy làm một cử chỉ nhỏ để thể hiện tình yêu một cách rõ ràng với người thân, hoặc hãy nhớ rằng bạn đang đứng dưới ngọn cờ tình yêu của Chúa.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài che chở con dưới ngọn cờ tình yêu của Ngài. Xin giúp con thể hiện tình yêu rõ ràng và chân thành với những người con thương. A-men."},{"sach":"Tình Ca","ma":"SNG","chuong":6,"cau":3,"loi_kinh_thanh":"Tôi thuộc về lương nhân tôi, Và lương nhân tôi thuộc về tôi; Người chăn bầy mình giữa đám hoa huệ.","bai_hoc":"\\"Tôi thuộc về lương nhân tôi, Và lương nhân tôi thuộc về tôi; Người chăn bầy mình giữa đám hoa huệ\\" Đây là sự thuộc về nhau, không phải sự chiếm hữu. Trong một tình yêu lành mạnh, hai người tự do chọn nhau và gắn bó với nhau. Điều đó đẹp, nhưng cũng đòi hỏi sự trung tín mỗi ngày. Và cuối cùng, mối quan hệ sâu sắc nhất chúng ta có là thuộc về Chúa, và Ngài thuộc về chúng ta. Ngài chọn bạn và không bao giờ bỏ bạn. Hôm nay, hãy nhớ rằng bạn thuộc về Ngài, và để điều đó làm lòng bạn vững vàng.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã chọn con và cho con thuộc về Ngài. Xin giúp con sống trung tín trong những mối quan hệ yêu thương của con, và vững lòng vì con là của Ngài. A-men."},{"sach":"Tình Ca","ma":"SNG","chuong":8,"cau":6,"loi_kinh_thanh":"Hãy để tôi như một cái ấn nơi lòng chàng, Như một cái ấn trên cánh tay chàng; Vì ái tình mạnh như sự chết, Lòng ghen hung dữ như âm phủ; Sự nóng nó là sự nóng của lửa, Thật một ngọn lửa của Đức Giê-hô-va.","bai_hoc":"\\"Hãy để tôi như một cái ấn nơi lòng chàng, Như một cái ấn trên cánh tay chàng; Vì ái tình mạnh như sự chết, Lòng ghen hung dữ như âm phủ; Sự nóng nó là sự nóng của lửa, Thật một ngọn lửa của Đức Giê-hô-va\\" Cái ấn là dấu hiệu của sự thuộc về lâu bền, không dễ xóa. Tình yêu thật không phải là cảm xúc thoáng qua, mà là cam kết sâu xa. Nó đòi hỏi sự trọn vẹn và sự trung tín. Trong bối cảnh đức tin, đó cũng là hình ảnh về tình yêu của Chúa dành cho chúng ta: Ngài đóng ấn tình yêu trên lòng Ngài, không bao giờ rời bỏ. Hôm nay, hãy nghĩ về điều bạn có thể cam kết trong tình yêu: một lời hứa, một sự kiên nhẫn, một sự tha thứ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài yêu con với một tình yêu bền vững. Xin giúp con yêu người khác bằng sự cam kết và trung tín, không chỉ bằng cảm xúc nhất thời. A-men."},{"sach":"Tình Ca","ma":"SNG","chuong":8,"cau":7,"loi_kinh_thanh":"Nước nhiều không tưới tắt được ái tình, Các sông chẳng nhận chìm nó được; Nếu người nào đem hết tài sản nhà mình, Đặng mua lấy ái tình, Ắt người ta sẽ khinh dể nó đến điều.","bai_hoc":"\\"Nước nhiều không tưới tắt được ái tình, Các sông chẳng nhận chìm nó được; Nếu người nào đem hết tài sản nhà mình, Đặng mua lấy ái tình, Ắt người ta sẽ khinh dể nó đến điều\\" Tình yêu thật có sức bền: nó sống sót qua thử thách, qua những khó khăn, qua những mùa nhiều sóng gió. Điều này có thể là lời an ủi cho những ai đang yêu thương trong gian nan: tình yêu của bạn có giá trị. Và đó cũng là lời nhắc về tình yêu của Chúa: không dòng nước nào có thể cuốn trôi tình yêu Ngài dành cho bạn. Hôm nay, nếu bạn đang trải qua thử thách trong một mối quan hệ, hãy xin Chúa ban sức mạnh để yêu thương bền bỉ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì tình yêu không dòng nước nào cuốn trôi được. Xin giúp con yêu thương bền bỉ trong thử thách, và nhớ rằng tình yêu của Ngài dành cho con luôn vững bền. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":1,"cau":18,"loi_kinh_thanh":"Đức Giê-hô-va phán: Bây giờ hãy đến, cho chúng ta biện luận cùng nhau. Dầu tội các ngươi như hồng điều, sẽ trở nên trắng như tuyết; dầu đỏ như son, sẽ trở nên trắng như lông chiên.","bai_hoc":"\\"Đức Giê-hô-va phán: Bây giờ hãy đến, cho chúng ta biện luận cùng nhau. Dầu tội các ngươi như hồng điều, sẽ trở nên trắng như tuyết; dầu đỏ như son, sẽ trở nên trắng như lông chiên\\" Hãy chú ý cách Chúa nói: Ngài mời bạn đến và cùng nói chuyện, không phải đến để bị xét xử. Dù điều bạn mang nặng nề đến đâu, màu đỏ thẫm ấy cũng có thể được làm trắng. Sự tha thứ của Chúa không phải là sự bỏ qua nhẹ nhàng, mà là sự làm sạch thật sự bằng giá Ngài đã trả. Hôm nay, nếu bạn thấy mình có điều gì không dám đến với Ngài, hãy bắt đầu cuộc trò chuyện ấy. Ngài đang chờ bạn với lòng nhân từ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài mời con đến và nói chuyện với Ngài. Xin tha thứ và làm sạch lòng con, và giúp con tin rằng sự tha thứ của Ngài thật và trọn vẹn. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":6,"cau":8,"loi_kinh_thanh":"Đoạn, tôi nghe tiếng Chúa phán rằng: Ta sẽ sai ai đi? Ai sẽ đi cho chúng ta? Tôi thưa rằng: Có tôi đây; xin hãy sai tôi.","bai_hoc":"\\"Đoạn, tôi nghe tiếng Chúa phán rằng: Ta sẽ sai ai đi? Ai sẽ đi cho chúng ta? Tôi thưa rằng: Có tôi đây; xin hãy sai tôi\\" Ê-sai vừa trải qua việc thấy sự thánh khiết của Chúa và được tha thứ, rồi ông sẵn lòng đáp lại. Lời gọi của Chúa thường đến sau khi ta nhận ơn Ngài. Sai đi không nhất thiết là đi xa, có thể là mang sự yêu thương đến một người ngay cạnh bạn. Hôm nay, hãy cầu nguyện lời này: \\"Có con đây.\\" Rồi hãy để ý xem Chúa đặt trước mặt bạn cơ hội nào để phục vụ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã tha thứ cho con. Con xin thưa: có con đây, xin sai con. Xin chỉ cho con cơ hội phục vụ Ngài và người khác hôm nay. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":7,"cau":14,"loi_kinh_thanh":"Vậy nên, chính Chúa sẽ ban một điềm cho các ngươi: nầy một gái đồng trinh sẽ chịu thai, sanh ra một trai, và đặt tên là Em-ma-nu-ên.","bai_hoc":"\\"Vậy nên, chính Chúa sẽ ban một điềm cho các ngươi: nầy một gái đồng trinh sẽ chịu thai, sanh ra một trai, và đặt tên là Em-ma-nu-ên\\" Em-ma-nu-ên nghĩa là Đức Chúa Trời ở cùng chúng ta. Lời này được nói trong thời kỳ nhiều sợ hãi, và Chúa trả lời bằng một lời hứa lớn: Ngài sẽ đến ở cùng. Cơ Đốc nhân thấy điều ấy ứng nghiệm nơi Chúa Giê-su. Điều đó có nghĩa là bạn không chỉ có một Đức Chúa Trời ở xa, mà có Đức Chúa Trời ở ngay giữa đời mình. Hôm nay, hãy thì thầm: \\"Chúa ở cùng con,\\" và để lòng nghỉ ngơi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đến ở giữa chúng con trong Chúa Giê-su. Xin giúp con nhớ rằng Ngài ở cùng con mỗi ngày, trong mọi hoàn cảnh con gặp. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":9,"cau":6,"loi_kinh_thanh":"(09-5) Vì có một con trẻ sanh cho chúng ta, tức là một con trai ban cho chúng ta; quyền cai trị sẽ nấy trên vai Ngài. Ngài sẽ được xưng là Đấng Lạ lùng, là Đấng Mưu luận, là Đức Chúa Trời Quyền năng, là Cha Đời đời, là Chúa Bình an.","bai_hoc":"\\"(09-5) Vì có một con trẻ sanh cho chúng ta, tức là một con trai ban cho chúng ta; quyền cai trị sẽ nấy trên vai Ngài. Ngài sẽ được xưng là Đấng Lạ lùng, là Đấng Mưu luận, là Đức Chúa Trời Quyền năng, là Cha Đời đời, là Chúa Bình an\\" Hãy đọc từng danh hiệu thật chậm. Mỗi danh hiệu là một lời hứa cho một nhu cầu của bạn: khi bạn cần sự khôn ngoan, Ngài là Cố Vấn; khi bạn cần sự bình an, Ngài là Chúa Bình An. Hôm nay, hãy chọn danh hiệu nào bạn đang cần nhất và thầm gọi Ngài bằng danh ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng Lạ Lùng, Cố Vấn, Đức Chúa Trời Quyền Năng, Cha Đời Đời, Chúa Bình An. Xin trở nên điều con cần nhất hôm nay, và ban cho con sự bình an của Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":11,"cau":1,"loi_kinh_thanh":"Có một chồi sẽ nứt lên từ gốc Y-sai, một nhánh từ rễ nó sẽ ra trái.","bai_hoc":"\\"Có một chồi sẽ nứt lên từ gốc Y-sai, một nhánh từ rễ nó sẽ ra trái\\" Sau khi cây đã bị đốn, chỉ còn gốc khô, Chúa nói rằng một chồi mới sẽ mọc lên. Đó là lời hứa về Đấng Mê-si, nhưng cũng là hình ảnh đẹp cho hy vọng của chúng ta: Chúa có thể làm mọc lên điều mới từ nơi tưởng như chết. Có thể trong đời bạn có những \\"gốc cây khô\\": một ước mơ đã tắt, một mối quan hệ đổ vỡ. Hôm nay, hãy nhớ rằng Chúa là Đấng khởi sự lại. Ngài nhìn vào gốc khô và thấy một chồi non.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng làm nảy chồi từ nơi tưởng như khô chết. Xin giúp con giữ hy vọng, và tin rằng Ngài có thể khởi sự điều mới trong những nơi con đã thôi mong đợi. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":11,"cau":6,"loi_kinh_thanh":"Bấy giờ muông sói sẽ ở với chiên con, beo nằm với dê con; bò con, sư tử con với bò nuôi mập cùng chung một chỗ, một đứa con trẻ sẽ dắt chúng nó đi.","bai_hoc":"\\"Bấy giờ muông sói sẽ ở với chiên con, beo nằm với dê con; bò con, sư tử con với bò nuôi mập cùng chung một chỗ, một đứa con trẻ sẽ dắt chúng nó đi\\" Đây là bức tranh về một thế giới được hòa thuận, nơi sự đối nghịch không còn, nơi kẻ mạnh và kẻ yếu sống bên nhau trong bình an. Đó là lời hứa của Chúa về ngày Ngài phục hồi mọi sự. Nó cho chúng ta hy vọng và cũng mời chúng ta bắt đầu sống hòa thuận ngay bây giờ. Hôm nay, hãy làm một việc nhỏ để xây dựng hòa bình: nhường nhịn, lắng nghe, hoặc làm hòa với ai đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa một thế giới hòa bình. Xin làm con thành người xây dựng hòa thuận trong gia đình, công việc và cộng đồng của con ngay từ hôm nay. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":26,"cau":3,"loi_kinh_thanh":"Người nào để trí mình nương dựa nơi Ngài, thì Ngài sẽ gìn giữ người trong sự bình yên trọn vẹn, vì người nhờ cậy Ngài.","bai_hoc":"Chúa sẽ giữ trong sự bình an trọn vẹn những người nào có ý chí kiên định, vì họ nhờ cậy nơi Ngài. Bình an trọn vẹn không phải là không có sóng gió, mà là lòng bạn đứng vững khi sóng gió đến. Chìa khóa là hướng tâm trí về Chúa: không phải tập trung vào vấn đề, mà tập trung vào Đấng lớn hơn vấn đề. Khi tâm trí chao đảo với hàng nghìn suy nghĩ, hãy kéo nó về một điều: Chúa ở đó. Hôm nay, hãy chọn một câu Kinh Thánh ngắn và lặp lại thầm khi bạn thấy lo lắng. Bình an của Ngài sẽ dần gìn giữ bạn.","loi_cau_nguyen":"Chúa ơi, xin giữ con trong sự bình an trọn vẹn khi tâm trí con hướng về Ngài. Khi con lo lắng, xin giúp con kéo lòng mình về với Ngài và nương cậy nơi Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":30,"cau":21,"loi_kinh_thanh":"Khi các ngươi xê qua bên hữu hoặc bên tả, tai các ngươi sẽ nghe có tiếng đằng sau mình rằng: Nầy là đường đây, hãy noi theo!","bai_hoc":"\\"Khi các ngươi xê qua bên hữu hoặc bên tả, tai các ngươi sẽ nghe có tiếng đằng sau mình rằng: Nầy là đường đây, hãy noi theo!\\" Chúa không chỉ chỉ đường từ xa, Ngài đi sau lưng bạn và nhẹ nhàng nhắc khi bạn lạc hướng. Hãy tưởng tượng một người cha đi phía sau đứa con đang tập đi xe đạp, sẵn sàng đỡ và chỉ dẫn. Nếu bạn không biết nên đi hướng nào, hãy dành thời gian yên lặng. Ngài có thể nói qua Lời Ngài, qua sự bình an trong lòng, qua lời khuyên của người khôn ngoan. Hôm nay, hãy xin Chúa chỉ cho bạn con đường và lắng nghe.","loi_cau_nguyen":"Chúa ơi, xin cho con nghe tiếng Ngài chỉ đường, khi con phân vân giữa các lựa chọn. Xin giúp con yên lặng lắng nghe, và can đảm đi theo hướng Ngài chỉ. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":40,"cau":1,"loi_kinh_thanh":"Đức Chúa Trời của các ngươi phán rằng: Hãy yên ủi, hãy yên ủi dân ta.","bai_hoc":"\\"Đức Chúa Trời của các ngươi phán rằng: Hãy yên ủi, hãy yên ủi dân ta\\" Chương này mở đầu bằng sự lặp lại: yên ủi, yên ủi. Chúa muốn nói với dân Ngài bằng sự dịu dàng sau một thời gian dài đau khổ và lưu đày. Có lẽ bạn cũng cần nghe lời này. Chúa không bảo bạn mạnh mẽ lên, mà bảo: Ta muốn an ủi con. Ngài hiểu nỗi mệt mỏi của bạn và muốn ôm lấy bạn. Hôm nay, hãy cho phép mình được an ủi: ngồi yên, đọc một đoạn Kinh Thánh dịu dàng, và để lời của Ngài vỗ về lòng bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài muốn yên ủi con. Xin chạm vào những nơi con mệt mỏi, ban cho con sự an ủi của Ngài, và giúp con an ủi người khác như Ngài an ủi con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":40,"cau":3,"loi_kinh_thanh":"Có tiếng kêu rằng: Hãy mở đường trong đồng vắng cho Đức Giê-hô-va; hãy ban bằng đường cái trong đất hoang cho Đức Chúa Trời chúng ta!","bai_hoc":"\\"Có tiếng kêu rằng: Hãy mở đường trong đồng vắng cho Đức Giê-hô-va; hãy ban bằng đường cái trong đất hoang cho Đức Chúa Trời chúng ta!\\" Trước khi Chúa đến, cần có sự chuẩn bị. Giăng Báp-tít ứng nghiệm lời này, kêu gọi dân sự ăn năn để đón Chúa Giê-su. Ngày nay, bạn cũng được mời dọn đường trong lòng mình: dẹp bớt những chướng ngại, san bằng những chỗ gập ghềnh để Chúa có thể đến. Hôm nay, hãy hỏi mình: điều gì đang cản trở tôi đến gần Chúa? Rồi hãy xin Ngài giúp bạn dọn dẹp một chướng ngại nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con dọn đường trong lòng để đón Ngài. Xin chỉ cho con điều gì đang ngăn cách con với Ngài, và ban sức để con sửa soạn lòng mình. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":40,"cau":8,"loi_kinh_thanh":"cỏ khô, hoa rụng; nhưng lời của Đức Chúa Trời chúng ta còn mãi đời đời!","bai_hoc":"\\"cỏ khô, hoa rụng; nhưng lời của Đức Chúa Trời chúng ta còn mãi đời đời!\\" Mọi thứ trong đời này đều có thể phai tàn: sức khỏe, vẻ đẹp, địa vị, thậm chí những kế hoạch lớn. Nhưng Lời Chúa thì không. Khi bạn đặt nền đời mình trên Lời Ngài, bạn đứng trên điều vững chắc nhất. Có những lúc mọi thứ xung quanh thay đổi nhanh, và bạn cảm thấy mất phương hướng. Hãy trở lại với Lời Chúa như trở lại một nơi quen thuộc và an toàn. Hôm nay, hãy đọc lại một câu Kinh Thánh yêu thích và để nó neo lòng bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì Lời Ngài còn đời đời. Khi mọi thứ thay đổi, xin giúp con đặt nền đời mình trên Lời Ngài, và tìm thấy sự vững chắc ở đó. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":40,"cau":31,"loi_kinh_thanh":"Nhưng ai trông đợi Đức Giê-hô-va thì chắc được sức mới, cất cánh bay cao như chim ưng; chạy mà không mệt nhọc, đi mà không mòn mỏi.","bai_hoc":"\\"Nhưng ai trông đợi Đức Giê-hô-va thì chắc được sức mới, cất cánh bay cao như chim ưng; chạy mà không mệt nhọc, đi mà không mòn mỏi\\" Trông cậy ở đây là sự chờ đợi đầy hy vọng, tin chắc rằng Chúa sẽ đến. Sức lực của chúng ta có giới hạn, ngay cả những người trẻ, mạnh mẽ cũng mệt. Nhưng người trông cậy Chúa nhận được nguồn sức mới từ bên ngoài chính mình. Hôm nay, nếu bạn thấy kiệt sức, hãy dành vài phút để ngồi yên với Chúa, hít thở và nói: \\"Con trông cậy nơi Ngài.\\" Sức mạnh của Ngài sẽ đến vào đúng lúc bạn cần.","loi_cau_nguyen":"Chúa ơi, xin ban cho con sức mới khi con trông cậy Ngài. Khi con thấy mình mệt mỏi và cạn kiệt, xin nâng con lên như đôi cánh chim ưng, để con tiếp tục đi mà không mòn mỏi. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":41,"cau":10,"loi_kinh_thanh":"Đừng sợ, vì ta ở với ngươi; chớ kinh khiếp, vì ta là Đức Chúa Trời ngươi! Ta sẽ bổ sức cho ngươi; phải, ta sẽ giúp đỡ ngươi, lấy tay hữu công bình ta mà nâng đỡ ngươi.","bai_hoc":"Có lẽ bạn đang đứng trước một điều khiến tim mình đập nhanh: một kết quả chưa biết, một cuộc trò chuyện khó, một chặng đường còn mờ mịt. Chúa không bảo bạn đừng sợ vì mọi việc sẽ dễ dàng. Ngài nói đừng sợ vì Ngài ở cùng bạn. Hãy chú ý những lời Ngài hứa: Ta sẽ làm cho ngươi mạnh mẽ, Ta sẽ giúp đỡ ngươi, Ta sẽ nâng ngươi lên. Bạn không phải tự mình gồng gánh. Có một bàn tay vững chãi và ấm áp đang đưa ra, sẵn sàng nắm lấy tay bạn. Hôm nay, hãy hít một hơi thật sâu, đặt nỗi lo vào tay Ngài, và bước tiếp từng bước nhỏ.","loi_cau_nguyen":"Chúa ơi, khi nỗi sợ đến, xin nhắc con rằng Ngài ở cùng con. Xin làm con mạnh mẽ, giúp đỡ con, và nâng con lên bằng tay hữu công bình của Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":43,"cau":1,"loi_kinh_thanh":"Bây giờ, hỡi Gia-cốp! Đức Giê-hô-va là Đấng đã dựng nên ngươi, hỡi Y-sơ-ra-ên! Ngài là Đấng đã tạo thành ngươi, phán như vầy: Đừng sợ, vì ta đã chuộc ngươi. Ta đã lấy tên ngươi gọi ngươi; ngươi thuộc về ta.","bai_hoc":"\\"Đừng sợ, vì Ta đã chuộc ngươi; Ta đã lấy tên ngươi gọi ngươi; ngươi thuộc về Ta.\\" Hãy để câu này chạm vào bạn: Chúa gọi bạn bằng tên. Không phải bằng một con số hay một vai trò, mà bằng tên riêng của bạn. Ngài biết bạn, đã chuộc bạn và nói bạn thuộc về Ngài. Khi bạn cảm thấy mình bị lãng quên giữa đám đông hoặc bị người khác xem nhẹ, hãy nhớ rằng bạn được biết đến và được yêu bởi Đấng quan trọng nhất. Hôm nay, hãy thầm nghe Chúa gọi tên bạn và đáp lại: \\"Dạ, con ở đây.\\"","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã chuộc con và gọi con bằng tên. Xin giúp con nhớ rằng con thuộc về Ngài, và để lòng con bớt sợ hãi khi con biết mình được Ngài biết đến. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":43,"cau":2,"loi_kinh_thanh":"Khi ngươi vượt qua các dòng nước, ta sẽ ở cùng; khi ngươi lội qua sông, sẽ chẳng che lấp. Khi ngươi bước qua lửa, sẽ chẳng bị cháy, ngọn lửa chẳng đốt ngươi.","bai_hoc":"\\"Khi ngươi vượt qua các dòng nước, ta sẽ ở cùng; khi ngươi lội qua sông, sẽ chẳng che lấp. Khi ngươi bước qua lửa, sẽ chẳng bị cháy, ngọn lửa chẳng đốt ngươi\\" Chú ý chữ \\"khi\\", không phải \\"nếu\\". Chúa không hứa rằng bạn sẽ không đi qua nước sâu hay lửa nóng. Ngài hứa Ngài ở cùng bạn khi đi qua. Sự hiện diện của Ngài làm khác biệt: nước không nhấn chìm, lửa không thiêu cháy. Có thể có một thử thách bạn đang đi qua hay sắp phải đi qua. Hãy nắm lấy lời hứa này như nắm lấy tay một người bạn đáng tin. Hôm nay, hãy nói với Chúa: \\"Con sẽ đi qua điều này cùng Ngài.\\"","loi_cau_nguyen":"Chúa ơi, khi con đi qua nước sâu và lửa thử thách, xin ở cùng con như Ngài đã hứa. Xin giúp con tin rằng con sẽ không bị nhấn chìm, vì Ngài ở bên con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":43,"cau":19,"loi_kinh_thanh":"Nầy, ta sắp làm một việc mới, việc nầy sẽ hiện ra ngay; các ngươi há chẳng biết sao? Ấy là ta sẽ vạch một con đường trong đồng vắng, và khiến những sông chảy trong nơi sa mạc.","bai_hoc":"\\"Nầy, ta sắp làm một việc mới, việc nầy sẽ hiện ra ngay; các ngươi há chẳng biết sao? Ấy là ta sẽ vạch một con đường trong đồng vắng, và khiến những sông chảy trong nơi sa mạc\\" Chúa là Đấng mở lối ở những nơi không ai nghĩ có lối. Đôi khi chúng ta bị kẹt trong quá khứ, nghĩ rằng mọi thứ đã kết thúc, và quên rằng Ngài vẫn đang làm điều mới. Hôm nay, hãy hỏi Chúa: Ngài đang làm việc mới nào trong đời tôi? Hãy mở mắt và lòng đón nhận. Có thể đó là một cơ hội nhỏ, một người mới, một cách nhìn mới. Hãy tin rằng Ngài đang mở đường.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng làm việc mới. Xin mở mắt con để thấy điều Ngài đang làm, và cho con can đảm bước vào điều mới Ngài chuẩn bị, thay vì bám lấy quá khứ. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":45,"cau":22,"loi_kinh_thanh":"Hỡi các ngươi hết thảy ở các nơi đầu cùng đất, hãy nhìn xem ta và được cứu! Vì ta là Đức Chúa Trời, chẳng có Chúa nào khác.","bai_hoc":"Chúa mời gọi mọi người ở khắp nơi trên đất hãy hướng nhìn về Ngài để được cứu. Lời mời này đơn giản đến mức làm ta ngạc nhiên: không cần làm điều gì to tát, không cần đạt một tiêu chuẩn nào, chỉ cần nhìn về Ngài. Có những lúc chúng ta nghĩ phải sửa mình xong mới đến với Chúa được, nhưng Ngài mời ta đến ngay khi còn lộn xộn. Ơn cứu dành cho tất cả các dân tộc, không loại trừ ai. Hôm nay, hãy dừng lại một chút giữa những việc bận rộn, hướng lòng nhìn lên Ngài, và để Ngài nói với lòng bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài mời mọi người nhìn về Ngài để được cứu. Xin giúp con hướng mắt nhìn lên Ngài mỗi ngày, ngay cả khi lòng con còn lộn xộn, và nhận lấy ơn cứu của Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":49,"cau":15,"loi_kinh_thanh":"Đàn bà há dễ quên con mình cho bú, không thương đến con trai ruột mình sao? Dầu đàn bà quên con mình, ta cũng chẳng quên ngươi.","bai_hoc":"Chúa dùng hình ảnh người mẹ và đứa con còn bú để nói về tình yêu của Ngài. Một người mẹ khó mà quên đứa con mình, nhưng ngay cả khi điều đó xảy ra, Chúa nói Ngài sẽ không quên bạn. Đây là một trong những lời hứa dịu dàng nhất trong Kinh Thánh. Có thể bạn từng có lúc cảm thấy mình bị lãng quên, không ai nhớ đến. Hãy để lời này chạm vào nơi đau ấy. Bạn được Chúa nhớ đến, được khắc trên lòng bàn tay Ngài. Hôm nay, hãy hít một hơi thật sâu và nhắc mình: Chúa không quên tôi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài không bao giờ quên con. Xin giúp con tin rằng con luôn nằm trong tâm trí và trái tim của Ngài, và chữa lành những nơi con từng cảm thấy bị bỏ quên. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":53,"cau":3,"loi_kinh_thanh":"Người đã bị người ta khinh dể và chán bỏ, từng trải sự buồn bực, biết sự đau ốm, bị khinh như kẻ mà người ta che mặt chẳng thèm xem; chúng ta cũng chẳng coi người ra gì.","bai_hoc":"Câu này mô tả Đấng Chịu Khổ bị loài người khinh dể, từ chối, là người từng trải sự đau thương và biết rõ nỗi buồn. Cơ Đốc nhân thấy ở đây hình ảnh Chúa Giê-su. Điều an ủi là Chúa không đứng ngoài nỗi đau của chúng ta. Ngài đã nếm trải sự từ chối, sự cô đơn và đau khổ. Khi bạn bị hiểu lầm hay bị bỏ rơi, bạn có một Đấng hiểu rõ cảm giác ấy. Hôm nay, nếu bạn đang mang nỗi đau bị từ chối, hãy kể với Chúa Giê-su. Ngài không chỉ nghe, Ngài hiểu từ chính trải nghiệm của Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã nếm trải nỗi đau bị từ chối vì con. Xin ở bên con khi con bị hiểu lầm hay bị bỏ rơi, và chữa lành những vết thương ấy trong lòng con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":53,"cau":4,"loi_kinh_thanh":"Thật người đã mang sự đau ốm của chúng ta, đã gánh sự buồn bực của chúng ta; mà chúng ta lại tưởng rằng người đã bị Đức Chúa Trời đánh và đập, và làm cho khốn khổ.","bai_hoc":"Câu này nói rằng Đấng Chịu Khổ đã gánh lấy những đau đớn và nỗi buồn của chúng ta. Có những gánh nặng ta cố gắng tự mang: nỗi buồn, sự xấu hổ, bệnh tật, thất vọng. Lời tiên tri này mời ta đặt chúng xuống, vì Chúa Giê-su đã mang chúng trước ta. Điều đó không có nghĩa là mọi nỗi đau biến mất ngay lập tức, nhưng ta không phải gánh một mình. Hôm nay, hãy nhớ đến một gánh nặng cụ thể và thầm trao nó cho Ngài. Hãy để Ngài cầm lấy nó, như một người bạn mang giùm một chiếc ba lô nặng.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã gánh lấy nỗi đau và nỗi buồn của con. Xin giúp con đặt xuống những gánh nặng con đã mang quá lâu, và để Ngài mang cùng con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":53,"cau":5,"loi_kinh_thanh":"Nhưng người đã vì tội lỗi chúng ta mà bị vết, vì sự gian ác chúng ta mà bị thương. Bởi sự sửa phạt người chịu chúng ta được bình an, bởi lằn roi người chúng ta được lành bịnh.","bai_hoc":"Đây là trái tim của Tin Lành: Ngài bị đâm vì những vi phạm của chúng ta, bị thương vì sự gian ác của chúng ta, và nhờ vết thương ấy chúng ta được chữa lành. Không phải ta tự cứu mình, mà Ngài đã chịu hình phạt thay ta. Mỗi vết thương trên thân thể Ngài là một dấu ấn của tình yêu. Khi bạn thấy mình không xứng đáng, hãy nhớ rằng giá của bạn đã được trả bằng điều vô cùng quý giá. Hôm nay, hãy dành một phút lặng lẽ biết ơn Chúa Giê-su vì điều Ngài đã làm.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã chịu thương tích để con được lành. Xin giúp con hiểu sâu hơn tình yêu ấy, và sống trong sự biết ơn và tự do mà Ngài đã mua cho con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":53,"cau":6,"loi_kinh_thanh":"Chúng ta thảy đều như chiên đi lạc, ai theo đường nấy; Đức Giê-hô-va đã làm cho tội lỗi của hết thảy chúng ta đều chất trên người.","bai_hoc":"Câu Kinh Thánh nói thật thà: \\"Chúng ta thảy đều như chiên đi lạc, ai theo đường nấy; Đức Giê-hô-va đã làm cho tội lỗi của hết thảy chúng ta đều chất trên người\\" Không ai ngoại lệ. Nhưng điều đẹp nhất nằm ở nửa sau: Chúa đã đặt tội lỗi của chúng ta trên Ngài. Người chăn không bỏ rơi những con chiên lạc, mà tự mình gánh lấy hậu quả để đưa chúng về. Nếu bạn từng thấy mình đã đi quá xa, đừng nghĩ rằng đã quá muộn. Chúa chủ động tìm kiếm và đón nhận bạn. Hôm nay, hãy thành thật thưa với Chúa về nơi bạn đã lạc, và để Ngài đón bạn về.","loi_cau_nguyen":"Chúa ơi, con nhận mình đã đi lạc như chiên. Cảm ơn Ngài đã gánh lấy tội lỗi con và tìm kiếm con. Xin dẫn con trở về, và giúp con ở lại gần Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":54,"cau":17,"loi_kinh_thanh":"Phàm binh khí chế ra nghịch cùng ngươi sẽ chẳng thạnh lợi, và ngươi sẽ định tội mọi lưỡi dấy lên để xét đoán ngươi. Đức Giê-hô-va phán: Ấy là phần cơ nghiệp của các tôi tớ Đức Giê-hô-va, và sự công bình bởi ta ban cho họ.","bai_hoc":"Chúa hứa rằng không khí giới nào làm ra để chống lại dân Ngài sẽ thành công, và mọi lời cáo gian sẽ bị bác bỏ. Cần hiểu lời này đúng: đây là lời hứa về sự bảo vệ tối hậu của Chúa dành cho dân Ngài, chứ không phải bảo đảm rằng bạn sẽ không bao giờ gặp khó khăn. Ngay cả trong gian nan, bạn vẫn an toàn trong tay Ngài, và kẻ thù không có tiếng nói cuối cùng. Hôm nay, nếu bạn đang cảm thấy bị tấn công, bằng lời nói hay hoàn cảnh, hãy nhớ rằng Chúa là Đấng bênh vực bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa bảo vệ dân Ngài. Khi con bị công kích hay hiểu lầm, xin giúp con tin rằng Ngài bênh vực con, và giữ lòng con bình an, không để oán giận chiếm chỗ. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":55,"cau":1,"loi_kinh_thanh":"Hỡi những kẻ nào khát, hãy đến suối nước! Và người nào không có tiền bạc, hãy đến, mua mà ăn! Hãy đến, mua rượu và sữa mà không cần tiền, không đòi giá.","bai_hoc":"Chúa mời tất cả những ai khát hãy đến nhận nước, ai không có tiền hãy đến mua và ăn. Đây là lời mời của một Đấng rộng rãi, không đòi bạn phải trả giá. Ơn cứu và sự thỏa lòng thật sự là món quà, không phải món hàng. Có khi chúng ta cố mua sự bình an bằng thành tích, tiền bạc, hay sự chấp nhận của người khác, rồi vẫn thấy khát. Hôm nay, hãy đến với Chúa tay không, đúng như bạn đang là, và để Ngài làm no lòng bạn bằng điều chỉ Ngài mới ban được.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài mời con đến nhận không tốn tiền. Xin giúp con thôi tìm sự thỏa lòng ở những nơi không thể làm no, và đến với Ngài như con đang là. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":55,"cau":6,"loi_kinh_thanh":"Hãy tìm kiếm Đức Giê-hô-va đang khi mình gặp được; hãy kêu cầu đang khi Ngài ở gần!","bai_hoc":"Chúa mời chúng ta tìm kiếm Ngài khi Ngài còn để cho gặp, và kêu cầu khi Ngài ở gần. Đây không phải lời đe dọa, mà là lời mời đầy khẩn thiết của một Đấng muốn bạn đến. Thời gian của chúng ta có hạn, và cơ hội gần gũi với Chúa là món quà quý giá cần được trân trọng. Đừng đợi đến khi mọi thứ sắp xếp xong hay khi bạn thấy đủ sức mới đến. Hôm nay là ngày thích hợp nhất. Hãy dành vài phút, dù ngắn thôi, để tìm kiếm Ngài và nói chuyện với Ngài một cách chân thành.","loi_cau_nguyen":"Chúa ơi, con muốn tìm kiếm Ngài khi Ngài còn để con gặp. Xin giúp con không trì hoãn, mà dành thời gian đến với Ngài hôm nay bằng một lời cầu nguyện chân thành. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":55,"cau":8,"loi_kinh_thanh":"Đức Giê-hô-va phán: Ý tưởng ta chẳng phải ý tưởng các ngươi, đường lối các ngươi chẳng phải đường lối ta.","bai_hoc":"Chúa nói rằng tư tưởng của Ngài không phải tư tưởng của chúng ta, và đường lối Ngài không phải đường lối chúng ta. Điều này có thể gây khó chịu khi ta không hiểu Chúa đang làm gì. Nhưng nó cũng là lời an ủi sâu sắc: Ngài nhìn thấy những điều ta không thể thấy. Khi mọi thứ có vẻ vô lý, bạn có thể tin rằng có một kế hoạch cao hơn đầy yêu thương. Bạn không cần hiểu tất cả, chỉ cần tin cậy Đấng hiểu. Hôm nay, nếu có điều gì bạn không thể giải thích, hãy thưa với Chúa và nghỉ ngơi trong sự tin cậy.","loi_cau_nguyen":"Chúa ơi, đường lối Ngài cao hơn đường lối con. Khi con không hiểu, xin giúp con tin cậy rằng Ngài thấy điều con không thấy, và đang làm việc vì điều tốt cho con. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":55,"cau":11,"loi_kinh_thanh":"thì lời nói của ta cũng vậy, đã ra từ miệng ta, thì chẳng trở về luống nhưng, mà chắc sẽ làm trọn điều ta muốn, thuận lợi công việc ta đã sai khiến nó.","bai_hoc":"Chúa so sánh Lời Ngài như mưa và tuyết rơi xuống làm đất sinh sản. Lời Ngài phán ra sẽ không trở về luống công, mà làm trọn điều Ngài muốn. Điều này khích lệ chúng ta khi đọc Kinh Thánh hay chia sẻ Lời Chúa: có thể không thấy kết quả ngay, nhưng hạt giống đã được gieo. Lời Chúa có sức sống riêng của nó. Hôm nay, hãy đọc hoặc nghe một đoạn Lời Chúa, và tin rằng nó đang làm việc trong lòng bạn, dù bạn chưa cảm nhận rõ. Cũng hãy chia sẻ một câu cho một người cần khích lệ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì Lời Ngài không trở về luống công. Xin giúp con đọc Lời Ngài với lòng tin cậy, và để Lời ấy làm việc trong con, cả khi con chưa thấy kết quả. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":59,"cau":2,"loi_kinh_thanh":"Nhưng ấy là sự gian ác các ngươi làm xa cách mình với Đức Chúa Trời; và tội lỗi các ngươi đã che khuất mặt Ngài khỏi các ngươi, đến nỗi Ngài không nghe các ngươi nữa.","bai_hoc":"Câu này nói rằng tội lỗi ngăn cách chúng ta với Chúa, như một bức tường. Đây là sự thật khó nghe nhưng cần thiết, vì nó giải thích vì sao chúng ta cần Chúa Giê-su. Ngài là Đấng phá bỏ bức tường ấy. Nếu bạn cảm thấy xa cách Chúa, đừng vội kết luận Ngài đã bỏ rơi bạn. Hãy kiểm tra lòng mình và đến với Ngài bằng sự thành thật. Sự tha thứ luôn có sẵn. Hôm nay, nếu có điều gì đang tạo khoảng cách giữa bạn và Chúa, hãy gọi tên nó trước mặt Ngài và xin Ngài phá bỏ bức tường đó.","loi_cau_nguyen":"Chúa ơi, xin cho con thấy điều gì đang ngăn cách con với Ngài. Cảm ơn Chúa Giê-su đã phá bỏ bức tường ấy. Xin tha thứ cho con, và đưa con trở lại sự gần gũi với Ngài. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":60,"cau":1,"loi_kinh_thanh":"Hãy dấy lên, và sáng lòe ra! Vì sự sáng ngươi đã đến, và vinh quang Đức Giê-hô-va đã mọc lên trên ngươi.","bai_hoc":"Chúa kêu gọi dân Ngài đứng dậy và chiếu sáng, vì ánh sáng của họ đã đến và vinh hiển Ngài đã chiếu trên họ. Ánh sáng ở đây không phải do bạn tự tạo ra, mà là phản chiếu từ Chúa. Có những lúc bạn thấy mình quá mệt hay quá tối để chiếu sáng cho ai. Nhưng bạn không phải tạo ra ánh sáng, chỉ cần quay về phía Ngài và để ánh sáng ấy phản chiếu qua bạn. Hôm nay, hãy làm một điều nhỏ để mang ánh sáng đến người khác: một nụ cười, một lời động viên, một việc tử tế.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là ánh sáng của con. Xin giúp con đứng dậy và phản chiếu ánh sáng của Ngài qua những việc nhỏ và những lời tử tế, ngay cả khi con thấy mình yếu đuối. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":61,"cau":1,"loi_kinh_thanh":"Thần của Chúa Giê-hô-va ngự trên ta; vì Đức Giê-hô-va đã xức dầu cho ta, đặng giảng tin lành cho kẻ khiêm nhường. Ngài đã sai ta đến đặng rịt những kẻ vỡ lòng, đặng rao cho kẻ phu tù được tự do, kẻ bị cầm tù được ra khỏi ngục;","bai_hoc":"Lời này nói về Đấng được Thánh Linh xức dầu để rao tin lành cho người nghèo, bó những người có lòng đau thương, và công bố sự giải phóng cho người bị giam. Chúa Giê-su đã đọc lời này tại nhà hội và nói rằng nó đã được ứng nghiệm. Đó là sứ mạng của Ngài, và là điều Ngài muốn làm trong đời bạn: mang tin lành, chữa lành lòng tan vỡ, và giải phóng. Hôm nay, hãy nghĩ xem phần nào trong lời này bạn cần nhất, và xin Chúa làm điều ấy trong bạn. Ngài vui lòng làm điều Ngài đã hứa.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đến để rao tin lành, chữa lành lòng đau thương và giải phóng người bị trói buộc. Xin làm điều ấy trong con và dùng con để giúp người khác. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":64,"cau":6,"loi_kinh_thanh":"Chúng tôi hết thảy đã trở nên như vật ô uế, mọi việc công bình của chúng tôi như áo nhớp; chúng tôi thảy đều héo như lá, và tội ác chúng tôi như gió đùa mình đi.","bai_hoc":"Câu này thừa nhận một sự thật khiêm nhường: ngay cả những việc công bình của chúng ta cũng không đủ để làm ta xứng đáng trước Chúa. Điều đó không nhằm làm bạn thất vọng, mà giải thoát bạn khỏi gánh nặng phải hoàn hảo. Ơn cứu không dựa trên việc làm của ta, mà dựa trên ân điển của Chúa. Khi bạn hiểu điều đó, bạn có thể làm việc lành vì biết ơn, không phải vì sợ hãi hay để tìm sự chấp nhận. Hôm nay, hãy làm một việc tốt vì yêu mến Chúa, không để chứng tỏ điều gì.","loi_cau_nguyen":"Chúa ơi, con nhận biết việc làm của con không đủ để cứu con. Cảm ơn Ngài vì ân điển. Xin giúp con làm điều tốt vì biết ơn, thay vì cố gắng chứng minh mình. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":64,"cau":8,"loi_kinh_thanh":"Hỡi Đức Giê-hô-va, dầu vậy, bây giờ Ngài là Cha chúng tôi! Chúng tôi là đất sét, Ngài là thợ gốm chúng tôi; chúng tôi thảy là việc của tay Ngài.","bai_hoc":"Câu này gọi Chúa là Cha và là thợ gốm, còn chúng ta là đất sét và công trình của tay Ngài. Đất sét không biết mình sẽ thành hình gì, nhưng tin vào bàn tay thợ. Quá trình nắn đúc đôi khi đau, đôi khi phải vo tròn lại từ đầu. Nhưng bàn tay ấy là bàn tay của một người cha yêu thương, không bao giờ bỏ rơi tác phẩm của mình. Hôm nay, hãy thử buông tay, thôi cố tự định hình bản thân, và thưa với Ngài: xin nắn đúc con theo ý Ngài. Bàn tay ấy luôn dịu dàng.","loi_cau_nguyen":"Chúa ơi, Ngài là Cha và là thợ gốm của con. Xin nắn đúc con theo ý Ngài, và giúp con kiên nhẫn tin cậy bàn tay Ngài, ngay cả khi con thấy quá trình ấy không dễ dàng. A-men."},{"sach":"Ê-sai","ma":"ISA","chuong":65,"cau":17,"loi_kinh_thanh":"Ta sẽ dựng trời mới đất mới; những việc trước sẽ chẳng nhớ nữa, chẳng còn nhắc đến nữa.","bai_hoc":"Chúa hứa dựng nên trời mới đất mới, nơi những điều cũ không còn được nhớ đến hay đến trong lòng. Đây là hy vọng lớn lao cho những ai mang nhiều đau thương: sẽ có một ngày mọi sự được làm mới. Nhưng ngay bây giờ, Chúa cũng làm mới từng phần nhỏ trong đời chúng ta. Hôm nay, hãy nghĩ đến một điều bạn mong Chúa làm mới: một mối quan hệ, một thói quen, một khía cạnh trong tấm lòng. Hãy trao điều ấy cho Ngài, và tin rằng Đấng làm mới muôn vật cũng đang làm mới điều đó trong bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa dựng nên trời mới đất mới. Xin làm mới những nơi trong đời con cần được phục hồi, và giữ con vững lòng với niềm hy vọng về ngày Ngài làm mới mọi sự. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":1,"cau":5,"loi_kinh_thanh":"trước khi ngươi sanh ra, ta đã biệt riêng ngươi, lập ngươi làm kẻ tiên tri cho các nước.","bai_hoc":"Chúa nói với Giê-rê-mi rằng Ngài đã biết ông trước khi ông được hình thành trong bụng mẹ, và đã biệt riêng ông. Lời này đầu tiên dành cho một vị tiên tri đang sợ hãi và cảm thấy mình quá trẻ, nhưng cũng cho chúng ta biết điều đẹp đẽ về tấm lòng Chúa: Ngài biết bạn từ rất lâu trước khi bạn biết chính mình. Đời bạn không phải một sự tình cờ. Hôm nay, nếu bạn thấy mình không đủ giỏi hay đủ tuổi cho một nhiệm vụ, hãy nhớ rằng Chúa đã chuẩn bị bạn từ lâu. Hãy xin Ngài cho bạn can đảm bước đi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã biết con từ trước khi con được hình thành. Xin giúp con tin rằng đời con có mục đích Ngài chuẩn bị, và cho con can đảm đón nhận điều Ngài kêu gọi. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":17,"cau":7,"loi_kinh_thanh":"Đáng chúc phước thay là kẻ nhờ cậy Đức Giê-hô-va, và lấy Đức Giê-hô-va làm sự trông cậy mình.","bai_hoc":"Lời này chúc phước cho người tin cậy Chúa và lấy Ngài làm nơi nương cậy. Người ấy như cây trồng bên dòng nước, rễ lan ra bờ sông, không sợ khi nắng nóng đến. Có những mùa hạn hán trong đời, khi mọi thứ khô cằn, nhưng rễ của người tin cậy Chúa vẫn tìm được nguồn sống. Điều này không có nghĩa là bạn không gặp khó khăn, mà là bạn có chỗ để tìm nước. Hôm nay, hãy hỏi mình: rễ tôi đang tìm nước ở đâu? Hãy chuyển hướng rễ về phía Chúa bằng một lời cầu nguyện hay một đoạn Kinh Thánh.","loi_cau_nguyen":"Chúa ơi, xin giúp con đặt lòng tin cậy nơi Ngài như cây trồng bên dòng nước. Khi mùa hạn hán đến, xin giữ rễ đức tin con tìm thấy nguồn sống nơi Ngài. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":17,"cau":9,"loi_kinh_thanh":"Lòng người ta là dối trá hơn mọi vật, và rất là xấu xa: ai có thể biết được?","bai_hoc":"Câu này nói thẳng rằng lòng người dối trá hơn mọi vật và rất xấu xa, ai có thể biết được. Đây không phải để bạn mất lòng tin vào chính mình, mà để bạn khiêm nhường nhận ra rằng cảm xúc đôi khi đánh lừa ta. Chúa là Đấng dò xét lòng người, và Ngài biết điều chúng ta còn chưa nhận ra về chính mình. Thay vì tin tuyệt đối vào cảm xúc nhất thời, hãy mời Chúa soi sáng. Hôm nay, hãy cầu nguyện: \\"Chúa ơi, xin cho con thấy lòng con thật sự như Ngài thấy\\", và lắng nghe lời Ngài.","loi_cau_nguyen":"Chúa ơi, xin dò xét lòng con và cho con thấy điều con chưa nhận ra. Xin giúp con khiêm nhường, không chỉ tin cảm xúc nhất thời, mà nương cậy sự soi sáng của Ngài. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":18,"cau":6,"loi_kinh_thanh":"Đức Giê-hô-va phán: Hỡi nhà Y-sơ-ra-ên, ta đối với các ngươi há chẳng làm được như người thợ gốm hay sao? Hỡi nhà Y-sơ-ra-ên, đất sét ở trong tay thợ gốm thể nào, thì các ngươi cũng ở trong tay ta thể ấy.","bai_hoc":"Chúa dẫn Giê-rê-mi đến nhà thợ gốm và cho ông thấy một chiếc bình hư trong tay thợ. Người thợ không vứt đi mà nắn lại thành một cái bình khác. Chúa nói với dân Ngài rằng họ cũng như đất sét trong tay Ngài. Đây là tin vui cho những ai cảm thấy mình đã hỏng: Chúa là Đấng nắn lại. Ngài không bỏ đi người đã lầm lỗi, mà làm lại với kiên nhẫn. Hôm nay, nếu bạn thấy mình có phần nào \\"bị hỏng\\", hãy đặt nó vào tay Ngài và tin rằng Ngài có thể làm điều đẹp từ chính chỗ ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Thợ Gốm không bỏ rơi chiếc bình hỏng. Xin nắn lại con theo ý Ngài, và cho con kiên nhẫn để quá trình ấy hoàn tất. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":29,"cau":11,"loi_kinh_thanh":"Đức Giê-hô-va phán: Vì ta biết ý tưởng ta nghĩ đối cùng các ngươi, là ý tưởng bình an, không phải tai họa, để cho các ngươi được sự trông cậy trong lúc cuối cùng của mình.","bai_hoc":"Lời này được gửi cho dân Chúa đang bị lưu đày ở nơi xa lạ, và Chúa nói rằng Ngài có ý định bình an và hy vọng cho họ, nhưng họ phải chờ nhiều năm. Điều này cho chúng ta hiểu lời hứa đúng cách: Chúa không hứa rằng khó khăn sẽ tan biến ngay, mà hứa rằng Ngài có kế hoạch tốt đẹp ngay cả giữa thời gian chờ đợi. Nếu bạn đang ở một mùa khó khăn, hãy kiên nhẫn. Ngài không quên bạn, và những suy nghĩ của Ngài dành cho bạn là bình an. Hôm nay, hãy tin cậy kế hoạch của Ngài, ngay cả khi con đường còn dài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài có ý định bình an và hy vọng cho con. Khi con phải chờ đợi lâu, xin giúp con kiên nhẫn, và tin rằng kế hoạch của Ngài tốt đẹp ngay cả khi con chưa thấy. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":29,"cau":13,"loi_kinh_thanh":"Các ngươi sẽ tìm ta, và gặp được, khi các ngươi tìm kiếm ta hết lòng.","bai_hoc":"Chúa hứa rằng ai tìm kiếm Ngài hết lòng sẽ gặp Ngài. Đây là lời hứa cho những ai thật lòng tìm kiếm, kể cả những người đang nghi ngờ hay mệt mỏi. Chúa không giấu mình khỏi người chân thành. Tìm kiếm Ngài không nhất thiết là dành nhiều giờ, mà là một tấm lòng sẵn sàng. Có thể bạn chỉ có vài phút mỗi ngày, hãy dùng chúng thật sự. Hôm nay, hãy dành một chút thời gian yên lặng, hỏi Chúa: Ngài muốn nói với con điều gì? và lắng nghe bằng cả tấm lòng. Ngài không ngại sự ngập ngừng của bạn.","loi_cau_nguyen":"Chúa ơi, con muốn tìm kiếm Ngài hết lòng. Cảm ơn Ngài hứa rằng con sẽ gặp Ngài. Xin giúp con dành thời gian thật sự cho Ngài hôm nay, và mở lòng lắng nghe. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":31,"cau":3,"loi_kinh_thanh":"Đức Giê-hô-va từ thuở xưa hiện ra cùng tôi và phán rằng: Phải, ta đã lấy sự yêu thương đời đời mà yêu ngươi; nên đã lấy sự nhân từ mà kéo ngươi đến.","bai_hoc":"Chúa nói với dân Ngài: Ta đã yêu ngươi bằng tình yêu đời đời, vì vậy Ta đã lấy lòng nhân từ kéo ngươi lại. Hãy chú ý hai điều: tình yêu của Ngài không có hồi kết, và Ngài kéo chúng ta lại bằng sự nhân từ, không bằng sự ép buộc. Có những lúc chúng ta cảm thấy không đáng được yêu, nhưng tình yêu Chúa không dựa trên việc ta xứng đáng. Nó có từ trước và sẽ còn mãi. Hôm nay, hãy để lòng bạn nghỉ ngơi trong sự thật này: bạn được yêu bằng tình yêu đời đời, không điều kiện, và bạn không cần làm gì để giữ nó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã yêu con bằng tình yêu đời đời. Xin giúp con nhận lấy tình yêu ấy, và để nó chữa lành những nơi con thấy mình không đáng được yêu. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":31,"cau":33,"loi_kinh_thanh":"Đức Giê-hô-va phán: Nầy là giao ước mà ta sẽ lập với nhà Y-sơ-ra-ên sau những ngày đó. Ta sẽ đặt luật pháp ta trong bụng chúng nó và chép vào lòng. Ta sẽ làm Đức Chúa Trời chúng nó, chúng nó sẽ làm dân ta.","bai_hoc":"Chúa hứa lập một giao ước mới: \\"Đức Giê-hô-va phán: Nầy là giao ước mà ta sẽ lập với nhà Y-sơ-ra-ên sau những ngày đó. Ta sẽ đặt luật pháp ta trong bụng chúng nó và chép vào lòng. Ta sẽ làm Đức Chúa Trời chúng nó, chúng nó sẽ làm dân ta\\" Thay vì những điều răn được khắc trên bảng đá, Ngài viết trong chính tấm lòng. Điều đó nghĩa là sự vâng lời không còn chỉ là bổn phận bên ngoài, mà thành một ước muốn từ bên trong. Đây là sự thay đổi mà Chúa Giê-su và Thánh Linh thực hiện. Hôm nay, hãy xin Chúa viết Lời Ngài vào lòng bạn: cho bạn muốn điều Ngài muốn và yêu điều Ngài yêu. Sự thay đổi ấy đến chậm rãi, bằng ân điển, và Ngài kiên nhẫn với bạn từng bước một trên hành trình đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa giao ước mới. Xin viết Lời Ngài vào lòng con, để con vâng theo Ngài từ tình yêu bên trong, không chỉ vì bổn phận bên ngoài. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":32,"cau":17,"loi_kinh_thanh":"Ôi! Hỡi Chúa Giê-hô-va! Chính Ngài đã dùng quyền phép lớn và cánh tay giơ ra mà làm nên trời và đất; chẳng có sự gì là khó quá cho Ngài cả.","bai_hoc":"Giê-rê-mi cầu nguyện lời này khi mọi thứ trông như tuyệt vọng: thành bị vây, dân sắp bị lưu đày. Nhưng ông bắt đầu bằng cách nhớ Chúa là Đấng dựng nên trời đất bằng quyền năng lớn lao, và không có việc gì quá khó cho Ngài. Khi bạn đối diện với một tình huống tưởng chừng không thể, hãy làm như ông: bắt đầu bằng việc nhớ Chúa là ai, trước khi nói về vấn đề. Hôm nay, hãy dành một chút thời gian ngợi khen Chúa vì sự vĩ đại của Ngài, rồi mới nói với Ngài về điều làm bạn lo.","loi_cau_nguyen":"Chúa ơi, Ngài đã dựng nên trời đất bằng quyền năng lớn lao, và không có việc gì quá khó cho Ngài. Xin giúp con nhìn tình huống của con trong ánh sáng sự vĩ đại của Ngài. A-men."},{"sach":"Giê-rê-mi","ma":"JER","chuong":33,"cau":3,"loi_kinh_thanh":"Hãy kêu cầu ta, ta sẽ trả lời cho; ta sẽ tỏ cho ngươi những việc lớn và khó, là những việc ngươi chưa từng biết.","bai_hoc":"Chúa mời gọi: \\"Hãy kêu cầu ta, ta sẽ trả lời cho; ta sẽ tỏ cho ngươi những việc lớn và khó, là những việc ngươi chưa từng biết\\" Đây là lời mời cầu nguyện đẹp đẽ: Chúa không chỉ nghe, Ngài hứa trả lời. Câu này được nói trong lúc Giê-rê-mi bị giam giữ, nghĩa là ngay cả khi bị giới hạn, cầu nguyện vẫn mở ra điều mới. Hôm nay, hãy thử kêu cầu Chúa về một điều cụ thể. Rồi hãy giữ lòng mở để nhận câu trả lời, có thể không phải theo cách bạn nghĩ, nhưng luôn đúng thời. Chúa không bao giờ lơ là lời cầu nguyện của bạn, dù ngắn hay dài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa đáp lời khi con kêu cầu. Xin giúp con cầu nguyện với lòng tin cậy, và mở mắt cho con thấy những điều Ngài muốn bày tỏ cho con. A-men."},{"sach":"Ai Ca","ma":"LAM","chuong":3,"cau":22,"loi_kinh_thanh":"Ấy là nhờ sự nhân từ Đức Giê-hô-va mà chúng ta chưa tuyệt. Vì sự thương xót của Ngài chẳng dứt.","bai_hoc":"Sách Ca Thương được viết giữa cảnh thành phố bị tàn phá, đầy nước mắt. Nhưng ngay giữa nỗi đau ấy, tác giả nhớ lại một điều: nhờ lòng nhân từ của Chúa mà chúng ta không bị tiêu diệt, vì sự thương xót Ngài chẳng dứt. Hy vọng ở đây không phủ nhận nỗi đau, mà đứng cạnh nó. Có những lúc bạn chỉ thấy tàn tạ xung quanh, nhưng bạn vẫn còn đây, và đó là nhờ ân điển Chúa. Hôm nay, nếu bạn đang đi qua một khoảng đổ vỡ, hãy tìm một dấu hiệu nhỏ của lòng thương xót Ngài và nắm lấy nó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì lòng thương xót Ngài không dứt. Giữa những đổ vỡ, xin giúp con nhìn thấy dấu hiệu ân điển của Ngài, và giữ hy vọng trong con. A-men."},{"sach":"Ai Ca","ma":"LAM","chuong":3,"cau":23,"loi_kinh_thanh":"Mỗi buổi sáng thì lại mới luôn, sự thành tín Ngài là lớn lắm.","bai_hoc":"Tác giả viết rằng sự thương xót Chúa mới mẻ mỗi buổi sáng, và sự thành tín Ngài rất lớn. Mỗi sáng là một cơ hội mới. Dù hôm qua có mệt mỏi, thất bại hay buồn bã thế nào, sáng nay lòng thương xót của Chúa đã sẵn sàng, như bánh còn nóng đặt trước cửa nhà. Bạn không phải kéo theo gánh nặng của ngày hôm qua vào hôm nay. Hôm nay, ngay khi bắt đầu ngày mới, hãy thầm cảm ơn Chúa vì sự thương xót mới mẻ này, và xin Ngài giúp bạn sống ngày hôm nay với lòng biết ơn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì sự thương xót mới mẻ mỗi buổi sáng. Xin giúp con bắt đầu ngày mới mà không kéo theo gánh nặng của hôm qua, và sống với lòng tin cậy sự thành tín lớn lao của Ngài. A-men."},{"sach":"Ai Ca","ma":"LAM","chuong":3,"cau":25,"loi_kinh_thanh":"Đức Giê-hô-va ban sự nhân từ cho những kẻ trông đợi Ngài, cho linh hồn tìm cầu Ngài.","bai_hoc":"Tác giả nói Chúa nhân từ với những người trông đợi Ngài và với linh hồn tìm kiếm Ngài. Chờ đợi Chúa không phải thời gian bị bỏ phí. Trong lúc chờ, lòng ta được tôi luyện, đức tin được thử và nuôi lớn, và ta học nhận biết Ngài sâu hơn. Chúa không vắng mặt trong lúc ta chờ. Ngài nhân từ ngay trong đó. Hôm nay, nếu bạn đang chờ một điều gì, hãy thử thay đổi cách nhìn: thay vì xem đây là khoảng trống, hãy xem đây là thời gian ở cùng Chúa. Hãy nói với Ngài về những gì bạn đang trông đợi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài nhân từ với người trông đợi Ngài. Khi con phải chờ, xin giúp con không xem đó là thời gian lãng phí, mà ở gần Ngài hơn trong lúc chờ đợi. A-men."},{"sach":"Ê-xê-chiên","ma":"EZK","chuong":18,"cau":20,"loi_kinh_thanh":"Linh hồn nào phạm tội thì sẽ chết. Con sẽ không mang sự gian ác của cha và cha không mang sự gian ác của con. Sự công bình của người công bình sẽ được kể cho mình, sự dữ của kẻ dữ sẽ chất trên mình.","bai_hoc":"Chúa nói rằng linh hồn nào phạm tội thì sẽ chết, con không phải gánh tội của cha và cha không phải gánh tội của con. Lời này giải thoát chúng ta khỏi hai gánh nặng: mặc cảm vì lỗi lầm của người đi trước, và sự đổ lỗi cho người khác. Mỗi người đứng trước Chúa với trách nhiệm của chính mình, và cũng có cơ hội được Ngài tha thứ. Nếu bạn lớn lên trong một gia đình nhiều tổn thương, bạn không bị định đoạt bởi quá khứ ấy. Hôm nay, hãy nhớ rằng bạn có thể bắt đầu một con đường mới với Chúa, không bị ràng buộc bởi lỗi lầm của người khác.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng công bình và nhân từ. Xin giải thoát con khỏi gánh nặng của quá khứ gia đình, và giúp con chịu trách nhiệm với lòng khiêm nhường và hy vọng trong Ngài. A-men."},{"sach":"Ê-xê-chiên","ma":"EZK","chuong":33,"cau":11,"loi_kinh_thanh":"Hãy nói cùng chúng nó rằng: Chúa Giê-hô-va phán: Thật như ta hằng sống, ta chẳng lấy sự kẻ dữ chết làm vui, nhưng vui về nó xây bỏ đường lối mình và được sống. Các ngươi khá xây bỏ, xây bỏ đường lối xấu của mình. Sao các ngươi muốn chết, hỡi nhà Y-sơ-ra-ên?","bai_hoc":"Chúa phán rằng Ngài không vui khi kẻ ác chết, nhưng muốn họ quay lại và được sống. Đây là tấm lòng thật của Chúa: không muốn ai bị hư mất, và luôn mở cửa cho sự trở lại. Có thể bạn mang một cảm giác rằng Ngài đang giận hay chờ bạn thất bại. Hãy nghe lại lời này. Ngài kiên nhẫn chờ bạn quay về, vì Ngài muốn bạn sống. Hôm nay, nếu bạn thấy mình đã đi sai hướng ở điểm nào đó, hãy quay lại với Ngài. Cánh tay Ngài đang dang rộng, không phải để trách móc mà để đón nhận bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài không muốn ai bị hư mất mà muốn tất cả được sống. Xin giúp con quay trở lại với Ngài mỗi khi con đi lạc, và tin vào sự kiên nhẫn đầy thương xót của Ngài. A-men."},{"sach":"Ê-xê-chiên","ma":"EZK","chuong":36,"cau":26,"loi_kinh_thanh":"Ta sẽ ban lòng mới cho các ngươi, và đặt thần mới trong các ngươi. Ta sẽ cất lòng bằng đá khỏi thịt các ngươi, và ban cho các ngươi lòng bằng thịt.","bai_hoc":"Chúa hứa ban cho dân Ngài một tấm lòng mới và một tinh thần mới, cất đi lòng bằng đá và ban lòng bằng thịt. Lòng bằng đá là lòng chai cứng vì tổn thương, vì cay đắng, vì quen che giấu cảm xúc. Chúa không chỉ muốn sửa hành vi bên ngoài, mà muốn thay đổi tận gốc. Điều đó là công việc của Ngài, không phải của sức riêng ta. Hôm nay, nếu bạn thấy lòng mình chai sạn, hãy xin Ngài làm mềm nó. Hãy kiên nhẫn: sự đổi mới thật diễn ra từ từ, nhưng nó là thật, vì Chúa là Đấng thực hiện.","loi_cau_nguyen":"Chúa ơi, xin cất khỏi con tấm lòng chai đá và ban cho con một tấm lòng mới, mềm mại và biết yêu thương. Con tin rằng Ngài làm được điều con không thể tự làm, và xin Ngài bắt đầu từ hôm nay. A-men."},{"sach":"Ê-xê-chiên","ma":"EZK","chuong":37,"cau":3,"loi_kinh_thanh":"Ngài phán cùng ta rằng: Hỡi con người, những hài cốt nầy có thể sống chăng? Ta thưa rằng: Lạy Chúa Giê-hô-va, chính Chúa biết điều đó!","bai_hoc":"Chúa đưa Ê-xê-chi-ên đến một thung lũng đầy xương khô và hỏi ông: những xương này có sống lại được không? Ông đáp một cách khôn ngoan: Chúa biết. Rồi Chúa bảo ông nói tiên tri, và xương hợp lại, có thịt, có hơi thở. Hình ảnh này nói về hy vọng cho những nơi tưởng như hoàn toàn chết: một ước mơ đã tàn, một mối quan hệ đã tan, một niềm tin đã nguội. Chúa có thể thổi sự sống vào đó. Hôm nay, hãy mang đến Chúa nơi nào trong đời bạn cảm thấy khô cằn, và xin Ngài thổi hơi thở sự sống.","loi_cau_nguyen":"Chúa ơi, Ngài biết những nơi trong đời con tưởng như đã chết. Xin thổi hơi thở sự sống vào đó, và giữ cho con hy vọng rằng Ngài có thể làm sống lại điều con đã thôi mong đợi. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":2,"cau":20,"loi_kinh_thanh":"Đoạn Đa-ni-ên cất tiếng nói rằng: Ngợi khen danh Đức Chúa Trời đời đời vô cùng! vì sự khôn ngoan và quyền năng đều thuộc về Ngài.","bai_hoc":"Đa-ni-ên vừa nhận được lời giải cho giấc mơ của vua nhờ cầu nguyện, và việc đầu tiên ông làm là ngợi khen Chúa. Ông nhận ra rằng sự khôn ngoan và quyền năng thuộc về Chúa, Ngài thay đổi thời kỳ và các mùa, dựng lên và phế bỏ các vua. Khi chúng ta nhận được một điều tốt, ta thường vui mừng ngay lập tức, nhưng dễ quên nói lời cảm ơn. Hôm nay, hãy dừng lại và nhớ một điều Chúa đã giúp bạn gần đây, rồi dành một khoảnh khắc ngợi khen Ngài, bằng lời hoặc bằng lòng.","loi_cau_nguyen":"Chúa ơi, sự khôn ngoan và quyền năng thuộc về Ngài. Xin giúp con luôn biết cảm tạ Ngài khi nhận được ơn giúp đỡ, thay vì quên rằng mọi điều tốt đẹp đều đến từ Ngài. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":3,"cau":17,"loi_kinh_thanh":"Nầy, hỡi vua! Đức Chúa Trời mà chúng tôi hầu việc, có thể cứu chúng tôi thoát khỏi lò lửa hực, và chắc cứu chúng tôi khỏi tay vua.","bai_hoc":"Ba người bạn của Đa-ni-ên đứng trước vua và lò lửa nóng, và họ tuyên bố rằng Đức Chúa Trời họ thờ có thể giải cứu họ khỏi lò lửa. Họ tin vào quyền năng của Chúa, không phải vì chắc chắn kết quả, mà vì biết Ngài là ai. Lòng tin của họ không dựa vào cảm giác an toàn, mà vào chính Ngài. Khi bạn đứng trước một thử thách lớn, hãy nhớ lại quyền năng của Chúa. Hôm nay, hãy nói điều này với chính mình: Chúa tôi thờ có thể làm được. Ngài luôn đứng cạnh bạn, dù bạn đang ở trong hoàn cảnh nào.","loi_cau_nguyen":"Chúa ơi, con tin Ngài có quyền năng giải cứu con. Xin củng cố đức tin con khi con đối diện thử thách, và giữ con vững vàng, tin cậy Ngài trong mọi hoàn cảnh. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":3,"cau":18,"loi_kinh_thanh":"Dầu chẳng vậy, hỡi vua, xin biết rằng chúng tôi không hầu việc các thần của vua, và không thờ phượng pho tượng vàng mà vua đã dựng.","bai_hoc":"Đây là một trong những câu đức tin đẹp nhất: ngay cả khi Chúa không cứu, họ vẫn chọn không thờ lạy tượng vàng. Lòng tin của họ không phụ thuộc vào việc Chúa làm theo ý họ. Đó là đức tin trưởng thành: tin Chúa vì Ngài đáng tin, dù kết quả thế nào. Điều này không dễ, và Chúa hiểu điều đó, Ngài sẽ không chê trách những lúc bạn còn run sợ. Hôm nay, nếu bạn đang cầu xin một điều mà chưa thấy được đáp, hãy thưa với Ngài: con xin điều này, nhưng dù Ngài làm gì, con vẫn tin cậy Ngài.","loi_cau_nguyen":"Chúa ơi, con xin Ngài giúp con, và dù Ngài làm gì con vẫn chọn tin cậy Ngài. Xin ban cho con đức tin trưởng thành, vững vàng trong cả những lúc kết quả không như con mong. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":6,"cau":22,"loi_kinh_thanh":"Đức Chúa Trời tôi đã sai thiên sứ Ngài, và bịt miệng các sư tử, nên chúng nó không làm hại chi đến tôi, bởi tôi đã được nhận là vô tội trước mặt Ngài. Hỡi vua, đối với vua cũng vậy, tôi chẳng từng làm hại gì.","bai_hoc":"Đa-ni-ên bị ném vào hang sư tử vì cứ giữ cầu nguyện, và sáng hôm sau ông bình an vô sự. Ông nói rằng Đức Chúa Trời đã sai thiên sứ ngăn miệng sư tử. Ông trung tín với Chúa dù phải trả giá, và Chúa bảo vệ ông. Không phải lúc nào người tin cũng được cứu khỏi khó khăn theo cách này, nhưng sự trung tín luôn được Chúa nhìn thấy. Hôm nay, hãy chọn giữ một thói quen thuộc linh nhỏ, như cầu nguyện, dù có điều gì cản trở, và tin rằng Chúa gìn giữ bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con trung tín với Ngài, kể cả khi điều đó đòi hỏi con phải trả giá. Cảm ơn Ngài là Đấng gìn giữ con, và xin cho con giữ vững thói quen tìm đến Ngài mỗi ngày. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":12,"cau":2,"loi_kinh_thanh":"Nhiều kẻ ngủ trong bụi đất sẽ thức dậy, kẻ thì để được sự sống đời đời, kẻ thì để chịu sự xấu hổ nhơ nhuốc đời đời.","bai_hoc":"Lời tiên tri này nói về sự sống lại: \\"Nhiều kẻ ngủ trong bụi đất sẽ thức dậy, kẻ thì để được sự sống đời đời, kẻ thì để chịu sự xấu hổ nhơ nhuốc đời đời\\" Đây là một trong những lời hứa sớm nhất trong Kinh Thánh về sự sống lại, và nó đem lại hy vọng lớn cho những ai đã mất người thân trong Chúa. Cái chết không phải điểm kết thúc. Hôm nay, nếu bạn đang nhớ về một người đã khuất, hãy để lời này an ủi bạn: cuộc chia ly này chưa phải là lời cuối cùng, và Chúa đã chuẩn bị một ngày gặp lại.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài về hy vọng sống lại. Xin an ủi những ai đang mất mát người thân, và giữ lòng con vững vàng trong niềm tin rằng cái chết không phải lời kết thúc. A-men."},{"sach":"Đa-niên","ma":"DAN","chuong":12,"cau":3,"loi_kinh_thanh":"Những kẻ khôn sáng sẽ được rực rỡ như sự sáng trên vòng khung; và những kẻ dắt đem nhiều người về sự công bình sẽ sáng láng như các ngôi sao đời đời mãi mãi.","bai_hoc":"Lời này hứa rằng những người khôn ngoan sẽ chiếu sáng như bầu trời, và những ai đưa nhiều người đến sự công bình sẽ như các vì sao đời đời. Chia sẻ đức tin, dạy dỗ, khích lệ và dẫn người khác đến với Chúa là việc có giá trị vĩnh cửu. Bạn không cần là nhà giảng thuyết nổi tiếng. Một lời chứng chân thành, một tấm gương sống, một lời cầu nguyện cho người khác đều được Chúa ghi nhận. Hôm nay, hãy nghĩ đến một người bạn mong họ biết Chúa, và làm một điều nhỏ để chia sẻ tình yêu của Ngài với họ.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống khôn ngoan và dẫn người khác đến với Ngài bằng lời nói và tấm gương của con. Xin cho con cơ hội và can đảm để chia sẻ tình yêu của Ngài với người con thương. A-men."},{"sach":"Ô-sê","ma":"HOS","chuong":4,"cau":6,"loi_kinh_thanh":"Dân ta bị diệt vì cớ thiếu sự thông biết. Bởi ngươi bỏ sự thông biết thì ta cũng bỏ ngươi, đặng ngươi không làm thầy tế lễ cho ta nữa; bởi ngươi đã quên luật pháp của Đức Chúa Trời mình, thì ta cũng sẽ quên con cái ngươi.","bai_hoc":"Chúa nói dân Ngài bị diệt vong vì thiếu hiểu biết, vì họ từ chối nhận biết Ngài. Đây không phải sự khinh miệt người ít học, mà là lời cảnh báo về việc xa rời Lời Chúa. Khi chúng ta không biết Ngài, chúng ta dễ bị cuốn theo mọi tiếng nói quanh mình. Học Lời Chúa không phải để thành người giỏi, mà để được bảo vệ và dẫn dắt. Hôm nay, hãy cam kết một thói quen nhỏ để biết Chúa hơn: đọc một đoạn Kinh Thánh, nghe một bài giảng, hoặc trò chuyện với một người có đức tin.","loi_cau_nguyen":"Chúa ơi, xin cho con khao khát biết Ngài hơn qua Lời Ngài. Xin giúp con không bị cuốn theo mọi điều quanh con, nhưng đứng vững nhờ sự hiểu biết và đời sống thân mật với Ngài. A-men."},{"sach":"Ô-sê","ma":"HOS","chuong":6,"cau":6,"loi_kinh_thanh":"Vì ta ưa sự nhân từ mà không ưa của lễ, ưa sự nhìn biết Đức Chúa Trời hơn là ưa của lễ thiêu.","bai_hoc":"Chúa phán rằng Ngài muốn lòng nhân từ chứ không phải của lễ, muốn sự nhận biết Ngài hơn của lễ thiêu. Chúa Giê-su đã nhắc lại câu này khi nói về lòng thương xót. Nghi thức tôn giáo không phải điều xấu, nhưng nếu thiếu tấm lòng, nó trở thành trống rỗng. Chúa tìm kiếm một mối quan hệ chân thành, thể hiện qua việc thương xót người khác. Hôm nay, hãy làm một việc nhân từ không ai biết, vì tình yêu đối với Chúa, và để ý xem lòng bạn cảm nhận gì khi làm điều ấy.","loi_cau_nguyen":"Chúa ơi, xin giúp con không chỉ làm những nghi thức bên ngoài, mà sống một đời thương xót và nhận biết Ngài. Xin ban cho con lòng nhân từ thật sự với những người quanh con. A-men."},{"sach":"Ô-sê","ma":"HOS","chuong":10,"cau":12,"loi_kinh_thanh":"Hãy gieo cho mình trong sự công bình, hãy gặt theo sự nhân từ; hãy vỡ đất mới! Vì là kỳ tìm kiếm Đức Giê-hô-va, cho đến chừng nào Ngài đến và sa mưa công bình trên các ngươi.","bai_hoc":"Chúa mời dân Ngài gieo trong sự công bình, gặt theo sự nhân từ, và khai khẩn đất hoang của mình, vì đã đến lúc tìm kiếm Chúa. Đất hoang là hình ảnh của một tấm lòng khô cứng, bỏ bê lâu ngày. Chúa mời ta cày xới nó lại, và hứa sẽ ban mưa công bình. Việc đó cần một nỗ lực nhỏ nhưng chân thành: bắt đầu lại, dù cảm thấy khó. Hôm nay, hãy chọn một vùng đất hoang trong lòng bạn, có thể là thói quen cầu nguyện hay một mối quan hệ, và bắt đầu xới nó lên.","loi_cau_nguyen":"Chúa ơi, xin giúp con khai khẩn những vùng đất hoang trong lòng con. Con muốn gieo sự công bình và tìm kiếm Ngài, và xin Ngài ban mưa ân điển trên con. A-men."},{"sach":"Giô-ên","ma":"JOL","chuong":2,"cau":13,"loi_kinh_thanh":"Hãy xé lòng các ngươi, và đừng xé áo các ngươi. Khá trở lại cùng Giê-hô-va Đức Chúa Trời các ngươi; vì Ngài là nhân từ và hay thương xót, chậm giận và giàu ơn, đổi ý về sự tai vạ.","bai_hoc":"Chúa kêu gọi dân Ngài xé lòng chứ đừng xé áo, và trở lại cùng Ngài vì Ngài nhân từ, thương xót, chậm giận và giàu ơn. Xé áo là dấu hiệu bên ngoài của đau buồn, còn xé lòng là sự ăn năn chân thật. Chúa không cần màn trình diễn, Ngài mong muốn sự thành thật. Và điều khuyến khích nhất là bản tính của Ngài: Ngài sẵn sàng tha thứ. Hôm nay, hãy trở lại với Chúa bằng một lời cầu nguyện chân thật, không cần văn hoa, chỉ là thật lòng. Ngài sẵn sàng đón bạn ngay lúc này, đúng như bạn đang là.","loi_cau_nguyen":"Chúa ơi, con muốn trở lại cùng Ngài bằng cả tấm lòng, không chỉ bằng hình thức bên ngoài. Cảm ơn Ngài nhân từ, thương xót và chậm giận. Xin đón nhận con. A-men."},{"sach":"Giô-ên","ma":"JOL","chuong":2,"cau":25,"loi_kinh_thanh":"Ta sẽ đền bù cho các ngươi về mấy năm đã bị cắn phá bởi cào cào, sâu lột vỏ, sâu keo, và châu chấu, là đạo binh lớn mà ta đã sai đến giữa các ngươi.","bai_hoc":"Chúa hứa đền bù những năm bị châu chấu cắn phá. Dân sự đã mất mùa màng, đã trải qua những năm tháng bị tàn phá, và Chúa không bảo họ quên đi mà hứa phục hồi. Điều này cho thấy lòng Chúa muốn chữa lành những năm tháng mất mát. Có thể bạn cảm thấy đã mất thời gian vì sai lầm, bệnh tật, hay hoàn cảnh. Chúa không xem nhẹ điều đó. Ngài có thể phục hồi theo cách Ngài biết. Hôm nay, hãy trao cho Ngài những năm bị châu chấu cắn của bạn, và xin Ngài làm mới.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa phục hồi những năm tháng đã mất. Xin chữa lành những phần đời con bị tổn thương hay bị lãng phí, và giữ lòng con hy vọng vào sự phục hồi của Ngài. A-men."},{"sach":"Giô-ên","ma":"JOL","chuong":2,"cau":28,"loi_kinh_thanh":"Sau đó, ta sẽ đổ Thần ta trên cả loài xác thịt; con trai và con gái các ngươi sẽ nói tiên tri; những người già cả các ngươi sẽ thấy chiêm bao, những kẻ trai trẻ các ngươi sẽ xem sự hiện thấy.","bai_hoc":"Chúa hứa sau này Ngài sẽ đổ Thần Ngài trên mọi xác thịt, con trai con gái sẽ nói tiên tri, người già có chiêm bao, người trẻ thấy dị tượng. Lời này không giới hạn cho một nhóm người đặc biệt, mà dành cho tất cả: già trẻ, nam nữ. Phi-e-rơ đã nhắc đến lời này vào ngày Lễ Ngũ Tuần. Thánh Linh Chúa dành cho mọi người tin. Hôm nay, hãy xin Ngài đầy dẫy bạn bằng Thánh Linh, và mở lòng đón nhận sự dẫn dắt của Ngài trong những việc nhỏ. Dù bạn trẻ hay già, Ngài đều muốn ở cùng bạn và nói với bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa đổ Thánh Linh trên mọi người. Xin đầy dẫy con bằng Thánh Linh Ngài, và giúp con nghe tiếng Ngài trong những việc hằng ngày. A-men."},{"sach":"A-mốt","ma":"AMO","chuong":3,"cau":3,"loi_kinh_thanh":"Nếu hai người không đồng ý với nhau, thì há cùng đi chung được sao?","bai_hoc":"Hai người có đi chung với nhau được không, nếu họ không đồng ý nhau? Câu hỏi này gợi nhắc rằng đi cùng ai cần có sự đồng thuận về hướng đi. Điều đó đúng trong các mối quan hệ, và cũng đúng trong đời sống đức tin: để đi cùng Chúa, ta cần cùng hướng về Ngài. Không phải lúc nào cũng dễ, vì ý muốn của ta đôi khi khác Ngài. Nhưng Ngài kiên nhẫn dẫn ta. Hôm nay, hãy hỏi Chúa: có điều gì trong đời tôi đang đi ngược hướng với Ngài không? Và xin Ngài giúp bạn điều chỉnh.","loi_cau_nguyen":"Chúa ơi, con muốn đi cùng Ngài và cùng hướng với Ngài. Xin chỉ cho con những điều đang đi ngược ý Ngài, và giúp con điều chỉnh bằng sự kiên nhẫn và ân điển của Ngài. A-men."},{"sach":"A-mốt","ma":"AMO","chuong":5,"cau":24,"loi_kinh_thanh":"Thà hãy làm cho sự chánh trực chảy xuống như nước, và sự công bình như sông lớn cuồn cuộn.","bai_hoc":"Chúa muốn sự công bình tuôn chảy như dòng nước, như sông lớn không bao giờ cạn. Ngài ghét việc thờ phượng mà thiếu công lý, tức là hát ca ngợi nhưng làm ngơ trước sự bất công. Đức tin thật thể hiện qua cách ta đối xử với người yếu thế: người nghèo, người bị bỏ rơi, người bị thiệt thòi. Hôm nay, hãy làm một điều nhỏ để thực thi công bình: một hành động công bằng ở nơi làm việc, một sự giúp đỡ cho người cần, hoặc một lời lên tiếng cho người không có tiếng nói.","loi_cau_nguyen":"Chúa ơi, xin giúp con không chỉ thờ phượng bằng lời mà sống công bình trong việc làm. Xin mở mắt con thấy người cần giúp đỡ, và cho con can đảm hành động vì công lý. A-men."},{"sach":"Giô-na","ma":"JON","chuong":1,"cau":17,"loi_kinh_thanh":"(02-1) Đức Giê-hô-va sắm sửa một con cá lớn đặng nuốt Giô-na; Giô-na ở trong bụng cá ba ngày ba đêm.","bai_hoc":"Giô-na chạy trốn lời Chúa gọi, và Chúa sai một con cá lớn nuốt ông. Dù đó là hậu quả của sự bất tuân, Chúa vẫn cứu ông, không để ông chìm. Chúa không bỏ cuộc với những người đi lạc. Ba ngày trong bụng cá là thời gian Giô-na ăn năn và cầu nguyện, rồi được trao một cơ hội thứ hai. Nếu bạn từng chạy trốn điều Chúa kêu gọi, hãy nhớ rằng Ngài vẫn cho bạn cơ hội mới. Hôm nay, hãy thưa với Chúa điều bạn đã né tránh và xin Ngài giúp bạn bắt đầu lại.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài không bỏ cuộc với con khi con chạy trốn. Xin cho con cơ hội mới, và giúp con can đảm đón nhận điều Ngài kêu gọi con làm. A-men."},{"sach":"Giô-na","ma":"JON","chuong":2,"cau":9,"loi_kinh_thanh":"(02-10) Nhưng tôi, tôi sẽ dùng tiếng cảm tạ mà dâng của lễ cho Ngài; Tôi sẽ trả sự tôi đã hứa nguyện. Sự cứu đến từ Đức Giê-hô-va!","bai_hoc":"Từ trong bụng cá, Giô-na cầu nguyện và kết luận rằng sự cứu rỗi thuộc về Đức Giê-hô-va. Đó là lời của một người đã thử mọi cách và nhận ra mình chỉ có thể trông cậy vào Chúa. Có khi chúng ta chỉ nhận ra điều đó khi bị dồn đến chân tường. Điều đẹp là Chúa nghe tiếng kêu từ chỗ sâu thẳm nhất. Bạn không cần ở nơi tốt đẹp mới được Ngài nghe. Hôm nay, hãy cầu nguyện từ nơi bạn đang đứng, dù nó là nơi nào, và tin rằng sự cứu rỗi thuộc về Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài nghe tiếng con từ nơi sâu thẳm. Con nhận biết sự cứu rỗi thuộc về Ngài. Xin giúp con luôn trông cậy Ngài, và tạ ơn Ngài vì ơn cứu. A-men."},{"sach":"Mi-ca","ma":"MIC","chuong":5,"cau":2,"loi_kinh_thanh":"(05-1) Hỡi Bết-lê-hem Ép-ra-ta, ngươi ở trong hàng ngàn Giu-đa là nhỏ lắm, song từ nơi ngươi sẽ ra cho ta một Đấng cai trị trong Y-sơ-ra-ên; gốc tích của Ngài bởi từ đời xưa, từ trước vô cùng.","bai_hoc":"Lời tiên tri nói rằng Đấng cai trị sẽ ra từ Bết-lê-hem, một thành nhỏ bé trong các ngàn của Giu-đa. Chúa thường chọn những nơi và những người tưởng như bình thường để làm điều lớn lao. Hơn bảy trăm năm sau, Chúa Giê-su sinh tại Bết-lê-hem, ứng nghiệm lời này. Điều đó khích lệ ta: dù bạn thấy mình nhỏ bé, ở nơi không ai để ý, Chúa vẫn có thể dùng bạn. Hôm nay, hãy đừng xem thường những việc nhỏ bé bạn đang làm, vì Chúa thường làm nên điều lớn qua những nơi khiêm tốn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài thường chọn những nơi nhỏ bé để làm điều lớn lao. Xin giúp con trung tín trong việc nhỏ, và không xem thường vị trí khiêm tốn Ngài đặt con vào. A-men."},{"sach":"Mi-ca","ma":"MIC","chuong":6,"cau":8,"loi_kinh_thanh":"Hỡi người! Ngài đã tỏ cho ngươi điều gì là thiện; cái điều mà Đức Giê-hô-va đòi ngươi há chẳng phải là làm sự công bình, ưa sự nhân từ và bước đi cách khiêm nhường với Đức Chúa Trời ngươi sao?","bai_hoc":"Tiên tri nói Chúa đã chỉ cho con người điều gì là tốt và điều Ngài đòi hỏi: làm theo sự công bình, ưa sự nhân từ, và bước đi cách khiêm nhường với Đức Chúa Trời. Ba điều giản dị mà sâu sắc. Chúa không đòi bạn phải làm những nghi lễ phức tạp hay nhiều của lễ. Ngài muốn đời sống bạn phản chiếu công bình, thương xót, và một mối quan hệ khiêm nhường với Ngài. Hôm nay, hãy chọn một trong ba điều và làm nó: một hành động công bằng, một việc nhân từ, hoặc một lời cầu nguyện khiêm nhường.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống công bình, yêu mến sự nhân từ, và bước đi khiêm nhường với Ngài. Xin biến những điều giản dị ấy thành nếp sống hằng ngày của con. A-men."},{"sach":"Mi-ca","ma":"MIC","chuong":7,"cau":18,"loi_kinh_thanh":"Ai là Đức Chúa Trời giống như Ngài, tha thứ sự gian ác, và bỏ qua sự phạm pháp của dân sót của sản nghiệp Ngài? Ngài không cưu giận đời đời, vì Ngài lấy sự nhân từ làm vui thích.","bai_hoc":"Tác giả hỏi: \\"Ai là Đức Chúa Trời giống như Ngài, tha thứ sự gian ác, và bỏ qua sự phạm pháp của dân sót của sản nghiệp Ngài? Ngài không cưu giận đời đời, vì Ngài lấy sự nhân từ làm vui thích\\" Ngài không giữ giận mãi, vì Ngài vui thích sự nhân từ. Hãy nghĩ về điều này: Chúa không miễn cưỡng tha thứ. Ngài vui lòng. Tha thứ là điều Ngài yêu thích làm. Điều đó đổi cách ta đến với Ngài: không phải với nỗi sợ bị khiển trách, mà với niềm tin rằng Ngài đón nhận ta bằng niềm vui. Hôm nay, nếu bạn mang điều gì khiến lòng nặng nề, hãy mang đến Ngài, và tin rằng Ngài vui lòng tha thứ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vui thích sự nhân từ và sẵn lòng tha thứ. Xin giúp con đến với Ngài mà không sợ hãi, và tin rằng sự tha thứ của Ngài dành cho con là thật. A-men."},{"sach":"Na-hâm","ma":"NAM","chuong":1,"cau":7,"loi_kinh_thanh":"Đức Giê-hô-va là tốt lành, làm đồn lũy trong ngày hoạn nạn, và biết những kẻ ẩn náu nơi Ngài.","bai_hoc":"Giữa một sách nói nhiều về sự phán xét, có một câu rất dịu dàng: \\"Đức Giê-hô-va là tốt lành, làm đồn lũy trong ngày hoạn nạn, và biết những kẻ ẩn náu nơi Ngài\\" Chú ý chữ \\"biết\\": Chúa không chỉ có đó, Ngài biết từng người, biết bạn bằng tên và hoàn cảnh. Khi hoạn nạn đến, bạn không phải tìm một nơi ẩn náu xa xôi, vì Ngài ở ngay đó. Hôm nay, nếu bạn thấy mình đang trải qua một ngày khó khăn, hãy chạy đến với Ngài bằng một lời cầu nguyện ngắn. Ngài đã sẵn sàng mở cửa cho bạn, và Ngài biết bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là nơi trú ẩn của con trong ngày hoạn nạn. Xin giúp con nương náu nơi Ngài, và nhớ rằng Ngài biết con từng chi tiết trong hoàn cảnh con. A-men."},{"sach":"Ha-ba-cúc","ma":"HAB","chuong":2,"cau":4,"loi_kinh_thanh":"Nầy, lòng người kiêu ngạo, không có sự ngay thẳng trong nó; song người công bình thì sống bởi đức tin mình.","bai_hoc":"Câu này nói rằng người công bình sẽ sống bởi đức tin. Tiên tri Ha-ba-cúc viết lời này giữa lúc thấy quá nhiều bất công và đang hỏi Chúa vì sao Ngài không hành động. Chúa không trả lời bằng một lời giải thích dài, mà bằng một lời mời: hãy sống bởi đức tin, tức là tin cậy Ngài ngay cả khi chưa thấy kết quả. Sứ đồ Phao-lô sau này dùng câu này để giải thích về ơn cứu. Hôm nay, nếu bạn có điều khiến lòng bạn thắc mắc, hãy thưa với Chúa, rồi chọn tiếp tục tin cậy Ngài từng ngày một.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống bởi đức tin, tin cậy Ngài ngay cả khi con chưa hiểu hay chưa thấy. Xin cho con kiên nhẫn chờ đợi điều Ngài đã hứa, và giữ lòng con vững vàng. A-men."},{"sach":"Ha-ba-cúc","ma":"HAB","chuong":2,"cau":14,"loi_kinh_thanh":"Vì sự nhận biết vinh quang Đức Giê-hô-va sẽ đầy dẫy khắp đất như nước đầy tràn biển.","bai_hoc":"Lời hứa này nói rằng đất sẽ đầy dẫy sự nhận biết vinh hiển của Đức Giê-hô-va như nước đầy biển. Hãy hình dung đại dương: không một chỗ nào trên đáy biển là không có nước. Chúa hứa một ngày như vậy, khi mọi nơi đều tràn ngập sự nhận biết Ngài. Đây là hy vọng lớn lao giữa một thế giới còn nhiều bất công và đau thương. Nó cũng mời chúng ta góp phần, bằng việc sống và chia sẻ điều mình biết về Ngài. Hôm nay, hãy làm một việc nhỏ để người khác nhận biết tình yêu của Chúa qua bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa ngày sự nhận biết vinh hiển Ngài đầy dẫy khắp đất. Xin dùng con làm một phần nhỏ trong kế hoạch ấy, qua lời nói và việc làm của con. A-men."},{"sach":"Ha-ba-cúc","ma":"HAB","chuong":3,"cau":17,"loi_kinh_thanh":"Vì dầu cây vả sẽ không nứt lộc nữa, Và sẽ không có trái trên những cây nho; Cây ô-li-ve không sanh sản, Và chẳng có ruộng nào sanh ra đồ ăn; Bầy chiên sẽ bị dứt khỏi ràn, Và không có bầy bò trong chuồng nữa.","bai_hoc":"Ha-ba-cúc mô tả một cảnh khó khăn: cây vả không trổ bông, vườn nho không có trái, đồng ruộng không sinh lương thực, chiên bị mất khỏi chuồng. Mọi nguồn sinh kế đều thiếu vắng. Nhưng tiếp theo, ông chọn một cách đáp lại đặc biệt. Lời này cho thấy đức tin không phải là phủ nhận hoàn cảnh khó khăn, mà là nhìn thẳng vào nó và vẫn chọn tin cậy Chúa. Điều này thành thật và đầy can đảm. Hôm nay, nếu bạn đang gặp thiếu thốn hay bất định, hãy gọi tên nó trước mặt Chúa, rồi chọn nương cậy Ngài.","loi_cau_nguyen":"Chúa ơi, khi mọi thứ con từng dựa vào dường như thiếu vắng, xin giúp con nhìn thẳng vào hoàn cảnh và vẫn chọn tin cậy Ngài. Xin ở bên con trong sự thiếu thốn, và nuôi dưỡng con bằng sự hiện diện của Ngài. A-men."},{"sach":"Ha-ba-cúc","ma":"HAB","chuong":3,"cau":18,"loi_kinh_thanh":"Dầu vậy, tôi sẽ vui mừng trong Đức Giê-hô-va, Tôi sẽ hớn hở trong Đức Chúa Trời của sự cứu rỗi tôi.","bai_hoc":"Sau khi mô tả cảnh khó khăn, Ha-ba-cúc nói: \\"Dầu vậy, tôi sẽ vui mừng trong Đức Giê-hô-va, Tôi sẽ hớn hở trong Đức Chúa Trời của sự cứu rỗi tôi\\" Niềm vui này không đến từ hoàn cảnh, mà từ chính Chúa. Có một loại niềm vui sâu hơn cảm xúc, và nó có thể sống chung với nước mắt. Đó là niềm vui của người biết mình được Chúa cứu và giữ. Hôm nay, hãy tìm một lý do để vui trong Chúa, dù hoàn cảnh còn khó: Ngài yêu bạn, Ngài ở cùng bạn, và Ngài là Đấng cứu bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đức Chúa Trời của sự cứu rỗi con. Xin cho con niềm vui trong Ngài, không phụ thuộc vào hoàn cảnh, và giúp con vui mừng vì biết Ngài yêu thương con. A-men."},{"sach":"Xô-phô-ni","ma":"ZEP","chuong":3,"cau":17,"loi_kinh_thanh":"Giê-hô-va Đức Chúa Trời ngươi ở giữa ngươi; Ngài là Đấng quyền năng sẽ giải cứu ngươi: Ngài sẽ vui mừng cả thể vì cớ ngươi; vì lòng yêu thương mình, Ngài sẽ nín lặng; và vì cớ ngươi Ngài sẽ ca hát mừng rỡ.","bai_hoc":"Chúa ở giữa bạn là Đấng quyền năng để cứu. Ngài sẽ vui mừng vì bạn, im lặng trong tình yêu của Ngài, và reo hò vì bạn bằng tiếng ca. Hãy dừng lại ở hình ảnh này: Chúa hát về bạn. Không phải Ngài chịu đựng bạn, hay thất vọng về bạn, mà Ngài vui mừng và reo ca. Có những lúc chúng ta nghĩ Chúa chỉ chú ý đến lỗi lầm của mình. Câu này nói ngược lại. Hôm nay, hãy để mình được yêu thương như vậy, và thầm tưởng tượng Chúa đang hát lên niềm vui về bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vui mừng vì con và reo ca vì con. Xin giúp con nhận lấy tình yêu ấy, và thôi nghĩ rằng Ngài chỉ nhìn thấy lỗi lầm của con. A-men."},{"sach":"Xa-cha-ri","ma":"ZEC","chuong":4,"cau":6,"loi_kinh_thanh":"Người đáp lại rằng: Đây là lời của Đức Giê-hô-va phán cho Xô-rô-ba-bên rằng: Ấy chẳng phải là bởi quyền thế, cũng chẳng phải là bởi năng lực, bèn là bởi Thần ta, Đức Giê-hô-va vạn quân phán vậy.","bai_hoc":"Chúa nhắn với Xô-rô-ba-bên, người đang xây lại đền thờ giữa nhiều khó khăn: không phải bởi quyền thế, không phải bởi sức mạnh, nhưng bởi Thần của Ta. Công việc của Chúa không thành nhờ nhân lực hay tài nguyên, mà nhờ Thánh Linh. Điều này vừa làm ta khiêm nhường, vừa làm ta nhẹ nhõm: bạn không phải làm mọi thứ bằng sức mình. Hôm nay, trước khi bắt đầu một công việc quan trọng, hãy dừng lại cầu xin Thánh Linh dẫn dắt và ban sức mạnh. Hãy làm phần của bạn, và để Ngài làm điều chỉ Ngài làm được.","loi_cau_nguyen":"Chúa ơi, công việc của Ngài không thành bởi sức riêng, nhưng bởi Thánh Linh của Ngài. Xin giúp con nương cậy Ngài, và cho con khiêm nhường làm việc với sự dẫn dắt của Thánh Linh. A-men."},{"sach":"Xa-cha-ri","ma":"ZEC","chuong":9,"cau":9,"loi_kinh_thanh":"Hỡi con gái Si-ôn, hãy mừng rỡ cả thể! Hỡi con gái Giê-ru-sa-lem, hãy trổi tiếng reo vui! Nầy, Vua ngươi đến cùng ngươi, Ngài là công bình và ban sự cứu rỗi, nhu mì và cỡi lừa, tức là con của lừa cái.","bai_hoc":"Tiên tri kêu gọi con gái Si-ôn hãy vui mừng, vì vua của nàng đến với nàng, công bình và có sự cứu rỗi, khiêm nhường và cưỡi lừa. Một vị vua không cưỡi ngựa chiến mà cưỡi lừa con là hình ảnh của sự khiêm nhường. Chúa Giê-su ứng nghiệm lời này khi vào thành Giê-ru-sa-lem. Vua của chúng ta không đến bằng quyền lực áp đảo, mà bằng sự dịu dàng và yêu thương. Hôm nay, hãy nhớ rằng bạn đang theo một Vua khiêm nhường, và hãy học cách sống khiêm nhường theo Ngài trong một việc cụ thể.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Vua khiêm nhường đã đến để cứu con. Xin giúp con sống khiêm nhường theo gương Ngài, và vui mừng vì Vua của con là Đấng công bình và đầy ơn cứu. A-men."},{"sach":"Xa-cha-ri","ma":"ZEC","chuong":12,"cau":10,"loi_kinh_thanh":"Ta sẽ đổ thần của ơn phước và của sự nài xin ra trên nhà Đa-vít, và trên dân cư Giê-ru-sa-lem; chúng nó sẽ nhìn xem ta là Đấng chúng nó đã đâm; và chúng nó sẽ thương khóc, như là thương khóc con trai một, sẽ ở trong sự cay đắng, như khi người ta ở trong sự cay đắng vì cớ con đầu lòng.","bai_hoc":"Lời này nói rằng người ta sẽ ngắm nhìn Đấng mà họ đã đâm, và sẽ than khóc vì Ngài như khóc con một. Cơ Đốc nhân hiểu rằng đây là lời tiên tri về Chúa Giê-su trên thập tự giá, và Tin Lành Giăng cũng trích dẫn câu này. Chúa hứa đổ trên dân Ngài thần ân điển và sự nài xin. Nhìn lên thập tự giá không phải để chìm trong mặc cảm, mà để thấy tình yêu và để lòng ăn năn được mở ra. Hôm nay, hãy dành một phút nhìn lên Chúa Giê-su và nói lời cảm ơn Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã chịu đâm vì con. Xin đổ trên con thần ân điển và sự cầu xin, để lòng con mềm ra trước tình yêu của Ngài và biết ăn năn thật. A-men."},{"sach":"Ma-la-chi","ma":"MAL","chuong":3,"cau":1,"loi_kinh_thanh":"Nầy, ta sai sứ giả ta, người sẽ dọn đường trước mặt ta; và Chúa mà các ngươi tìm kiếm sẽ thình lình vào trong đền thờ Ngài, tức là thiên sứ của sự giao ước mà các ngươi trông mong. Nầy, Ngài đến, Đức Giê-hô-va vạn quân phán vậy.","bai_hoc":"Chúa phán rằng Ngài sẽ sai sứ giả đi trước dọn đường, và rồi Chúa mà dân tìm kiếm sẽ đến đền thờ Ngài. Các sách Phúc Âm nói rằng Giăng Báp-tít là sứ giả này, chuẩn bị cho Chúa Giê-su. Lời hứa này được nói vào thời kỳ dân sự mệt mỏi và hoài nghi, và Chúa nhắc rằng Ngài sẽ đến. Dù có lúc bạn thấy Chúa im lặng, Ngài vẫn đang chuẩn bị và đang đến gần. Hôm nay, hãy chuẩn bị lòng mình để đón Ngài, bằng một khoảnh khắc yên lặng và biết ơn. Ngài đáng được chờ đợi.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa sai sứ giả đi trước và chính Ngài đến. Xin giúp con chuẩn bị lòng mình, và kiên nhẫn đợi Ngài trong những lúc con thấy Ngài im lặng. A-men."},{"sach":"Ma-la-chi","ma":"MAL","chuong":3,"cau":6,"loi_kinh_thanh":"Vì ta là Đức Giê-hô-va, ta không hề thay đổi; bởi cớ đó, các ngươi là con trai Gia-cốp, chẳng bị diệt vong.","bai_hoc":"Chúa phán: \\"Vì ta là Đức Giê-hô-va, ta không hề thay đổi; bởi cớ đó, các ngươi là con trai Gia-cốp, chẳng bị diệt vong\\" Đây là điều đáng kinh ngạc: sự sống còn của dân sự dựa trên sự không đổi thay của Chúa, không phải trên sự trung tín của họ. Tính cách và tình yêu của Ngài vững chắc hôm qua, hôm nay và mãi mãi. Khi mọi thứ xung quanh thay đổi, bạn có một điểm tựa không đổi. Hôm nay, hãy nhớ rằng điều bạn có thể dựa vào nhất là Chúa không đổi thay, và hãy nghỉ ngơi trong đó. Dù ngày mai thế nào, Ngài vẫn là Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài không bao giờ thay đổi. Khi mọi thứ xung quanh con đổi thay, xin cho con đặt lòng tin vào sự thành tín bền vững của Ngài. A-men."},{"sach":"Ma-la-chi","ma":"MAL","chuong":3,"cau":10,"loi_kinh_thanh":"Các ngươi hãy đem hết thảy phần mười vào kho, hầu cho có lương thực trong nhà ta; và từ nay các ngươi khá lấy điều nầy mà thử ta, Đức Giê-hô-va vạn quân phán, xem ta có mở các cửa sổ trên trời cho các ngươi, đổ phước xuống cho các ngươi đến nỗi không chỗ chứa chăng!","bai_hoc":"Chúa mời dân Ngài đem trọn phần mười vào kho, và thử xem Ngài có mở các cửa sổ trên trời đổ phước cho họ không. Đây là lời mời tin cậy Chúa qua sự dâng hiến. Dâng không phải để mua phước, mà là bày tỏ rằng mọi thứ ta có đều đến từ Ngài và ta tin cậy Ngài chu cấp. Điều này nên được làm với lòng vui và sự khôn ngoan, không vì ép buộc hay sợ hãi. Hôm nay, hãy cầu nguyện về cách bạn có thể bày tỏ lòng biết ơn và sự tin cậy với Chúa qua việc dâng hiến, theo khả năng của mình.","loi_cau_nguyen":"Chúa ơi, mọi điều con có đều đến từ Ngài. Xin giúp con dâng hiến với lòng vui và sự khôn ngoan, như một cách bày tỏ lòng biết ơn và tin cậy Ngài là Đấng chu cấp. A-men."},{"sach":"Ma-la-chi","ma":"MAL","chuong":4,"cau":2,"loi_kinh_thanh":"Nhưng về phần các ngươi là kẻ kính sợ danh ta, thì mặt trời công bình sẽ mọc lên cho, trong cánh nó có sự chữa bịnh; các ngươi sẽ đi ra và nhảy nhót như bò tơ của chuồng.","bai_hoc":"Với những ai kính sợ danh Ngài, Mặt Trời công bình sẽ mọc lên, với sự chữa lành trong cánh Ngài. Hình ảnh này đẹp: một buổi bình minh đến sau đêm dài, mang theo hơi ấm và sự chữa lành. Đây là lời hứa cuối cùng của Cựu Ước, và nó chỉ về Chúa Giê-su, Ánh Sáng của thế gian. Có những đêm dài trong đời, và Chúa hứa buổi sáng sẽ đến. Hôm nay, nếu bạn đang trải qua một đêm tối, hãy nhớ rằng mặt trời đang mọc, và Ngài mang theo sự chữa lành cho những ai trông đợi Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Mặt Trời công bình mang sự chữa lành. Xin giữ con trông đợi Ngài trong đêm dài, và ban cho con hy vọng về buổi sáng Ngài hứa. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":1,"cau":23,"loi_kinh_thanh":"Nầy, một gái đồng trinh sẽ chịu thai, và sanh một con trai, Rồi người ta sẽ đặt tên con trai đó là Em-ma-nu-ên; nghĩa là: Đức Chúa Trời ở cùng chúng ta.","bai_hoc":"Em-ma-nu-ên, nghĩa là Đức Chúa Trời ở cùng chúng ta. Đó là tên gọi của Chúa Giê-su theo lời tiên tri được Ma-thi-ơ trích dẫn. Hãy dừng lại ở ý nghĩa này: Đức Chúa Trời, Đấng Tạo Hóa của vũ trụ, chọn đến ở giữa con người, trở thành một em bé trong máng cỏ. Ngài không muốn là một Đấng ở xa. Ngài muốn ở cùng bạn trong cả những ngày bình thường nhất, những ngày mệt mỏi, những đêm nhiều lo lắng. Hôm nay, hãy thầm nhắc: Chúa ở cùng tôi, và để lòng được yên ổn trong sự thật ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đến ở cùng chúng con trong Chúa Giê-su. Xin giúp con cảm nhận sự hiện diện của Ngài trong những ngày bình thường, và không bao giờ cảm thấy mình đơn độc. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":3,"cau":17,"loi_kinh_thanh":"Tức thì có tiếng từ trên trời phán rằng: Nầy là Con yêu dấu của ta, đẹp lòng ta mọi đàng.","bai_hoc":"Khi Chúa Giê-su vừa chịu báp-têm, có tiếng từ trời phán: Nầy là Con yêu dấu của Ta, đẹp lòng Ta mọi đường. Lời này được nói trước khi Chúa Giê-su làm bất cứ phép lạ hay giảng dạy nào. Chúa Cha nói điều đó không phải vì Ngài làm được gì, mà vì Ngài là Con. Và khi bạn tin Chúa Giê-su, bạn cũng được nhận làm con trong gia đình Ngài. Hôm nay, hãy để mình nghe lời yêu thương này: bạn không phải làm gì để có chỗ trong lòng Cha, bạn đã được yêu. Hãy để lời ấy lắng xuống trong lòng bạn.","loi_cau_nguyen":"Chúa Cha ơi, cảm ơn Cha đã nhận con làm con qua Chúa Giê-su. Xin giúp con sống trong sự chắc chắn rằng con được yêu, và không phải làm điều gì để chứng minh mình đáng được Cha thương. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":4,"cau":4,"loi_kinh_thanh":"Đức Chúa Jêsus đáp: Có lời chép rằng: Người ta sống chẳng phải chỉ nhờ bánh mà thôi, song nhờ mọi lời nói ra từ miệng Đức Chúa Trời.","bai_hoc":"Khi bị cám dỗ trong đồng vắng, Chúa Giê-su trả lời quỷ bằng Lời Chúa: Có chép rằng, người ta sống chẳng phải chỉ nhờ bánh. Ngài vừa đói sau bốn mươi ngày nhịn ăn, nhưng Ngài chọn tin vào lời của Cha hơn là thỏa mãn nhu cầu theo cách của cám dỗ. Điều này dạy ta rằng Lời Chúa là vũ khí và là lương thực. Khi bạn đối diện cám dỗ, một câu Kinh Thánh bạn đã ghi nhớ có thể trở thành nơi nương tựa. Hôm nay, hãy học thuộc một câu ngắn để mang theo trong những lúc yếu lòng.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã cho con Lời Ngài để nuôi dưỡng và bảo vệ con. Xin giúp con học thuộc và dùng Lời Ngài khi gặp cám dỗ, theo gương Chúa Giê-su. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":4,"cau":19,"loi_kinh_thanh":"Ngài phán cùng hai người rằng: Các ngươi hãy theo ta, ta sẽ cho các ngươi nên tay đánh lưới người.","bai_hoc":"Chúa Giê-su gặp những ngư phủ đang vá lưới và nói: \\"Ngài phán cùng hai người rằng: Các ngươi hãy theo ta, ta sẽ cho các ngươi nên tay đánh lưới người\\" Họ để lại lưới và theo Ngài ngay. Chúa không gọi những người giỏi nhất hay có địa vị, mà gọi những người bình thường đang làm việc hằng ngày. Ngài mời họ đi theo và hứa biến đổi họ. Điều đó cũng đúng với bạn: Ngài gọi bạn như bạn đang là, rồi từng bước làm bạn nên điều Ngài định. Hôm nay, hãy nghe tiếng gọi Hãy theo Ta ngay giữa những công việc quen thuộc của bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài gọi con theo Ngài như con đang là. Xin giúp con đáp lại tiếng gọi ấy với lòng sẵn sàng, và dùng đời con để dẫn người khác đến với Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":3,"loi_kinh_thanh":"Phước cho những kẻ có lòng khó khăn, vì nước thiên đàng là của những kẻ ấy!","bai_hoc":"Phước cho những người nghèo khó trong tâm linh, vì nước thiên đàng là của họ. Bài giảng trên núi bắt đầu bằng một lời chúc phước kỳ lạ. Nghèo khó trong tâm linh là nhận biết mình cần Chúa, không tự đủ, không tự cứu được mình. Đó là điều ngược với xã hội luôn đề cao sự tự tin và thành tựu. Nhưng nước Trời dành cho những người biết rằng họ cần Ngài. Hôm nay, hãy thành thật thưa với Chúa: con cần Ngài. Đó không phải là yếu đuối, mà là bước khởi đầu đẹp nhất để nhận phước từ Ngài.","loi_cau_nguyen":"Chúa ơi, con thành thật thưa rằng con cần Ngài trong mọi việc. Xin giúp con có tấm lòng khiêm nhường, nhận biết mình nghèo khó trong tâm linh, và nhận lấy nước Trời Ngài ban. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":6,"loi_kinh_thanh":"Phước cho những kẻ đói khát sự công bình, vì sẽ được no đủ!","bai_hoc":"Phước cho những người đói khát sự công bình, vì sẽ được no đủ. Hãy nghĩ về cảm giác đói thật sự: nó không thể bị lờ đi và thúc đẩy ta tìm thức ăn. Chúa mời ta khao khát sự công bình, lẽ thật và điều đúng đắn mạnh mẽ như vậy. Và Ngài hứa những ai khao khát như vậy sẽ được thỏa mãn. Có lẽ bạn đang khao khát một thế giới công bình hơn, hay một đời sống ngay thẳng hơn. Đó là khao khát Chúa đặt trong bạn. Hôm nay, hãy làm một điều nhỏ để nuôi dưỡng sự công bình, và xin Ngài làm no lòng bạn.","loi_cau_nguyen":"Chúa ơi, xin cho con khao khát sự công bình như người đói khát. Xin giúp con sống ngay thẳng, làm điều đúng, và làm no lòng con bằng sự công bình của Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":7,"loi_kinh_thanh":"Phước cho những kẻ hay thương xót, vì sẽ được thương xót!","bai_hoc":"Phước cho những người hay thương xót, vì sẽ được thương xót. Chúng ta đều đã nhận lòng thương xót từ Chúa, và lòng thương xót ấy mời ta chia sẻ cho người khác. Thương xót là nhìn người khác với sự thông cảm và sẵn sàng tha thứ, kể cả khi họ chưa xứng đáng. Chúa Giê-su dạy rằng thái độ ta dành cho người khác sẽ lặp lại điều ta nhận. Hôm nay, hãy chọn một người đang làm bạn khó chịu hoặc đã làm bạn tổn thương, và thử nhìn họ với một chút thương xót hơn, rồi cầu nguyện cho họ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã thương xót con. Xin cho con lòng thương xót với người khác, nhất là những người khó thương, và giúp con đối xử với họ như Ngài đã đối xử với con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":8,"loi_kinh_thanh":"Phước cho những kẻ có lòng trong sạch, vì sẽ thấy Đức Chúa Trời!","bai_hoc":"Phước cho những người có lòng trong sạch, vì sẽ thấy Đức Chúa Trời. Trong sạch ở đây là sự chân thành, không hai lòng, không giả hình. Đó là việc làm cho lòng mình ngay thẳng và rõ ràng trước mặt Chúa. Điều đẹp là lời hứa đi kèm: họ sẽ thấy Chúa. Khi lòng bạn càng trong sạch, bạn càng nhận ra Ngài trong cuộc sống: trong thiên nhiên, trong con người, trong lời Ngài. Hôm nay, hãy hỏi Chúa: có điều gì làm lòng tôi đục? Và xin Ngài làm sạch. Ngài làm điều ấy bằng sự dịu dàng, không phải bằng sự trách móc, và Ngài kiên nhẫn với bạn.","loi_cau_nguyen":"Chúa ơi, xin làm cho lòng con trong sạch, chân thành và không hai lòng. Xin giúp con nhận ra Ngài hơn mỗi ngày, trong những điều nhỏ bé quanh con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":9,"loi_kinh_thanh":"Phước cho những kẻ làm cho người hòa thuận, vì sẽ được gọi là con Đức Chúa Trời!","bai_hoc":"Phước cho những người làm cho người ta hòa thuận, vì sẽ được gọi là con Đức Chúa Trời. Người làm hòa không chỉ tránh xung đột, mà chủ động đem lại sự hòa thuận. Đó là việc khó: phải lắng nghe, nhường nhịn, đôi khi chịu thiệt. Nhưng đó cũng là công việc của Chúa trong thế gian, nên ai làm hòa thì giống Cha mình. Có thể có một mối quan hệ cần được hàn gắn trong đời bạn. Hôm nay, hãy làm một bước nhỏ: một lời nhắn, một lời xin lỗi, hay một lời cầu nguyện cho người ấy.","loi_cau_nguyen":"Chúa ơi, xin làm con thành người đem lại hòa thuận. Xin cho con can đảm làm bước đầu để hàn gắn một mối quan hệ, và lòng nhẫn nại để đi hết con đường ấy. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":13,"loi_kinh_thanh":"Các ngươi là muối của đất; song nếu mất mặn đi, thì sẽ lấy giống chi mà làm cho mặn lại? Muối ấy không dùng chi được nữa, chỉ phải quăng ra ngoài và bị người ta đạp dưới chân.","bai_hoc":"Chúa Giê-su nói các môn đồ là muối của đất. Muối giữ cho thức ăn khỏi hư và làm cho món ăn có hương vị. Muối không cần phô trương, nó hòa vào và làm khác biệt từ bên trong. Đời sống người tin cũng vậy: không cần ồn ào, nhưng sự chân thành, tử tế và ngay thẳng của bạn làm cho nơi bạn đang sống tốt hơn. Hôm nay, hãy nghĩ xem bạn có thể là muối ở đâu: một cuộc họp, một bữa cơm gia đình, một nhóm bạn. Hãy làm một điều nhỏ mang hương vị của Chúa vào đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con là muối của đất, giữ gìn và làm cho cuộc sống quanh con thêm hương vị tốt lành. Xin cho con sống chân thành và tử tế, ngay cả khi không ai để ý. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":14,"loi_kinh_thanh":"Các ngươi là sự sáng của thế gian; một cái thành ở trên núi thì không khi nào bị khuất được:","bai_hoc":"Chúa Giê-su nói các môn đồ là ánh sáng của thế gian, như một thành xây trên núi không thể bị che khuất. Ánh sáng không cố gắng, nó chỉ cần được thắp lên. Khi bạn đã tin Chúa Giê-su, ánh sáng của Ngài ở trong bạn. Không cần ép mình trở thành ai khác, chỉ cần sống thật với điều Chúa làm trong bạn. Có thể bạn nghĩ ánh sáng của mình quá nhỏ, nhưng trong bóng tối, ngay cả ánh sáng nhỏ cũng quý. Hôm nay, hãy để ánh sáng ấy chiếu qua một hành động tử tế cho ai đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã thắp lên ánh sáng của Ngài trong con. Xin giúp con để ánh sáng ấy chiếu ra qua việc làm và lời nói tử tế, và không giấu đi vì sợ hay ngại. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":16,"loi_kinh_thanh":"Sự sáng các ngươi hãy soi trước mặt người ta như vậy, đặng họ thấy những việc lành của các ngươi, và ngợi khen Cha các ngươi ở trên trời.","bai_hoc":"Chúa Giê-su dạy hãy để sự sáng mình soi trước mặt người ta, để họ thấy việc lành của mình và ngợi khen Cha trên trời. Mục đích của việc lành không phải để được khen, mà để người ta nhìn thấy Chúa. Khi bạn làm điều tốt với lòng chân thành, những người xung quanh có thể được chạm đến bởi tình yêu của Cha. Hôm nay, hãy làm một việc lành và thầm dâng nó lên Chúa, mong rằng qua đó ai đó nhận ra sự tốt lành của Ngài. Bạn không cần làm điều lớn lao, chỉ cần chân thành và để Chúa làm phần còn lại. Có những việc nhỏ như một lời hỏi han hay một bữa ăn cũng đủ làm một người cảm nhận tình thương.","loi_cau_nguyen":"Chúa ơi, xin cho việc lành của con làm cho người khác thấy Ngài chứ không phải con. Xin giúp con làm điều tốt với lòng chân thành, và dâng mọi vinh hiển cho Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":5,"cau":44,"loi_kinh_thanh":"Song ta nói cùng các ngươi rằng: Hãy yêu kẻ thù nghịch, và cầu nguyện cho kẻ bắt bớ các ngươi,","bai_hoc":"Chúa Giê-su dạy hãy yêu kẻ thù và cầu nguyện cho những người bắt bớ mình. Đây là một trong những lời dạy khó nhất. Yêu kẻ thù không có nghĩa là chấp nhận điều sai, mà là chọn không để cay đắng chi phối, và cầu xin điều tốt cho họ. Chính Chúa đã làm điều đó với chúng ta: Ngài yêu ta khi ta còn xa cách. Quyết định này không dễ và có thể phải lặp lại nhiều lần. Hôm nay, hãy cầu nguyện cho một người làm bạn tổn thương, dù chỉ một câu đơn giản: Chúa ơi, xin ban phước cho người ấy.","loi_cau_nguyen":"Chúa ơi, con khó yêu những người làm con tổn thương, nhưng con muốn làm theo lời Ngài. Xin giúp con cầu nguyện cho họ, giải thoát con khỏi cay đắng, và đổ tình yêu của Ngài vào lòng con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":9,"loi_kinh_thanh":"Vậy các ngươi hãy cầu như vầy: Lạy Cha chúng tôi ở trên trời; Danh Cha được thánh;","bai_hoc":"Chúa Giê-su dạy các môn đồ cầu nguyện bắt đầu bằng hai chữ giản dị: Cha chúng con. Không phải một danh xưng xa cách, mà là cách gọi của đứa con với người cha. Trước khi xin điều gì, chúng ta được mời nhớ mình đang nói chuyện với ai: một Đấng yêu thương, lắng nghe, và là Cha chung của cả cộng đoàn. Câu này cũng nhắc rằng chúng ta cầu nguyện cùng nhau, không chỉ cho riêng mình. Hôm nay, hãy thử bắt đầu lời cầu nguyện bằng chữ Cha ơi, và để chữ ấy chạm vào lòng bạn trước khi nói tiếp.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã cho con được gọi Cha. Xin giúp con đến với Cha như một đứa con với người cha, tin cậy, thành thật, và biết rằng Cha lắng nghe con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":10,"loi_kinh_thanh":"Nước Cha được đến; ý Cha được nên, ở đất như trời!","bai_hoc":"Trong lời cầu nguyện Chúa dạy, có lời xin nước Cha được đến và ý Cha được nên ở đất như ở trời. Điều này đổi hướng lời cầu nguyện: không chỉ xin Chúa làm theo ý mình, mà xin lòng mình hướng theo ý Ngài. Đó là sự tin cậy rằng ý Chúa tốt hơn ý ta, dù ta chưa hiểu hết. Và đó cũng là lời mời để ta góp phần đem nước Ngài đến qua việc làm. Hôm nay, hãy hỏi Chúa: ý Ngài muốn được nên ở đâu trong đời tôi hôm nay? Hãy lắng nghe và sẵn lòng làm theo.","loi_cau_nguyen":"Cha ơi, xin cho nước Cha đến và ý Cha được nên, trong con, trong gia đình con và nơi con đang sống. Xin sắp xếp lòng con theo ý Cha, và giúp con tin rằng ý Cha tốt hơn ý con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":11,"loi_kinh_thanh":"Xin cho chúng tôi hôm nay đồ ăn đủ ngày;","bai_hoc":"Xin cho chúng con hôm nay đồ ăn đủ ngày. Một lời cầu nguyện thật thực tế: \\"Xin cho chúng tôi hôm nay đồ ăn đủ ngày\\" Chúa mời ta sống từng ngày với sự tin cậy, không tích trữ lo âu cho cả năm. Có thể bạn lo về những khoản chi, công việc, sức khỏe. Chúa không bảo bạn đừng lập kế hoạch, mà mời bạn tin rằng Ngài lo cho từng ngày. Hãy đừng quên cả việc biết ơn những gì đã có trên bàn ăn của bạn. Hôm nay, trước bữa ăn, hãy dừng lại cảm ơn Chúa thật sự, không chỉ qua loa.","loi_cau_nguyen":"Cha ơi, xin cho con đủ những gì con cần cho ngày hôm nay. Xin giúp con tin cậy Cha lo từng ngày một, và biết ơn những gì Cha đã ban, dù nhỏ bé. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":12,"loi_kinh_thanh":"Xin tha tội lỗi cho chúng tôi, như chúng tôi cũng tha kẻ phạm tội nghịch cùng chúng tôi;","bai_hoc":"Xin tha nợ cho chúng con, như chúng con cũng tha cho kẻ có nợ chúng con. Lời cầu nguyện này nối kết sự tha thứ ta nhận với sự tha thứ ta trao. Khi hiểu mình đã được tha nhiều, ta dễ dàng hơn trong việc tha cho người khác. Tha thứ không có nghĩa là nói điều sai là đúng, hay phải quên ngay nỗi đau. Đó là quyết định buông bỏ quyền đòi nợ. Quá trình ấy có thể mất thời gian. Hôm nay, hãy nghĩ đến một người bạn cần tha thứ, và xin Chúa giúp bạn bắt đầu bước đầu tiên, dù nhỏ.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã tha thứ cho con. Xin giúp con tha thứ cho người khác, từng bước một, và giải thoát con khỏi sự cay đắng. Xin cho con bắt đầu từ chỗ con có thể, bằng ân điển của Cha. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":13,"loi_kinh_thanh":"Xin chớ để chúng tôi bị cám dỗ, mà cứu chúng tôi khỏi điều ác! Vì nước, quyền, vinh hiển đều thuộc về Cha đời đời. A-men.","bai_hoc":"Xin đừng dẫn chúng con vào sự cám dỗ, nhưng cứu chúng con khỏi điều ác. Lời cầu nguyện này thừa nhận rằng ta cần được bảo vệ mỗi ngày. Chúng ta không đủ mạnh để đứng một mình trước mọi cám dỗ. Việc thừa nhận điều đó không phải yếu đuối, mà là sự khôn ngoan. Cha biết điểm yếu của chúng ta và sẵn lòng gìn giữ. Hôm nay, hãy nhận ra một lĩnh vực mà bạn dễ vấp ngã, và cầu xin Chúa giữ bạn ở đó. Hãy dùng cả những cách khôn ngoan: tránh xa những tình huống cám dỗ, tìm một người bạn cầu thay.","loi_cau_nguyen":"Cha ơi, xin giữ con khỏi những cám dỗ mà con không đủ sức chống lại một mình. Xin cứu con khỏi điều ác, và cho con sự khôn ngoan để tránh xa những tình huống dễ làm con vấp ngã. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":20,"loi_kinh_thanh":"nhưng phải chứa của cải ở trên trời, là nơi chẳng có sâu mối, ten rét làm hư, cũng chẳng có kẻ trộm đào ngạch khoét vách mà lấy.","bai_hoc":"Chúa Giê-su khuyên hãy chất của cải cho mình ở trên trời, là nơi mối mọt và rỉ sét không làm hư, kẻ trộm không đào ngạch. Ngài không bảo ta khinh thường công việc hay tiền bạc, mà mời ta đầu tư vào điều tồn tại mãi: các mối quan hệ, lòng nhân từ, đức tin, việc giúp đỡ người khác. Có những điều chỉ có giá trị trong một thời gian, và có những điều có giá trị đời đời. Hôm nay, hãy làm một việc nhỏ đầu tư cho điều vĩnh cửu: một cuộc trò chuyện chân thành, một sự giúp đỡ âm thầm, một lời cầu nguyện cho ai đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con đầu tư đời mình vào những điều có giá trị đời đời. Xin cho con biết đặt thời gian, tiền bạc và sức lực vào những việc đẹp lòng Ngài, và để lòng con không bám chặt vào những điều phù du. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":21,"loi_kinh_thanh":"Vì chưng của cải ngươi ở đâu, thì lòng ngươi cũng ở đó.","bai_hoc":"Của cải ngươi ở đâu, thì lòng ngươi cũng ở đó. Câu này giản dị mà sâu sắc: điều bạn đầu tư thời gian, tiền bạc, sự chú ý nhiều nhất sẽ kéo lòng bạn về phía nó. Bạn có thể nhìn vào cách mình dùng thời gian và tiền để biết lòng mình đang ở đâu. Điều đó không nhằm gây mặc cảm mà để nhận ra và điều chỉnh. Nếu muốn lòng gần Chúa hơn, hãy bắt đầu đầu tư vào các điều thuộc về Ngài. Hôm nay, hãy nhìn lại cách bạn dùng một giờ trong ngày, và xem có thể dành một phần cho điều đáng giá lâu bền.","loi_cau_nguyen":"Chúa ơi, xin cho lòng con ở nơi kho báu thật sự của con là Ngài. Xin giúp con nhìn lại cách con dùng thời gian và tiền bạc, và điều chỉnh những chỗ cần điều chỉnh bằng sự dẫn dắt của Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":24,"loi_kinh_thanh":"Chẳng ai được làm tôi hai chủ; vì sẽ ghét người nầy mà yêu người kia, hoặc trọng người nầy mà khinh người kia. Các ngươi không có thể làm tôi Đức Chúa Trời lại làm tôi Ma-môn nữa.","bai_hoc":"Không ai có thể làm tôi hai chủ, vì sẽ ghét người này mà yêu người kia. Không thể vừa hầu việc Đức Chúa Trời vừa hầu việc tiền bạc. Câu này nói về sự trung tâm của đời sống. Tiền bạc là điều cần thiết, nhưng nếu nó trở thành chủ nhân, nó sẽ điều khiển lựa chọn, thời gian và lòng ta. Chúa muốn ta là người quản lý của cải, không là nô lệ của nó. Hôm nay, hãy hỏi mình: có điều gì về tiền bạc đang khiến tôi lo lắng hơn là tin cậy Chúa? Và hãy trao điều đó cho Ngài.","loi_cau_nguyen":"Chúa ơi, xin giúp con không để tiền bạc làm chủ lòng con. Xin cho con quản lý của cải với sự khôn ngoan và tự do, và đặt Ngài lên hàng đầu trong mọi quyết định về tiền bạc. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":25,"loi_kinh_thanh":"Vậy nên ta phán cùng các ngươi rằng: đừng vì sự sống mình mà lo đồ ăn uống; cũng đừng vì thân thể mình mà lo đồ mặc. Sự sống há chẳng quí trọng hơn đồ ăn sao, thân thể há chẳng quí trọng hơn quần áo sao?","bai_hoc":"Chúa Giê-su nói đừng lo lắng về mạng sống, về ăn uống, về thân thể và áo mặc. Ngài không bảo ta thờ ơ, mà nhắc ta rằng cuộc sống lớn hơn những lo toan ấy. Hãy nhìn chim trời: chúng không gieo gặt mà Cha trên trời vẫn nuôi chúng, và bạn quý giá hơn chúng nhiều. Lo lắng là một thói quen rất khó bỏ, và Chúa biết điều đó, nên Ngài dịu dàng nhắc lại. Hôm nay, khi một nỗi lo xuất hiện, hãy dừng lại nhìn ra ngoài cửa sổ, tìm một con chim hay một chiếc lá, và nhớ rằng Cha cũng chăm sóc bạn.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha chăm sóc chim trời và chăm sóc con. Xin giúp con bớt lo lắng, tin cậy Cha lo liệu những điều con cần, và sống nhẹ nhàng hơn trong từng ngày. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":33,"loi_kinh_thanh":"Nhưng trước hết, hãy tìm kiếm nước Đức Chúa Trời và sự công bình của Ngài, thì Ngài sẽ cho thêm các ngươi mọi điều ấy nữa.","bai_hoc":"Hãy tìm kiếm nước Đức Chúa Trời và sự công bình của Ngài trước, thì Ngài sẽ ban thêm mọi điều ấy cho. Đây là lời nói về thứ tự ưu tiên. Chúa không bảo bạn bỏ bê công việc hay cuộc sống, mà mời bạn đặt Ngài ở vị trí đầu tiên, rồi những điều khác sẽ có chỗ đúng của chúng. Khi Chúa ở đầu, lòng bạn bình an hơn và các quyết định sáng suốt hơn. Hôm nay, hãy bắt đầu ngày mới bằng việc tìm kiếm Chúa trước, dù chỉ vài phút, trước khi mở điện thoại hay bắt đầu công việc.","loi_cau_nguyen":"Chúa ơi, xin giúp con đặt Ngài lên hàng đầu trong cuộc sống. Xin cho con tìm kiếm nước Ngài trước, và tin rằng Ngài lo liệu những điều con cần, khi con đặt đúng thứ tự ưu tiên. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":6,"cau":34,"loi_kinh_thanh":"Vậy, chớ lo lắng chi về ngày mai; vì ngày mai sẽ lo về việc ngày mai. Sự khó nhọc ngày nào đủ cho ngày ấy.","bai_hoc":"Đừng lo lắng về ngày mai, vì ngày mai sẽ tự lo cho nó. Ngày nào có sự khó nhọc của ngày ấy. Chúa Giê-su không hứa ngày mai sẽ nhẹ nhàng, nhưng Ngài mời ta sống từng ngày. Mang theo cả những nỗi lo của ngày mai sẽ làm ta mệt trước khi cần phải mệt. Hôm nay đã có đủ điều để đối diện, và Chúa ban đủ ơn cho hôm nay. Hãy thử thu hẹp tầm nhìn xuống ngày hôm nay: một việc, một bước, một hơi thở. Khi ngày mai đến, Ngài cũng sẽ ở đó với ơn đủ cho ngày ấy.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống từng ngày, không mang theo nỗi lo của ngày mai. Cảm ơn Ngài ban đủ ơn cho hôm nay, và xin giúp con tin rằng ngày mai Ngài cũng ở đó. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":7,"cau":1,"loi_kinh_thanh":"Các ngươi đừng đoán xét ai, để mình khỏi bị đoán xét.","bai_hoc":"Đừng xét đoán ai, để khỏi bị xét đoán. Chúa Giê-su không bảo ta thôi phân biệt đúng sai, mà nhắc ta cẩn thận với thái độ phán xét người khác một cách tự phụ. Chúng ta thường thấy rõ lỗi của người khác và dễ bỏ qua lỗi của mình. Thay vì vội kết luận, hãy thử thấu hiểu. Hãy nhìn người khác bằng ánh mắt của Chúa nhìn mình: nhiều thương xót hơn nhiều so với ta tưởng. Hôm nay, khi bạn thấy mình sắp phán xét ai, hãy dừng lại và hỏi: Mình có biết hết câu chuyện của họ không?","loi_cau_nguyen":"Chúa ơi, xin giúp con không vội phán xét người khác. Xin cho con nhìn họ với sự thấu hiểu và thương xót, và nhìn lại chính mình trước khi nhìn lỗi của người khác. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":7,"cau":7,"loi_kinh_thanh":"Hãy xin, sẽ được; hãy tìm, sẽ gặp; hãy gõ cửa, sẽ mở cho.","bai_hoc":"Hãy xin, sẽ được; hãy tìm, sẽ gặp; hãy gõ cửa, sẽ mở cho. Chúa mời ta cầu nguyện bằng sự kiên trì: xin, tìm, gõ, ba động từ tăng dần mức độ. Ngài là Cha tốt lành, không chê trách những lời cầu xin của con cái. Điều đó không có nghĩa là Ngài luôn ban đúng điều ta xin theo ý ta, mà ban điều tốt nhất theo sự khôn ngoan của Ngài. Nhưng Ngài luôn đáp lời. Hôm nay, hãy chọn một điều và cầu xin Chúa bằng sự kiên trì, không bỏ cuộc, và tin rằng Ngài nghe.","loi_cau_nguyen":"Cha ơi, con xin, con tìm, con gõ cửa. Xin giúp con kiên trì cầu nguyện, tin rằng Cha nghe và đáp lời theo sự khôn ngoan và tình yêu của Cha. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":7,"cau":12,"loi_kinh_thanh":"Ấy vậy, hễ điều chi mà các ngươi muốn người ta làm cho mình, thì cũng hãy làm điều đó cho họ, vì ấy là luật pháp và lời tiên tri.","bai_hoc":"Mọi điều các ngươi muốn người ta làm cho mình, thì cũng hãy làm cho họ. Đó là luật pháp và các lời tiên tri. Chúa Giê-su tóm gọn cả Cựu Ước trong một câu đơn giản có thể áp dụng ngay hôm nay. Bạn muốn được lắng nghe, được tôn trọng, được tha thứ, được giúp đỡ khi cần? Hãy làm những điều ấy cho người khác trước. Không cần đợi họ làm trước với bạn. Hôm nay, hãy chọn một điều bạn mong người khác làm cho mình và làm điều đó cho một người thật cụ thể.","loi_cau_nguyen":"Chúa ơi, xin giúp con đối xử với người khác như con mong được đối xử. Xin cho con chủ động làm điều tốt trước, không chờ người khác làm trước, và thấy Ngài trong mỗi người con gặp. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":7,"cau":13,"loi_kinh_thanh":"Hãy vào cửa hẹp, vì cửa rộng và đường khoảng khoát dẫn đến sự hư mất, kẻ vào đó cũng nhiều.","bai_hoc":"Hãy vào cửa hẹp. Vì cửa rộng và đường khoảng khoát dẫn đến sự hư mất, kẻ vào đó đông; còn cửa hẹp và đường chật dẫn đến sự sống, kẻ tìm được thì ít. Chúa Giê-su nói thật rằng đi theo Ngài đòi hỏi quyết tâm, không phải đi theo đám đông. Điều đó không nhằm làm ta nản lòng, mà để ta biết mình đang chọn gì. Con đường hẹp dẫn đến sự sống, và Ngài đi cùng ta trên đó. Hôm nay, hãy chọn một việc nhỏ làm theo Chúa dù không ai làm vậy quanh bạn, và để Ngài củng cố quyết định ấy.","loi_cau_nguyen":"Chúa ơi, xin giúp con chọn con đường hẹp dẫn đến sự sống, ngay cả khi nhiều người đi hướng khác. Xin cho con quyết tâm đi theo Ngài, và tin rằng Ngài đi cùng con trên con đường ấy. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":7,"cau":24,"loi_kinh_thanh":"Vậy, kẻ nào nghe và làm theo lời ta phán đây, thì giống như một người khôn ngoan cất nhà mình trên hòn đá.","bai_hoc":"Kẻ nào nghe những lời Ta và làm theo thì giống như người khôn xây nhà trên đá. Mưa sa, nước chảy, gió lay, nhà không sập vì đã đặt nền trên đá. Chúa Giê-su không nói rằng cơn bão sẽ không đến, mà nói nhà vững khi đặt nền đúng. Nghe Lời Chúa là bước đầu, làm theo mới là cái nền. Có những điều bạn đã nghe nhiều lần, và hôm nay là lúc làm. Hãy chọn một lời dạy của Chúa Giê-su mà bạn biết nhưng chưa làm trọn, và quyết định thực hành nó trong tuần này.","loi_cau_nguyen":"Chúa ơi, xin giúp con không chỉ nghe Lời Ngài mà còn làm theo. Xin giúp con xây đời mình trên đá vững là Lời Ngài, để khi cơn bão đến con vẫn đứng vững. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":9,"cau":37,"loi_kinh_thanh":"Ngài bèn phán cùng môn đồ rằng: Mùa gặt thì thật trúng, song con gặt thì ít.","bai_hoc":"Chúa Giê-su nói mùa gặt thì trúng, song con gặt thì ít. Ngài thấy đoàn dân đông, nhiều người đang khốn khổ, như chiên không có người chăn, và lòng Ngài động thương. Rồi Ngài mời các môn đồ cầu xin Chủ mùa gặt sai thợ ra gặt. Có nhiều người quanh ta đang cần tình yêu và sự an ủi, và chúng ta có thể là những người thợ. Hôm nay, hãy cầu nguyện xin Chúa sai thợ, và sẵn lòng nói: nếu Ngài muốn, xin dùng con trong việc nhỏ hôm nay. Mùa gặt của Ngài luôn cần thêm bàn tay, và bàn tay của bạn có giá trị.","loi_cau_nguyen":"Chúa ơi, xin sai thêm thợ vào mùa gặt của Ngài. Xin cho con lòng thương xót như Ngài, mở mắt con thấy người cần giúp đỡ, và dùng con trong những việc nhỏ hôm nay. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":11,"cau":28,"loi_kinh_thanh":"Hỡi những kẻ mệt mỏi và gánh nặng, hãy đến cùng ta, ta sẽ cho các ngươi được yên nghỉ.","bai_hoc":"Hỡi những kẻ mệt mỏi và gánh nặng, hãy đến cùng Ta, Ta sẽ cho các ngươi được yên nghỉ. Lời mời này đến với người mệt, không phải người mạnh. Chúa Giê-su không bảo bạn phải đến khi đã ổn thỏa, mà mời bạn đến ngay với sự mệt mỏi của mình. Sự yên nghỉ ở đây không chỉ là ngủ ngon, mà là sự bình an của người biết mình được yêu và được nâng đỡ. Hôm nay, nếu bạn thấy mình mang quá nhiều, hãy dừng lại, thở sâu, và thưa: Con đến, Chúa ơi. Ngài đang chờ bạn với vòng tay mở.","loi_cau_nguyen":"Chúa Giê-su ơi, con mệt mỏi và mang nhiều gánh nặng. Con đến với Ngài, xin cho con được yên nghỉ. Xin nhận lấy những gì con đang mang, và ban cho con sự bình an của Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":11,"cau":29,"loi_kinh_thanh":"Ta có lòng nhu mì, khiêm nhường; nên hãy gánh lấy ách của ta, và học theo ta; thì linh hồn các ngươi sẽ được yên nghỉ.","bai_hoc":"Hãy mang lấy ách của Ta, và học theo Ta, vì Ta có lòng nhu mì khiêm nhường, thì linh hồn các ngươi sẽ được yên nghỉ. Ách là dụng cụ đặt trên vai hai con bò để cùng kéo, và Chúa mời ta chung ách với Ngài, nghĩa là Ngài kéo cùng ta, không để ta kéo một mình. Chúa Giê-su có lòng nhu mì và khiêm nhường, Ngài không quát tháo hay hối thúc. Học theo Ngài là học sự dịu dàng. Hôm nay, hãy hỏi mình: có việc nào tôi đang kéo một mình mà Ngài muốn kéo cùng? Hãy mời Ngài vào đó.","loi_cau_nguyen":"Chúa Giê-su ơi, xin cho con chung ách với Ngài, và học theo lòng nhu mì khiêm nhường của Ngài. Xin giúp con thôi cố kéo mọi thứ một mình, và tìm thấy sự yên nghỉ khi đi cùng Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":11,"cau":30,"loi_kinh_thanh":"Vì ách ta dễ chịu và gánh ta nhẹ nhàng.","bai_hoc":"Vì ách Ta dễ chịu, gánh Ta nhẹ nhàng. Sau lời mời ở các câu trước, Chúa Giê-su bảo đảm rằng đi với Ngài không phải gánh nặng thêm. Có người sợ đức tin là một bộ luật nặng nề, nhưng Chúa nói ách của Ngài dễ chịu. Điều đó không có nghĩa là không có khó khăn, mà là Ngài ở cùng và chia sẻ sức nặng. Khi ta cố làm theo sức riêng, mọi thứ trở nên nặng nề. Khi ta nương vào Ngài, nó nhẹ hơn. Hôm nay, hãy thử dâng một việc nặng nề cho Ngài và xem điều gì thay đổi trong lòng bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài nói ách Ngài dễ chịu và gánh Ngài nhẹ nhàng. Xin giúp con sống đức tin không như gánh nặng, nhưng như một mối quan hệ nhẹ nhàng với Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":14,"cau":27,"loi_kinh_thanh":"Nhưng Đức Chúa Jêsus liền phán rằng: Các ngươi hãy yên lòng; ấy là ta đây, đừng sợ!","bai_hoc":"Giữa đêm, các môn đồ thấy Chúa Giê-su đi trên mặt biển và sợ hãi, tưởng là ma. Ngài lập tức nói với họ: Hãy yên lòng, chính Ta đây, đừng sợ. Ngài không chờ cơn bão tan mới đến. Ngài đến ngay giữa sóng gió, và câu đầu tiên là lời trấn an. Điều đáng kinh ngạc nhất là nhìn thấy Ngài trong chính nơi ta không ngờ đến. Có thể có một cơn bão trong đời bạn. Hôm nay, hãy lắng nghe tiếng Chúa nói trong đó: Hãy yên lòng, Ta đây. Nhìn vào Ngài thay vì nhìn vào sóng.","loi_cau_nguyen":"Chúa Giê-su ơi, xin đến với con ngay giữa cơn bão và nói với con: Hãy yên lòng, Ta đây. Xin giúp con nhìn vào Ngài thay vì chỉ nhìn sóng gió, và cho con bình an. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":16,"cau":16,"loi_kinh_thanh":"Si-môn Phi-e-rơ thưa rằng: Chúa là Đấng Christ, con Đức Chúa Trời hằng sống.","bai_hoc":"Phi-e-rơ trả lời Chúa Giê-su: \\"Si-môn Phi-e-rơ thưa rằng: Chúa là Đấng Christ, con Đức Chúa Trời hằng sống\\" Đây là một trong những lời tuyên xưng quan trọng nhất trong Kinh Thánh. Câu hỏi Chúa Giê-su đặt ra vẫn dành cho mỗi chúng ta: Các ngươi nói Ta là ai? Đây không phải một câu hỏi lý thuyết, mà là câu hỏi sống động trong đời sống. Khi ta trả lời Ngài là Chúa và Đấng Cứu Thế của mình, mọi thứ trong đời ta được sắp xếp lại quanh điều đó. Hôm nay, hãy trả lời câu hỏi ấy bằng chính lời của bạn trong một lời cầu nguyện ngắn.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là Đấng Christ, Con của Đức Chúa Trời hằng sống. Xin giúp con tuyên xưng điều đó bằng cả lòng, và sống mỗi ngày như một người thuộc về Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":16,"cau":18,"loi_kinh_thanh":"Còn ta, ta bảo ngươi rằng: Ngươi là Phi-e-rơ, ta sẽ lập Hội thánh ta trên đá nầy, các cửa âm phủ chẳng thắng được hội đó.","bai_hoc":"Chúa Giê-su nói Ngài sẽ xây Hội Thánh Ngài trên đá này, và các cửa âm phủ sẽ không thắng được. Hội Thánh không phải của một người hay một tổ chức, mà thuộc về Chúa Giê-su, và Ngài là Đấng xây dựng. Điều này khích lệ ta khi thấy Hội Thánh có nhiều yếu đuối. Dù con người có thất bại, công việc của Chúa vẫn đứng vững. Và mỗi chúng ta là một phần của công trình ấy. Hôm nay, hãy cầu nguyện cho Hội Thánh nơi bạn thuộc về, và hỏi Chúa bạn có thể góp phần gì để xây dựng cộng đoàn ấy.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài xây dựng Hội Thánh của Ngài. Xin bảo vệ và làm vững mạnh cộng đoàn con thuộc về, và dùng con để góp phần nhỏ trong công việc của Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":16,"cau":24,"loi_kinh_thanh":"Đức Chúa Jêsus bèn phán cùng môn đồ rằng: Nếu ai muốn theo ta, thì phải liều mình, vác thập tự giá mình mà theo ta.","bai_hoc":"Chúa Giê-su nói nếu ai muốn theo Ta, hãy tự bỏ mình, vác thập tự giá mình mà theo Ta. Đây là lời kêu gọi thẳng thắn: theo Ngài nghĩa là đặt Ngài lên trên ý riêng của mình. Điều đó đòi hỏi sự đánh đổi, nhưng cũng là con đường dẫn đến đời sống thật sự. Thập tự giá không phải để ta mang một mình, vì Ngài đã mang trước. Hôm nay, hãy nghĩ đến một điều nhỏ bạn có thể buông xuống vì Chúa: một thói quen, một sự ích kỷ, một điều bạn muốn làm theo ý mình, và dâng nó cho Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, con muốn theo Ngài. Xin giúp con tự bỏ mình và vác thập tự giá hằng ngày, và cho con sức mạnh để đặt ý Ngài lên trên ý riêng con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":16,"cau":26,"loi_kinh_thanh":"Người nào nếu được cả thiên hạ mà mất linh hồn mình, thì có ích gì? Vậy thì người lấy chi mà đổi linh hồn mình lại?","bai_hoc":"Người nào được cả thế gian mà mất linh hồn mình thì có ích gì? Hay là có người nào lấy chi mà đổi linh hồn mình? Chúa Giê-su hỏi một câu khiến ta phải suy nghĩ về điều gì thật sự quan trọng. Chúng ta dễ chạy theo thành tựu, của cải, địa vị, và quên chăm sóc linh hồn mình. Linh hồn là điều bạn mang theo mãi mãi. Hôm nay, hãy dành vài phút chăm sóc linh hồn: cầu nguyện, đọc Lời Chúa, ngồi yên. Và hãy tự hỏi: điều gì đang chiếm quá nhiều chỗ so với điều thật sự quan trọng?","loi_cau_nguyen":"Chúa ơi, xin giúp con nhớ rằng linh hồn con quý hơn mọi điều trên đời. Xin giữ con khỏi chạy theo những điều phù du, và cho con biết chăm sóc đời sống thuộc linh của mình mỗi ngày. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":17,"cau":20,"loi_kinh_thanh":"Ngài đáp rằng: Ấy là tại các ngươi ít đức tin: vì ta nói thật cùng các ngươi, nếu các ngươi có đức tin bằng một hột cải, sẽ khiến núi nầy rằng: Hãy dời đây qua đó, thì nó liền dời qua, và không có sự gì mà các ngươi chẳng làm được.","bai_hoc":"Chúa Giê-su nói nếu các ngươi có đức tin bằng hạt cải, các ngươi sẽ nói cùng hòn núi này: \\"Ngài đáp rằng: Ấy là tại các ngươi ít đức tin: vì ta nói thật cùng các ngươi, nếu các ngươi có đức tin bằng một hột cải, sẽ khiến núi nầy rằng: Hãy dời đây qua đó, thì nó liền dời qua, và không có sự gì mà các ngươi chẳng làm được\\" Hạt cải là hạt rất nhỏ. Ngài không bảo bạn phải có đức tin thật lớn, mà chỉ cần đức tin thật. Điều quan trọng là đối tượng của đức tin: Đức Chúa Trời có quyền năng. Đức tin nhỏ đặt đúng chỗ vẫn làm được nhiều điều. Hôm nay, nếu đức tin bạn nhỏ, đừng nản lòng. Hãy trao cho Chúa phần đức tin ít ỏi ấy và để Ngài làm điều lớn.","loi_cau_nguyen":"Chúa ơi, đức tin của con còn nhỏ như hạt cải, nhưng con trao cho Ngài. Xin làm nó lớn lên, và giúp con tin rằng không điều gì quá khó với Ngài, dù con thấy mình yếu đuối. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":18,"cau":20,"loi_kinh_thanh":"Vì nơi nào có hai ba người nhân danh ta nhóm nhau lại, thì ta ở giữa họ.","bai_hoc":"Chúa Giê-su hứa rằng ở đâu có hai ba người nhân danh Ngài nhóm lại, Ngài ở giữa họ. Bạn không cần một nhóm đông hay một nơi đặc biệt. Hai người cùng cầu nguyện, cùng đọc Lời Chúa, cùng nói về Ngài là đủ để Ngài có mặt. Điều đó khích lệ những ai thuộc một nhóm nhỏ hoặc cảm thấy mình ít người. Hôm nay, hãy mời một người bạn hay thành viên gia đình cùng cầu nguyện ngắn, dù chỉ một phút, và tin rằng Chúa đang ở giữa hai bạn. Ngài không đòi hỏi lời cầu nguyện dài, chỉ cần tấm lòng hướng về Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài hứa ở giữa những người nhóm lại trong danh Ngài. Xin giúp con tìm kiếm sự thông công với anh chị em, và cầu nguyện cùng nhau với lòng tin cậy. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":18,"cau":22,"loi_kinh_thanh":"Ngài đáp rằng: Ta không nói cùng ngươi rằng: đến bảy lần đâu, nhưng đến bảy mươi lần bảy.","bai_hoc":"Phi-e-rơ hỏi tha cho anh em mấy lần là đủ, bảy lần chăng? Chúa Giê-su đáp: \\"Ngài đáp rằng: Ta không nói cùng ngươi rằng: đến bảy lần đâu, nhưng đến bảy mươi lần bảy\\" Ý của Ngài không phải là đếm đến 490, mà là sự tha thứ không có giới hạn. Điều này khó, nhất là khi một người liên tục làm ta tổn thương. Tha thứ không có nghĩa là cho phép bị làm hại, mà là không để sự cay đắng trói buộc lòng mình. Hôm nay, nếu có một người bạn cần tha thứ, hãy xin Chúa ban sức mạnh để tha thứ thêm một lần nữa, vì Ngài đã tha cho bạn rất nhiều.","loi_cau_nguyen":"Chúa ơi, con biết Ngài đã tha thứ cho con rất nhiều. Xin giúp con tha thứ cho người khác, ngay cả khi điều đó khó, và giải thoát lòng con khỏi sự cay đắng. Xin cho con sức mạnh để làm điều con không thể tự làm. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":19,"cau":6,"loi_kinh_thanh":"Thế thì, vợ chồng không phải là hai nữa, nhưng một thịt mà thôi. Vậy, loài người không nên phân rẽ những kẻ mà Đức Chúa Trời đã phối hiệp!","bai_hoc":"Chúa Giê-su nói điều Đức Chúa Trời đã phối hiệp, loài người không nên phân rẽ. Hôn nhân là một giao ước thiêng liêng, không chỉ là hợp đồng hay cảm xúc. Điều này nhắc ta trân trọng hôn nhân và làm việc để gìn giữ nó. Đồng thời, Chúa cũng đầy thương xót với những ai đã trải qua đổ vỡ. Hôm nay, nếu bạn đang trong hôn nhân, hãy nói một lời trân trọng với người bạn đời. Nếu bạn đang mang vết thương trong chuyện này, hãy nhớ rằng Chúa luôn ở đó với sự dịu dàng và chữa lành.","loi_cau_nguyen":"Chúa ơi, xin giúp con trân trọng và gìn giữ hôn nhân, và ban phước cho những gia đình đang đi qua khó khăn. Xin chữa lành những ai mang vết thương trong tình yêu, bằng lòng thương xót của Ngài. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":19,"cau":14,"loi_kinh_thanh":"Song Đức Chúa Jêsus phán rằng: Hãy để con trẻ đến cùng ta, đừng ngăn trở; vì nước thiên đàng thuộc về những kẻ giống như con trẻ ấy.","bai_hoc":"Chúa Giê-su nói hãy để con trẻ đến với Ta, đừng ngăn cấm chúng, vì nước thiên đàng thuộc về những người giống như vậy. Các môn đồ từng cố ngăn trẻ nhỏ, nhưng Ngài mở rộng vòng tay. Trẻ em đến với Chúa bằng sự tin cậy đơn sơ, không toan tính. Đó là cách Ngài mời tất cả chúng ta đến với Ngài. Hôm nay, hãy thử đến với Chúa với lòng đơn sơ như một đứa trẻ: không cần lời hoa mỹ, chỉ cần nói thật những gì trong lòng, và để Ngài ôm lấy bạn. Ngài không bao giờ ngại sự đơn sơ của người đến với Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài mở rộng vòng tay đón nhận trẻ nhỏ. Xin giúp con đến với Ngài bằng lòng đơn sơ và tin cậy, và giúp con biết đón nhận và yêu thương những đứa trẻ quanh con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":19,"cau":26,"loi_kinh_thanh":"Đức Chúa Jêsus ngó môn đồ mà phán rằng: Điều đó loài người không thể làm được, song Đức Chúa Trời làm mọi việc đều được.","bai_hoc":"Chúa Giê-su nhìn các môn đồ và nói: \\"Đức Chúa Jêsus ngó môn đồ mà phán rằng: Điều đó loài người không thể làm được, song Đức Chúa Trời làm mọi việc đều được\\" Câu này được nói khi các môn đồ ngạc nhiên về việc ai có thể được cứu. Nó đem lại hy vọng: ơn cứu và sự biến đổi không phụ thuộc vào sức người, mà vào quyền năng Chúa. Có những việc trong đời bạn mà bạn không làm nổi bằng sức riêng. Hôm nay, hãy trao cho Chúa một điều như vậy và nói: con không làm được, nhưng Ngài làm được. Hãy buông tay và tin rằng Ngài sẽ làm theo cách tốt nhất.","loi_cau_nguyen":"Chúa ơi, có những điều con không thể làm bằng sức riêng. Con trao chúng cho Ngài, vì với Ngài mọi việc đều có thể. Xin giúp con tin cậy và buông tay, để Ngài làm điều Ngài biết là tốt nhất. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":22,"cau":37,"loi_kinh_thanh":"Đức Chúa Jêsus đáp rằng: Ngươi hãy hết lòng, hết linh hồn, hết ý mà yêu mến Chúa, là Đức Chúa Trời ngươi.","bai_hoc":"Chúa Giê-su nói hãy hết lòng, hết linh hồn, hết ý mà yêu mến Chúa là Đức Chúa Trời ngươi. Đây là điều răn lớn nhất. Yêu Chúa không phải chỉ là cảm xúc, mà là toàn bộ con người: tâm hồn, lý trí, ý chí. Có những ngày lòng ta nguội lạnh, và Chúa không bắt ta tạo ra cảm xúc ấy, nhưng mời ta quay về với Ngài. Tình yêu thật được nuôi dưỡng qua thời gian ở bên Chúa. Hôm nay, hãy dành một khoảnh khắc nói với Chúa rằng bạn yêu Ngài, bằng lời của chính bạn, dù đơn giản.","loi_cau_nguyen":"Chúa ơi, con muốn yêu Ngài hết lòng, hết linh hồn và hết ý. Xin giúp tình yêu ấy lớn lên trong con, và nhen lại ngọn lửa yêu mến Ngài khi con thấy lòng nguội lạnh. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":22,"cau":39,"loi_kinh_thanh":"Còn điều răn thứ hai đây, cũng như vậy: Ngươi hãy yêu kẻ lân cận như mình.","bai_hoc":"Điều răn thứ hai cũng giống như vậy: Ngươi hãy yêu người lân cận như mình. Chúa Giê-su đặt hai điều răn bên cạnh nhau: yêu Chúa và yêu người. Tình yêu dành cho Chúa không thể tách khỏi cách ta đối xử với người xung quanh. Người lân cận là bất kỳ ai ta gặp: người trong nhà, đồng nghiệp, người xa lạ. Yêu họ như chính mình nghĩa là mong điều tốt cho họ, tôn trọng họ và sẵn lòng giúp họ. Hôm nay, hãy chọn một người và làm một điều cụ thể để thể hiện tình yêu: lắng nghe họ kỹ hơn bình thường.","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu người lân cận như yêu chính mình. Xin mở mắt con thấy người cần được yêu, và cho con làm điều cụ thể, dù nhỏ, để thể hiện tình yêu của Ngài qua con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":24,"cau":35,"loi_kinh_thanh":"Trời đất sẽ qua, nhưng lời ta nói chẳng bao giờ qua đi.","bai_hoc":"Chúa Giê-su nói trời đất sẽ qua đi, nhưng lời Ta không qua đi. Giữa một thế giới thay đổi nhanh và nhiều điều bất định, đây là lời bảo đảm mạnh mẽ. Những lời hứa và lời dạy của Chúa Giê-su không phụ thuộc vào thời đại hay hoàn cảnh. Điều Ngài đã nói là nền vững mãi. Khi bạn bối rối giữa nhiều tiếng nói, hãy quay lại với Lời Ngài. Hôm nay, hãy chọn một lời của Chúa Giê-su, một câu bạn yêu thích, và để nó là điểm neo cho tâm trí bạn khi mọi thứ xung quanh có vẻ bấp bênh.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài vì lời Ngài không bao giờ qua đi. Xin giúp con đặt nền đời mình trên Lời Ngài, và tìm thấy sự vững vàng ở đó khi mọi thứ quanh con thay đổi. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":25,"cau":21,"loi_kinh_thanh":"Chủ nói với người rằng: Hỡi đầy tớ ngay lành trung tín kia, được lắm; ngươi đã trung tín trong việc nhỏ, ta sẽ lập ngươi coi sóc nhiều; hãy đến hưởng sự vui mừng của chúa ngươi.","bai_hoc":"Chủ khen người đầy tớ: Hỡi đầy tớ ngay lành trung tín, ngươi đã trung tín trong việc nhỏ, ta sẽ lập ngươi coi sóc nhiều việc, hãy vào sự vui mừng của chủ ngươi. Chúa không đo bằng kích thước của việc ta làm, mà bằng lòng trung tín. Việc nhỏ như chăm sóc người nhà, làm tròn công việc, giữ lời hứa đều có giá trị trước mặt Ngài. Và phần thưởng không phải là gánh nặng, mà là sự vui mừng chung với Chúa. Hôm nay, hãy làm một việc nhỏ trung tín, dù không ai thấy, như dâng nó cho Chúa.","loi_cau_nguyen":"Chúa ơi, xin giúp con trung tín trong những việc nhỏ. Xin cho con làm mọi việc với lòng chân thành như làm cho Ngài, và mong ngày được nghe Ngài nói với con những lời nhân từ ấy. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":25,"cau":40,"loi_kinh_thanh":"Vua sẽ trả lời rằng: Quả thật, ta nói cùng các ngươi, hễ các ngươi đã làm việc đó cho một người trong những người rất hèn mọn nầy của anh em ta, ấy là đã làm cho chính mình ta vậy.","bai_hoc":"Chúa Giê-su nói: \\"Vua sẽ trả lời rằng: Quả thật, ta nói cùng các ngươi, hễ các ngươi đã làm việc đó cho một người trong những người rất hèn mọn nầy của anh em ta, ấy là đã làm cho chính mình ta vậy\\" Điều này làm đổi cách ta nhìn việc giúp đỡ người khác: mỗi hành động tử tế dành cho người nghèo, người bệnh, người cô đơn là hành động dành cho Chúa. Không có việc giúp nào là nhỏ bé. Hôm nay, hãy tìm một người có thể cần sự giúp đỡ của bạn: một cuộc thăm hỏi, một bữa ăn, một lời động viên, và làm điều ấy như làm cho chính Chúa Giê-su.","loi_cau_nguyen":"Chúa Giê-su ơi, xin mở mắt con thấy Ngài nơi những người nhỏ bé và cần giúp đỡ. Xin cho con lòng nhân từ để phục vụ họ như phục vụ chính Ngài, bằng những việc nhỏ hằng ngày. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":28,"cau":6,"loi_kinh_thanh":"Ngài không ở đây đâu; Ngài sống lại rồi, như lời Ngài đã phán. Hãy đến xem chỗ Ngài đã nằm;","bai_hoc":"Thiên sứ nói với những người phụ nữ ở mộ: \\"Ngài không ở đây đâu; Ngài sống lại rồi, như lời Ngài đã phán. Hãy đến xem chỗ Ngài đã nằm\\" Đây là tin vui lớn nhất của đức tin Cơ Đốc. Cái chết không có tiếng nói cuối cùng. Mộ trống nghĩa là lời hứa của Chúa Giê-su là thật, và hy vọng của chúng ta có nền vững. Hôm nay, bất kể bạn đang đối diện điều gì, hãy nhớ rằng Chúa Giê-su đã sống lại, và Ngài còn sống. Hãy để niềm vui ấy chạm vào lòng bạn, dù chỉ trong một khoảnh khắc. Ngài đã sống lại, và Ngài đang sống, ở cùng bạn hôm nay.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã sống lại. Xin giúp con sống với niềm hy vọng ấy mỗi ngày, và tin rằng cái chết không có tiếng nói cuối cùng, vì Ngài đã chiến thắng. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":28,"cau":18,"loi_kinh_thanh":"Đức Chúa Jêsus đến gần, phán cùng môn đồ như vầy: Hết cả quyền phép ở trên trời và dưới đất đã giao cho ta.","bai_hoc":"Chúa Giê-su phán: Hết cả quyền phép ở trên trời và dưới đất đã giao cho Ta. Trước khi sai các môn đồ đi, Ngài nhắc rằng quyền năng thuộc về Ngài. Điều đó có nghĩa là sứ mạng Ngài giao không dựa vào sức lực hay khả năng của ta, mà dựa vào quyền của Ngài. Khi bạn thấy mình không đủ khả năng để làm điều Ngài kêu gọi, hãy nhớ rằng Đấng sai bạn có mọi quyền. Hôm nay, hãy dâng một việc bạn thấy khó cho Chúa, và xin Ngài ban quyền phép để làm. Bạn không cần đủ khả năng, vì quyền phép đến từ Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài có mọi quyền phép trên trời dưới đất. Xin giúp con dựa vào quyền năng của Ngài khi con thấy mình không đủ khả năng, và làm điều Ngài kêu gọi con. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":28,"cau":19,"loi_kinh_thanh":"Vậy, hãy đi dạy dỗ muôn dân, hãy nhân danh Đức Cha, Đức Con, và Đức Thánh Linh mà làm phép báp tem cho họ,","bai_hoc":"Chúa Giê-su sai các môn đồ đi dạy dỗ muôn dân, làm phép báp-têm nhân danh Cha, Con và Thánh Linh. Sứ mạng này mở rộng cho tất cả dân tộc, và cũng cho mỗi người tin Ngài. Bạn không cần ra nước ngoài mới thực hiện sứ mạng. Nó có thể bắt đầu ở gia đình, nơi làm việc, vòng bạn bè: chia sẻ điều Chúa đã làm trong đời bạn bằng tấm lòng chân thành. Hôm nay, hãy nghĩ đến một người mà bạn có thể chia sẻ về tình yêu của Chúa, và cầu nguyện xin Ngài mở cơ hội.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con thực hiện sứ mạng của Ngài ngay nơi con đang sống. Xin cho con can đảm và sự khôn ngoan để chia sẻ tình yêu của Ngài với những người xung quanh. A-men."},{"sach":"Ma-thi-ơ","ma":"MAT","chuong":28,"cau":20,"loi_kinh_thanh":"và dạy họ giữ hết cả mọi điều mà ta đã truyền cho các ngươi. Và nầy, ta thường ở cùng các ngươi luôn cho đến tận thế.","bai_hoc":"Câu cuối cùng của sách Ma-thi-ơ là lời hứa: \\"và dạy họ giữ hết cả mọi điều mà ta đã truyền cho các ngươi. Và nầy, ta thường ở cùng các ngươi luôn cho đến tận thế\\" Chúa Giê-su kết thúc bằng một lời hứa về sự hiện diện, không phải một mệnh lệnh. Ngài sai các môn đồ đi và nói rằng Ngài sẽ ở cùng họ, mọi ngày, trong mọi hoàn cảnh. Đó cũng là lời hứa dành cho bạn. Dù hôm nay bạn đang ở đâu, đang làm gì, Ngài ở đó. Hãy thử thì thầm lời hứa này khi bạn bắt đầu một việc: Chúa ở cùng tôi. Bạn sẽ thấy lòng mình vững hơn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài hứa ở cùng con mọi ngày. Xin cho con cảm nhận sự hiện diện của Ngài trong mỗi việc con làm, và không bao giờ quên rằng con không đi một mình. A-men."},{"sach":"Mác","ma":"MRK","chuong":1,"cau":15,"loi_kinh_thanh":"mà rằng: Kỳ đã trọn, nước Đức Chúa Trời đã đến gần; các ngươi hãy ăn năn và tin đạo Tin Lành.","bai_hoc":"Chúa Giê-su bắt đầu chức vụ bằng lời công bố: \\"mà rằng: Kỳ đã trọn, nước Đức Chúa Trời đã đến gần; các ngươi hãy ăn năn và tin đạo Tin Lành\\" Ăn năn không chỉ là buồn vì lỗi lầm, mà là quay lại, đổi hướng về phía Chúa. Tin Lành là tin vui: Chúa đã đến gần. Đây không phải lời kêu gọi nặng nề, mà là lời mời đón nhận điều tốt lành. Hôm nay, hãy hỏi mình: có hướng nào trong đời tôi đang đi xa Chúa mà tôi có thể quay lại? Hãy làm một bước nhỏ để quay về phía Ngài, và tin vào tin vui rằng Ngài đã đến gần.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã đem nước Đức Chúa Trời đến gần chúng con. Xin giúp con ăn năn, quay về với Ngài, và tin vào Tin Lành bằng cả lòng, mỗi ngày. A-men."},{"sach":"Mác","ma":"MRK","chuong":2,"cau":17,"loi_kinh_thanh":"Đức Chúa Jêsus nghe vậy, bèn phán cùng họ rằng: Chẳng phải kẻ mạnh khỏe cần thầy thuốc đâu, nhưng là kẻ có bịnh; ta chẳng phải đến gọi người công bình, nhưng gọi kẻ có tội.","bai_hoc":"Chúa Giê-su nói những người khỏe mạnh không cần thầy thuốc, chỉ người bệnh mới cần. Ta đến không phải để kêu gọi người công bình, nhưng kêu gọi kẻ có tội. Câu này nói với những người tự cho mình đã đủ tốt. Chúa Giê-su không đến để khen thưởng sự hoàn hảo, mà để chữa lành những ai nhận biết mình cần Ngài. Điều đó có nghĩa là bạn không cần phải sửa mình xong mới đến với Chúa. Chính khi bạn thấy mình có vấn đề, Ngài mời bạn đến. Hôm nay, hãy mang đến Ngài chỗ đau nhất và cho phép Ngài chữa.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đến để chữa lành những ai cần Ngài. Con nhận biết mình cần Ngài. Xin chữa lành những nơi trong con còn bệnh, và đón nhận con như con đang là. A-men."},{"sach":"Mác","ma":"MRK","chuong":4,"cau":39,"loi_kinh_thanh":"Ngài bèn thức dậy, quở gió và phán cùng biển rằng: Hãy êm đi, lặng đi! Gió liền dứt và đều yên lặng như tờ.","bai_hoc":"Trong cơn bão trên biển, các môn đồ hoảng sợ còn Chúa Giê-su đang ngủ. Khi họ đánh thức Ngài, Ngài quở gió và phán với biển: Hãy êm lặng, đừng ồn ào. Gió liền dứt và biển yên. Có những cơn bão trong lòng cũng cần tiếng nói của Ngài: lo âu, sợ hãi, rối bời. Ngài không bảo bạn phải tự làm yên chúng, mà mời bạn gọi Ngài. Hôm nay, nếu lòng bạn đang bão tố, hãy thưa với Chúa: xin nói với cơn bão trong con. Và tin rằng Ngài có thể làm yên điều không ai làm yên được.","loi_cau_nguyen":"Chúa Giê-su ơi, xin nói với cơn bão trong lòng con: Hãy êm lặng. Cảm ơn Ngài có quyền trên mọi sóng gió, và xin ban cho con sự bình an chỉ Ngài mới ban được. A-men."},{"sach":"Mác","ma":"MRK","chuong":8,"cau":36,"loi_kinh_thanh":"Người nào nếu được cả thiên hạ mà mất linh hồn mình, thì có ích gì?","bai_hoc":"Chúa Giê-su hỏi một câu để ta suy ngẫm: \\"Người nào nếu được cả thiên hạ mà mất linh hồn mình, thì có ích gì?\\" Ngài không nói tiền bạc hay thành công là xấu, mà nhắc ta đặt chúng đúng chỗ. Có thể có những lúc ta chạy theo những thứ cần thiết cho đời sống đến mức quên chăm sóc điều bên trong. Linh hồn là điều bạn mang theo mãi mãi. Hôm nay, hãy dành thời gian chăm sóc linh hồn: một đoạn Kinh Thánh, một lời cầu nguyện, một khoảnh khắc yên lặng. Rồi hỏi mình: điều gì quan trọng nhất đối với tôi?","loi_cau_nguyen":"Chúa ơi, xin giúp con không đánh mất linh hồn mình khi chạy theo những điều khác. Xin cho con biết chăm sóc đời sống thuộc linh của mình và đặt điều quan trọng nhất ở vị trí đầu tiên. A-men."},{"sach":"Mác","ma":"MRK","chuong":9,"cau":23,"loi_kinh_thanh":"Đức Chúa Jêsus đáp rằng: Sao ngươi nói: Nếu thầy làm được? Kẻ nào tin thì mọi việc đều được cả.","bai_hoc":"Chúa Giê-su nói với người cha có con bệnh: \\"Đức Chúa Jêsus đáp rằng: Sao ngươi nói: Nếu thầy làm được? Kẻ nào tin thì mọi việc đều được cả\\" Câu này có thể khiến ta cảm thấy bị đòi hỏi, nhưng hãy chú ý bối cảnh: người cha đang khẩn thiết tìm sự giúp đỡ cho con mình, và Chúa Giê-su đáp lại bằng lòng thương xót. Ngài mời ông tin, rồi chính Ngài giúp đỡ phần niềm tin còn thiếu. Khi bạn cầu xin Chúa điều gì đó, bạn không cần có niềm tin hoàn hảo. Hôm nay, hãy đến với Ngài và nói thật những gì bạn đang tin và những gì bạn còn nghi ngờ.","loi_cau_nguyen":"Chúa Giê-su ơi, con đến với Ngài với những gì con có. Xin giúp con tin, và củng cố đức tin con khi con còn nghi ngờ, vì Ngài làm được mọi việc cho người tin. A-men."},{"sach":"Mác","ma":"MRK","chuong":9,"cau":24,"loi_kinh_thanh":"Tức thì cha đứa trẻ la lên rằng: Tôi tin; xin Chúa giúp đỡ trong sự không tin của tôi!","bai_hoc":"Người cha kêu lên ngay lập tức: Tôi tin, xin Chúa giúp đức tin kém của tôi. Một lời cầu nguyện rất thật: ông nói cả hai điều cùng lúc, tin và cần sự giúp đỡ để tin. Chúa Giê-su không chê trách ông, mà chữa lành con trai ông. Điều này an ủi ta khi đức tin mình còn dao động. Bạn không cần giả vờ chắc chắn. Chúa nhận lời cầu nguyện chân thật. Hôm nay, hãy thử dùng chính lời này khi bạn thấy mình ở giữa niềm tin và nghi ngờ, và để Ngài giúp đỡ phần còn thiếu.","loi_cau_nguyen":"Chúa ơi, con tin, xin giúp đức tin kém của con. Cảm ơn Ngài không chê trách con khi con còn nghi ngờ, và xin củng cố niềm tin của con từng ngày bằng ân điển của Ngài. A-men."},{"sach":"Mác","ma":"MRK","chuong":10,"cau":45,"loi_kinh_thanh":"Vì Con người đã đến không phải để người ta hầu việc mình, song để hầu việc người ta, và phó sự sống mình làm giá chuộc cho nhiều người.","bai_hoc":"Con Người đến không phải để người ta hầu việc mình, nhưng để hầu việc người ta, và phó sự sống mình làm giá chuộc nhiều người. Chúa Giê-su nói điều này khi các môn đồ đang tranh luận ai lớn nhất. Ngài đảo ngược cách hiểu về sự vĩ đại: người lớn nhất là người phục vụ. Và chính Ngài làm gương: Ngài phục vụ đến mức hiến mạng. Hôm nay, hãy tìm một cách phục vụ nhỏ cho ai đó mà không mong được ghi nhận: rửa chén, lắng nghe, giúp một việc nhỏ. Đó là cách bước theo Chúa.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã hầu việc con và hiến mạng vì con. Xin giúp con sống phục vụ như Ngài, khiêm nhường, âm thầm, và yêu thương những người quanh con bằng việc làm. A-men."},{"sach":"Mác","ma":"MRK","chuong":11,"cau":24,"loi_kinh_thanh":"Bởi vậy ta nói cùng các ngươi: Mọi điều các ngươi xin trong lúc cầu nguyện, hãy tin đã được, tất điều đó sẽ ban cho các ngươi.","bai_hoc":"Chúa Giê-su dạy rằng mọi điều các ngươi cầu nguyện và xin, hãy tin rằng mình đã nhận được thì sẽ được như ý. Điều này mời gọi chúng ta cầu nguyện với lòng tin cậy, không chỉ nói cho có. Cần hiểu lời này trong toàn bộ Kinh Thánh: Chúa là Cha khôn ngoan, và lòng tin của ta đặt vào chính Ngài, không phải vào việc ép Ngài làm theo ý mình. Đức tin thật hòa hợp với ý muốn của Ngài. Hôm nay, hãy cầu nguyện một điều với lòng tin cậy vào tình yêu và sự khôn ngoan của Cha, và để kết quả trong tay Ngài.","loi_cau_nguyen":"Cha ơi, xin giúp con cầu nguyện với lòng tin cậy nơi Cha, không phải với sự ép buộc. Xin cho con xin điều hợp ý Cha, và tin rằng Cha nghe và đáp lời theo sự khôn ngoan của Ngài. A-men."},{"sach":"Mác","ma":"MRK","chuong":12,"cau":30,"loi_kinh_thanh":"Ngươi phải hết lòng, hết linh hồn, hết trí khôn, hết sức mà kính mến Chúa là Đức Chúa Trời ngươi.","bai_hoc":"Chúa Giê-su nói hãy hết lòng, hết linh hồn, hết ý, hết sức mà yêu mến Chúa là Đức Chúa Trời ngươi. Bốn phần của con người đều được kêu gọi: lòng, linh hồn, trí tuệ và sức lực. Yêu Chúa không phải chỉ trong nhà thờ, mà trong cách ta suy nghĩ, làm việc, và sống mỗi ngày. Có những ngày ta yêu Ngài rất nhiều, có ngày chỉ còn chút ít. Chúa hiểu, và Ngài vui khi ta chọn quay về với Ngài. Hôm nay, hãy dâng một việc thường ngày cho Chúa như một cách yêu mến Ngài bằng sức lực của mình.","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu mến Ngài bằng cả lòng, linh hồn, trí tuệ và sức lực. Xin cho những việc thường ngày của con trở thành cách con bày tỏ tình yêu với Ngài. A-men."},{"sach":"Mác","ma":"MRK","chuong":12,"cau":31,"loi_kinh_thanh":"Nầy là điều thứ hai: Ngươi phải yêu kẻ lân cận như mình. Chẳng có điều răn nào lớn hơn hai điều đó.","bai_hoc":"Điều răn thứ hai: Ngươi hãy yêu kẻ lân cận như mình. Chúa Giê-su nói không có điều răn nào lớn hơn hai điều này. Tình yêu thương người khác là cách ta sống đức tin trong thực tế. Người lân cận có thể là người ta không chọn và đôi khi khó thương. Yêu họ không có nghĩa phải thích mọi thứ về họ, mà là mong điều tốt cho họ và đối xử với họ bằng sự tôn trọng. Hôm nay, hãy nghĩ đến một người xung quanh bạn và làm điều gì đó cụ thể để thể hiện sự quan tâm: một lời hỏi thăm, một sự giúp đỡ nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu người lân cận như yêu chính mình. Xin cho con lòng quan tâm chân thành, và dạy con làm điều cụ thể để thể hiện tình yêu với những người quanh con. A-men."},{"sach":"Mác","ma":"MRK","chuong":16,"cau":15,"loi_kinh_thanh":"Ngài phán cùng các sứ đồ rằng: Hãy đi khắp thế gian, giảng Tin Lành cho mọi người.","bai_hoc":"Chúa Giê-su sai các môn đồ: Hãy đi khắp thế gian, giảng Tin Lành cho mọi người. Đây là sứ mạng không giới hạn nơi chốn hay đối tượng. Tin Lành là tin tốt lành: Chúa yêu thương, cứu rỗi và mời mọi người đến với Ngài. Bạn không cần là nhà truyền giáo chuyên nghiệp, chỉ cần là người đã nhận được tin vui và muốn chia sẻ. Hôm nay, hãy nghĩ đến người bạn có thể chia sẻ điều Chúa đã làm trong đời bạn, và cầu xin Chúa mở một cánh cửa cho cuộc trò chuyện tự nhiên với họ.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con chia sẻ Tin Lành với những người quanh con bằng lời nói và việc làm. Xin cho con can đảm, khôn ngoan và lòng yêu thương, và mở cho con những cơ hội tự nhiên. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":1,"cau":37,"loi_kinh_thanh":"Bởi vì không việc chi Đức Chúa Trời chẳng làm được.","bai_hoc":"Thiên sứ nói với Ma-ri rằng không có việc gì Đức Chúa Trời chẳng làm được. Ma-ri là một thiếu nữ bình thường, nhận được một tin khó tin nổi, và câu này là nền để cô đáp lại bằng sự tin cậy. Có những điều trong đời bạn mà lý trí nói là không thể. Hãy mang chúng đến với lòng khiêm nhường như Ma-ri. Chúa không bảo bạn phải hiểu hết, chỉ cần tin rằng với Ngài, không điều gì là bất khả. Hôm nay, hãy trao cho Ngài một điều bạn đang nghĩ là không thể và để lòng bạn nghỉ ngơi trong lời hứa này.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng mà không việc gì là không thể. Xin giúp con tin cậy Ngài như Ma-ri, và trao cho Ngài những điều con nghĩ là bất khả với lòng khiêm nhường và sẵn sàng. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":2,"cau":10,"loi_kinh_thanh":"Thiên sứ bèn phán rằng: Đừng sợ chi; vì nầy, ta báo cho các ngươi một Tin Lành, sẽ làm một sự vui mừng lớn cho muôn dân;","bai_hoc":"Thiên sứ nói với những người chăn chiên đang sợ hãi trong đêm: \\"Thiên sứ bèn phán rằng: Đừng sợ chi; vì nầy, ta báo cho các ngươi một Tin Lành, sẽ làm một sự vui mừng lớn cho muôn dân\\" Điều đáng chú ý là Tin Lành đến với những người chăn chiên, những người bình thường, làm việc đêm. Tin vui không dành riêng cho người quan trọng. Nó dành cho mọi người, kể cả bạn. Hôm nay, hãy để lòng bạn nghe lại lời này như lần đầu: có một tin vui lớn cho bạn, và nó bắt đầu bằng Đừng sợ.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã báo tin lành cho cả những người bình thường như con. Xin giúp con đón nhận niềm vui lớn ấy, và để lòng con bớt sợ hãi khi con nhớ rằng Ngài đến vì con. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":2,"cau":11,"loi_kinh_thanh":"ấy là hôm nay tại thành Đa-vít đã sanh cho các ngươi một Đấng Cứu thế, là Christ, là Chúa.","bai_hoc":"Thiên sứ báo tin: Hôm nay, tại thành Đa-vít đã sanh cho các ngươi một Cứu Chúa, là Christ, là Chúa. Chú ý hai chữ: cho các ngươi. Đấng Cứu Thế được sinh ra là dành cho những người nghe tin ấy, bao gồm cả bạn. Chúa Giê-su không đến cho một nhóm người đặc biệt, Ngài đến cho từng người. Dù bạn đã nghe câu chuyện Giáng Sinh bao nhiêu lần, hãy để điều ấy thấm vào lòng: Ngài sinh ra vì bạn. Hôm nay, hãy dành một chút thời gian cảm ơn Chúa Giê-su vì đã đến. Đó là món quà lớn nhất mà bạn từng nhận, và nó dành cho bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã đến thế gian làm Cứu Chúa của con. Xin giúp con luôn nhớ rằng Ngài sinh ra vì con, và sống với lòng biết ơn về món quà tuyệt vời ấy. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":2,"cau":14,"loi_kinh_thanh":"Sáng danh Chúa trên các từng trời rất cao, Bình an dưới đất, ân trạch cho loài người!","bai_hoc":"Đoàn thiên binh ngợi khen: Sự vinh hiển cho Đức Chúa Trời trong nơi rất cao, bình an dưới đất, ân trạch cho loài người. Lời ca này gắn vinh hiển của Chúa với bình an của con người. Khi ta tôn vinh Ngài, bình an bắt đầu lan tỏa. Bình an thật không chỉ là sự yên tĩnh bên ngoài, mà là sự hòa thuận giữa ta với Chúa và với nhau. Hôm nay, hãy tìm một cách đem bình an đến một người, và để lời ngợi khen này làm nhạc nền cho ngày của bạn. Một nụ cười, một lời hỏi han, một sự nhường nhịn đều có thể làm lan tỏa bình an của Ngài.","loi_cau_nguyen":"Chúa ơi, vinh hiển thuộc về Ngài ở nơi rất cao. Xin ban bình an trên đất và ân điển cho loài người. Xin giúp con trở thành người mang bình an của Ngài đến những nơi con đến. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":2,"cau":52,"loi_kinh_thanh":"Đức Chúa Jêsus khôn ngoan càng thêm, thân hình càng lớn, càng được đẹp lòng Đức Chúa Trời và người ta.","bai_hoc":"Chúa Giê-su khôn ngoan càng thêm, thân hình càng lớn, được ơn trước mặt Đức Chúa Trời và người ta. Câu này tóm lại tuổi thơ và thời niên thiếu của Ngài: tăng trưởng toàn diện về trí tuệ, thể chất, mối quan hệ với Chúa và với người. Đây là mẫu mực cho sự phát triển lành mạnh. Chúng ta cũng được mời lớn lên trong mọi khía cạnh, từng chút một. Hôm nay, hãy hỏi mình: phần nào của tôi cần được chăm sóc và lớn lên nhiều hơn: tâm trí, thân thể, đức tin hay các mối quan hệ? Hãy chọn một bước nhỏ cho điều ấy.","loi_cau_nguyen":"Chúa ơi, xin giúp con lớn lên một cách toàn diện, về trí tuệ, thể chất, đức tin và các mối quan hệ. Xin dạy con học theo gương Chúa Giê-su, kiên nhẫn và đều đặn mỗi ngày. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":4,"cau":18,"loi_kinh_thanh":"Thần của Chúa ngự trên ta: Vì Ngài đã xức dầu cho ta đặng truyền Tin Lành cho kẻ nghèo;","bai_hoc":"Chúa Giê-su đọc tại nhà hội: Thần của Chúa ngự trên ta, vì Ngài xức dầu cho ta để rao tin lành cho kẻ nghèo, chữa lành những kẻ có lòng đau thương, rao cho kẻ bị bắt được tự do. Đây là lời công bố sứ mạng của Ngài. Nó cho thấy trái tim Chúa Giê-su dành cho người nghèo, người đau và người bị trói buộc. Đó cũng là điều Ngài muốn làm trong và qua đời bạn. Hôm nay, hãy nghĩ xem phần nào bạn cần nhất và xin Ngài làm điều ấy, rồi nghĩ xem bạn có thể mang điều đó đến ai.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đến để rao tin lành, chữa lành lòng đau thương và giải phóng người bị trói buộc. Xin làm điều ấy trong con và dùng con để giúp người khác. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":6,"cau":31,"loi_kinh_thanh":"Các ngươi muốn người ta làm cho mình thể nào, hãy làm cho người ta thể ấy.","bai_hoc":"Chúa Giê-su dạy: Các ngươi muốn người ta làm cho mình thể nào, hãy làm cho người ta thể ấy. Đây là nguyên tắc rất đơn giản và rất khó làm. Nó đòi hỏi ta đặt mình vào vị trí người khác: nếu tôi là họ, tôi muốn được đối xử thế nào? Khi bạn dừng lại và hỏi câu ấy, nhiều quyết định của bạn sẽ thay đổi. Hôm nay, hãy chọn một tình huống cụ thể, một cuộc trò chuyện hay một việc phải làm với ai đó, và áp dụng nguyên tắc này, rồi để ý xem lòng bạn cảm thấy thế nào.","loi_cau_nguyen":"Chúa ơi, xin giúp con đối xử với người khác như con muốn được đối xử. Xin cho con đủ khiêm nhường để đặt mình vào vị trí của họ, và sống theo nguyên tắc yêu thương ấy mỗi ngày. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":6,"cau":38,"loi_kinh_thanh":"Hãy cho, người sẽ cho mình; họ sẽ lấy đấu lớn, nhận, lắc cho đầy tràn, mà nộp trong lòng các ngươi; vì các ngươi lường mực nào, thì họ cũng lường lại cho các ngươi mực ấy.","bai_hoc":"Hãy cho, thì sẽ được cho; sẽ lấy đấu tốt, đã dằn, lắc cho đầy tràn mà nhậm trong lòng các ngươi. Chúa Giê-su nói về sự rộng rãi: khi ta cho đi, Chúa cũng cho lại, theo cách Ngài biết. Điều này không phải là cách để làm giàu, mà là một nguyên tắc của nước Chúa: lòng rộng rãi thường mang lại sự phong phú, kể cả những điều không đo bằng tiền. Hôm nay, hãy cho đi điều gì đó, thời gian, một lời tử tế, sự giúp đỡ, mà không mong đợi được đáp lại, và tin rằng Chúa nhìn thấy.","loi_cau_nguyen":"Chúa ơi, xin cho con tấm lòng rộng rãi như Ngài. Xin giúp con cho đi với niềm vui và không tính toán, và tin rằng Ngài ban lại theo cách tốt nhất và đúng lúc. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":9,"cau":23,"loi_kinh_thanh":"Đoạn, Ngài phán cùng mọi người rằng: Nếu ai muốn theo ta, phải tự bỏ mình đi, mỗi ngày vác thập tự giá mình mà theo ta.","bai_hoc":"Chúa Giê-su nói với mọi người: \\"Đoạn, Ngài phán cùng mọi người rằng: Nếu ai muốn theo ta, phải tự bỏ mình đi, mỗi ngày vác thập tự giá mình mà theo ta\\" Chú ý chữ mỗi ngày: theo Chúa là quyết định lặp lại, không chỉ một lần. Tự bỏ mình là đặt ý Chúa lên trên ý riêng, dù đôi khi khó. Nhưng chúng ta không đi một mình, vì Ngài đã đi trước và cùng đi. Hôm nay, hãy xác định một điều nhỏ mà bạn sẵn lòng buông xuống vì Chúa, và thưa với Ngài: hôm nay con chọn theo Ngài trong việc này.","loi_cau_nguyen":"Chúa Giê-su ơi, hôm nay con chọn theo Ngài. Xin giúp con tự bỏ mình và đặt ý Ngài lên hàng đầu, mỗi ngày, trong những việc cụ thể, và cho con sức mạnh để đi theo Ngài. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":10,"cau":37,"loi_kinh_thanh":"Thầy dạy luật thưa rằng: Ấy là người đã lấy lòng thương xót đãi người. Đức Chúa Jêsus phán rằng: Hãy đi, làm theo như vậy.","bai_hoc":"Sau khi kể dụ ngôn người Sa-ma-ri nhân lành, Chúa Giê-su hỏi ai là người lân cận của người bị cướp. Người thông giáo đáp: \\"Thầy dạy luật thưa rằng: Ấy là người đã lấy lòng thương xót đãi người. Đức Chúa Jêsus phán rằng: Hãy đi, làm theo như vậy\\" Chúa Giê-su nói: Ngươi hãy đi, làm theo như vậy. Lòng thương xót thật được thể hiện bằng hành động cụ thể, tốn thời gian và công sức. Hôm nay, hãy để ý xung quanh bạn: có ai đang cần được giúp đỡ? Dù chỉ một lời hỏi han hay một món quà nhỏ, hãy làm điều ấy. Đó là cách bạn đáp lại câu Hãy đi, làm theo như vậy.","loi_cau_nguyen":"Chúa Giê-su ơi, xin cho con lòng thương xót như người Sa-ma-ri nhân lành. Xin mở mắt con thấy người cần giúp đỡ, và cho con sẵn sàng dừng lại và làm điều cụ thể cho họ. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":11,"cau":9,"loi_kinh_thanh":"Ta lại nói cùng các ngươi: Hãy xin, sẽ ban cho; hãy tìm, sẽ gặp; hãy gõ cửa, sẽ mở cho.","bai_hoc":"Chúa Giê-su nói: \\"Ta lại nói cùng các ngươi: Hãy xin, sẽ ban cho; hãy tìm, sẽ gặp; hãy gõ cửa, sẽ mở cho\\" Ngài dạy điều này sau khi kể về người bạn kiên trì gõ cửa lúc nửa đêm. Chúa mời ta cầu nguyện với sự bền bỉ, không phải vì Ngài miễn cưỡng, mà vì sự kiên trì làm ta lớn lên và hiểu điều mình thật sự cần. Hôm nay, hãy chọn một lời cầu xin mà bạn đã lặp lại nhiều lần, và đừng bỏ cuộc. Cứ tiếp tục gõ cửa, và tin rằng Cha nghe và sẽ đáp theo sự khôn ngoan của Ngài.","loi_cau_nguyen":"Cha ơi, con xin, con tìm, con gõ cửa. Xin giúp con kiên trì cầu nguyện và không nản lòng, và tin rằng Cha nghe con và sẽ đáp lời đúng lúc, theo cách tốt nhất cho con. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":12,"cau":34,"loi_kinh_thanh":"Vì của báu các ngươi ở đâu, thì lòng cũng ở đó.","bai_hoc":"Chúa Giê-su nói: \\"Vì của báu các ngươi ở đâu, thì lòng cũng ở đó\\" Điều chúng ta quý trọng nhất sẽ chi phối lòng ta. Nếu ta đặt tâm huyết vào những thứ nhất thời, lòng ta sẽ lo âu khi chúng lung lay. Nếu ta đặt vào điều đời đời, lòng ta vững vàng hơn. Hãy nhìn vào cách bạn dùng thời gian và tiền, đó là tấm gương phản chiếu điều bạn thật sự quý. Hôm nay, hãy chọn một điều nhỏ để đầu tư vào điều bền lâu: một mối quan hệ, một cuộc trò chuyện với Chúa, một việc làm nhân từ.","loi_cau_nguyen":"Chúa ơi, xin cho lòng con ở nơi kho báu thật sự là Ngài. Xin giúp con đầu tư thời gian và tiền bạc vào những điều đời đời, và nhìn lại những chỗ lòng con đang bám vào điều phù du. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":15,"cau":20,"loi_kinh_thanh":"Nó bèn đứng dậy mà về cùng cha mình. Khi còn ở đàng xa, cha nó thấy thì động lòng thương xót, chạy ra ôm lấy cổ mà hôn.","bai_hoc":"Trong dụ ngôn người con hoang đàng, khi người con quay về, người cha thấy từ xa, chạnh lòng thương, chạy lại ôm lấy cổ và hôn con. Người cha chạy ra đón con, không chờ con xin lỗi trước. Đó là hình ảnh của Cha trên trời dành cho chúng ta. Dù bạn đã đi xa thế nào, khi quay về, Ngài đã đứng đó nhìn ra con đường. Hôm nay, nếu bạn thấy mình xa Chúa, hãy làm bước đầu tiên quay lại, và tin rằng Ngài sẽ chạy ra đón bạn bằng vòng tay mở. Bạn không cần chuẩn bị lời xin lỗi hoàn hảo, chỉ cần quay về.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã chạy ra đón con trở về. Xin giúp con tin rằng khi con quay lại, Cha luôn mở rộng vòng tay, và cho con dũng khí để trở về khi con thấy mình đã đi xa. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":15,"cau":24,"loi_kinh_thanh":"vì con ta đây đã chết mà bây giờ lại sống, đã mất mà bây giờ lại thấy được. Đoạn, họ khởi sự vui mừng.","bai_hoc":"Người cha nói về đứa con trở về: \\"vì con ta đây đã chết mà bây giờ lại sống, đã mất mà bây giờ lại thấy được. Đoạn, họ khởi sự vui mừng\\" Từ ngữ sống lại và được tìm thấy nói về sự phục hồi trọn vẹn. Cả nhà cùng vui mừng và ăn tiệc. Đây là cách Chúa nhìn khi một người quay về: không phải sự trách móc, mà là niềm vui của người cha. Có thể bạn từng thấy mình là người mất đi, hãy nhớ rằng bạn đã được tìm thấy. Hôm nay, hãy vui vì mình là người con được đón về, và nếu có thể, hãy vui cùng người khác khi họ quay về với Chúa.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã tìm thấy con khi con lạc, và làm cho con sống lại. Xin giúp con sống trong niềm vui của người con được đón về, và biết vui mừng cùng khi người khác trở về với Cha. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":18,"cau":1,"loi_kinh_thanh":"Đức Chúa Jêsus phán cùng môn đồ một thí dụ, để tỏ ra rằng phải cầu nguyện luôn, chớ hề mỏi mệt:","bai_hoc":"Chúa Giê-su kể một dụ ngôn để dạy rằng phải cầu nguyện luôn luôn, chớ nản lòng. Một bà góa kiên trì đến xin quan tòa cho đến khi được đáp. Chúa không so sánh quan tòa với Ngài, mà để ta hiểu: nếu người xấu cũng đáp lại sự kiên trì, thì Cha tốt lành sẽ đáp lời hơn nhiều. Cầu nguyện bền bỉ giúp ta không bỏ cuộc giữa chừng. Hôm nay, hãy chọn một điều và cam kết cầu nguyện cho nó mỗi ngày trong tuần này, và đừng nản nếu chưa thấy kết quả ngay. Sự kiên trì là cách bạn nói với Chúa rằng bạn thật sự tin vào Ngài.","loi_cau_nguyen":"Chúa ơi, xin giúp con cầu nguyện luôn luôn và không nản lòng. Xin cho con kiên trì với những lời cầu xin của con, và tin rằng Ngài là Cha tốt lành, nghe và đáp lời đúng lúc. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":18,"cau":27,"loi_kinh_thanh":"Ngài đáp rằng: Sự chi người ta không làm được, thì Đức Chúa Trời làm được.","bai_hoc":"Chúa Giê-su nói điều không thể đối với người ta thì có thể đối với Đức Chúa Trời. Ngài nói điều này sau khi một người giàu buồn bã bỏ đi vì không dám buông của cải. Các môn đồ hỏi vậy thì ai được cứu? Chúa đáp bằng lời hứa này: ơn cứu và sự thay đổi lòng là công việc của Đức Chúa Trời, không phải của sức người. Hôm nay, nếu có điều gì bạn thấy mình không thể làm được, hãy nói với Chúa: con không làm được, xin Ngài làm. Rồi tin cậy Ngài sẽ hành động.","loi_cau_nguyen":"Chúa ơi, có những điều con không thể làm bằng sức người. Con trao chúng cho Ngài, vì điều không thể với con thì có thể với Ngài. Xin làm trong con điều con không thể tự làm. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":19,"cau":10,"loi_kinh_thanh":"Bởi Con người đã đến tìm và cứu kẻ bị mất.","bai_hoc":"Chúa Giê-su nói về mình: Con Người đã đến tìm và cứu kẻ bị mất. Ngài nói điều này sau khi vào nhà Xa-chê, người thu thuế bị mọi người khinh. Chúa không chờ Xa-chê dọn mình sạch sẽ, Ngài tự đến và mời mình vào nhà ông. Chúa chủ động tìm kiếm, kể cả những người bị xã hội nhìn xuống. Nếu bạn đã từng cảm thấy mình bị mất phương hướng hoặc bị bỏ lại, hãy nhớ rằng Ngài đang tìm bạn, không phải để trách, mà để cứu. Hôm nay, hãy để Ngài tìm thấy bạn bằng một lời cầu nguyện.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã đến tìm và cứu kẻ bị mất. Xin giúp con để Ngài tìm thấy con, và dùng con để tìm kiếm những người đang lạc lối bằng tình yêu của Ngài. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":23,"cau":34,"loi_kinh_thanh":"Song Đức Chúa Jêsus cầu rằng: Lạy Cha, xin tha cho họ, vì họ không biết mình làm điều gì. Đoạn, họ bắt thăm chia nhau áo xống của Ngài.","bai_hoc":"Trên thập tự giá, Chúa Giê-su cầu nguyện: \\"Song Đức Chúa Jêsus cầu rằng: Lạy Cha, xin tha cho họ, vì họ không biết mình làm điều gì. Đoạn, họ bắt thăm chia nhau áo xống của Ngài\\" Giữa nỗi đau tột cùng, Ngài cầu nguyện cho những người đóng đinh Ngài. Đó là sự tha thứ ở mức không tưởng được. Điều đó cho ta thấy lòng thương xót của Chúa lớn đến đâu và mời ta học theo Ngài. Có thể tha thứ khiến ta thấy rất khó, nhưng ta có thể bắt đầu bằng việc cầu nguyện như Ngài, dù chỉ một câu. Hôm nay, hãy nghĩ đến người đã làm tổn thương bạn và thầm thưa: Chúa ơi, xin tha cho họ.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã cầu nguyện tha thứ cho những người đóng đinh Ngài. Xin giúp con học theo Ngài, tha thứ cho người đã làm con tổn thương, và giải thoát lòng con khỏi sự cay đắng. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":23,"cau":43,"loi_kinh_thanh":"Đức Chúa Jêsus đáp rằng: Quả thật, ta nói cùng ngươi, hôm nay ngươi sẽ được ở với ta trong nơi Ba-ra-đi.","bai_hoc":"Trên thập tự giá, một người tội phạm bên cạnh Chúa Giê-su nói: Lạy Chúa Giê-su, khi Ngài đến trong nước Ngài, xin nhớ đến tôi. Chúa đáp: Hôm nay, ngươi sẽ được ở với Ta trong nơi Ba-ra-đi. Chỉ một lời cầu nguyện ngắn trong giờ phút cuối đời, và Chúa hứa chắc chắn. Điều đó cho ta thấy ơn cứu không dựa vào việc làm tốt, mà vào sự tin cậy Chúa Giê-su. Không bao giờ quá muộn để đến với Ngài. Hôm nay, hãy thưa với Chúa bằng chính lời của người ấy: Xin nhớ đến con.","loi_cau_nguyen":"Chúa Giê-su ơi, xin nhớ đến con. Cảm ơn Ngài hứa ơn cứu cho người tin, dù ở bất kỳ lúc nào. Xin giúp con tin cậy Ngài với lòng chân thành như người ấy. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":23,"cau":46,"loi_kinh_thanh":"Đức Chúa Jêsus bèn kêu lớn rằng: Hỡi Cha, tôi giao linh hồn lại trong tay Cha! Ngài vừa nói xong thì tắt hơi.","bai_hoc":"Chúa Giê-su kêu lớn tiếng: Lạy Cha, con giao linh hồn con trong tay Cha. Đây là lời cầu nguyện cuối cùng của Ngài trên thập tự giá, một lời của sự tin cậy trọn vẹn. Dù đang chịu đau khổ cực độ, Ngài vẫn phó thác cho Cha. Đó cũng là lời cầu nguyện mà mỗi người tin có thể nói, mỗi ngày và đến cuối đời: phó thác sự sống mình trong tay Cha tốt lành. Hôm nay, trước khi ngủ, hãy thử nói lời này, giao phó ngày qua và đêm tới trong tay Cha. Bạn có thể ngủ yên, vì Ngài thức canh giữ.","loi_cau_nguyen":"Cha ơi, con giao linh hồn con và cả đời con trong tay Cha. Xin giúp con tin cậy Cha trọn vẹn, như Chúa Giê-su đã làm, trong cả sự sống lẫn lúc đau khổ, và cho con bình an nơi Ngài. A-men."},{"sach":"Lu-ca","ma":"LUK","chuong":24,"cau":6,"loi_kinh_thanh":"Ngài không ở đây đâu, song Ngài đã sống lại. Hãy nhớ khi Ngài còn ở xứ Ga-li-lê, phán cùng các ngươi thể nào,","bai_hoc":"Thiên sứ nói với những người phụ nữ ở mộ: \\"Ngài không ở đây đâu, song Ngài đã sống lại. Hãy nhớ khi Ngài còn ở xứ Ga-li-lê, phán cùng các ngươi thể nào\\" Hãy nhớ lại lời Ngài đã nói. Những người phụ nữ đến mộ với hương liệu để chăm sóc thi thể, nhưng họ nhận được tin vui lớn nhất trong lịch sử. Điều đó nhắc ta rằng đôi khi ta đến với Chúa mong đợi điều nhỏ, mà Ngài cho điều lớn hơn nhiều. Hôm nay, hãy nhớ lại một lời Chúa Giê-su đã hứa trong Kinh Thánh, và để niềm vui của sự phục sinh làm lòng bạn nhẹ nhõm.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã sống lại như Ngài đã hứa. Xin giúp con sống trong niềm vui của sự phục sinh, và nhớ rằng Ngài luôn giữ lời hứa, vượt hơn điều con mong đợi. A-men."},{"sach":"Giăng","ma":"JHN","chuong":1,"cau":1,"loi_kinh_thanh":"Ban đầu có Ngôi Lời, Ngôi Lời ở cùng Đức Chúa Trời, và Ngôi Lời là Đức Chúa Trời.","bai_hoc":"Sách Giăng mở đầu bằng những chữ như một bài thơ: Ban đầu có Ngôi Lời, Ngôi Lời ở cùng Đức Chúa Trời, và Ngôi Lời là Đức Chúa Trời. Giăng nói về Chúa Giê-su trước khi Ngài sinh ra làm người: Ngài đã có từ đời đời. Hãy dừng lại và để điều ấy làm lòng bạn kinh ngạc: Đấng bạn đang đến với trong lời cầu nguyện không chỉ là một người thầy tốt, mà là Đức Chúa Trời. Ngài có từ ban đầu, và ở cùng Cha. Hôm nay, hãy thờ phượng Ngài đơn giản bằng việc suy ngẫm: Chúa Giê-su là Ngôi Lời đời đời, và Ngài biết bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là Ngôi Lời có từ ban đầu, ở cùng Đức Chúa Trời và là Đức Chúa Trời. Xin giúp con thờ phượng Ngài với lòng kính trọng, và biết rằng Đấng ấy cũng biết và yêu thương con. A-men."},{"sach":"Giăng","ma":"JHN","chuong":1,"cau":12,"loi_kinh_thanh":"Nhưng hễ ai đã nhận Ngài, thì Ngài ban cho quyền phép trở nên con cái Đức Chúa Trời, là ban cho những kẻ tin danh Ngài,","bai_hoc":"Giăng viết rằng những ai đã nhận Ngài, tức là tin danh Ngài, thì Ngài ban cho quyền phép trở nên con cái Đức Chúa Trời. Chú ý chữ quyền: đó là một địa vị được ban cho, không phải một thứ ta tự giành được. Trở thành con cái Chúa không phải do công trạng, mà do đón nhận và tin. Điều này thay đổi cách ta nhìn chính mình: ta không phải đứa trẻ mồ côi hay người xa lạ, ta là con trong nhà Cha. Hôm nay, hãy sống như một người được yêu: bước đi với sự an tâm của một đứa con trong gia đình.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã cho con quyền trở nên con cái Cha qua Chúa Giê-su. Xin giúp con sống trong sự an tâm của người con được yêu, và nhớ rằng địa vị ấy là món quà, không phải điều con phải giành được. A-men."},{"sach":"Giăng","ma":"JHN","chuong":1,"cau":14,"loi_kinh_thanh":"Ngôi Lời đã trở nên xác thịt, ở giữa chúng ta, đầy ơn và lẽ thật; chúng ta đã ngắm xem sự vinh hiển của Ngài, thật như vinh hiển của Con một đến từ nơi Cha.","bai_hoc":"Ngôi Lời đã trở nên xác thịt và ở giữa chúng ta, đầy ơn và đầy lẽ thật. Đức Chúa Trời không chỉ phán từ xa, Ngài đến sống trong thế giới của chúng ta với những giới hạn của con người. Ngài biết thế nào là mệt, là đói, là buồn. Điều đó có nghĩa là khi bạn cầu nguyện, bạn đang nói với Đấng thật sự hiểu cuộc sống con người. Ngài ở giữa chúng ta, gần đến mức bạn có thể thì thầm và Ngài nghe. Hôm nay, hãy nhớ rằng Chúa không xa cách, và hãy để điều ấy làm lòng bạn ấm lên.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã trở nên xác thịt và ở giữa chúng con. Xin giúp con nhớ rằng Ngài hiểu cuộc sống con người, và đến với Ngài với sự tin cậy vì Ngài gần gũi và đầy ơn. A-men."},{"sach":"Giăng","ma":"JHN","chuong":1,"cau":29,"loi_kinh_thanh":"Qua ngày sau, Giăng thấy Đức Chúa Jêsus đến cùng mình, thì nói rằng: Kìa, Chiên con của Đức Chúa Trời, là Đấng cất tội lỗi thế gian đi.","bai_hoc":"Giăng Báp-tít thấy Chúa Giê-su đến và nói: Kìa, Chiên Con của Đức Chúa Trời, là Đấng cất tội lỗi thế gian đi. Chiên Con là hình ảnh của của lễ chuộc tội. Giăng chỉ cho mọi người thấy rằng Chúa Giê-su là Đấng sẽ gánh lấy tội lỗi của thế gian. Đây là trọng tâm của Tin Lành: Chúa không chỉ đến để dạy, mà để cất tội lỗi đi. Hôm nay, nếu bạn đang mang theo điều gì khiến lòng nặng nề, hãy nhìn lên Ngài và nhớ rằng Ngài đến chính là để cất nó đi. Bạn không phải gánh nó thêm một ngày nào nữa.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài là Chiên Con của Đức Chúa Trời đã cất tội lỗi con đi. Xin giúp con tin rằng gánh nặng của con đã được Ngài gánh, và sống tự do trong ơn tha thứ. A-men."},{"sach":"Giăng","ma":"JHN","chuong":3,"cau":3,"loi_kinh_thanh":"Đức Chúa Jêsus cất tiếng đáp rằng: Quả thật, quả thật, ta nói cùng ngươi, nếu một người chẳng sanh lại, thì không thể thấy được nước Đức Chúa Trời.","bai_hoc":"Chúa Giê-su nói với Ni-cô-đem rằng nếu một người chẳng sanh lại thì không thể thấy được nước Đức Chúa Trời. Ni-cô-đem là người có học thức và địa vị, nhưng Chúa Giê-su nói điều ông cần không phải là học thêm hay làm thêm, mà là một sự sinh ra mới. Sự sinh lại là công việc của Thánh Linh, một sự thay đổi từ bên trong mà ta không thể tự tạo ra. Đó là một món quà, giống như sự ra đời không do ta chọn. Hôm nay, hãy cầu xin Chúa làm mới lòng bạn, và biết ơn vì Ngài sẵn lòng làm điều đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ban cho con sự sống mới qua Thánh Linh. Xin làm mới con từ bên trong, và giúp con sống như người được sinh lại, với tấm lòng mới và hy vọng mới. A-men."},{"sach":"Giăng","ma":"JHN","chuong":3,"cau":16,"loi_kinh_thanh":"Vì Đức Chúa Trời yêu thương thế gian, đến nỗi đã ban Con một của Ngài, hầu cho hễ ai tin Con ấy không bị hư mất mà được sự sống đời đời.","bai_hoc":"Đức Chúa Trời yêu thương thế gian, đến nỗi đã ban Con một của Ngài, hầu cho hễ ai tin Con ấy không bị hư mất mà được sự sống đời đời. Trước khi bạn làm được bất cứ điều gì đúng, trước khi bạn kịp xứng đáng, Đức Chúa Trời đã yêu bạn. Câu Kinh Thánh quen thuộc này kể về một tình yêu dám trao đi điều quý giá nhất: chính Con một của Ngài. Bạn không cần đạt điều gì để được yêu, cũng không phải làm cho mình tốt hơn trước khi đến với Ngài. Ngài chỉ mời bạn tin và nhận lấy món quà. Hôm nay, hãy nhớ rằng bạn quý giá đến mức Chúa đã trả một giá vô cùng đắt.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã yêu thương thế gian và ban Con một của Cha cho con. Xin giúp con tin và nhận lấy món quà ấy, và sống trong sự chắc chắn rằng con được yêu. A-men."},{"sach":"Giăng","ma":"JHN","chuong":3,"cau":17,"loi_kinh_thanh":"Vả, Đức Chúa Trời đã sai Con Ngài xuống thế gian, chẳng phải để đoán xét thế gian đâu, nhưng hầu cho thế gian nhờ Con ấy mà được cứu.","bai_hoc":"Đức Chúa Trời đã sai Con Ngài đến thế gian, chẳng phải để đoán xét thế gian đâu, nhưng hầu cho thế gian nhờ Con ấy mà được cứu. Có khi ta sợ Chúa như một vị quan tòa đang chờ bắt lỗi. Nhưng Chúa Giê-su đến không phải để lên án mà để cứu. Mục đích của Ngài là ơn cứu và phục hồi. Khi bạn đến với Ngài, bạn không cần phòng thủ hay chuẩn bị lời biện hộ, vì Ngài đến với lòng nhân từ. Hôm nay, hãy đến với Ngài mà không sợ bị khiển trách, và để lòng bạn được yên.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đến để cứu, không để lên án. Xin giúp con đến với Ngài không sợ hãi, và tin rằng Ngài đón nhận con bằng lòng thương xót và muốn con được sống. A-men."},{"sach":"Giăng","ma":"JHN","chuong":3,"cau":30,"loi_kinh_thanh":"Ngài phải dấy lên, ta phải hạ xuống.","bai_hoc":"Giăng Báp-tít nói về Chúa Giê-su: \\"Ngài phải dấy lên, ta phải hạ xuống\\" Khi các môn đồ ông lo lắng vì mọi người đang đến với Chúa Giê-su, ông bình tĩnh nhắc rằng đó là điều ông mong đợi. Giăng hiểu vai trò của mình là chỉ về Chúa, không phải thu hút về mình. Khiêm nhường thật là vui khi Chúa được tôn lên. Hôm nay, hãy nhìn lại động lực của bạn trong công việc, trong việc phục vụ: bạn đang muốn được nhìn thấy, hay muốn Chúa được tôn cao? Hãy xin Ngài giúp bạn có lòng như Giăng.","loi_cau_nguyen":"Chúa ơi, xin giúp con có lòng khiêm nhường như Giăng, để Ngài được tôn cao và con ở phía sau. Xin gỡ khỏi con sự ham muốn được khen và cho con vui khi Ngài được vinh hiển. A-men."},{"sach":"Giăng","ma":"JHN","chuong":4,"cau":24,"loi_kinh_thanh":"Đức Chúa Trời là Thần, nên ai thờ lạy Ngài thì phải lấy tâm thần và lẽ thật mà thờ lạy.","bai_hoc":"Đức Chúa Trời là Thần, nên ai thờ lạy Ngài phải lấy tâm thần và lẽ thật mà thờ lạy. Chúa Giê-su nói điều này với người phụ nữ Sa-ma-ri đang hỏi nên thờ phượng ở ngọn núi nào. Ngài đổi cách nhìn: thờ phượng thật không bị giới hạn bởi nơi chốn hay hình thức, mà là điều xảy ra trong lòng, thành thật và chân thật. Bạn có thể thờ phượng Chúa ở bất cứ đâu: trên xe, trong bếp, giữa công việc. Hôm nay, hãy thử dâng một lời thờ phượng ngay chỗ bạn đang ở, bằng tấm lòng chân thành.","loi_cau_nguyen":"Chúa ơi, xin giúp con thờ phượng Ngài bằng tâm thần và lẽ thật, ở bất cứ nơi nào con đang ở. Xin cho sự thờ phượng của con xuất phát từ tấm lòng chân thành, không chỉ hình thức bên ngoài. A-men."},{"sach":"Giăng","ma":"JHN","chuong":6,"cau":35,"loi_kinh_thanh":"Đức Chúa Jêsus phán rằng: Ta là bánh của sự sống; ai đến cùng ta chẳng hề đói, và ai tin ta chẳng hề khát.","bai_hoc":"Chúa Giê-su phán: \\"Đức Chúa Jêsus phán rằng: Ta là bánh của sự sống; ai đến cùng ta chẳng hề đói, và ai tin ta chẳng hề khát\\" Bánh là thức ăn cơ bản nhất, ăn mỗi ngày. Chúa nói Ngài là điều cơ bản ấy cho linh hồn. Chúng ta thường tìm thỏa lòng ở nhiều nơi rồi vẫn còn cảm giác thiếu thiếu. Chúa mời ta đến với Ngài là nguồn thỏa lòng thật. Đến với Ngài không phải một lần, mà là thói quen mỗi ngày như ăn. Hôm nay, hãy dành một khoảnh khắc đến với Chúa như đến bàn ăn: nhận lấy điều Ngài ban.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là bánh của sự sống. Xin làm no lòng con mỗi ngày, và giúp con đến với Ngài như đến với nguồn thỏa lòng thật, thay vì tìm ở những nơi không làm no được. A-men."},{"sach":"Giăng","ma":"JHN","chuong":8,"cau":12,"loi_kinh_thanh":"Đức Chúa Jêsus lại cất tiếng phán cùng chúng rằng: Ta là sự sáng của thế gian; người nào theo ta, chẳng đi trong nơi tối tăm, nhưng có ánh sáng của sự sống.","bai_hoc":"Chúa Giê-su nói: \\"Đức Chúa Jêsus lại cất tiếng phán cùng chúng rằng: Ta là sự sáng của thế gian; người nào theo ta, chẳng đi trong nơi tối tăm, nhưng có ánh sáng của sự sống\\" Ánh sáng không chỉ giúp ta thấy đường mà còn mang theo sự ấm áp và sự sống. Có những lúc ta thấy cuộc sống tối tăm: không rõ hướng đi, lòng nặng nề. Chúa mời ta theo Ngài, nghĩa là bước theo từng bước, và ánh sáng sẽ đi cùng ta. Hôm nay, khi bạn thấy mình bối rối, hãy dừng lại và hỏi: Chúa Giê-su ơi, bước tiếp theo của con là gì? Ngài sẽ soi sáng đủ cho bước ấy.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là sự sáng của thế gian. Xin giúp con bước theo Ngài, và không đi trong bóng tối, nhưng có ánh sáng sự sống. Xin soi sáng bước chân tiếp theo của con hôm nay. A-men."},{"sach":"Giăng","ma":"JHN","chuong":8,"cau":32,"loi_kinh_thanh":"các ngươi sẽ biết lẽ thật, và lẽ thật sẽ buông tha các ngươi.","bai_hoc":"Chúa Giê-su nói: Các ngươi sẽ biết lẽ thật, và lẽ thật sẽ buông tha các ngươi. Lẽ thật ở đây không chỉ là sự thật khách quan, mà chính là Chúa Giê-su và lời Ngài. Biết lẽ thật mang đến sự tự do: khỏi sự dối trá về bản thân, khỏi những lời xấu đã nghe, khỏi những nỗi sợ không có thật. Chúa không chỉ muốn ta biết thông tin, mà muốn ta được tự do. Hôm nay, hãy hỏi mình: có điều dối trá nào về bản thân hoặc về Chúa mà tôi đang tin? Hãy đối chiếu với Lời Ngài và để sự thật giải phóng bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, xin cho con biết lẽ thật và được lẽ thật giải phóng. Xin giúp con nhận ra những điều dối trá con đang tin, và đối chiếu với Lời Ngài để sống tự do trong sự thật của Ngài. A-men."},{"sach":"Giăng","ma":"JHN","chuong":10,"cau":10,"loi_kinh_thanh":"Kẻ trộm chỉ đến để cướp giết và hủy diệt; còn ta đã đến, hầu cho chiên được sự sống và được sự sống dư dật.","bai_hoc":"Chúa Giê-su nói: Ta đã đến, hầu cho chiên được sự sống, và được sự sống dư dật. Tên trộm chỉ đến để cướp, giết và phá hủy, còn Chúa đến để ban sự sống. Sự sống dư dật không có nghĩa là không có khó khăn, mà là một đời sống đầy ý nghĩa, bình an và niềm vui, ngay cả giữa khó khăn. Điều đó là món quà Ngài muốn cho bạn. Hôm nay, hãy nghĩ về một điều khiến lòng bạn cảm thấy sống động và đầy ý nghĩa, và cảm ơn Ngài vì món quà ấy. Rồi xin Ngài ban thêm sự sống trong những nơi còn khô cạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã đến để con được sống, và sống dư dật. Xin giúp con nhận lấy sự sống đầy đủ Ngài ban, và đem sự sống ấy đến những người quanh con. A-men."},{"sach":"Giăng","ma":"JHN","chuong":10,"cau":11,"loi_kinh_thanh":"Ta là người chăn hiền lành; người chăn hiền lành vì chiên mình phó sự sống mình.","bai_hoc":"Chúa Giê-su phán: \\"Ta là người chăn hiền lành; người chăn hiền lành vì chiên mình phó sự sống mình\\" Một người chăn thuê có thể bỏ chạy khi sói đến, nhưng người chăn thật bảo vệ chiên bằng cả mạng sống. Chúa Giê-su đã làm điều đó thật sự. Ngài không phải là người chăn xa cách, mà biết từng con chiên và hy sinh vì chúng. Hôm nay, nếu bạn cảm thấy không ai chăm sóc mình, hãy nhớ rằng bạn có một Người Chăn Hiền Lành, đã chọn trả giá cao nhất vì bạn và đang dõi theo bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài là Người Chăn hiền lành đã hy sinh sự sống vì con. Xin giúp con tin tưởng vào sự chăm sóc của Ngài, và đi theo tiếng Ngài mỗi ngày. A-men."},{"sach":"Giăng","ma":"JHN","chuong":10,"cau":27,"loi_kinh_thanh":"Chiên ta nghe tiếng ta, ta quen nó, và nó theo ta.","bai_hoc":"Chúa Giê-su nói: \\"Chiên ta nghe tiếng ta, ta quen nó, và nó theo ta\\" Ba điều đẹp đẽ: chiên nghe, Chúa biết, chiên theo. Mối quan hệ giữa người chăn và chiên được xây qua thời gian quen thuộc. Chiên nhận ra tiếng người chăn giữa nhiều tiếng khác. Cũng vậy, khi bạn dành nhiều thời gian với Chúa, bạn sẽ dần nhận ra tiếng Ngài giữa vô vàn tiếng ồn. Hôm nay, hãy dành vài phút yên lặng để lắng nghe, và tập nhận ra tiếng Chúa trong lòng, qua Lời Ngài và sự bình an. Đừng nản nếu lúc đầu chưa nhận ra ngay, vì sự quen thuộc cần thời gian, và Ngài rất kiên nhẫn.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con nghe và nhận ra tiếng Ngài giữa nhiều tiếng ồn. Cảm ơn Ngài biết con, và xin giúp con đi theo Ngài với lòng tin cậy. A-men."},{"sach":"Giăng","ma":"JHN","chuong":10,"cau":28,"loi_kinh_thanh":"Ta ban cho nó sự sống đời đời; nó chẳng chết mất bao giờ, và chẳng ai cướp nó khỏi tay ta.","bai_hoc":"Chúa Giê-su nói: Ta ban cho chúng sự sống đời đời, chúng sẽ chẳng hề bị hư mất, và không ai cướp chúng khỏi tay Ta. Hãy nghĩ về tay Ngài, một bàn tay vững chắc và đầy yêu thương, nắm lấy bạn. Không ai, không điều gì có thể giật bạn khỏi bàn tay ấy. Đây là sự an ủi lớn cho những lúc ta cảm thấy mình sắp rơi, sắp mất đức tin, sắp không giữ nổi. Không phải sức ta giữ Chúa, mà bàn tay Ngài giữ ta. Hôm nay, hãy nghỉ ngơi trong sự bảo đảm ấy.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài ban sự sống đời đời và giữ con trong tay Ngài. Xin giúp con yên lòng vì biết không ai và không điều gì có thể cướp con khỏi tay Ngài. A-men."},{"sach":"Giăng","ma":"JHN","chuong":11,"cau":25,"loi_kinh_thanh":"Đức Chúa Jêsus phán rằng: Ta là sự sống lại và sự sống; kẻ nào tin ta thì sẽ sống, mặc dầu đã chết rồi.","bai_hoc":"Chúa Giê-su nói với Ma-thê đang đau buồn vì anh mình qua đời: Ta là sự sống lại và sự sống; kẻ nào tin Ta thì sẽ sống, mặc dầu đã chết rồi. Ngài không chỉ hứa về sự sống lại, mà tuyên bố chính Ngài là sự sống lại. Điều này đặt hy vọng của chúng ta nơi một Con Người, không phải một ý niệm. Nếu bạn từng mất người thân, lời này nói rằng sự chia ly không phải điều cuối cùng cho những ai thuộc về Ngài. Hôm nay, hãy để Chúa Giê-su nói câu này với bạn, và lắng nghe trong lòng.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là sự sống lại và sự sống. Xin an ủi những ai đang mất người thân, và giữ lòng con vững vàng trong hy vọng về ngày chúng con được gặp lại trong Ngài. A-men."},{"sach":"Giăng","ma":"JHN","chuong":11,"cau":35,"loi_kinh_thanh":"Đức Chúa Jêsus khóc.","bai_hoc":"Câu ngắn nhất trong Kinh Thánh: Đức Chúa Jêsus khóc. Dù biết sắp làm cho La-xa-rơ sống lại, Ngài vẫn khóc trước nỗi đau của những người thân yêu. Điều đó cho thấy Chúa không xem nhẹ nỗi buồn của chúng ta. Ngài không bảo ta thôi khóc, mà khóc cùng ta. Nước mắt không phải dấu hiệu của đức tin yếu, nó là điều Chúa chia sẻ. Hôm nay, nếu bạn đang buồn, hãy nhớ rằng Chúa hiểu. Hãy cho phép mình khóc trước mặt Ngài, và để Ngài khóc cùng. Bạn không cần phải mạnh mẽ giả tạo hay giải thích với Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã khóc cùng người đau buồn. Xin giúp con biết rằng nước mắt của con không bị chê trách, và ôm lấy con trong nỗi buồn, như Ngài đã làm với những người thân của La-xa-rơ. A-men."},{"sach":"Giăng","ma":"JHN","chuong":13,"cau":34,"loi_kinh_thanh":"Ta ban cho các ngươi một điều răn mới, nghĩa là các ngươi phải yêu nhau; như ta đã yêu các ngươi thể nào, thì các ngươi cũng hãy yêu nhau thể ấy.","bai_hoc":"Chúa Giê-su phán: \\"Ta ban cho các ngươi một điều răn mới, nghĩa là các ngươi phải yêu nhau; như ta đã yêu các ngươi thể nào, thì các ngươi cũng hãy yêu nhau thể ấy\\" Điều mới ở đây là chuẩn mực: yêu như Ngài đã yêu, tức là hy sinh, phục vụ, tha thứ, kiên nhẫn. Đó là mức yêu thương rất cao, và ta không thể làm bằng sức riêng. Nhưng Ngài cho ta nguồn: tình yêu Ngài dành cho ta. Khi ta nhận được, ta có thể trao đi. Hôm nay, hãy chọn một người trong cộng đoàn hay gia đình và làm một việc yêu thương cụ thể cho họ.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con yêu thương người khác như Ngài đã yêu con. Xin đổ đầy lòng con bằng tình yêu của Ngài, để con có thể chia sẻ với những người quanh con, nhất là những người khó yêu. A-men."},{"sach":"Giăng","ma":"JHN","chuong":13,"cau":35,"loi_kinh_thanh":"Nếu các ngươi yêu nhau, thì ấy là tại điều đó mà thiên hạ sẽ nhận biết các ngươi là môn đồ ta.","bai_hoc":"Chúa Giê-su nói: \\"Nếu các ngươi yêu nhau, thì ấy là tại điều đó mà thiên hạ sẽ nhận biết các ngươi là môn đồ ta\\" Dấu hiệu nhận biết người theo Chúa không phải là sự hiểu biết thần học hay mức độ sốt sắng, mà là tình yêu thương dành cho nhau. Cộng đoàn đức tin thật sự là nơi người ta cảm nhận được sự yêu thương. Hôm nay, hãy tìm một cách để thể hiện tình yêu rõ ràng trong cộng đoàn của bạn: một lời khích lệ, một sự giúp đỡ, một cái ôm, để người khác nhận ra Chúa Giê-su qua bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con yêu thương anh chị em trong đức tin bằng việc làm cụ thể. Xin cho tình yêu giữa chúng con làm chứng cho Ngài, để người khác nhìn vào mà nhận biết chúng con là môn đồ của Ngài. A-men."},{"sach":"Giăng","ma":"JHN","chuong":14,"cau":1,"loi_kinh_thanh":"Lòng các ngươi chớ hề bối rối; hãy tin Đức Chúa Trời, cũng hãy tin ta nữa.","bai_hoc":"Chúa Giê-su nói với các môn đồ trước khi Ngài ra đi: \\"Lòng các ngươi chớ hề bối rối; hãy tin Đức Chúa Trời, cũng hãy tin ta nữa\\" Ngài nói điều này khi họ sắp trải qua những ngày khó khăn nhất. Ngài không phủ nhận nỗi lo lắng, mà chỉ cho họ nơi để đặt niềm tin. Có những lúc lòng bạn bối rối, và Ngài nhẹ nhàng nhắc điều tương tự. Hôm nay, khi lòng bạn rối loạn, hãy nhắc mình đặt niềm tin vào Ngài. Hít thở chậm và lặp lại lời này: Chúa ơi, con tin Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, khi lòng con bối rối, xin giúp con đặt niềm tin nơi Cha và nơi Ngài. Xin ban cho con sự bình an và vững vàng, để lòng con không bị xáo động. A-men."},{"sach":"Giăng","ma":"JHN","chuong":14,"cau":2,"loi_kinh_thanh":"Trong nhà Cha ta có nhiều chỗ ở; bằng chẳng vậy, ta đã nói cho các ngươi rồi. Ta đi sắm sẵn cho các ngươi một chỗ.","bai_hoc":"Chúa Giê-su nói: \\"Trong nhà Cha ta có nhiều chỗ ở; bằng chẳng vậy, ta đã nói cho các ngươi rồi. Ta đi sắm sẵn cho các ngươi một chỗ\\" Ngài nói điều này với những người đang lo lắng vì Ngài sắp rời họ. Nhà Cha là nơi có chỗ cho mỗi người. Ngài không chỉ ra đi, mà đi để chuẩn bị. Điều đó an ủi ta khi nghĩ về tương lai, về cái chết, về những điều chưa biết: có một nơi đã được chuẩn bị cho bạn bởi chính Chúa Giê-su. Hôm nay, hãy để lời này làm lòng bạn nhẹ nhàng, và biết ơn vì bạn có một nơi trong lòng Cha.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đi sắm sẵn một chỗ cho con trong nhà Cha. Xin giúp con sống với niềm hy vọng ấy, và tin cậy Ngài khi con nghĩ về tương lai và những điều con chưa biết. A-men."},{"sach":"Giăng","ma":"JHN","chuong":14,"cau":6,"loi_kinh_thanh":"Vậy Đức Chúa Jêsus đáp rằng: Ta là đường đi, lẽ thật, và sự sống; chẳng bởi ta thì không ai được đến cùng Cha.","bai_hoc":"Chúa Giê-su phán: Ta là đường đi, lẽ thật, và sự sống; chẳng bởi Ta thì không ai được đến cùng Cha. Ngài trả lời câu hỏi của Thô-ma về đường đi. Ngài không chỉ chỉ đường, mà chính Ngài là đường. Điều này vừa rõ ràng vừa đơn giản: đến với Cha là đến qua Ngài. Cũng vậy, Ngài là lẽ thật mà ta tìm, và sự sống mà ta cần. Khi bạn không biết phải đi hướng nào, hãy nhớ rằng bạn không cần bản đồ, bạn cần Người. Hôm nay, hãy hướng về Chúa Giê-su như con đường của bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là đường đi, lẽ thật và sự sống. Xin dẫn con đến Cha, và giúp con theo Ngài, không chỉ biết về Ngài, nhưng đi cùng Ngài mỗi ngày. A-men."},{"sach":"Giăng","ma":"JHN","chuong":14,"cau":15,"loi_kinh_thanh":"Nếu các ngươi yêu mến ta, thì giữ gìn các điều răn ta.","bai_hoc":"Chúa Giê-su nói: Nếu các ngươi yêu mến Ta, thì giữ gìn các điều răn Ta. Ngài đặt tình yêu trước sự vâng lời. Chúng ta vâng lời không để mua tình yêu của Ngài, mà vì ta yêu Ngài. Khi yêu một người, ta muốn làm điều họ vui. Vâng lời Chúa cũng vậy: là cách ta bày tỏ tình yêu, và Thánh Linh giúp ta làm được. Hôm nay, hãy hỏi mình: có điều nào Chúa Giê-su đã dạy mà tôi đang chưa làm vì tình yêu dành cho Ngài? Hãy chọn một điều và làm. Đừng chờ cảm xúc đến rồi mới làm, vì yêu mến cũng là một quyết định, và Ngài sẽ ban sức khi bạn bước đi.","loi_cau_nguyen":"Chúa Giê-su ơi, con muốn yêu mến Ngài và giữ lời Ngài. Xin giúp con vâng lời vì tình yêu, không vì bổn phận, và ban Thánh Linh để giúp con làm điều Ngài dạy. A-men."},{"sach":"Giăng","ma":"JHN","chuong":14,"cau":27,"loi_kinh_thanh":"Ta để sự bình an lại cho các ngươi; ta ban sự bình an ta cho các ngươi; ta cho các ngươi sự bình an chẳng phải như thế gian cho. Lòng các ngươi chớ bối rối và đừng sợ hãi.","bai_hoc":"Chúa Giê-su nói: \\"Ta để sự bình an lại cho các ngươi; ta ban sự bình an ta cho các ngươi; ta cho các ngươi sự bình an chẳng phải như thế gian cho. Lòng các ngươi chớ bối rối và đừng sợ hãi\\" Bình an của thế gian thường phụ thuộc hoàn cảnh: khi mọi việc suôn sẻ thì có, khi khó khăn thì mất. Bình an của Chúa là một món quà ở sâu hơn, vẫn còn đó giữa sóng gió. Ngài ban nó cho ta, không phải ta phải tự tạo ra. Hôm nay, hãy nhận lấy bình an ấy: dừng lại, hít một hơi thật sâu, và nhận lấy món quà Ngài đã để lại cho bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài để lại sự bình an cho con. Xin giúp con nhận lấy bình an ấy giữa những lúc bất an, và cho lòng con đừng bối rối, đừng sợ hãi. A-men."},{"sach":"Giăng","ma":"JHN","chuong":15,"cau":5,"loi_kinh_thanh":"Ta là gốc nho, các ngươi là nhánh. Ai cứ ở trong ta và ta trong họ thì sinh ra lắm trái; vì ngoài ta, các ngươi chẳng làm chi được.","bai_hoc":"Chúa Giê-su nói: \\"Ta là gốc nho, các ngươi là nhánh. Ai cứ ở trong ta và ta trong họ thì sinh ra lắm trái; vì ngoài ta, các ngươi chẳng làm chi được\\" Ai ở trong Ta, và Ta trong người, thì sinh ra nhiều quả, vì ngoài Ta, các ngươi chẳng làm chi được. Nhánh không tự cố gắng ra trái, nó chỉ cần ở lại gắn liền với thân cây. Có những lúc ta mệt vì cố làm nhiều mà quên ở lại với Chúa. Ở trong Ngài là thời gian đều đặn với Ngài, nghe Lời Ngài, cầu nguyện. Từ đó, trái tự nhiên được sinh ra. Hôm nay, hãy ưu tiên ở lại với Chúa trước khi làm nhiều việc.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là cây nho và con là nhánh. Xin giúp con ở lại trong Ngài, và để sự sống của Ngài chảy qua con và sinh ra trái tốt lành, thay vì cố gắng làm mọi thứ bằng sức riêng. A-men."},{"sach":"Giăng","ma":"JHN","chuong":15,"cau":12,"loi_kinh_thanh":"Điều răn của ta đây nầy: Các ngươi hãy yêu nhau, cũng như ta đã yêu các ngươi.","bai_hoc":"Chúa Giê-su nói: \\"Điều răn của ta đây nầy: Các ngươi hãy yêu nhau, cũng như ta đã yêu các ngươi\\" Ngài nhắc lại lệnh yêu thương, lặp lại vì điều này là cốt lõi. Mẫu mực không phải là cảm xúc của ta, mà là tình yêu Ngài đã bày tỏ trên thập tự giá. Điều đó khiến tình yêu trở nên cụ thể: hy sinh, tha thứ, kiên nhẫn. Hôm nay, hãy nghĩ đến một người mà bạn thấy khó yêu, và hỏi: Chúa Giê-su sẽ yêu họ thế nào? Rồi làm một việc nhỏ theo câu trả lời đó. Dù chỉ là một lời nói dịu dàng hay một sự kiên nhẫn thêm, Chúa vẫn thấy và vui lòng.","loi_cau_nguyen":"Chúa Giê-su ơi, xin dạy con yêu như Ngài đã yêu. Xin cho con biết yêu bằng hy sinh, kiên nhẫn và tha thứ, và giúp con làm một việc cụ thể bày tỏ tình yêu hôm nay. A-men."},{"sach":"Giăng","ma":"JHN","chuong":15,"cau":13,"loi_kinh_thanh":"Chẳng có sự yêu thương nào lớn hơn là vì bạn hữu mà phó sự sống mình.","bai_hoc":"Chúa Giê-su nói: \\"Chẳng có sự yêu thương nào lớn hơn là vì bạn hữu mà phó sự sống mình\\" Ngài nói điều này, rồi không lâu sau, thực hiện nó trên thập tự giá. Đó là bằng chứng lớn nhất của tình yêu. Ngài gọi ta là bạn hữu, không phải kẻ tôi tớ. Một người bạn như vậy xứng đáng được tin cậy. Hôm nay, hãy dành thời gian nhớ lại điều Ngài đã làm vì bạn, và để lòng biết ơn lớn lên. Hãy cảm ơn Ngài như cảm ơn một người bạn đã vì mình mà trả giá.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã hy sinh mạng sống vì bạn hữu, và gọi con là bạn. Xin giúp con yêu Ngài với lòng biết ơn, và sống như bạn của Ngài, trung tín và chân thành. A-men."},{"sach":"Giăng","ma":"JHN","chuong":16,"cau":33,"loi_kinh_thanh":"Ta đã bảo các ngươi những điều đó, hầu cho các ngươi có lòng bình yên trong ta. Các ngươi sẽ có sự hoạn nạn trong thế gian, nhưng hãy cứ vững lòng, ta đã thắng thế gian rồi!","bai_hoc":"Chúa Giê-su nói: \\"Ta đã bảo các ngươi những điều đó, hầu cho các ngươi có lòng bình yên trong ta. Các ngươi sẽ có sự hoạn nạn trong thế gian, nhưng hãy cứ vững lòng, ta đã thắng thế gian rồi!\\" Các ngươi sẽ có hoạn nạn trong thế gian, nhưng hãy cứ vững lòng, Ta đã thắng thế gian rồi. Chúa không hứa cuộc sống không có khó khăn. Ngài nói thật: sẽ có hoạn nạn. Nhưng bình an ở trong Ngài, và chiến thắng cuối cùng thuộc về Ngài. Điều đó cho ta can đảm. Hôm nay, hãy nhớ rằng dù khó khăn có thật, Ngài đã thắng, và bạn có thể giữ bình an trong Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài nói thật về hoạn nạn và hứa bình an trong Ngài. Xin giúp con vững lòng vì Ngài đã thắng thế gian, và giữ con trong bình an khi gặp khó khăn. A-men."},{"sach":"Giăng","ma":"JHN","chuong":17,"cau":3,"loi_kinh_thanh":"Vả, sự sống đời đời là nhìn biết Cha, tức là Đức Chúa Trời có một và thật, cùng Jêsus Christ, là Đấng Cha đã sai đến.","bai_hoc":"Chúa Giê-su cầu nguyện: \\"Vả, sự sống đời đời là nhìn biết Cha, tức là Đức Chúa Trời có một và thật, cùng Jêsus Christ, là Đấng Cha đã sai đến\\" Sự sống đời đời không chỉ là sống mãi, mà là biết Chúa, một mối quan hệ. Và mối quan hệ ấy bắt đầu ngay bây giờ, không chỉ sau khi chết. Mỗi ngày bạn dành thời gian với Ngài là một ngày sống sự sống đời đời. Hôm nay, hãy dành một khoảnh khắc để biết Chúa hơn: đọc một câu Kinh Thánh, suy ngẫm về một điều Ngài đã làm.","loi_cau_nguyen":"Chúa ơi, xin giúp con biết Ngài sâu hơn mỗi ngày. Cảm ơn Ngài vì sự sống đời đời là mối quan hệ với Cha và Chúa Giê-su, và xin giúp con sống trong mối quan hệ ấy ngay bây giờ. A-men."},{"sach":"Giăng","ma":"JHN","chuong":19,"cau":30,"loi_kinh_thanh":"Khi Đức Chúa Jêsus chịu lấy giấm ấy rồi, bèn phán rằng: Mọi việc đã được trọn; rồi Ngài gục đầu mà trút linh hồn.","bai_hoc":"Khi Chúa Giê-su nhận lấy giấm, Ngài phán: Mọi việc đã được trọn. Rồi Ngài gục đầu và trút linh hồn. Chữ trọn nghĩa là hoàn tất, công việc cứu chuộc đã xong. Không còn gì phải thêm vào, không còn nợ nào chưa trả. Điều đó nghĩa là bạn không cần cố gắng thêm để xứng đáng với ơn cứu. Chúa đã làm tất cả. Hôm nay, hãy nghỉ ngơi trong sự thật này: Ngài đã làm trọn. Nếu bạn thấy mình cố gắng quá nhiều để được Chúa chấp nhận, hãy buông xuống. Ơn cứu là một món quà đã được hoàn tất, và bạn chỉ cần nhận lấy bằng lòng biết ơn, rồi sống tự do trong đó mỗi ngày, không còn sợ hãi hay mặc cảm.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã làm trọn mọi việc trên thập tự giá. Xin giúp con thôi cố gắng để xứng đáng, và nghỉ ngơi trong ơn cứu đã hoàn tất mà Ngài ban cho con. A-men."},{"sach":"Giăng","ma":"JHN","chuong":20,"cau":29,"loi_kinh_thanh":"Đức Chúa Jêsus phán: Vì ngươi đã thấy ta, nên ngươi tin. Phước cho những kẻ chẳng từng thấy mà đã tin vậy!","bai_hoc":"Chúa Giê-su nói với Thô-ma: \\"Đức Chúa Jêsus phán: Vì ngươi đã thấy ta, nên ngươi tin. Phước cho những kẻ chẳng từng thấy mà đã tin vậy!\\" Thô-ma đã nghi ngờ cho đến khi tận mắt thấy, và Chúa kiên nhẫn đáp ứng. Nhưng Ngài cũng nhắc đến những người sau này sẽ tin mà chưa thấy, tức chúng ta. Đức tin của ta quý giá trước mặt Ngài. Có những lúc bạn khó tin vì không thấy, và Chúa hiểu điều đó. Hôm nay, hãy nói thật với Ngài những điều bạn khó tin, và xin Ngài giúp đức tin bạn lớn lên. Ngài đủ kiên nhẫn để đồng hành cùng bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài kiên nhẫn với những lúc con nghi ngờ. Xin giúp đức tin con lớn lên, để con tin Ngài dù chưa thấy, và nhận lấy phước Ngài hứa cho người tin. A-men."},{"sach":"Giăng","ma":"JHN","chuong":20,"cau":31,"loi_kinh_thanh":"Nhưng các việc nầy đã chép, để cho các ngươi tin rằng Đức Chúa Jêsus là Đấng Christ, tức là Con Đức Chúa Trời, và để khi các ngươi tin, thì nhờ danh Ngài mà được sự sống.","bai_hoc":"Giăng nói về mục đích của sách mình: \\"Nhưng các việc nầy đã chép, để cho các ngươi tin rằng Đức Chúa Jêsus là Đấng Christ, tức là Con Đức Chúa Trời, và để khi các ngươi tin, thì nhờ danh Ngài mà được sự sống\\" Cả cuốn sách là một lời mời đến đức tin. Giăng không viết để chứa tất cả mọi điều Chúa Giê-su làm, mà chọn những điều đủ để bạn tin. Nếu bạn đang đọc Kinh Thánh, hãy đọc với tâm thế ấy: để gặp Chúa Giê-su và tin. Hôm nay, hãy đọc một đoạn Phúc Âm và hỏi: điều này cho tôi biết gì về Chúa Giê-su?","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con tin Ngài là Đấng Christ, Con Đức Chúa Trời, và nhờ tin mà có sự sống trong danh Ngài. Xin mở mắt con khi đọc Lời Ngài để con nhận biết Ngài rõ hơn. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":1,"cau":8,"loi_kinh_thanh":"Nhưng khi Đức Thánh Linh giáng trên các ngươi, thì các ngươi sẽ nhận lấy quyền phép, và làm chứng về ta tại thành Giê-ru-sa-lem, cả xứ Giu-đê, xứ Sa-ma-ri, cho đến cùng trái đất.","bai_hoc":"Chúa Giê-su nói với các môn đồ trước khi Ngài lên trời: Khi Đức Thánh Linh giáng trên các ngươi, thì các ngươi sẽ nhận lấy quyền phép, và làm chứng về Ta. Họ còn đang lo lắng và chưa biết phải làm gì, nhưng Ngài hứa sẽ ban quyền phép. Làm chứng không phải là thuyết phục bằng sức riêng, mà là sống và nói về Chúa với sự giúp đỡ của Thánh Linh. Bạn không cần phải hoàn hảo, chỉ cần sẵn lòng. Hôm nay, hãy xin Thánh Linh ban cho bạn sức mạnh và lòng can đảm để làm chứng về Chúa Giê-su bằng chính cuộc sống của bạn.","loi_cau_nguyen":"Chúa ơi, xin ban Thánh Linh cho con quyền phép để làm chứng về Chúa Giê-su. Xin giúp con sống và nói về Ngài với can đảm, chân thành và tình yêu, ngay nơi con đang sống. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":2,"cau":38,"loi_kinh_thanh":"Phi-e-rơ trả lời rằng: Hãy hối cải, ai nấy phải nhân danh Đức Chúa Jêsus chịu phép báp-tem, để được tha tội mình, rồi sẽ được lãnh sự ban cho Đức Thánh Linh.","bai_hoc":"Phi-e-rơ trả lời đám đông đang xúc động sau khi nghe ông giảng: \\"Phi-e-rơ trả lời rằng: Hãy hối cải, ai nấy phải nhân danh Đức Chúa Jêsus chịu phép báp-tem, để được tha tội mình, rồi sẽ được lãnh sự ban cho Đức Thánh Linh\\" Lời đáp ngắn gọn nhưng đầy hy vọng: ăn năn, nhận phép báp-têm, được tha tội, nhận Thánh Linh. Sự tha thứ và Thánh Linh là món quà dành cho người đáp lại. Hôm nay, hãy nhớ lại điều Chúa đã làm cho bạn qua đức tin, và cảm ơn Ngài vì sự tha thứ và Thánh Linh Ngài ban.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ban sự tha thứ tội lỗi và ơn Đức Thánh Linh cho người ăn năn và tin Ngài. Xin giúp con sống trong ơn ấy mỗi ngày, và biết ơn về những điều Ngài đã làm cho con. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":4,"cau":12,"loi_kinh_thanh":"Chẳng có sự cứu rỗi trong đấng nào khác; vì ở dưới trời, chẳng có danh nào khác ban cho loài người, để chúng ta phải nhờ đó mà được cứu.","bai_hoc":"Phi-e-rơ nói về Chúa Giê-su: \\"Chẳng có sự cứu rỗi trong đấng nào khác; vì ở dưới trời, chẳng có danh nào khác ban cho loài người, để chúng ta phải nhờ đó mà được cứu\\" Lời này mạnh mẽ và rõ ràng, được nói trước những người có quyền thế. Nó có thể nghe khắt khe, nhưng đây cũng là một tin vui: có một con đường rõ ràng và đáng tin cậy để được cứu, và Ngài mở rộng cho mọi người. Ơn cứu không phải một điều mơ hồ, nó có một danh, đó là Chúa Giê-su. Hôm nay, hãy tạ ơn Ngài vì đã mở con đường ấy.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài là con đường cứu rỗi mà Cha đã ban cho chúng con. Xin giúp con tin cậy danh Ngài, và chia sẻ tin vui này với người khác bằng lòng yêu thương. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":16,"cau":31,"loi_kinh_thanh":"Hai người trả lời rằng: Hãy tin Đức Chúa Jêsus, thì ngươi và cả nhà đều sẽ được cứu rỗi.","bai_hoc":"Người cai ngục ở Phi-líp hỏi Phao-lô và Si-la: \\"Hai người trả lời rằng: Hãy tin Đức Chúa Jêsus, thì ngươi và cả nhà đều sẽ được cứu rỗi\\" Họ đáp: Hãy tin Đức Chúa Jêsus, thì ngươi và cả nhà ngươi đều sẽ được cứu. Một câu trả lời đơn giản và dịu dàng. Không có danh sách việc phải làm, chỉ có một lời mời: tin Chúa Giê-su. Và lời hứa ấy mở rộng cho cả gia đình, nghĩa là Chúa quan tâm đến những người ta yêu thương. Hôm nay, hãy cầu nguyện cho người thân của bạn, và tin rằng Chúa quan tâm đến họ, và đang làm việc trong đời họ.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài vì ơn cứu đến bởi đức tin nơi Ngài. Xin ban ơn cứu cho gia đình con, và giúp con cầu nguyện cho những người thân với lòng tin cậy và kiên nhẫn. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":17,"cau":28,"loi_kinh_thanh":"Vì tại trong Ngài, chúng ta được sống, động, và có, y như xưa một vài thi nhân của các ngươi có nói rằng: Chúng ta cũng là dòng dõi của Ngài.","bai_hoc":"Phao-lô nói với người Hy Lạp ở A-thên: Vì tại trong Ngài chúng ta được sống, động, và có. Ông dùng lời của các thi sĩ Hy Lạp để cho họ thấy Chúa không xa mỗi người trong chúng ta. Mỗi hơi thở, mỗi nhịp tim của ta đều ở trong Ngài. Đây là cách để thấy Chúa trong những điều bình thường nhất của cuộc sống. Ngài không chỉ ở nơi đền thờ hay lúc cầu nguyện, mà ở trong mọi khoảnh khắc. Hôm nay, hãy nhận ra sự hiện diện của Ngài trong một việc thường ngày: một bữa ăn, một con đường, một cuộc trò chuyện.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì chúng con sống, động và có trong Ngài. Xin giúp con nhận ra sự hiện diện của Ngài trong những khoảnh khắc thường ngày, và sống với lòng biết ơn trước Đấng gần gũi với con. A-men."},{"sach":"Công Vụ Các Sứ Đồ","ma":"ACT","chuong":20,"cau":35,"loi_kinh_thanh":"Tôi từng bày bảo luôn cho anh em rằng phải chịu khó làm việc như vậy, để giúp đỡ người yếu đuối, và nhớ lại lời chính Đức Chúa Jêsus có phán rằng: Ban cho thì có phước hơn là nhận lãnh.","bai_hoc":"Phao-lô nhắc các trưởng lão ở Ê-phê-sô nhớ lời Chúa Giê-su: Ban cho thì có phước hơn là nhận lãnh. Câu này không xuất hiện trong các sách Phúc Âm, nhưng Phao-lô biết nó từ truyền thống. Ông muốn họ làm việc để giúp đỡ người yếu đuối. Sự cho đi mang lại một niềm vui khác với sự nhận: nó nối kết ta với người khác và với Chúa. Hôm nay, hãy cho đi một điều nhỏ: thời gian, sự chú ý, một món quà, một lời khích lệ, và để ý xem điều gì xảy ra trong lòng bạn khi làm như vậy.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con hiểu niềm vui của việc cho đi. Xin cho con tấm lòng rộng rãi, biết nhìn thấy người cần giúp đỡ và sẵn sàng ban cho bằng niềm vui, theo gương Ngài. A-men."},{"sach":"La-mã","ma":"ROM","chuong":1,"cau":16,"loi_kinh_thanh":"Thật vậy, tôi không hổ thẹn về Tin Lành đâu, vì là quyền phép của Đức Chúa Trời để cứu mọi kẻ tin, trước là người Giu-đa, sau là người Gờ-réc;","bai_hoc":"Phao-lô viết rằng ông không hổ thẹn về Tin Lành, vì là quyền phép của Đức Chúa Trời để cứu mọi kẻ tin. Ông viết cho những người ở thành Rô-ma, trung tâm quyền lực của thế giới thời ấy, nơi Tin Lành có thể bị xem là yếu đuối. Nhưng ông nói nó có quyền phép. Có những lúc ta ngại chia sẻ đức tin vì sợ bị đánh giá. Hôm nay, hãy nhớ rằng Tin Lành không cần ta bảo vệ bằng sức riêng, nó có quyền phép tự thân. Hãy xin Chúa cho bạn can đảm sống và nói về Ngài, không hổ thẹn.","loi_cau_nguyen":"Chúa ơi, xin cho con không hổ thẹn về Tin Lành, vì đó là quyền phép của Ngài để cứu mọi người tin. Xin ban cho con can đảm và sự dịu dàng để chia sẻ đức tin của con khi có cơ hội. A-men."},{"sach":"La-mã","ma":"ROM","chuong":1,"cau":17,"loi_kinh_thanh":"vì trong Tin Lành nầy có bày tỏ sự công bình của Đức Chúa Trời, bởi đức tin mà được, lại dẫn đến đức tin nữa, như có chép rằng: Người công bình sẽ sống bởi đức tin.","bai_hoc":"Phao-lô viết rằng trong Tin Lành, sự công bình của Đức Chúa Trời được bày tỏ từ đức tin đến đức tin, như có chép rằng: Người công bình sẽ sống bởi đức tin. Ta được xưng công bình trước mặt Chúa không phải nhờ việc làm hay công lao, mà nhờ tin cậy Ngài. Và đời sống đức tin cũng tiếp tục bởi đức tin, từ ngày này qua ngày khác. Điều này giải thoát ta khỏi áp lực phải chứng minh mình và mời ta nương cậy Chúa. Hôm nay, hãy sống một ngày như người tin: trao một điều cho Chúa và bước đi mà không cần kiểm soát tất cả.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài xưng con là công bình bởi đức tin. Xin giúp con sống bởi đức tin mỗi ngày, và thôi cố chứng minh mình, nhưng nương cậy ơn Ngài và tin cậy Ngài trong mọi sự. A-men."},{"sach":"La-mã","ma":"ROM","chuong":3,"cau":23,"loi_kinh_thanh":"vì mọi người đều đã phạm tội, thiếu mất sự vinh hiển của Đức Chúa Trời,","bai_hoc":"Phao-lô viết: Vì mọi người đều đã phạm tội, thiếu mất sự vinh hiển của Đức Chúa Trời. Câu này thật thà: không ai ngoại lệ, tất cả đều cần ơn Chúa. Nghe có vẻ nặng nề, nhưng nó cũng đặt mọi người ngang hàng: không ai tốt hơn hay thấp hơn ai trước Chúa. Điều đó giải thoát ta khỏi việc so sánh và phán xét. Và nó đưa ta đến câu tiếp theo, về ơn cứu nhưng không. Hôm nay, hãy thành thật nhận ra mình cần ơn Chúa, và đừng giấu giếm điều ấy với Ngài, vì Ngài đã chuẩn bị sẵn lòng thương xót.","loi_cau_nguyen":"Chúa ơi, con nhận biết con cũng như mọi người, cần ơn của Ngài. Xin giúp con thành thật với Ngài, thôi so sánh mình với người khác, và nhận lấy ơn cứu miễn phí Ngài ban cho tất cả. A-men."},{"sach":"La-mã","ma":"ROM","chuong":3,"cau":24,"loi_kinh_thanh":"và họ nhờ ân điển Ngài mà được xưng công bình nhưng không, bởi sự chuộc tội đã làm trọn trong Đức Chúa Jêsus Christ,","bai_hoc":"Phao-lô tiếp tục: \\"và họ nhờ ân điển Ngài mà được xưng công bình nhưng không, bởi sự chuộc tội đã làm trọn trong Đức Chúa Jêsus Christ\\" Hai chữ nhưng không là điều quý giá nhất: ta không phải trả bất cứ giá nào, vì Chúa Giê-su đã trả. Sự xưng công bình nghĩa là Chúa nhìn ta như người vô tội, nhờ công lao của Chúa Giê-su. Điều này là món quà, không phải phần thưởng. Hôm nay, hãy dừng lại và nói lời cảm ơn thật lòng với Chúa về món quà ân điển ấy, và để lòng bạn nghỉ ngơi trong đó.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã trả giá để con được xưng công bình nhưng không. Xin giúp con nhận món quà ấy bằng lòng biết ơn, và sống trong tự do của ân điển, không còn sợ hãi hay mặc cảm. A-men."},{"sach":"La-mã","ma":"ROM","chuong":5,"cau":1,"loi_kinh_thanh":"Vậy chúng ta đã được xưng công bình bởi đức tin, thì được hòa thuận với Đức Chúa Trời, bởi Đức Chúa Jêsus Christ chúng ta,","bai_hoc":"Phao-lô viết rằng chúng ta đã được xưng công bình bởi đức tin, thì được bình an với Đức Chúa Trời, nhờ Đức Chúa Jêsus Christ. Bình an ở đây là mối quan hệ được hòa thuận. Trước đây tội lỗi tạo ra khoảng cách, nay Chúa Giê-su đã hàn gắn. Bạn không còn là kẻ xa lạ hay kẻ thù, mà đã được đưa vào mối quan hệ bình an. Điều này không phụ thuộc cảm giác hôm nay của bạn. Dù tâm trạng thế nào, trạng thái ấy là sự thật. Hôm nay, hãy nhớ rằng bạn đang bình an với Chúa, và để điều ấy vững chắc lòng bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã mang lại bình an giữa con và Đức Chúa Trời. Xin giúp con sống trong sự thật ấy, và để bình an với Ngài củng cố lòng con khi con thấy bất an. A-men."},{"sach":"La-mã","ma":"ROM","chuong":5,"cau":8,"loi_kinh_thanh":"Nhưng Đức Chúa Trời tỏ lòng yêu thương Ngài đối với chúng ta, khi chúng ta còn là người có tội, thì Đấng Christ vì chúng ta chịu chết.","bai_hoc":"Phao-lô viết: \\"Nhưng Đức Chúa Trời tỏ lòng yêu thương Ngài đối với chúng ta, khi chúng ta còn là người có tội, thì Đấng Christ vì chúng ta chịu chết\\" Chúa không chờ ta trở nên tốt rồi mới yêu. Ngài yêu ta khi ta còn xa cách. Đó là tình yêu không điều kiện. Khi bạn thấy mình không xứng đáng, hãy nhớ rằng tình yêu của Chúa không đo bằng sự xứng đáng của bạn mà bằng lòng thương của Ngài. Hôm nay, hãy để sự thật này thấm vào lòng: bạn được yêu, không phải vì bạn tốt, mà vì Ngài là Đấng yêu thương.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã yêu con khi con còn là người có tội, và Chúa Giê-su đã chết vì con. Xin giúp con nhận lấy tình yêu không điều kiện ấy, và để nó chữa lành những chỗ con thấy mình không xứng đáng. A-men."},{"sach":"La-mã","ma":"ROM","chuong":6,"cau":23,"loi_kinh_thanh":"Vì tiền công của tội lỗi là sự chết; nhưng sự ban cho của Đức Chúa Trời là sự sống đời đời trong Đức Chúa Jêsus Christ, Chúa chúng ta.","bai_hoc":"Phao-lô viết: Vì tiền công của tội lỗi là sự chết; nhưng sự ban cho của Đức Chúa Trời là sự sống đời đời trong Đức Chúa Jêsus Christ, Chúa chúng ta. Đây là sự tương phản rất rõ giữa công và ơn. Tội lỗi có giá, và giá ấy là sự chết. Nhưng ơn cứu là món quà, không phải lương. Ta không làm việc để nhận, ta chỉ nhận. Điều này nên làm lòng ta biết ơn hơn là sợ hãi. Hôm nay, hãy thầm nói: cảm ơn Chúa vì món quà sự sống đời đời, và để món quà ấy định hình cách bạn sống hôm nay, với lòng biết ơn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài vì sự ban cho của Đức Chúa Trời là sự sống đời đời. Xin giúp con nhận món quà ấy với lòng biết ơn, và sống mỗi ngày như người đã được ban cho điều quý giá nhất. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":1,"loi_kinh_thanh":"Cho nên hiện nay chẳng còn có sự đoán phạt nào cho những kẻ ở trong Đức Chúa Jêsus Christ;","bai_hoc":"Phao-lô viết: Như vậy, hiện nay chẳng còn có sự đoán phạt nào cho những kẻ ở trong Đức Chúa Jêsus Christ. Đây là một trong những câu an ủi nhất trong Kinh Thánh. Nếu bạn ở trong Chúa Giê-su, bạn không bị kết án. Không phải đang bị cân nhắc, mà đã không còn đoán phạt. Điều đó không có nghĩa ta không còn lỗi lầm, nhưng ta không còn bị định đoạt bởi chúng. Khi tiếng nói của mặc cảm vang lên, hãy dùng câu này đáp lại. Hôm nay, hãy sống như người được tha: nhẹ nhàng, tự do, và biết ơn Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài vì những người ở trong Ngài không còn bị đoán phạt. Xin giúp con thôi nghe tiếng của mặc cảm tội lỗi, và sống tự do trong ơn tha thứ trọn vẹn của Ngài. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":18,"loi_kinh_thanh":"Vả, tôi tưởng rằng những sự đau đớn bây giờ chẳng đáng so sánh với sự vinh hiển hầu đến, là sự sẽ được bày ra trong chúng ta.","bai_hoc":"Phao-lô viết: \\"Vả, tôi tưởng rằng những sự đau đớn bây giờ chẳng đáng so sánh với sự vinh hiển hầu đến, là sự sẽ được bày ra trong chúng ta\\" Phao-lô không xem nhẹ đau khổ, ông đã trải qua rất nhiều. Nhưng ông nhìn xa hơn: có một vinh hiển lớn lao đang chờ đợi. Điều này không làm nỗi đau biến mất, nhưng cho nó một chỗ trong câu chuyện lớn hơn. Hy vọng làm cho ta kiên nhẫn. Hôm nay, nếu bạn đang đau, hãy cho phép mình đau, và cũng để hy vọng vào vinh hiển Chúa chuẩn bị nâng đỡ bạn, từng chút một.","loi_cau_nguyen":"Chúa ơi, xin nâng đỡ con trong những nỗi đau bây giờ. Xin cho con hy vọng vào vinh hiển Ngài đã chuẩn bị, và giúp con kiên nhẫn đi qua mọi điều khó khăn với niềm tin nơi Ngài. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":28,"loi_kinh_thanh":"Vả, chúng ta biết rằng mọi sự hiệp lại làm ích cho kẻ yêu mến Đức Chúa Trời, tức là cho kẻ được gọi theo ý muốn Ngài đã định.","bai_hoc":"Phao-lô viết: Chúng ta biết rằng mọi sự hiệp lại làm ích cho kẻ yêu mến Đức Chúa Trời, tức là cho kẻ được gọi theo ý muốn Ngài đã định. Câu này không nói mọi sự đều tốt, mà nói Chúa làm cho mọi sự hiệp lại để có ích cho những ai yêu Ngài. Có những điều xảy ra thật đau đớn, và Chúa không bảo ta rằng chúng tốt. Nhưng Ngài có thể dùng chúng, trong thời gian của Ngài, cho điều tốt. Hôm nay, hãy trao cho Ngài một điều làm bạn đau, và tin rằng Ngài không bỏ phí nó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài làm cho mọi sự hiệp lại làm ích cho người yêu mến Ngài. Xin giúp con tin cậy Ngài khi mọi thứ có vẻ rối ren, và dùng mọi điều trong đời con theo ý muốn tốt lành của Ngài. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":31,"loi_kinh_thanh":"Đã vậy thì chúng ta sẽ nói làm sao? Nếu Đức Chúa Trời vùa giúp chúng ta, thì còn ai nghịch với chúng ta?","bai_hoc":"Phao-lô viết: \\"Đã vậy thì chúng ta sẽ nói làm sao? Nếu Đức Chúa Trời vùa giúp chúng ta, thì còn ai nghịch với chúng ta?\\" Sau khi kể về tình yêu và ơn cứu của Chúa, ông hỏi một câu hùng hồn. Không có nghĩa là không ai chống lại ta, mà là không ai thắng được ta khi Chúa ở về phía ta. Khi bạn cảm thấy bị chống đối, bị hiểu lầm hay bị bỏ rơi, hãy nhớ điều này. Hôm nay, hãy đứng vững với sự bảo đảm rằng Chúa đứng về phía bạn, và để lòng bạn bớt sợ hãi. Ngài không bao giờ rời khỏi vị trí bên cạnh bạn, và sự ủng hộ của Ngài vững vàng hơn mọi lời chống đối.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã đứng về phía con. Xin giúp con vững lòng trước những điều chống lại con, và nhớ rằng với Ngài ở cùng, không điều gì có thể thắng được con. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":37,"loi_kinh_thanh":"Trái lại, trong mọi sự đó, chúng ta nhờ Đấng yêu thương mình mà thắng hơn bội phần.","bai_hoc":"Phao-lô viết: Trái lại, trong mọi sự đó, chúng ta nhờ Đấng yêu thương mình mà thắng hơn bội phần. Sau khi kể về đau khổ, hoạn nạn, bắt bớ, ông nói ta chiến thắng, nhưng không phải bằng sức riêng. Nhờ Đấng yêu thương mình. Chiến thắng của ta đến từ tình yêu của Chúa. Điều này thay đổi cách ta nhìn thử thách: không phải cuộc chiến để ta thắng bằng ý chí, mà là hành trình trong tình yêu của Ngài. Hôm nay, hãy nhớ rằng bạn được yêu, và để điều ấy là sức mạnh của bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì nhờ Đấng yêu thương con mà con thắng hơn bội phần. Xin giúp con sống trong tình yêu ấy, và nhận sức mạnh từ Ngài khi con đối diện với thử thách. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":38,"loi_kinh_thanh":"Vì tôi chắc rằng bất kỳ sự chết, sự sống, các thiên sứ, các kẻ cầm quyền, việc bây giờ, việc hầu đến, quyền phép,","bai_hoc":"Phao-lô viết: \\"Vì tôi chắc rằng bất kỳ sự chết, sự sống, các thiên sứ, các kẻ cầm quyền, việc bây giờ, việc hầu đến, quyền phép\\" Ông liệt kê mọi thứ có thể làm ta sợ, và khẳng định không điều gì làm ta xa khỏi tình yêu Chúa. Hãy để danh sách ấy làm lòng bạn vững. Hôm nay, nếu có nỗi sợ nào về việc bị bỏ rơi hay mất tình yêu của Ngài, hãy nhắc nó bằng lời này. Hãy để danh sách ấy làm lòng bạn vững hơn mỗi khi nỗi sợ về việc bị bỏ rơi xuất hiện, vì tình yêu của Chúa dành cho bạn không hề phụ thuộc vào hoàn cảnh hay cảm xúc của bạn hôm nay.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì không điều gì có thể phân rẽ con khỏi tình yêu Ngài. Xin giúp con vững lòng trong sự bảo đảm ấy, và thôi sợ rằng con sẽ mất tình yêu của Ngài. A-men."},{"sach":"La-mã","ma":"ROM","chuong":8,"cau":39,"loi_kinh_thanh":"bề cao, hay là bề sâu, hoặc một vật nào, chẳng có thể phân rẽ chúng ta khỏi sự yêu thương mà Đức Chúa Trời đã chứng cho chúng ta trong Đức Chúa Jêsus Christ, là Chúa chúng ta.","bai_hoc":"Phao-lô kết thúc: \\"bề cao, hay là bề sâu, hoặc một vật nào, chẳng có thể phân rẽ chúng ta khỏi sự yêu thương mà Đức Chúa Trời đã chứng cho chúng ta trong Đức Chúa Jêsus Christ, là Chúa chúng ta\\" Từ trên cao đến dưới sâu, không nơi nào, không tạo vật nào có thể ngăn tình yêu ấy đến với bạn. Dù bạn ở đâu: đỉnh cao của thành công hay vực sâu của thất vọng, tình yêu Chúa vẫn ở đó. Hôm nay, hãy nghỉ ngơi trong sự thật này, và để nó là điểm tựa cho lòng bạn suốt ngày.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì tình yêu trong Chúa Giê-su không gì ngăn cách được. Xin giúp con nhớ rằng dù ở nơi cao hay sâu, con vẫn được Ngài yêu, và để điều đó nâng đỡ con mỗi ngày. A-men."},{"sach":"La-mã","ma":"ROM","chuong":10,"cau":9,"loi_kinh_thanh":"Vậy nếu miệng ngươi xưng Đức Chúa Jêsus ra và lòng ngươi tin rằng Đức Chúa Trời đã khiến Ngài từ kẻ chết sống lại, thì ngươi sẽ được cứu;","bai_hoc":"Phao-lô viết: Nếu miệng ngươi xưng Đức Chúa Jêsus ra, và lòng ngươi tin rằng Đức Chúa Trời đã khiến Ngài từ kẻ chết sống lại, thì ngươi sẽ được cứu. Hai điều đi cùng nhau: lời xưng ra bằng miệng và niềm tin trong lòng. Không phức tạp, không đòi hỏi kiến thức cao. Đó là lời tuyên xưng đơn giản: Chúa Giê-su là Chúa, và Ngài đã sống lại. Hôm nay, hãy nói lời ấy ra thành tiếng trong lời cầu nguyện, với lòng chân thành, dù bạn đã nói nhiều lần hay đang nói lần đầu. Chúa vui lòng nghe bạn mỗi lần.","loi_cau_nguyen":"Chúa Giê-su ơi, con xưng Ngài là Chúa, và con tin Cha đã khiến Ngài sống lại từ kẻ chết. Xin cho đức tin ấy là nền tảng của đời con, và giúp con sống bằng lời tuyên xưng ấy mỗi ngày. A-men."},{"sach":"La-mã","ma":"ROM","chuong":10,"cau":13,"loi_kinh_thanh":"Vì ai kêu cầu danh Chúa thì sẽ được cứu.","bai_hoc":"Phao-lô trích dẫn: Vì ai kêu cầu danh Chúa thì sẽ được cứu. Hai chữ ai nghĩa là bất kỳ ai, không giới hạn bởi quá khứ, địa vị hay lỗi lầm. Chỉ cần kêu cầu danh Chúa. Một lời kêu cầu chân thành, dù ngắn, dù run rẩy, đều được Chúa nghe. Điều này mở rộng cánh cửa cho mọi người, kể cả người cảm thấy mình đã quá xa. Hôm nay, nếu bạn cần được cứu khỏi điều gì: tội lỗi, nỗi sợ, tuyệt vọng, hãy kêu cầu danh Chúa. Ngài đang lắng nghe, và không bao giờ quay đi với một người kêu cầu Ngài bằng tấm lòng thật.","loi_cau_nguyen":"Chúa ơi, con kêu cầu danh Ngài. Xin cứu con khỏi những điều con không thể tự thoát, và cảm ơn Ngài hứa rằng mọi người kêu cầu danh Ngài đều được cứu. A-men."},{"sach":"La-mã","ma":"ROM","chuong":10,"cau":17,"loi_kinh_thanh":"Như vậy, đức tin đến bởi sự người ta nghe, mà người ta nghe, là khi lời của Đấng Christ được rao giảng.","bai_hoc":"Phao-lô viết: Vậy, đức tin đến bởi sự người ta nghe, mà người ta nghe là khi lời của Đấng Christ được rao giảng. Đức tin không phải điều ta tự tạo ra bằng cố gắng, nó lớn lên khi ta nghe Lời Chúa. Nếu bạn muốn đức tin mạnh hơn, hãy bắt đầu bằng việc nghe và đọc Lời Ngài đều đặn. Giống như hạt giống cần nước, đức tin cần Lời Chúa. Hôm nay, hãy dành thời gian nghe hoặc đọc một đoạn Kinh Thánh, và để Lời ấy nuôi dưỡng đức tin của bạn. Chỉ cần ít thôi, nhưng đều đặn, như tưới nước mỗi ngày cho một cây non.","loi_cau_nguyen":"Chúa ơi, xin giúp đức tin con lớn lên qua việc nghe và đọc Lời Ngài. Xin cho con thói quen đều đặn với Kinh Thánh, và mở lòng con để Lời Ngài làm việc trong con. A-men."},{"sach":"La-mã","ma":"ROM","chuong":12,"cau":1,"loi_kinh_thanh":"Vậy, hỡi anh em, tôi lấy sự thương xót của Đức Chúa Trời khuyên anh em dâng thân thể mình làm của lễ sống và thánh, đẹp lòng Đức Chúa Trời, ấy là sự thờ phượng phải lẽ của anh em.","bai_hoc":"Phao-lô viết: Vậy, hỡi anh em, tôi lấy sự thương xót của Đức Chúa Trời khuyên anh em dâng thân thể mình làm của lễ sống và thánh, đẹp lòng Đức Chúa Trời, ấy là sự thờ phượng phải lẽ của anh em. Chú ý chữ vậy: đây là phản ứng trước ơn cứu. Dâng thân thể mình, cả đời sống thường ngày, làm sự thờ phượng. Không chỉ là những giờ trong nhà thờ. Công việc, giấc ngủ, ăn uống, cách ta đối xử với người khác đều là cơ hội thờ phượng. Hôm nay, hãy dâng ngày của bạn cho Chúa như một của lễ sống, từ buổi sáng.","loi_cau_nguyen":"Chúa ơi, vì lòng thương xót của Ngài, con dâng cả đời sống và thân thể con làm của lễ sống. Xin giúp con thờ phượng Ngài trong những việc thường ngày, và sống để đẹp lòng Ngài mỗi giờ. A-men."},{"sach":"La-mã","ma":"ROM","chuong":12,"cau":2,"loi_kinh_thanh":"Đừng làm theo đời nầy, nhưng hãy biến hóa bởi sự đổi mới của tâm thần mình, để thử cho biết ý muốn tốt lành, đẹp lòng và trọn vẹn của Đức Chúa Trời là thể nào.","bai_hoc":"Phao-lô viết: Đừng làm theo đời nầy, nhưng hãy biến hóa bởi sự đổi mới của tâm thần mình, để thử cho biết ý muốn tốt lành, đẹp lòng và trọn vẹn của Đức Chúa Trời là thế nào. Thế gian có cách nghĩ riêng, và dễ dàng cuốn ta theo. Chúa mời ta được biến đổi từ bên trong qua việc làm mới tâm trí. Quá trình này diễn ra từ từ qua Lời Chúa và cầu nguyện. Khi tâm trí đổi mới, ta bắt đầu hiểu ý Chúa. Hôm nay, hãy để ý một suy nghĩ thế gian đang ảnh hưởng bạn, và thay thế bằng một lẽ thật trong Lời Chúa.","loi_cau_nguyen":"Chúa ơi, xin giúp con không rập khuôn theo thế gian, nhưng được biến đổi nhờ tâm trí được làm mới. Xin dạy con hiểu ý muốn tốt lành, đẹp lòng và trọn vẹn của Ngài, và sống theo đó. A-men."},{"sach":"La-mã","ma":"ROM","chuong":12,"cau":12,"loi_kinh_thanh":"Hãy vui mừng trong sự trông cậy, nhịn nhục trong sự hoạn nạn, bền lòng mà cầu nguyện.","bai_hoc":"Phao-lô viết: \\"Hãy vui mừng trong sự trông cậy, nhịn nhục trong sự hoạn nạn, bền lòng mà cầu nguyện\\" Ba lời khuyên ngắn gọn dành cho những người đang sống giữa áp lực. Vui mừng trong hy vọng: nhìn xa hơn hiện tại. Nhịn nhục trong hoạn nạn: kiên nhẫn qua thử thách. Bền đỗ cầu nguyện: giữ liên lạc với Chúa. Ba thói quen này giữ ta vững trong những mùa khó. Hôm nay, hãy chọn một trong ba điều và thực hành: nhớ một điều để hy vọng, kiên nhẫn trong một việc khó, hay dành thêm thời gian cầu nguyện.","loi_cau_nguyen":"Chúa ơi, xin giúp con vui mừng trong hy vọng, nhịn nhục trong hoạn nạn, và bền đỗ trong cầu nguyện. Xin cho con sức mạnh để giữ ba thói quen ấy khi con gặp khó khăn. A-men."},{"sach":"La-mã","ma":"ROM","chuong":12,"cau":21,"loi_kinh_thanh":"Đừng để điều ác thắng mình, nhưng hãy lấy điều thiện thắng điều ác.","bai_hoc":"Phao-lô viết: Đừng để điều ác thắng mình, nhưng hãy lấy điều thiện thắng điều ác. Khi bị đối xử bất công, phản ứng tự nhiên là đáp trả. Nhưng nếu đáp lại điều ác bằng điều ác, vòng xoáy tiếp tục. Chúa mời ta phá vỡ vòng xoáy ấy bằng điều thiện. Điều đó không có nghĩa là yếu đuối, mà là sức mạnh lớn hơn. Hôm nay, nếu có ai làm bạn tổn thương, hãy cân nhắc một cách đáp lại tử tế: một lời tốt, một lời cầu nguyện, hoặc đơn giản là không đáp trả bằng sự gay gắt.","loi_cau_nguyen":"Chúa ơi, xin giúp con không để điều ác thắng mình, nhưng lấy điều thiện thắng điều ác. Xin cho con sức mạnh để phá vỡ vòng xoáy báo thù, và đáp lại bằng sự tử tế và bình an. A-men."},{"sach":"La-mã","ma":"ROM","chuong":13,"cau":10,"loi_kinh_thanh":"Sự yêu thương chẳng hề làm hại kẻ lân cận; vậy yêu thương là sự làm trọn luật pháp.","bai_hoc":"Phao-lô viết: \\"Sự yêu thương chẳng hề làm hại kẻ lân cận; vậy yêu thương là sự làm trọn luật pháp\\" Nếu bạn muốn một tiêu chuẩn đơn giản cho hành động, hãy hỏi: điều này có làm hại ai không? Tình yêu thương bao hàm mọi điều răn: không gian dối, không trộm cắp, không làm điều ác cho người khác. Khi yêu thương thật sự, ta tự nhiên sống đúng. Hôm nay, hãy kiểm tra một quyết định của bạn bằng câu hỏi ấy, và chọn con đường không làm hại ai. Dù là một lời nói, một việc làm hay một im lặng, tình yêu luôn tìm cách xây dựng người bên cạnh.","loi_cau_nguyen":"Chúa ơi, xin giúp con yêu thương người lân cận bằng việc làm, không bao giờ làm hại họ. Xin cho con lấy tình yêu làm chuẩn mực cho mọi quyết định và hành động trong ngày hôm nay. A-men."},{"sach":"La-mã","ma":"ROM","chuong":15,"cau":13,"loi_kinh_thanh":"Vậy xin Đức Chúa Trời của sự trông cậy, làm cho anh em đầy dẫy mọi điều vui vẻ và mọi điều bình an trong đức tin, hầu cho anh em nhờ quyền phép Đức Thánh Linh được dư dật sự trông cậy!","bai_hoc":"Phao-lô cầu chúc: \\"Vậy xin Đức Chúa Trời của sự trông cậy, làm cho anh em đầy dẫy mọi điều vui vẻ và mọi điều bình an trong đức tin, hầu cho anh em nhờ quyền phép Đức Thánh Linh được dư dật sự trông cậy!\\" Chúa là nguồn của hy vọng, vui mừng và bình an. Ta không phải tạo ra chúng bằng sức riêng. Chúng đến từ Ngài, qua Thánh Linh. Đây là một lời chúc phước đẹp dành cho mỗi người. Hôm nay, hãy đọc lời này như lời chúc dành cho bạn, và hít thở chậm, để hy vọng, vui mừng, bình an của Ngài làm đầy lòng.","loi_cau_nguyen":"Chúa ơi, Ngài là Đức Chúa Trời của sự trông cậy. Xin làm đầy lòng con bằng niềm vui và bình an, và qua quyền phép Thánh Linh, cho con dư dật hy vọng để sống và để chia sẻ với người khác. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":2,"cau":9,"loi_kinh_thanh":"Song le, như có chép rằng: Ấy là sự mắt chưa thấy, tai chưa nghe, Và lòng người chưa nghĩ đến, Nhưng Đức Chúa Trời đã sắm sẵn điều ấy cho những người yêu mến Ngài.","bai_hoc":"Phao-lô viết, theo lời tiên tri: \\"Song le, như có chép rằng: Ấy là sự mắt chưa thấy, tai chưa nghe, Và lòng người chưa nghĩ đến, Nhưng Đức Chúa Trời đã sắm sẵn điều ấy cho những người yêu mến Ngài\\" Điều Chúa chuẩn bị lớn hơn những gì ta có thể tưởng tượng. Chúng ta thường mơ ước trong giới hạn của những gì ta biết, nhưng Ngài có kế hoạch vượt xa hơn. Điều đó cho ta hy vọng khi tương lai có vẻ mịt mờ. Phía trước còn những điều tốt đẹp bạn chưa thể hình dung. Hôm nay, hãy giữ lòng mở và biết ơn, tin rằng Chúa đang chuẩn bị điều tốt cho những ai yêu Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã chuẩn bị cho người yêu mến Ngài những điều vượt quá điều con có thể nghĩ đến. Xin giúp con giữ lòng hy vọng và tin cậy kế hoạch của Ngài, kể cả khi con chưa thấy rõ. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":10,"cau":13,"loi_kinh_thanh":"Những sự cám dỗ đến cho anh em, chẳng có sự nào quá sức loài người. Đức Chúa Trời là thành tín, Ngài chẳng hề cho anh em bị cám dỗ quá sức mình đâu; nhưng trong sự cám dỗ, Ngài cũng mở đàng cho ra khỏi, để anh em có thể chịu được.","bai_hoc":"Phao-lô viết: Anh em chưa bị cám dỗ nào ngoài sự cám dỗ vẫn có thường giữa loài người. Đức Chúa Trời là thành tín, Ngài không để anh em bị cám dỗ quá sức mình, nhưng trong sự cám dỗ, Ngài cũng sẽ mở đường cho ra khỏi. Lời này vừa thật thà vừa an ủi: cám dỗ là kinh nghiệm chung, không ai đơn độc, và Chúa luôn mở lối thoát. Khi bạn đang bị cám dỗ, đừng nghĩ mình đặc biệt yếu đuối. Hôm nay, hãy tìm lối thoát Chúa mở ra, dù nhỏ: rời khỏi một nơi, gọi một người bạn, hoặc cầu nguyện ngay lúc đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài thành tín, không để con bị cám dỗ quá sức. Xin giúp con nhận ra lối thoát Ngài mở ra, và có can đảm bước đi theo lối ấy khi con đối diện với cám dỗ. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":10,"cau":31,"loi_kinh_thanh":"Vậy, anh em hoặc ăn, hoặc uống, hay là làm sự chi khác, hãy vì sự vinh hiển Đức Chúa Trời mà làm.","bai_hoc":"Phao-lô viết: \\"Vậy, anh em hoặc ăn, hoặc uống, hay là làm sự chi khác, hãy vì sự vinh hiển Đức Chúa Trời mà làm\\" Đây là lời nói về sự tinh thần hóa cuộc sống thường ngày. Không có việc gì quá nhỏ để dâng cho Chúa: một bữa ăn, một công việc, một cuộc trò chuyện. Khi ta làm mọi thứ với ý thức rằng đó là cho Ngài, những việc bình thường trở nên ý nghĩa. Hôm nay, hãy chọn một việc thường ngày, như nấu ăn, dọn dẹp hay đi làm, và thầm dâng nó cho Chúa. Bạn sẽ thấy việc ấy mang một ý nghĩa khác.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm mọi việc, dù ăn hay uống hay bất cứ việc gì, vì sự vinh hiển của Ngài. Xin cho những việc thường ngày của con trở thành sự thờ phượng và dâng Ngài với lòng biết ơn. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":13,"cau":4,"loi_kinh_thanh":"Tình yêu thương hay nhịn nhục; tình yêu thương hay nhân từ; tình yêu thương chẳng ghen tị, chẳng khoe mình, chẳng lên mình kiêu ngạo,","bai_hoc":"Phao-lô mô tả tình yêu thương: Tình yêu thương hay nhịn nhục; tình yêu thương có lòng nhân từ; chẳng ghen tị, chẳng khoe mình, chẳng lên mình kiêu ngạo. Hãy đọc lại bằng cách thay chữ tình yêu thương bằng tên của bạn. Bạn có nhịn nhục, nhân từ không? Hoặc thay bằng tên Chúa Giê-su, để thấy Ngài yêu ta thế nào. Đây là mô tả của tình yêu thật, và là mục tiêu cho cuộc sống chúng ta. Hôm nay, hãy chọn một đức tính trong câu này như sự nhịn nhục, và thực hành nó với một người cụ thể.","loi_cau_nguyen":"Chúa ơi, xin dạy con yêu thương như Ngài mô tả: nhịn nhục, nhân từ, không ghen tị, không kiêu ngạo. Xin giúp con thực hành một điều ấy hôm nay, với người đang ở gần con. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":13,"cau":7,"loi_kinh_thanh":"Tình yêu thương hay dung thứ mọi sự, tin mọi sự, trông cậy mọi sự, nín chịu mọi sự.","bai_hoc":"Phao-lô viết: \\"Tình yêu thương hay dung thứ mọi sự, tin mọi sự, trông cậy mọi sự, nín chịu mọi sự\\" Bốn điều này tạo nên sức bền của tình yêu: bao dung, tin tưởng, hy vọng, chịu đựng. Tình yêu không dễ bỏ cuộc. Điều đó không có nghĩa ta chấp nhận bị làm hại, nhưng là chọn không dễ dàng bỏ rơi người mình yêu. Chúa yêu ta với tình yêu như vậy. Hôm nay, hãy nghĩ đến một mối quan hệ cần sự kiên nhẫn của bạn, và xin Chúa cho bạn thêm sức để tiếp tục yêu thương trong sự bao dung và hy vọng.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài yêu con bằng tình yêu không bỏ cuộc. Xin giúp con yêu người khác với sự bao dung, tin tưởng, hy vọng và chịu đựng, và ban cho con sức mạnh trong những mối quan hệ khó. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":13,"cau":8,"loi_kinh_thanh":"Tình yêu thương chẳng hề hư mất bao giờ. Các lời tiên tri sẽ hết, sự ban cho nói tiếng lạ sẽ thôi, sự thông biết hầu bị bỏ.","bai_hoc":"Phao-lô viết: Tình yêu thương chẳng hề hư mất bao giờ. Mọi ân tứ khác như nói tiên tri, nói tiếng lạ, tri thức đều sẽ chấm dứt, nhưng tình yêu thì còn mãi. Điều này đặt tình yêu lên trên mọi điều khác trong đức tin. Những thành tựu, kiến thức, ân tứ đều quan trọng, nhưng tình yêu là điều bền nhất. Khi ta nhìn lại đời mình, điều đọng lại là cách ta yêu thương. Hôm nay, hãy dành thời gian cho điều tồn tại mãi: một cuộc trò chuyện chân thành với người thân, một lời cảm ơn, hay một lời cầu nguyện cho ai đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì tình yêu thương không bao giờ hư mất. Xin giúp con ưu tiên tình yêu hơn mọi điều khác, và sống để điều con để lại cho người khác là sự yêu thương. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":13,"cau":12,"loi_kinh_thanh":"Ngày nay chúng ta xem như trong một cái gương, cách mập mờ: đến bấy giờ chúng ta sẽ thấy hai mặt đối nhau; ngày nay tôi biết chưa hết: đến bấy giờ tôi sẽ biết như Chúa đã biết tôi vậy.","bai_hoc":"Phao-lô viết: \\"Ngày nay chúng ta xem như trong một cái gương, cách mập mờ: đến bấy giờ chúng ta sẽ thấy hai mặt đối nhau; ngày nay tôi biết chưa hết: đến bấy giờ tôi sẽ biết như Chúa đã biết tôi vậy\\" Bây giờ tôi biết một phần, đến bấy giờ tôi sẽ biết như Chúa biết tôi. Có nhiều điều trong đời ta chưa hiểu: vì sao có đau khổ, vì sao một việc xảy ra. Phao-lô thừa nhận điều đó. Nhưng ông hy vọng một ngày ta sẽ thấy rõ. Điều này làm ta nhẹ lòng: không cần hiểu hết bây giờ. Hôm nay, hãy trao cho Chúa những câu hỏi chưa có lời đáp, và yên tâm rằng Ngài biết bạn trọn vẹn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài biết con trọn vẹn. Xin giúp con yên lòng khi con chưa hiểu hết, và tin rằng một ngày con sẽ thấy rõ mặt đối mặt. Trong lúc chờ đợi, xin giữ con trong đức tin và tin cậy. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":13,"cau":13,"loi_kinh_thanh":"Nên bây giờ còn có ba điều nầy: đức tin, sự trông cậy, tình yêu thương; nhưng điều trọng hơn trong ba điều đó là tình yêu thương.","bai_hoc":"Phao-lô kết thúc bài ca về tình yêu: \\"Nên bây giờ còn có ba điều nầy: đức tin, sự trông cậy, tình yêu thương; nhưng điều trọng hơn trong ba điều đó là tình yêu thương\\" Ba điều này tạo nên nền của đời sống tin kính: tin Chúa, hy vọng nơi Ngài và yêu thương. Trong đó, tình yêu là lớn nhất, vì nó phản ánh bản tính của Chúa. Hôm nay, hãy hỏi mình: trong ba điều này, điều nào tôi cần nuôi dưỡng nhất lúc này? Rồi dành một khoảnh khắc cầu xin Chúa làm lớn lên điều đó trong bạn.","loi_cau_nguyen":"Chúa ơi, xin làm lớn lên trong con đức tin, hy vọng và tình yêu, nhất là tình yêu. Xin cho con sống để ba điều ấy thể hiện trong lời nói và việc làm của con với những người xung quanh. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":15,"cau":55,"loi_kinh_thanh":"Hỡi sự chết, sự thắng của mầy ở đâu? Hỡi sự chết, cái nọc của mầy ở đâu?","bai_hoc":"Phao-lô hỏi: Hỡi sự chết, sự thắng của mầy ở đâu? Hỡi âm phủ, cái nọc của mầy ở đâu? Ông nói điều này sau khi giải thích về sự sống lại của Chúa Giê-su. Cái chết có vẻ là điều cuối cùng, nhưng vì Chúa Giê-su đã sống lại, nó mất đi sức mạnh chiến thắng. Ông chế giễu cái chết như một kẻ đã bại trận. Điều này cho ta hy vọng khi đối diện với mất mát. Hôm nay, nếu bạn đang đau buồn vì ai đó, hãy nhớ rằng cái chết không có tiếng nói cuối cùng. Hãy để lời này an ủi bạn một cách nhẹ nhàng.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã chiến thắng sự chết. Xin an ủi những ai đang đau buồn vì mất mát, và giữ con vững lòng trong niềm hy vọng về sự sống lại trong Ngài. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":15,"cau":57,"loi_kinh_thanh":"Nhưng, tạ ơn Đức Chúa Trời đã cho chúng ta sự thắng, nhờ Đức Chúa Jêsus Christ chúng ta.","bai_hoc":"Phao-lô viết: \\"Nhưng, tạ ơn Đức Chúa Trời đã cho chúng ta sự thắng, nhờ Đức Chúa Jêsus Christ chúng ta\\" Chiến thắng của chúng ta là món quà. Không phải ta giành được bằng sức mạnh, mà Chúa Giê-su đã chiến thắng và chia sẻ với ta. Điều đó làm ta biết ơn hơn là kiêu hãnh. Trong những cuộc chiến của đời sống, ta chiến đấu từ vị trí đã được ban chiến thắng, không phải để giành chiến thắng. Hôm nay, hãy dành một khoảnh khắc tạ ơn Chúa về chiến thắng ấy, và để lòng bạn vững hơn khi đối diện với khó khăn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ban cho chúng con sự thắng nhờ Chúa Giê-su Christ. Xin giúp con sống từ vị trí của người đã được chiến thắng, với lòng biết ơn và tin cậy, khi con đối diện những khó khăn. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":15,"cau":58,"loi_kinh_thanh":"Vậy, hỡi anh em yêu dấu của tôi, hãy vững vàng chớ rúng động, hãy làm công việc Chúa cách dư dật luôn, vì biết rằng công khó của anh em trong Chúa chẳng phải là vô ích đâu.","bai_hoc":"Phao-lô kết thúc chương về sự sống lại: \\"Vậy, hỡi anh em yêu dấu của tôi, hãy vững vàng chớ rúng động, hãy làm công việc Chúa cách dư dật luôn, vì biết rằng công khó của anh em trong Chúa chẳng phải là vô ích đâu\\" Hy vọng về sự sống lại thay đổi cách ta làm việc: ta làm vì biết rằng mọi việc làm trong Chúa không uổng phí. Dù bạn chăm sóc gia đình, dạy dỗ, phục vụ trong thầm lặng, Chúa ghi nhớ. Hôm nay, hãy tiếp tục làm điều tốt, và nhắc mình: không điều gì làm trong Chúa là vô ích.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì công khó của con trong Chúa không vô ích. Xin giúp con vững vàng và không rúng động, tiếp tục làm công việc của Ngài với lòng nhiệt thành, dù đôi khi con chưa thấy kết quả. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":16,"cau":13,"loi_kinh_thanh":"Anh em hãy tỉnh thức, hãy vững vàng trong đức tin, hãy dốc chí trượng phu và mạnh mẽ.","bai_hoc":"Phao-lô viết những lời cuối: \\"Anh em hãy tỉnh thức, hãy vững vàng trong đức tin, hãy dốc chí trượng phu và mạnh mẽ\\" Bốn mệnh lệnh ngắn cho một Hội Thánh đang chịu nhiều áp lực. Tỉnh thức là chú ý đến đời sống thuộc linh. Đứng vững là không bị lay chuyển. Dũng cảm là dám bước tới. Mạnh mẽ là nhờ sức của Chúa. Những lời này cũng dành cho bạn trong những ngày thử thách. Hôm nay, hãy chọn một lời mà bạn cần nhất và cầu xin Chúa giúp bạn thực hành điều ấy trong một việc cụ thể.","loi_cau_nguyen":"Chúa ơi, xin giúp con tỉnh thức, đứng vững trong đức tin, dũng cảm và mạnh mẽ. Xin ban cho con sức mạnh từ Ngài khi con phải đối diện với áp lực và những ngày thử thách. A-men."},{"sach":"I Cô-rinh","ma":"1CO","chuong":16,"cau":14,"loi_kinh_thanh":"Mọi điều anh em làm, hãy lấy lòng yêu thương mà làm.","bai_hoc":"Phao-lô thêm một câu ngắn mà sâu: Mọi điều anh em làm, hãy lấy lòng yêu thương mà làm. Đây là cách nhìn lại mọi hành động của ta: động lực là gì? Ta có thể làm đúng việc nhưng thiếu tình yêu, và việc ấy mất đi hương vị. Khi ta làm với lòng yêu thương, ngay cả việc nhỏ cũng có sức mạnh. Hôm nay, hãy chọn một việc bạn sắp làm, một công việc, một cuộc trò chuyện, và thầm xin Chúa giúp bạn làm với lòng yêu thương, thay vì chỉ vì bổn phận. Tình yêu làm cho ngay cả việc đơn giản nhất trở nên có giá trị trước mặt Ngài.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm mọi việc trong tình yêu thương. Xin cho tình yêu của Ngài là động lực của con, và giúp con nhìn những người con phục vụ bằng đôi mắt dịu dàng. A-men."},{"sach":"II Cô-rinh","ma":"2CO","chuong":4,"cau":18,"loi_kinh_thanh":"bởi chúng ta chẳng chăm sự thấy được, nhưng chăm sự không thấy được; vì những sự thấy được chỉ là tạm thời, mà sự không thấy được là đời đời không cùng vậy.","bai_hoc":"Phao-lô viết: \\"bởi chúng ta chẳng chăm sự thấy được, nhưng chăm sự không thấy được; vì những sự thấy được chỉ là tạm thời, mà sự không thấy được là đời đời không cùng vậy\\" Ông đang nói về việc nhìn qua đau khổ và khó khăn hiện tại để thấy điều đời đời. Mắt thường thấy khó khăn, nhưng mắt đức tin thấy điều Chúa đang chuẩn bị. Điều đó giúp ta không quá nặng nề với những điều tạm thời. Hôm nay, hãy thử nhìn một khó khăn từ góc nhìn đời đời, và hỏi: điều này sẽ quan trọng thế nào trong ánh sáng của sự đời đời?","loi_cau_nguyen":"Chúa ơi, xin giúp con nhìn vào những điều không thấy được và đời đời, hơn là chỉ những điều thấy được và tạm thời. Xin cho con quan điểm của Ngài trong những khó khăn con đang đối diện. A-men."},{"sach":"II Cô-rinh","ma":"2CO","chuong":5,"cau":7,"loi_kinh_thanh":"vì chúng ta bước đi bởi đức tin, chớ chẳng phải bởi mắt thấy.","bai_hoc":"Phao-lô viết ngắn gọn: \\"vì chúng ta bước đi bởi đức tin, chớ chẳng phải bởi mắt thấy\\" Có những lúc ta không thể thấy đường phía trước, và điều đó làm ta bất an. Đức tin không phải là biết rõ đường mà là tin vào Đấng dẫn đường. Giống như đi trong đêm với một ngọn đèn nhỏ, ta chỉ thấy vài bước, nhưng đủ để tiến lên. Hôm nay, hãy thử bước đi một bước bằng đức tin: làm điều Chúa chỉ dù chưa thấy kết quả, và tin rằng Ngài đi cùng bạn. Ngài không đòi bạn thấy hết con đường, chỉ cần tin cậy và bước đi.","loi_cau_nguyen":"Chúa ơi, xin giúp con bước đi bởi đức tin, không bởi mắt thấy. Khi con không thấy đường phía trước, xin cho con tin cậy sự dẫn dắt của Ngài và có can đảm bước tiếp một bước. A-men."},{"sach":"II Cô-rinh","ma":"2CO","chuong":5,"cau":17,"loi_kinh_thanh":"Vậy, nếu ai ở trong Đấng Christ, thì nấy là người dựng nên mới; những sự cũ đã qua đi, nầy mọi sự đều trở nên mới.","bai_hoc":"Phao-lô viết: Vậy, nếu ai ở trong Đấng Christ, thì nấy là người dựng nên mới; những sự cũ đã qua đi, nầy mọi sự đều trở nên mới. Đây là một lời hứa khởi đầu mới. Quá khứ của bạn, những lỗi lầm, những tổn thương, không còn định nghĩa bạn. Trong Chúa Giê-su, bạn là người mới. Quá trình này không xảy ra ngay lập tức, nhưng căn tính mới đã được trao. Hôm nay, hãy nhìn lại một điều cũ bạn vẫn mang, và xin Chúa giúp bạn đặt xuống để sống trong căn tính mới ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài làm cho con thành người mới trong Chúa Giê-su. Xin giúp con thôi bị quá khứ định nghĩa, và sống mỗi ngày trong căn tính mới Ngài ban, với hy vọng và tự do. A-men."},{"sach":"II Cô-rinh","ma":"2CO","chuong":9,"cau":7,"loi_kinh_thanh":"Mỗi người nên tùy theo lòng mình đã định mà quyên ra, không phải phàn nàn hay vì ép uổng; vì Đức Chúa Trời yêu kẻ thí của cách vui lòng.","bai_hoc":"Phao-lô viết: \\"Mỗi người nên tùy theo lòng mình đã định mà quyên ra, không phải phàn nàn hay vì ép uổng; vì Đức Chúa Trời yêu kẻ thí của cách vui lòng\\" Chúa không muốn sự cho đi trong sự miễn cưỡng, mà trong niềm vui. Điều đó không đo bằng số lượng, mà bằng tấm lòng. Có khi ta cho nhiều nhưng không vui, hoặc cho ít nhưng với tất cả tấm lòng. Chúa nhìn vào tấm lòng ấy. Hôm nay, hãy cho một điều gì đó với lòng vui: thời gian, tiền bạc, sự giúp đỡ, và để ý niềm vui thật sự trong việc cho.","loi_cau_nguyen":"Chúa ơi, xin cho con lòng vui khi cho đi, không miễn cưỡng hay ép buộc. Xin giúp con cho theo tấm lòng và khả năng của con, và cảm nhận niềm vui của việc chia sẻ những gì Ngài đã ban. A-men."},{"sach":"II Cô-rinh","ma":"2CO","chuong":12,"cau":9,"loi_kinh_thanh":"Nhưng Chúa phán rằng: Ân điển ta đủ cho ngươi rồi, vì sức mạnh của ta nên trọn vẹn trong sự yếu đuối. Vậy, tôi sẽ rất vui lòng khoe mình về sự yếu đuối tôi, hầu cho sức mạnh của Đấng Christ ở trong tôi.","bai_hoc":"Phao-lô cầu xin Chúa cất đi một cái gai trong xác thịt, và Chúa đáp: \\"Nhưng Chúa phán rằng: Ân điển ta đủ cho ngươi rồi, vì sức mạnh của ta nên trọn vẹn trong sự yếu đuối. Vậy, tôi sẽ rất vui lòng khoe mình về sự yếu đuối tôi, hầu cho sức mạnh của Đấng Christ ở trong tôi\\" Chúa không cất đi gai, nhưng hứa ban ơn đủ. Điều này không dễ nghe, nhưng đầy an ủi: sự yếu đuối của bạn không ngăn cản Chúa làm việc, mà là chỗ để sức mạnh Ngài hiện ra. Hôm nay, hãy đừng giấu sự yếu đuối với Chúa. Hãy đưa nó cho Ngài, và xin ơn đủ cho ngày hôm nay, đúng điều Ngài hứa. Bạn không cần phải mạnh mẽ giả tạo, vì sức Ngài hiện ra rõ nhất khi bạn thật thà.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa ơn Ngài đủ cho con, và sức mạnh Ngài nên trọn vẹn trong sự yếu đuối. Xin giúp con không giấu những yếu đuối của mình, mà đến với Ngài và nhận ơn đủ cho hôm nay. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":2,"cau":20,"loi_kinh_thanh":"Tôi đã bị đóng đinh vào thập tự giá với Đấng Christ, mà tôi sống, không phải là tôi sống nữa, nhưng Đấng Christ sống trong tôi; nay tôi còn sống trong xác thịt, ấy là tôi sống trong đức tin của Con Đức Chúa Trời, là Đấng đã yêu tôi, và đã phó chính mình Ngài vì tôi.","bai_hoc":"Phao-lô viết: Tôi đã bị đóng đinh vào thập tự giá với Đấng Christ, mà tôi sống, không phải là tôi sống nữa, nhưng Đấng Christ sống trong tôi. Ông mô tả đời sống đức tin: một đời sống được chia sẻ, nơi Chúa Giê-su sống trong ông. Điều đó có nghĩa là bạn không phải sống đời tin Chúa bằng sức riêng, mà bằng sự sống của Ngài trong bạn. Ông nói về Chúa Giê-su là Đấng yêu thương và phó mình vì ông. Hôm nay, hãy sống ngày này với ý thức: Chúa Giê-su đang sống trong tôi, và Ngài làm việc cùng tôi.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã yêu con và phó mình vì con. Xin sống trong con, và giúp con sống đời đức tin bằng sự sống của Ngài, không bằng sức riêng của con. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":3,"cau":28,"loi_kinh_thanh":"Tại đây không còn chia ra người Giu-đa hoặc người Gờ-réc; không còn người tôi mọi hoặc người tự chủ; không còn đàn ông hoặc đàn bà; vì trong Đức Chúa Jêsus Christ, anh em thảy đều làm một.","bai_hoc":"Phao-lô viết: \\"Tại đây không còn chia ra người Giu-đa hoặc người Gờ-réc; không còn người tôi mọi hoặc người tự chủ; không còn đàn ông hoặc đàn bà; vì trong Đức Chúa Jêsus Christ, anh em thảy đều làm một\\" Những ranh giới xã hội thời ấy rất sâu, nhưng trong Chúa Giê-su, mọi người bình đẳng và hiệp một. Điều này nhắc ta nhìn người khác qua mắt Chúa: không phải theo dân tộc, địa vị hay giới tính, mà là người được Ngài yêu thương. Hôm nay, hãy để ý xem bạn có đang nhìn ai bằng định kiến, và xin Chúa giúp bạn nhìn họ như Ngài nhìn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài làm cho chúng con nên một trong Chúa Giê-su. Xin giúp con nhìn mọi người bằng mắt của Ngài, không theo địa vị hay khác biệt, và xây dựng sự hiệp một trong cộng đoàn con thuộc về. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":5,"cau":22,"loi_kinh_thanh":"Nhưng trái của Thánh Linh, ấy là lòng yêu thương, sự vui mừng, bình an, nhịn nhục, nhân từ, hiền lành, trung tín, mềm mại, tiết độ:","bai_hoc":"Phao-lô viết: \\"Nhưng trái của Thánh Linh, ấy là lòng yêu thương, sự vui mừng, bình an, nhịn nhục, nhân từ, hiền lành, trung tín, mềm mại, tiết độ\\" Chú ý chữ trái, số ít: đó là một sự tăng trưởng tự nhiên khi ta sống gần Thánh Linh, không phải kết quả của sự cố gắng. Giống như cây táo ra táo khi nó được chăm sóc, đời sống ở trong Chúa sinh ra những phẩm chất này. Hôm nay, hãy chọn một phẩm chất trong danh sách mà bạn muốn thấy lớn lên, và xin Thánh Linh làm điều ấy trong bạn.","loi_cau_nguyen":"Chúa ơi, xin cho Thánh Linh Ngài sinh trái trong con: yêu thương, vui mừng, bình an, nhịn nhục, nhân từ, hiền lành, trung tín. Xin giúp con ở gần Ngài để những phẩm chất ấy lớn lên tự nhiên. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":6,"cau":2,"loi_kinh_thanh":"Hãy mang lấy gánh nặng cho nhau, như vậy anh em sẽ làm trọn luật pháp của Đấng Christ.","bai_hoc":"Phao-lô viết: Hãy mang gánh nặng cho nhau, như vậy anh em sẽ làm trọn luật pháp của Đấng Christ. Chúng ta đều có gánh nặng, và chúng ta không được kêu gọi để mang một mình. Cộng đoàn đức tin là nơi ta cùng nhau chia sẻ gánh nặng. Điều này đòi hỏi hai điều: dám để người khác biết mình cần giúp, và chịu để ý đến người khác. Hôm nay, hãy hỏi một người xem họ có đang mang điều gì nặng không, và lắng nghe. Và nếu bạn đang mang gánh nặng, hãy can đảm chia sẻ với một người đáng tin.","loi_cau_nguyen":"Chúa ơi, xin giúp con mang gánh nặng cho người khác và biết nhờ người khác mang gánh cùng con. Xin cho con sự dịu dàng để lắng nghe, và can đảm để chia sẻ khi con cần giúp đỡ. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":6,"cau":7,"loi_kinh_thanh":"Chớ hề dối mình; Đức Chúa Trời không chịu khinh dể đâu; vì ai gieo giống chi, lại gặt giống ấy.","bai_hoc":"Phao-lô viết: Đừng tự dối mình; Đức Chúa Trời không chịu khinh dể đâu, vì ai gieo giống chi, lại gặt giống ấy. Đây là nguyên tắc về gieo và gặt: những lựa chọn của ta có hậu quả. Câu này là lời cảnh báo nhưng cũng là lời khích lệ. Nếu ta gieo điều tốt, ta sẽ gặt điều tốt, dù có thể cần thời gian. Hôm nay, hãy nhìn lại hạt giống nào bạn đang gieo: trong lời nói, thời gian, các mối quan hệ. Hãy gieo vào những điều lành, dù nhỏ, và tin rằng Chúa sẽ làm cho chúng sinh trái đúng lúc.","loi_cau_nguyen":"Chúa ơi, xin giúp con gieo những hạt giống tốt trong lời nói, hành động và các mối quan hệ của con. Xin cho con kiên nhẫn chờ mùa gặt, và giữ con khỏi tự dối mình về những điều con gieo. A-men."},{"sach":"Ga-la-ti","ma":"GAL","chuong":6,"cau":9,"loi_kinh_thanh":"Chớ mệt nhọc về sự làm lành, vì nếu chúng ta không trễ nải, thì đến kỳ chúng ta sẽ gặt.","bai_hoc":"Phao-lô viết: \\"Chớ mệt nhọc về sự làm lành, vì nếu chúng ta không trễ nải, thì đến kỳ chúng ta sẽ gặt\\" Ông biết chúng ta dễ mệt mỏi khi làm điều tốt mà không thấy kết quả. Lời khích lệ ở đây là hãy kiên trì, vì mùa gặt sẽ đến vào đúng kỳ. Điều tốt không bao giờ vô ích, dù thời gian có thể lâu. Hôm nay, nếu bạn đang thấy mệt vì làm điều lành, như chăm sóc người thân hay phục vụ trong thầm lặng, hãy nghe lời này như một cái ôm: đừng bỏ cuộc, Ngài thấy và sẽ ban thưởng đúng lúc.","loi_cau_nguyen":"Chúa ơi, khi con mệt mỏi vì làm điều lành, xin giúp con không bỏ cuộc. Xin cho con sức mạnh để kiên trì, và nhắc con rằng đến kỳ con sẽ gặt nếu con không trễ nải. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":2,"cau":8,"loi_kinh_thanh":"Vả, ấy là nhờ ân điển, bởi đức tin, mà anh em được cứu, điều đó không phải đến từ anh em, bèn là sự ban cho của Đức Chúa Trời.","bai_hoc":"Phao-lô viết: Vì chưng nhờ ân điển, bởi đức tin, mà anh em được cứu, điều đó không phải đến từ anh em, bèn là sự ban cho của Đức Chúa Trời. Đây là nền tảng của đức tin Cơ Đốc: ơn cứu là món quà. Bạn không phải làm cho mình xứng đáng, không phải đạt được mức nào đó. Chỉ cần đón nhận bằng đức tin. Điều này giải thoát ta khỏi gánh nặng chứng minh. Hôm nay, hãy nhận lấy món quà ấy như lần đầu: đơn giản và biết ơn, và để lòng bạn nghỉ ngơi trong ân điển.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì ơn cứu là món quà bởi ân điển và đức tin, không do công trạng của con. Xin giúp con nhận lấy với lòng biết ơn, và sống tự do khỏi gánh nặng phải chứng minh mình. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":2,"cau":9,"loi_kinh_thanh":"Ấy chẳng phải bởi việc làm đâu, hầu cho không ai khoe mình;","bai_hoc":"Phao-lô tiếp tục: Ấy chẳng phải bởi việc làm đâu, hầu cho không ai khoe mình. Ơn cứu không dựa trên việc làm của chúng ta để không ai có cớ kiêu ngạo. Điều này làm ta khiêm nhường: mọi người đều nhận cùng một món quà. Nó cũng làm ta tự do: ta không phải so sánh thành tích của mình với ai. Hôm nay, hãy để ý khi bạn bắt đầu tự hào về điều mình làm, và nhắc mình rằng mọi thứ đều là ân điển. Rồi hãy biết ơn Chúa vì điều đó. Lòng khiêm nhường mở ra cho bạn một sự tự do thật sự và niềm vui đơn giản.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì ơn cứu không do việc làm để không ai khoe mình. Xin giúp con sống khiêm nhường và biết ơn, và thôi so sánh thành tích với người khác. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":2,"cau":10,"loi_kinh_thanh":"vì chúng ta là việc Ngài làm ra, đã được dựng nên trong Đức Chúa Jêsus Christ để làm việc lành mà Đức Chúa Trời đã sắm sẵn trước cho chúng ta làm theo.","bai_hoc":"Phao-lô viết: \\"vì chúng ta là việc Ngài làm ra, đã được dựng nên trong Đức Chúa Jêsus Christ để làm việc lành mà Đức Chúa Trời đã sắm sẵn trước cho chúng ta làm theo\\" Sau khi nói ơn cứu không do việc làm, ông nói mục đích của ơn cứu là việc lành. Chúng ta là tác phẩm của Chúa và có mục đích. Ngài đã chuẩn bị những việc lành cho ta từ trước. Hôm nay, hãy hỏi Chúa: việc lành nào Ngài đã sắm sẵn cho tôi? Hãy để ý một cơ hội nhỏ và làm điều ấy với lòng sẵn sàng.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì con là tác phẩm của Ngài, được dựng nên để làm việc lành. Xin chỉ cho con những việc Ngài đã sắm sẵn, và giúp con làm chúng với lòng sẵn sàng và yêu thương. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":3,"cau":20,"loi_kinh_thanh":"Vả, Đức Chúa Trời, bởi quyền lực cảm động trong chúng ta, có thể làm trổi hơn vô cùng mọi việc chúng ta cầu xin hoặc suy tưởng,","bai_hoc":"Phao-lô cầu chúc: \\"Vả, Đức Chúa Trời, bởi quyền lực cảm động trong chúng ta, có thể làm trổi hơn vô cùng mọi việc chúng ta cầu xin hoặc suy tưởng\\" Chúa có thể làm vượt xa những gì ta dám mong. Điều này mời ta cầu nguyện với lòng mong đợi lớn hơn. Có những lúc ta ngần ngại xin vì cảm thấy mình xin quá nhiều. Nhưng Ngài sẵn sàng làm nhiều hơn. Hôm nay, hãy xin Chúa một điều lớn hơn bạn thường dám xin, và để ý xem Ngài làm gì. Và nhớ rằng quyền phép Ngài đang hoạt động trong chính bạn, từng ngày, ngay cả khi bạn chưa cảm nhận rõ.","loi_cau_nguyen":"Chúa ơi, Ngài có quyền làm nhiều hơn mọi điều con cầu xin hay suy tưởng. Xin cho con dám xin và mong đợi nơi Ngài, và để quyền phép Ngài làm việc trong con theo cách vượt xa điều con nghĩ. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":4,"cau":26,"loi_kinh_thanh":"Ví bằng anh em đang cơn giận, thì chớ phạm tội; chớ căm giận cho đến khi mặt trời lặn,","bai_hoc":"Phao-lô viết: Hãy nóng giận, nhưng đừng phạm tội; chớ để mặt trời lặn trong cơn giận của anh em. Giận dữ là cảm xúc tự nhiên, và bản thân nó không phải là tội. Vấn đề là điều ta làm với cơn giận. Nếu ta để nó âm ỉ, nó dần trở thành cay đắng. Lời khuyên là giải quyết nó trong ngày, đừng mang vào đêm. Hôm nay, nếu bạn đang giận ai, hãy thành thật với Chúa về điều đó và tìm cách giải quyết lành mạnh: nói chuyện, tha thứ hoặc đặt ranh giới, trước khi ngày kết thúc.","loi_cau_nguyen":"Chúa ơi, xin giúp con xử lý cơn giận một cách lành mạnh, không để nó dẫn con vào tội lỗi. Xin cho con khôn ngoan để giải quyết, tha thứ, và không mang cay đắng vào ban đêm. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":4,"cau":32,"loi_kinh_thanh":"Hãy ở với nhau cách nhân từ, đầy dẫy lòng thương xót, tha thứ nhau như Đức Chúa Trời đã tha thứ anh em trong Đấng Christ vậy.","bai_hoc":"Phao-lô viết: Hãy ở với nhau cách nhân từ, đầy dẫy lòng thương xót, tha thứ nhau như Đức Chúa Trời đã tha thứ anh em trong Đấng Christ vậy. Chúng ta tha thứ vì đã được tha. Tiêu chuẩn tha thứ là sự tha thứ Chúa đã dành cho ta, và điều đó giúp ta nhớ mình cũng đã nhận nhiều. Hôm nay, hãy làm một điều nhân từ cho một người gần bạn, và nếu có điều gì cần tha thứ, hãy nhớ đến lòng thương xót bạn đã nhận, rồi xin Chúa giúp bạn bắt đầu tha.","loi_cau_nguyen":"Chúa ơi, xin giúp con ở với người khác cách nhân từ và đầy lòng thương xót. Xin cho con tha thứ như Ngài đã tha thứ con, và nhớ rằng con đã nhận được rất nhiều ân điển từ Ngài. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":6,"cau":1,"loi_kinh_thanh":"Hỡi kẻ làm con cái, hãy vâng phục cha mẹ mình trong Chúa, vì điều đó là phải lắm.","bai_hoc":"Phao-lô viết: \\"Hỡi kẻ làm con cái, hãy vâng phục cha mẹ mình trong Chúa, vì điều đó là phải lắm\\" Lời này dành cho con cái, nhưng cũng cho mọi người ở mọi tuổi biết ơn cha mẹ mình. Vâng phục trong Chúa có nghĩa là trong khuôn khổ ngay thẳng và với tinh thần tôn trọng. Gia đình lành mạnh dựa trên sự tôn trọng hai chiều. Hôm nay, nếu bạn là con cái, hãy làm một điều nhỏ để tôn trọng cha mẹ. Nếu bạn là cha mẹ, hãy cầu nguyện cho con cái và làm gương bằng lối sống của mình.","loi_cau_nguyen":"Chúa ơi, xin giúp con tôn trọng cha mẹ mình, và xin ban phước cho gia đình con. Xin cho con biết ơn những người đã nuôi dưỡng con, và giúp mối quan hệ trong gia đình được hòa thuận và chữa lành. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":6,"cau":10,"loi_kinh_thanh":"Vả lại, anh em phải làm mạnh dạn trong Chúa, nhờ sức toàn năng của Ngài.","bai_hoc":"Phao-lô viết: \\"Vả lại, anh em phải làm mạnh dạn trong Chúa, nhờ sức toàn năng của Ngài\\" Ông không bảo ta mạnh mẽ bằng sức riêng, mà mạnh mẽ trong Chúa. Có những lúc ta thấy mình yếu đuối, và đó là chỗ để dựa vào sức Ngài. Lời này mở đầu đoạn về khí giới thuộc linh, nhắc rằng ta cần sức mạnh từ Ngài để đứng vững. Hôm nay, trước khi bắt đầu một việc khó, hãy dừng lại cầu xin: Chúa ơi, xin cho con sức mạnh của Ngài. Rồi bước tiếp với lòng tin cậy. Bạn không phải đối diện điều đó một mình, vì sức Ngài sẵn có cho bạn.","loi_cau_nguyen":"Chúa ơi, xin cho con mạnh mẽ trong Ngài và trong sức toàn năng của Ngài. Khi con thấy mình yếu đuối, xin giúp con dựa vào Ngài, và bước đi với sự tin cậy hơn là sức riêng. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":6,"cau":11,"loi_kinh_thanh":"Hãy mang lấy mọi khí giới của Đức Chúa Trời, để được đứng vững mà địch cùng mưu kế của ma quỉ.","bai_hoc":"Phao-lô viết: \\"Hãy mang lấy mọi khí giới của Đức Chúa Trời, để được đứng vững mà địch cùng mưu kế của ma quỉ\\" Ông dùng hình ảnh khí giới của người lính La Mã: chân lý, công bình, bình an, đức tin, sự cứu rỗi, và Lời Chúa. Không phải ta tự chế tạo chúng, mà Chúa ban. Việc ta cần làm là mang lấy mỗi ngày. Hôm nay, hãy thử mặc từng phần khí giới trong cầu nguyện, từ chân lý đến Lời Chúa, như chuẩn bị cho một ngày nhiều thách thức. Việc ấy chỉ mất vài phút nhưng giúp lòng bạn vững hơn rất nhiều.","loi_cau_nguyen":"Chúa ơi, xin giúp con mang lấy mọi khí giới của Ngài để đứng vững trước mưu kế của ma quỷ. Xin giúp con mặc chân lý, công bình, bình an, đức tin, sự cứu rỗi và Lời Ngài mỗi ngày. A-men."},{"sach":"Ê-phê-sô","ma":"EPH","chuong":6,"cau":12,"loi_kinh_thanh":"Vì chúng ta đánh trận, chẳng phải cùng thịt và huyết, bèn là cùng chủ quyền, cùng thế lực, cùng vua chúa của thế gian mờ tối nầy, cùng các thần dữ ở các miền trên trời vậy.","bai_hoc":"Phao-lô nhắc: \\"Vì chúng ta đánh trận, chẳng phải cùng thịt và huyết, bèn là cùng chủ quyền, cùng thế lực, cùng vua chúa của thế gian mờ tối nầy, cùng các thần dữ ở các miền trên trời vậy\\" Nhiều khi ta đấu tranh với những người xung quanh, trong khi cuộc chiến thật sự nằm ở phương diện thuộc linh. Điều này giúp ta bớt giận người khác và biết nương cậy cầu nguyện. Hôm nay, nếu có ai khiến bạn bực bội, hãy nhắc mình rằng họ không phải kẻ thù thật, và cầu nguyện cho họ thay vì chống lại họ.","loi_cau_nguyen":"Chúa ơi, xin giúp con nhớ rằng cuộc chiến thật của con không phải với con người, mà với các thế lực thuộc linh. Xin cho con khôn ngoan để cầu nguyện thay vì tranh cãi, và nương cậy sự bảo vệ của Ngài. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":1,"cau":6,"loi_kinh_thanh":"tôi tin chắc rằng Đấng đã khởi làm việc lành trong anh em, sẽ làm trọn hết cho đến ngày của Đức Chúa Jêsus Christ.","bai_hoc":"Phao-lô viết cho Hội Thánh Phi-líp: \\"tôi tin chắc rằng Đấng đã khởi làm việc lành trong anh em, sẽ làm trọn hết cho đến ngày của Đức Chúa Jêsus Christ\\" Điều này khích lệ những ai thấy mình chưa trọn vẹn. Chúa không bỏ dở công việc Ngài đã bắt đầu trong bạn. Quá trình thay đổi đôi khi chậm và có lúc thụt lùi, nhưng Ngài kiên nhẫn và thành tín. Bạn không cần phải hoàn hảo hôm nay. Hôm nay, hãy biết ơn về một điều Chúa đã làm trong bạn, dù nhỏ, và tin rằng Ngài sẽ tiếp tục cho đến khi hoàn tất, bằng sự kiên nhẫn và tình yêu của Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã bắt đầu việc lành trong con và hứa làm cho trọn. Xin giúp con kiên nhẫn với chính mình, và tin rằng Ngài không bỏ dở công việc Ngài đã khởi sự trong đời con. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":1,"cau":21,"loi_kinh_thanh":"Vì Đấng Christ là sự sống của tôi, và sự chết là điều ích lợi cho tôi vậy.","bai_hoc":"Phao-lô viết: \\"Vì Đấng Christ là sự sống của tôi, và sự chết là điều ích lợi cho tôi vậy\\" Ông viết khi đang ở trong tù, đối diện với khả năng mất mạng, nhưng lòng ông bình an vì ông biết mục đích của đời mình. Sống là Đấng Christ nghĩa là Chúa Giê-su là trung tâm, ý nghĩa và mục tiêu của mọi việc. Khi ta đặt Ngài ở trung tâm, ta không quá sợ mất những điều khác. Hôm nay, hãy hỏi mình: điều gì đang là trung tâm của đời tôi? Và nhẹ nhàng đặt Chúa Giê-su vào vị trí ấy, trong mọi việc bạn làm.","loi_cau_nguyen":"Chúa Giê-su ơi, xin cho Ngài là sự sống của con, là trung tâm và ý nghĩa của mọi việc con làm. Xin giúp con sống mỗi ngày với mục đích rõ ràng, và không quá sợ hãi trước những điều con có thể mất. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":2,"cau":10,"loi_kinh_thanh":"hầu cho nghe đến danh Đức Chúa Jêsus, mọi đầu gối trên trời, dưới đất, bên dưới đất, thảy đều quì xuống,","bai_hoc":"Phao-lô viết về Chúa Giê-su: \\"hầu cho nghe đến danh Đức Chúa Jêsus, mọi đầu gối trên trời, dưới đất, bên dưới đất, thảy đều quì xuống\\" Đây là lời về sự tôn cao danh Chúa Giê-su sau khi Ngài khiêm nhường hạ mình đến chết trên thập tự giá. Ngài là Đấng cao trọng nhất, nhưng chọn đi con đường khiêm nhường nhất. Đó là mẫu mực cho chúng ta. Hôm nay, hãy dành một khoảnh khắc quỳ gối hoặc cúi đầu trong lòng, và thờ phượng Ngài vì Ngài xứng đáng, và xin Ngài dạy bạn lòng khiêm nhường như Ngài.","loi_cau_nguyen":"Chúa Giê-su ơi, danh Ngài cao trọng hơn mọi danh. Con xin thờ phượng Ngài. Xin dạy con lòng khiêm nhường như Ngài đã hạ mình, và giúp con tôn cao danh Ngài trong lời nói và cách sống của con. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":3,"cau":14,"loi_kinh_thanh":"nhưng tôi cứ làm một điều: quên lửng sự ở đằng sau, mà bươn theo sự ở đằng trước, tôi nhắm mục đích mà chạy, để giựt giải về sự kêu gọi trên trời của Đức Chúa Trời trong Đức Chúa Jêsus Christ.","bai_hoc":"Phao-lô viết: Tôi nhắm mục đích mà chạy, để giựt giải về sự kêu gọi trên trời của Đức Chúa Trời trong Đức Chúa Jêsus Christ. Ông nói trước đó rằng ông quên điều đã qua và gắng sức theo điều ở trước mặt. Điều này khích lệ chúng ta buông bỏ gánh nặng của quá khứ, cả thành công lẫn thất bại, và hướng về phía trước. Đời sống đức tin như một cuộc chạy đua có mục tiêu. Hôm nay, hãy đặt xuống một điều trong quá khứ mà bạn đang bám lấy, và nhìn về phía trước với hy vọng nơi sự kêu gọi của Chúa dành cho bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con quên điều đã qua và gắng sức theo điều ở trước mặt. Xin cho con nhắm mục đích Ngài đã đặt cho con, và tiếp tục chạy với hy vọng, không bị quá khứ trói buộc. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":4,"loi_kinh_thanh":"Hãy vui mừng trong Chúa luôn luôn. Tôi lại còn nói nữa: hãy vui mừng đi.","bai_hoc":"Phao-lô viết từ trong tù: Hãy vui mừng trong Chúa luôn luôn. Tôi lặp lại: hãy vui mừng. Ông lặp lại vì biết rằng điều này không dễ. Niềm vui ở đây không phải cảm xúc phụ thuộc hoàn cảnh, mà là niềm vui trong Chúa. Có những ngày ta không cảm thấy vui, nhưng vẫn có thể chọn nhìn vào Chúa, và dần dần niềm vui đến. Hôm nay, hãy tìm một lý do để vui trong Chúa: một ân phước, một lời hứa, một ký ức. Hãy nói thành lời với Ngài, và để niềm vui ấy chạm vào lòng bạn, dù nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con vui mừng trong Ngài luôn luôn, không phụ thuộc vào hoàn cảnh. Xin cho con tìm thấy lý do để vui mừng trong Ngài hôm nay, và để niềm vui ấy nâng đỡ lòng con. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":6,"loi_kinh_thanh":"Chớ lo phiền chi hết, nhưng trong mọi sự hãy dùng lời cầu nguyện, nài xin, và sự tạ ơn mà trình các sự cầu xin của mình cho Đức Chúa Trời.","bai_hoc":"Phao-lô viết: Chớ lo phiền chi hết, nhưng trong mọi sự hãy dùng lời cầu nguyện, nài xin, và sự tạ ơn mà trình các sự cầu xin của mình cho Đức Chúa Trời. Ông không bảo ta đừng cảm thấy lo lắng, mà chỉ cho ta nơi để đặt nó. Mỗi nỗi lo có thể trở thành lời cầu nguyện. Và lời cầu nguyện đi kèm sự tạ ơn: nhớ những gì Chúa đã làm. Hôm nay, khi lo lắng đến, hãy chuyển nó ngay thành một lời cầu nguyện ngắn, cụ thể, rồi thêm một lời cảm tạ, và để ý lòng bạn thay đổi thế nào.","loi_cau_nguyen":"Chúa ơi, con muốn biến những nỗi lo của con thành lời cầu nguyện. Xin giúp con trình mọi điều cho Ngài với lòng tạ ơn, và tin rằng Ngài nghe và chăm sóc con trong từng điều nhỏ lẫn lớn. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":7,"loi_kinh_thanh":"Sự bình an của Đức Chúa Trời vượt quá mọi sự hiểu biết, sẽ giữ gìn lòng và ý tưởng anh em trong Đức Chúa Jêsus Christ.","bai_hoc":"Phao-lô tiếp tục: Sự bình an của Đức Chúa Trời, vượt quá mọi sự hiểu biết, sẽ giữ gìn lòng và ý tưởng anh em trong Đức Chúa Jêsus Christ. Chữ giữ gìn là từ của người lính canh gác. Bình an của Chúa canh giữ lòng và tâm trí ta. Bình an này vượt quá sự hiểu biết: nó có thể đến ngay cả khi hoàn cảnh chưa thay đổi và ta không thể giải thích. Hôm nay, sau khi bạn cầu nguyện về một điều lo lắng, hãy để ý sự bình an Chúa đặt vào lòng, và nhận lấy nó như món quà.","loi_cau_nguyen":"Chúa ơi, xin ban cho con bình an vượt quá mọi sự hiểu biết, canh giữ lòng và tâm trí con trong Chúa Giê-su. Xin giúp con nhận lấy bình an ấy, ngay cả khi hoàn cảnh của con chưa thay đổi. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":8,"loi_kinh_thanh":"Rốt lại, hỡi anh em, phàm điều chi chân thật, điều chi đáng tôn, điều chi công bình, điều chi thánh sạch, điều chi đáng yêu chuộng, điều chi có tiếng tốt, điều chi có nhân đức đáng khen, thì anh em phải nghĩ đến.","bai_hoc":"Phao-lô viết: Hễ điều chi chân thật, điều chi đáng trọng, điều chi công bình, điều chi thanh sạch, điều chi đáng yêu chuộng, điều chi có tiếng tốt, điều chi có nhân đức đáng khen, thì anh em phải nghĩ đến. Tâm trí là nơi nhiều cuộc chiến diễn ra. Ông mời ta chủ động hướng suy nghĩ vào những điều tốt đẹp. Điều đó không phủ nhận thực tế, nhưng tạo cân bằng cho tâm hồn. Hôm nay, hãy chọn một điều chân thật và đáng yêu để suy nghĩ khi bạn thấy tâm trí đi vào những ý nghĩ tiêu cực, và thực hành lặp lại điều đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con hướng tâm trí vào những điều chân thật, đáng trọng, công bình, thanh sạch và đáng yêu. Xin canh giữ ý nghĩ của con, và giúp con nuôi dưỡng một tâm trí bình an. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":13,"loi_kinh_thanh":"Tôi làm được mọi sự nhờ Đấng ban thêm sức cho tôi.","bai_hoc":"Phao-lô viết: Tôi làm được mọi sự nhờ Đấng ban thêm sức cho tôi. Lời này nằm trong bối cảnh Phao-lô nói về việc học biết bằng lòng trong mọi hoàn cảnh, dù đủ hay thiếu. Điều ông có thể làm nhờ Chúa là sống vững vàng trong cả hai. Câu này không phải lời hứa rằng ta sẽ thành công trong mọi mục tiêu, mà là sức mạnh để kiên nhẫn, bằng lòng và giữ lòng trung tín trong mọi hoàn cảnh. Hôm nay, hãy xin Chúa ban sức để bạn đối diện với điều khó, giữ lòng bình an và biết ơn trong hoàn cảnh bạn đang có.","loi_cau_nguyen":"Chúa ơi, xin ban cho con sức mạnh để vững vàng trong mọi hoàn cảnh, dù thiếu hay đủ. Xin giúp con học biết bằng lòng, và nhận sức từ Ngài để làm điều Ngài kêu gọi con làm. A-men."},{"sach":"Phi-líp","ma":"PHP","chuong":4,"cau":19,"loi_kinh_thanh":"Đức Chúa Trời tôi sẽ làm cho đầy đủ mọi sự cần dùng của anh em y theo sự giàu có của Ngài ở nơi vinh hiển trong Đức Chúa Jêsus Christ.","bai_hoc":"Phao-lô viết: \\"Đức Chúa Trời tôi sẽ làm cho đầy đủ mọi sự cần dùng của anh em y theo sự giàu có của Ngài ở nơi vinh hiển trong Đức Chúa Jêsus Christ\\" Ông viết cho Hội Thánh đã giúp đỡ ông, và nói rằng Chúa sẽ chăm lo cho họ. Chú ý chữ cần dùng: Chúa lo cho nhu cầu của ta, không nhất thiết mọi mong muốn. Ngài biết điều ta thật sự cần. Hôm nay, nếu bạn đang lo lắng về một nhu cầu, hãy trình với Ngài một cách cụ thể và tin rằng Ngài sẽ lo liệu, theo sự giàu có và sự khôn ngoan của Ngài.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa châu cấp mọi điều con cần theo sự giàu có của Ngài. Xin giúp con tin cậy Ngài lo liệu, phân biệt nhu cầu thật sự, và biết ơn những gì Ngài đã ban. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":3,"cau":2,"loi_kinh_thanh":"Hãy ham mến các sự ở trên trời, đừng ham mến các sự ở dưới đất;","bai_hoc":"Phao-lô viết: \\"Hãy ham mến các sự ở trên trời, đừng ham mến các sự ở dưới đất\\" Ông không bảo ta thờ ơ với đời sống thực tại, mà mời ta hướng tầm nhìn lên cao hơn. Khi ta chỉ tập trung vào những điều trần thế, ta dễ lo âu và nản lòng. Khi ta nhớ đến điều đời đời, lòng ta được nới rộng. Hôm nay, hãy dành vài phút đầu ngày để hướng lòng lên Chúa, trước khi cuốn vào lịch làm việc, và nhớ rằng bạn đang sống trong một câu chuyện lớn hơn những việc hằng ngày.","loi_cau_nguyen":"Chúa ơi, xin giúp con hướng lòng về những điều ở trên cao, không chỉ bị cuốn vào những điều trần thế. Xin cho con tầm nhìn đời đời, để con bớt lo âu và sống có ý nghĩa hơn. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":3,"cau":14,"loi_kinh_thanh":"Nhưng trên hết mọi sự đó, phải mặc lấy lòng yêu thương, vì là dây liên lạc của sự trọn lành.","bai_hoc":"Phao-lô viết: \\"Nhưng trên hết mọi sự đó, phải mặc lấy lòng yêu thương, vì là dây liên lạc của sự trọn lành\\" Sau khi liệt kê những đức tính như nhân từ, khiêm nhường, nhịn nhục, ông nói tình yêu thương là sợi dây buộc tất cả lại với nhau. Không có tình yêu, những đức tính khác dễ trở thành hình thức. Hôm nay, hãy mặc lấy tình yêu như mặc một chiếc áo ngoài cùng: trước khi bước ra ngoài, hãy nhắc mình sẽ đối xử với mọi người bằng tình yêu thương, đặc biệt với người khó yêu.","loi_cau_nguyen":"Chúa ơi, xin giúp con mặc lấy tình yêu thương trên hết mọi điều, như dây liên lạc của sự trọn lành. Xin cho tình yêu của Ngài kết nối những phẩm chất khác trong con, và chảy qua con đến người khác. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":3,"cau":15,"loi_kinh_thanh":"Nguyền xin sự bình an của Đấng Christ cai trị trong lòng anh em, là bình an mà anh em đã được gọi đến đặng hiệp nên một thể; lại phải biết ơn.","bai_hoc":"Phao-lô viết: \\"Nguyền xin sự bình an của Đấng Christ cai trị trong lòng anh em, là bình an mà anh em đã được gọi đến đặng hiệp nên một thể; lại phải biết ơn\\" Chữ cai trị gợi lên hình ảnh một trọng tài trong lòng ta, quyết định khi có điều gì cần phân xử. Khi ta đứng trước một lựa chọn, sự bình an của Chúa có thể là dấu chỉ. Và bình an này cũng hiệp nhất chúng ta trong cộng đoàn. Hôm nay, hãy để ý sự bình an hoặc bất an trong lòng khi bạn quyết định điều gì, và cầu xin Chúa dùng sự bình an Ngài để dẫn dắt bạn.","loi_cau_nguyen":"Chúa ơi, xin để sự bình an của Chúa Giê-su cai trị trong lòng con. Xin dùng bình an ấy làm kim chỉ nam cho các quyết định của con, và gắn kết chúng con trong sự hiệp một. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":3,"cau":17,"loi_kinh_thanh":"Mặc dầu anh em nói hãy làm, cũng phải nhân danh Đức Chúa Jêsus mà làm mọi điều, nhờ Ngài mà tạ ơn Đức Chúa Trời, là Đức Chúa Cha.","bai_hoc":"Phao-lô viết: \\"Mặc dầu anh em nói hãy làm, cũng phải nhân danh Đức Chúa Jêsus mà làm mọi điều, nhờ Ngài mà tạ ơn Đức Chúa Trời, là Đức Chúa Cha\\" Mọi việc, từ lời nói đến hành động, đều có thể làm trong danh Chúa Giê-su. Điều đó nghĩa là ta làm với ý thức rằng mình đại diện cho Ngài, và với lòng tạ ơn. Việc ở nhà, ở công sở, trên mạng xã hội, trong cuộc trò chuyện, đều là cơ hội. Hôm nay, trước khi nói hoặc làm một điều gì quan trọng, hãy dừng lại hỏi: tôi có thể làm điều này nhân danh Chúa Giê-su không?","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con làm mọi việc trong lời nói và hành động nhân danh Ngài, với lòng tạ ơn Cha. Xin cho con ý thức rằng con đại diện cho Ngài trong từng việc, dù nhỏ hay lớn. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":3,"cau":23,"loi_kinh_thanh":"Hễ làm việc gì, hãy hết lòng mà làm, như làm cho Chúa, chớ không phải làm cho người ta,","bai_hoc":"Phao-lô viết: Hễ làm việc gì, hãy hết lòng mà làm, như làm cho Chúa, chớ không phải làm cho người ta. Lời này nói với những người tôi tớ thời ấy, nhưng áp dụng cho mọi công việc. Khi ta làm cho Chúa, công việc có ý nghĩa mới. Dù không ai khen, dù không ai thấy, Ngài thấy. Dù cấp trên khắt khe, ta vẫn có lý do để làm tốt. Hôm nay, hãy chọn một việc bạn thường làm cho xong, và thử làm với tất cả tấm lòng, như dâng cho Chúa, rồi để ý cảm giác bình an trong đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm mọi việc hết lòng, như làm cho Ngài, không chỉ để làm vừa lòng người. Xin cho con tìm thấy ý nghĩa và niềm vui trong công việc, dù không ai ghi nhận. A-men."},{"sach":"Cô-lô-se","ma":"COL","chuong":4,"cau":6,"loi_kinh_thanh":"Lời nói anh em phải có ân hậu theo luôn, và nêm thêm muối, hầu cho anh em biết nên đối đáp mỗi người là thể nào.","bai_hoc":"Phao-lô viết: \\"Lời nói anh em phải có ân hậu theo luôn, và nêm thêm muối, hầu cho anh em biết nên đối đáp mỗi người là thể nào\\" Lời nói có ơn là lời dịu dàng, thông cảm. Muối là sự đậm đà, ý nghĩa, có chất lượng. Một lời nói vừa tử tế vừa khôn ngoan có thể mở cánh cửa trò chuyện và chạm đến lòng người. Hôm nay, trước khi nói với một người, đặc biệt người đang căng thẳng hay khó tính, hãy hít một hơi và chọn lời có ơn, dịu dàng và chân thành. Bạn sẽ thấy sức mạnh của sự tử tế.","loi_cau_nguyen":"Chúa ơi, xin cho lời nói của con luôn có ơn và nêm muối. Xin giúp con biết nên đáp lại mỗi người thế nào, với sự dịu dàng, khôn ngoan và chân thành, và làm cho lời con xây dựng người nghe. A-men."},{"sach":"I Tê-sa-lô-ni-ca","ma":"1TH","chuong":4,"cau":16,"loi_kinh_thanh":"Vì sẽ có tiếng kêu lớn và tiếng của thiên sứ lớn cùng tiếng kèn của Đức Chúa Trời, thì chính mình Chúa ở trên trời giáng xuống; bấy giờ những kẻ chết trong Đấng Christ, sẽ sống lại trước hết.","bai_hoc":"Phao-lô viết cho những người đang buồn vì người thân đã qua đời: \\"Vì sẽ có tiếng kêu lớn và tiếng của thiên sứ lớn cùng tiếng kèn của Đức Chúa Trời, thì chính mình Chúa ở trên trời giáng xuống; bấy giờ những kẻ chết trong Đấng Christ, sẽ sống lại trước hết\\" Đây là lời hy vọng cho những ai mất người thân. Sự chia ly không phải điều cuối cùng. Chúa hứa một ngày gặp lại. Hôm nay, nếu bạn đang nhớ một người đã khuất, hãy để lời này an ủi bạn, và biết ơn về niềm hy vọng Chúa ban.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài ban hy vọng về sự sống lại và ngày gặp lại. Xin an ủi những ai đang nhớ thương người đã khuất, và giữ lòng con vững vàng trong niềm hy vọng chắc chắn nơi Ngài. A-men."},{"sach":"I Tê-sa-lô-ni-ca","ma":"1TH","chuong":5,"cau":16,"loi_kinh_thanh":"Hãy vui mừng mãi mãi,","bai_hoc":"Phao-lô viết ngắn gọn: Hãy vui mừng mãi mãi. Chỉ ba chữ trong bản tiếng Việt, nhưng chứa một lời mời lớn. Ông không bảo ta luôn cảm thấy vui, mà bảo ta chọn vui mừng, vì lý do vui mừng của người tin không phụ thuộc hoàn cảnh: Chúa yêu ta, cứu ta và ở cùng ta. Hôm nay, hãy tìm một điều để vui, dù nhỏ, và nói với Chúa. Nếu thật sự khó vui, hãy cho phép mình trung thực với Ngài, và hỏi: Chúa ơi, điều gì trong Ngài làm con vui hôm nay? Ngài sẽ giúp bạn thấy một điều, dù rất nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con chọn vui mừng trong Ngài mỗi ngày. Khi con khó thấy lý do để vui, xin nhắc con những điều Ngài đã làm và đang làm, và cho con niềm vui sâu hơn hoàn cảnh. A-men."},{"sach":"I Tê-sa-lô-ni-ca","ma":"1TH","chuong":5,"cau":17,"loi_kinh_thanh":"cầu nguyện không thôi,","bai_hoc":"Phao-lô viết: \\"cầu nguyện không thôi\\" Điều này không có nghĩa là quỳ gối cả ngày, mà là sống trong mối liên lạc liên tục với Chúa, nói chuyện với Ngài trong những việc thường ngày: khi bước đi, khi chờ đợi, khi làm việc. Một lời thì thầm ngắn trong ngày cũng là cầu nguyện. Chúa vui khi ta nhớ đến Ngài. Hôm nay, hãy thử đặt một vài nhắc nhở nhỏ trong ngày để nói chuyện với Chúa: khi mở cửa, khi pha trà, khi chờ đèn đỏ. Một câu ngắn cũng đủ. Chúa luôn ở gần và vui khi nghe bạn gọi Ngài, dù chỉ bằng một lời thì thầm.","loi_cau_nguyen":"Chúa ơi, xin giúp con cầu nguyện không thôi, sống trong sự liên lạc thân mật với Ngài suốt ngày. Xin nhắc con nói chuyện với Ngài trong những việc nhỏ, và biến thói quen ấy thành nếp sống. A-men."},{"sach":"I Tê-sa-lô-ni-ca","ma":"1TH","chuong":5,"cau":18,"loi_kinh_thanh":"phàm làm việc gì cũng phải tạ ơn Chúa; vì ý muốn của Đức Chúa Trời trong Đức Chúa Jêsus Christ đối với anh em là như vậy.","bai_hoc":"Phao-lô viết: \\"phàm làm việc gì cũng phải tạ ơn Chúa; vì ý muốn của Đức Chúa Trời trong Đức Chúa Jêsus Christ đối với anh em là như vậy\\" Cảm tạ trong mọi sự, không phải cảm tạ vì mọi sự. Có những điều ta không thể cảm tạ, nhưng trong chính những lúc ấy, vẫn có điều để biết ơn: sự hiện diện của Chúa, người đồng hành, một chút bình an. Lòng biết ơn thay đổi cách ta nhìn cuộc sống. Hôm nay, hãy viết hoặc nghĩ ra ba điều biết ơn, dù ngày hôm nay khó khăn thế nào.","loi_cau_nguyen":"Chúa ơi, xin giúp con biết tạ ơn trong mọi hoàn cảnh. Xin cho con tìm thấy điều để biết ơn ngay cả trong những ngày khó, và để lòng biết ơn thay đổi cách con nhìn cuộc sống. A-men."},{"sach":"I Tê-sa-lô-ni-ca","ma":"1TH","chuong":5,"cau":21,"loi_kinh_thanh":"hãy xem xét mọi việc, điều chi lành thì giữ lấy.","bai_hoc":"Phao-lô viết: \\"hãy xem xét mọi việc, điều chi lành thì giữ lấy\\" Ông khuyến khích ta đừng nhắm mắt tin tất cả những gì nghe thấy, nhưng cũng đừng khước từ mọi thứ. Hãy cẩn thận xem xét, so với Lời Chúa, rồi giữ điều tốt. Đây là sự khôn ngoan trong thời đại có quá nhiều thông tin và quan điểm. Hôm nay, khi bạn nghe hoặc đọc điều gì ảnh hưởng đến lòng bạn, một bài giảng, một bài viết, một lời khuyên, hãy hỏi: điều này có phù hợp với Lời Chúa không? Giữ điều lành và buông điều không đúng.","loi_cau_nguyen":"Chúa ơi, xin cho con sự khôn ngoan để thử mọi sự và giữ lấy điều lành. Xin giúp con đối chiếu những điều con nghe và đọc với Lời Ngài, và không bị cuốn theo mọi tiếng nói. A-men."},{"sach":"II Tê-sa-lô-ni-ca","ma":"2TH","chuong":3,"cau":3,"loi_kinh_thanh":"Chúa là thành tín, sẽ làm cho anh em bền vững và giữ cho khỏi Ác giả.","bai_hoc":"Phao-lô viết: \\"Chúa là thành tín, sẽ làm cho anh em bền vững và giữ cho khỏi Ác giả\\" Giữa những thử thách, ông nhắc rằng điều ta có thể dựa vào là sự thành tín của Chúa. Không phải sức mạnh ta, mà sự thành tín của Ngài. Khi ta yếu đuối hay bị tấn công, Ngài giữ ta. Hôm nay, nếu bạn thấy mình đang dễ lung lay, hãy nhắc mình: Chúa là thành tín. Rồi cầu xin Ngài làm cho bạn vững vàng và gìn giữ bạn khỏi những điều làm tổn hại. Ngài không bao giờ để bạn chiến đấu một mình.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng thành tín. Xin làm con vững vàng và giữ gìn con khỏi điều ác. Khi con thấy mình yếu đuối, xin giúp con nương cậy vào sự thành tín của Ngài hơn sức riêng con. A-men."},{"sach":"II Tê-sa-lô-ni-ca","ma":"2TH","chuong":3,"cau":13,"loi_kinh_thanh":"Hỡi anh em, phần anh em chớ nên chán mệt làm sự lành.","bai_hoc":"Phao-lô viết: \\"Hỡi anh em, phần anh em chớ nên chán mệt làm sự lành\\" Câu này ngắn, nhưng được lặp lại trong nhiều bức thư của ông, vì ông biết làm điều lành lâu dài rất dễ mệt. Khi bạn chăm sóc người khác, dạy dỗ, phục vụ, mà không thấy kết quả, cám dỗ lớn nhất là bỏ cuộc. Chúa thấy sự kiên trì của bạn và không quên. Hôm nay, hãy làm một việc lành nữa, dù bạn thấy mệt, và xin Chúa ban sức cho bạn tiếp tục. Bạn đang làm điều có giá trị trong mắt Ngài, và đừng để sự mệt mỏi thuyết phục bạn rằng nó vô nghĩa.","loi_cau_nguyen":"Chúa ơi, khi con thấy mệt mỏi vì làm điều lành, xin ban cho con sức mới. Xin giúp con không bỏ cuộc, và nhớ rằng Ngài thấy sự kiên trì của con, dù không ai khác thấy. A-men."},{"sach":"I Ti-mô-thê","ma":"1TI","chuong":1,"cau":15,"loi_kinh_thanh":"Đức Chúa Jêsus Christ đã đến trong thế gian để cứu vớt kẻ có tội, ấy là lời chắc chắn, đáng đem lòng tin trọn vẹn mà nhận lấy; trong những kẻ có tội đó ta là đầu.","bai_hoc":"Phao-lô viết: \\"Đức Chúa Jêsus Christ đã đến trong thế gian để cứu vớt kẻ có tội, ấy là lời chắc chắn, đáng đem lòng tin trọn vẹn mà nhận lấy; trong những kẻ có tội đó ta là đầu\\" Một người từng bắt bớ Hội Thánh nói mình là tội nhân đứng đầu, và ông không nói điều đó để tự hạ thấp mà để nhấn mạnh sự lớn lao của ân điển. Nếu Chúa cứu ông, Ngài cũng cứu được mọi người. Hôm nay, nếu bạn thấy mình không xứng đáng, hãy nhớ rằng Chúa Giê-su đến chính là vì những người như bạn, và nhận lấy ân điển Ngài ban.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã đến thế gian để cứu tội nhân. Con nhận biết mình cần ơn Ngài, xin giúp con nhận lấy ân điển ấy, và không để cảm giác mình không xứng đáng ngăn con đến với Ngài. A-men."},{"sach":"I Ti-mô-thê","ma":"1TI","chuong":2,"cau":5,"loi_kinh_thanh":"Vì chỉ có một Đức Chúa Trời, và chỉ có một Đấng Trung bảo ở giữa Đức Chúa Trời và loài người, tức là Đức Chúa Jêsus Christ, là người;","bai_hoc":"Phao-lô viết: \\"Vì chỉ có một Đức Chúa Trời, và chỉ có một Đấng Trung bảo ở giữa Đức Chúa Trời và loài người, tức là Đức Chúa Jêsus Christ, là người\\" Đấng trung bảo là người đứng giữa để nối hai bên. Chúa Giê-su vừa là Đức Chúa Trời vừa là người, nên Ngài hiểu cả hai phía. Điều này có nghĩa là bạn không cần ai khác để đến với Chúa Cha, và bạn có thể đến một cách trực tiếp. Hôm nay, hãy cầu nguyện một cách tự tin, không chỉ qua một người nào, nhưng qua Chúa Giê-su, Đấng đã mở đường.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài là Đấng trung bảo giữa Đức Chúa Trời và loài người. Xin giúp con đến với Cha một cách tự tin qua Ngài, và biết rằng Ngài hiểu cả hai phía, cả Chúa và con. A-men."},{"sach":"I Ti-mô-thê","ma":"1TI","chuong":4,"cau":12,"loi_kinh_thanh":"Chớ để người ta khinh con vì trẻ tuổi; nhưng phải lấy lời nói, nết làm, sự yêu thương, đức tin và sự tinh sạch mà làm gương cho các tín đồ.","bai_hoc":"Phao-lô viết cho Ti-mô-thê, một người trẻ: \\"Chớ để người ta khinh con vì trẻ tuổi; nhưng phải lấy lời nói, nết làm, sự yêu thương, đức tin và sự tinh sạch mà làm gương cho các tín đồ\\" Ông không bảo Ti-mô-thê phải đòi hỏi sự tôn trọng, mà hãy sống gương mẫu để sự tôn trọng đến tự nhiên. Điều này có thể khích lệ bất kỳ ai cảm thấy mình quá trẻ hay thiếu kinh nghiệm. Hôm nay, hãy làm gương trong một việc cụ thể: lời nói, việc làm hay tình yêu thương, và để cuộc sống bạn nói lên điều đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con làm gương trong lời nói, việc làm, tình yêu, đức tin và sự tinh sạch, dù con trẻ hay ít kinh nghiệm. Xin cho con can đảm và khiêm nhường để dẫn dắt người khác bằng đời sống của con. A-men."},{"sach":"I Ti-mô-thê","ma":"1TI","chuong":6,"cau":10,"loi_kinh_thanh":"Bởi chưng sự tham tiền bạc là cội rễ mọi điều ác, có kẻ vì đeo đuổi nó mà bội đạo, chuốc lấy nhiều điều đau đớn.","bai_hoc":"Phao-lô viết: \\"Bởi chưng sự tham tiền bạc là cội rễ mọi điều ác, có kẻ vì đeo đuổi nó mà bội đạo, chuốc lấy nhiều điều đau đớn\\" Chú ý ông nói sự tham tiền, không phải tiền bạc. Tiền là phương tiện, nhưng lòng yêu tiền có thể dẫn ta xa Chúa và gây nhiều đau đớn. Câu này mời ta kiểm tra lòng mình. Hôm nay, hãy hỏi: tôi đang yêu tiền hay đang dùng tiền để yêu người? Hãy xin Chúa cho bạn lòng biết đủ và sự tự do, và hãy làm điều hào phóng, dù nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giữ lòng con khỏi sự tham tiền bạc. Xin cho con lòng biết đủ, và giúp con dùng của cải để yêu thương và phục vụ, không để nó chi phối lòng con hay làm con xa Ngài. A-men."},{"sach":"I Ti-mô-thê","ma":"1TI","chuong":6,"cau":12,"loi_kinh_thanh":"Hãy vì đức tin mà đánh trận tốt lành, bắt lấy sự sống đời đời, là sự mà con đã được gọi đến, và vì đó mà con đã làm chứng tốt lành trước mặt nhiều người chứng kiến.","bai_hoc":"Phao-lô viết: \\"Hãy vì đức tin mà đánh trận tốt lành, bắt lấy sự sống đời đời, là sự mà con đã được gọi đến, và vì đó mà con đã làm chứng tốt lành trước mặt nhiều người chứng kiến\\" Đức tin không chỉ là niềm tin thụ động, mà là cuộc chiến cần sự kiên trì. Ông gọi đó là trận chiến tốt lành vì mục đích tốt đẹp. Có những ngày ta thấy mệt mỏi trong cuộc chiến ấy, và Chúa hiểu. Hãy nắm lấy sự sống đời đời, điều bạn đã được gọi. Hôm nay, hãy làm một việc nhỏ để củng cố đức tin: đọc Lời Chúa, cầu nguyện, hoặc chia sẻ với một người bạn đồng hành.","loi_cau_nguyen":"Chúa ơi, xin giúp con đánh trận tốt lành của đức tin và nắm lấy sự sống đời đời Ngài đã gọi con. Khi con mệt mỏi, xin ban sức mới, và cho con những người bạn đồng hành trên con đường ấy. A-men."},{"sach":"II Ti-mô-thê","ma":"2TI","chuong":1,"cau":7,"loi_kinh_thanh":"Vì Đức Chúa Trời chẳng ban cho chúng ta tâm thần nhút nhát, bèn là tâm thần mạnh mẽ, có tình thương yêu và dè giữ.","bai_hoc":"Phao-lô viết: \\"Vì Đức Chúa Trời chẳng ban cho chúng ta tâm thần nhút nhát, bèn là tâm thần mạnh mẽ, có tình thương yêu và dè giữ\\" Ông viết cho Ti-mô-thê có lẽ đang sợ hãi và ngần ngại. Chúa không ban sự nhút nhát, nhưng ban sức mạnh, tình yêu và sự tự chủ. Điều đó có nghĩa là nỗi sợ không đến từ Ngài, và ta có thể xin Ngài thay thế nó. Hôm nay, nếu bạn thấy mình sợ hãi trước một việc, hãy xin Chúa ban sức mạnh, tình yêu và sự tự chủ cho việc ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài không ban cho con tâm thần nhút nhát, nhưng mạnh mẽ, yêu thương và tự chủ. Xin giúp con đối diện với nỗi sợ bằng những điều Ngài đã ban, và hành động với lòng can đảm. A-men."},{"sach":"II Ti-mô-thê","ma":"2TI","chuong":2,"cau":15,"loi_kinh_thanh":"Hãy chuyên tâm cho được đẹp lòng Đức Chúa Trời như người làm công không chỗ trách được, lấy lòng ngay thẳng giảng dạy lời của lẽ thật.","bai_hoc":"Phao-lô viết: \\"Hãy chuyên tâm cho được đẹp lòng Đức Chúa Trời như người làm công không chỗ trách được, lấy lòng ngay thẳng giảng dạy lời của lẽ thật\\" Ông khuyến khích Ti-mô-thê học Lời Chúa nghiêm túc và cẩn thận. Không phải để kiêu ngạo về kiến thức, mà để dạy đúng. Chúng ta cũng được mời học Kinh Thánh với sự chăm chỉ và khiêm nhường. Hôm nay, hãy đọc một đoạn Kinh Thánh chậm rãi, hỏi ba câu: Điều này nói gì? Điều này có ý nghĩa gì? Tôi cần làm gì? Học Kinh Thánh là một hành trình lâu dài, và Chúa kiên nhẫn đồng hành.","loi_cau_nguyen":"Chúa ơi, xin giúp con chuyên tâm học Lời Ngài với sự cẩn thận và khiêm nhường. Xin dạy con hiểu đúng lời của lẽ thật, và sống theo những gì con học được. A-men."},{"sach":"II Ti-mô-thê","ma":"2TI","chuong":3,"cau":16,"loi_kinh_thanh":"Cả Kinh Thánh đều là bởi Đức Chúa Trời soi dẫn, có ích cho sự dạy dỗ, bẻ trách, sửa trị, dạy người trong sự công bình,","bai_hoc":"Phao-lô viết: Cả Kinh Thánh đều là bởi Đức Chúa Trời soi dẫn, có ích cho sự dạy dỗ, bẻ trách, sửa trị, dạy người trong sự công bình. Kinh Thánh không chỉ là sách để đọc, mà là Lời của Chúa với ta. Nó dạy điều đúng, chỉ ra điều sai, sửa lại và rèn luyện. Mỗi chức năng đều là một món quà, kể cả khi nó khiến ta khó chịu. Hôm nay, hãy đọc Kinh Thánh với lòng sẵn sàng được dạy dỗ, và hỏi Chúa: điều gì Ngài muốn nói với tôi qua đoạn này hôm nay?","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã ban cho con Kinh Thánh, Lời được Ngài soi dẫn. Xin giúp con đọc với lòng sẵn sàng được dạy dỗ và sửa trị, và để Lời Ngài rèn luyện con trong sự công bình. A-men."},{"sach":"II Ti-mô-thê","ma":"2TI","chuong":4,"cau":7,"loi_kinh_thanh":"Ta đã đánh trận tốt lành, đã xong sự chạy, đã giữ được đức tin.","bai_hoc":"Phao-lô viết gần cuối đời: Ta đã đánh trận tốt lành, đã xong sự chạy, đã giữ được đức tin. Đây là lời nhìn lại của một người đã sống trọn vẹn cho Chúa, dù trải qua nhiều khó khăn. Ông không nói mình hoàn hảo, mà đã trung tín cho đến cuối. Điều đó là mục tiêu cho đời sống của chúng ta: không phải không vấp ngã, mà là giữ đức tin đến cùng. Hôm nay, hãy nghĩ đến cách bạn muốn nhìn lại đời mình, và chọn một hành động nhỏ hôm nay để hướng tới điều đó.","loi_cau_nguyen":"Chúa ơi, xin giúp con đánh trận tốt lành, hoàn thành cuộc chạy, và giữ được đức tin cho đến cuối. Xin ban cho con sức mạnh để trung tín mỗi ngày, và nâng đỡ con khi con vấp ngã. A-men."},{"sach":"II Ti-mô-thê","ma":"2TI","chuong":4,"cau":8,"loi_kinh_thanh":"Hiện nay mão triều thiên của sự công bình đã để dành cho ta; Chúa là quan án công bình, sẽ ban mão ấy cho ta trong ngày đó, không những cho ta mà thôi, nhưng cũng cho mọi kẻ yêu mến sự hiện đến của Ngài.","bai_hoc":"Phao-lô tiếp tục: \\"Hiện nay mão triều thiên của sự công bình đã để dành cho ta; Chúa là quan án công bình, sẽ ban mão ấy cho ta trong ngày đó, không những cho ta mà thôi, nhưng cũng cho mọi kẻ yêu mến sự hiện đến của Ngài\\" Ông không chỉ nói về mình mà cho tất cả những ai yêu mến Chúa. Điều đó cho thấy phần thưởng của Chúa dành cho mọi người trung tín, không giới hạn. Hôm nay, hãy nghĩ đến sự hiện đến của Ngài với lòng yêu mến và hy vọng, và để điều ấy khích lệ bạn tiếp tục.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã dành sẵn mão triều thiên của sự công bình cho những người yêu mến sự hiện đến của Ngài. Xin giúp con sống với hy vọng ấy, và yêu mến Ngài mỗi ngày. A-men."},{"sach":"Tít","ma":"TIT","chuong":3,"cau":5,"loi_kinh_thanh":"không phải cứu vì việc công bình chúng ta đã làm, nhưng cứ theo lòng thương xót Ngài, bởi sự rửa về sự lại sanh và sự đổi mới của Đức Thánh Linh","bai_hoc":"Phao-lô viết: \\"không phải cứu vì việc công bình chúng ta đã làm, nhưng cứ theo lòng thương xót Ngài, bởi sự rửa về sự lại sanh và sự đổi mới của Đức Thánh Linh\\" Lần nữa Kinh Thánh nhấn mạnh: ơn cứu đến từ lòng thương xót của Chúa, không từ việc làm của ta. Và Thánh Linh làm mới ta từ bên trong. Điều này làm lòng ta biết ơn và khiêm nhường. Hôm nay, hãy dành một khoảnh khắc nhớ lại điều Chúa đã làm trong bạn, và cảm ơn Ngài vì lòng thương xót, điều bạn không thể tự giành lấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã cứu con không bởi việc làm của con, nhưng bởi lòng thương xót của Ngài. Xin tiếp tục làm mới con bởi Thánh Linh, và giúp con sống với lòng biết ơn sâu sắc. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":4,"cau":12,"loi_kinh_thanh":"Vì lời của Đức Chúa Trời là lời sống và linh nghiệm, sắc hơn gươm hai lưỡi, thấu vào đến đỗi chia hồn, linh, cốt, tủy, xem xét tư tưởng và ý định trong lòng.","bai_hoc":"Tác giả viết: \\"Vì lời của Đức Chúa Trời là lời sống và linh nghiệm, sắc hơn gươm hai lưỡi, thấu vào đến đỗi chia hồn, linh, cốt, tủy, xem xét tư tưởng và ý định trong lòng\\" Lời Chúa không chỉ là chữ trên trang giấy, nó sống và làm việc. Nó có thể soi thấu những điều ta chưa nhận ra về chính mình. Điều đó đôi khi khiến ta khó chịu, nhưng là để chữa lành. Hôm nay, hãy đọc Kinh Thánh với tâm thế để Lời ấy đọc bạn: để Chúa nói với bạn qua từng câu, và cho phép Ngài chạm vào lòng.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì Lời Ngài sống và linh nghiệm. Xin để Lời Ngài soi thấu lòng con, chỉ ra điều cần được chữa lành, và giúp con đọc Kinh Thánh với tấm lòng mở và sẵn sàng thay đổi. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":4,"cau":16,"loi_kinh_thanh":"Vậy, chúng ta hãy vững lòng đến gần ngôi ơn phước, hầu cho được thương xót và tìm được ơn để giúp chúng ta trong thì giờ có cần dùng.","bai_hoc":"Tác giả mời gọi: \\"Vậy, chúng ta hãy vững lòng đến gần ngôi ơn phước, hầu cho được thương xót và tìm được ơn để giúp chúng ta trong thì giờ có cần dùng\\" Ông nói về Chúa Giê-su là Thầy Tế Lễ Thượng Phẩm thấu hiểu sự yếu đuối của ta. Vì vậy, ta không phải sợ hãi khi đến với Chúa. Ngôi của Ngài là ngôi ơn phước, không phải ngôi phán xét đối với người đến với lòng tin. Hôm nay, hãy đến gần Ngài một cách mạnh dạn với điều bạn đang cần: sự thương xót hoặc ơn giúp đỡ. Ngài đã sẵn sàng đón nhận.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài mời con đến gần ngôi ơn phước một cách vững lòng. Xin ban cho con sự thương xót và ơn giúp đỡ trong lúc con cần, và giúp con đến với Ngài mà không sợ hãi. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":9,"cau":27,"loi_kinh_thanh":"Theo như đã định cho loài người phải chết một lần, rồi chịu phán xét,","bai_hoc":"Tác giả viết: Theo như đã định cho loài người phải chết một lần, rồi chịu phán xét. Lời này nhắc rằng đời sống của ta có hạn, và mỗi ngày là một món quà. Điều này không nhằm làm ta sợ hãi mà để ta nghĩ nghiêm túc về cách sống. Với người tin Chúa Giê-su, sự phán xét không còn là nỗi sợ, vì Ngài đã gánh thay. Câu tiếp theo nói Ngài sẽ hiện ra lần thứ hai để cứu những ai chờ đợi Ngài. Hôm nay, hãy chọn một điều quan trọng thật sự mà bạn muốn dành thời gian cho, và làm điều ấy với lòng biết ơn.","loi_cau_nguyen":"Chúa ơi, xin giúp con sống mỗi ngày với ý thức rằng đời sống con có hạn, và đừng lãng phí điều quý giá. Cảm ơn Ngài đã gánh thay sự phán xét cho con trong Chúa Giê-su, và xin giữ con trong hy vọng. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":10,"cau":25,"loi_kinh_thanh":"chớ bỏ sự nhóm lại như mấy kẻ quen làm, nhưng phải khuyên bảo nhau, và hễ anh em thấy ngày ấy hầu gần chừng nào, thì càng phải làm như vậy chừng nấy.","bai_hoc":"Tác giả viết: \\"chớ bỏ sự nhóm lại như mấy kẻ quen làm, nhưng phải khuyên bảo nhau, và hễ anh em thấy ngày ấy hầu gần chừng nào, thì càng phải làm như vậy chừng nấy\\" Cộng đoàn đức tin là một món quà để khích lệ nhau. Có những lúc ta thấy mệt mỏi và muốn tránh xa, nhưng chính lúc ấy ta cần cộng đoàn nhất. Hôm nay, hãy nghĩ đến một người trong cộng đoàn mà bạn có thể khích lệ, và làm một việc nhỏ: một tin nhắn, một lời hỏi thăm, một lời mời cùng cầu nguyện.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài cho con một cộng đoàn đức tin. Xin giúp con không bỏ sự nhóm lại, và cho con biết khích lệ anh chị em, cũng như nhận được sự khích lệ từ họ khi con cần. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":11,"cau":1,"loi_kinh_thanh":"Vả, đức tin là sự biết chắc vững vàng của những điều mình đang trông mong là bằng cớ của những điều mình chẳng xem thấy.","bai_hoc":"Tác giả viết: \\"Vả, đức tin là sự biết chắc vững vàng của những điều mình đang trông mong là bằng cớ của những điều mình chẳng xem thấy\\" Đức tin không phải là đoán mò hay hy vọng mơ hồ, mà là sự chắc chắn dựa trên Đấng đáng tin cậy. Chương này sau đó kể về nhiều người đã sống bởi đức tin dù chưa thấy kết quả. Điều đó khích lệ ta: ta không phải là người duy nhất đi trên con đường này. Hôm nay, hãy nhớ lại một người đã sống đức tin và truyền cảm hứng cho bạn, và xin Chúa ban cho bạn một đức tin chắc chắn như vậy.","loi_cau_nguyen":"Chúa ơi, xin ban cho con đức tin là sự biết chắc những điều con trông mong và bằng cớ của những điều con chưa thấy. Xin giúp con tin cậy Ngài như những người đã đi trước con trên con đường đức tin. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":11,"cau":6,"loi_kinh_thanh":"Vả, không có đức tin, thì chẳng hề có thế nào ở cho đẹp ý Ngài; vì kẻ đến gần Đức Chúa Trời phải tin rằng có Đức Chúa Trời, và Ngài là Đấng hay thưởng cho kẻ tìm kiếm Ngài.","bai_hoc":"Tác giả viết: \\"Vả, không có đức tin, thì chẳng hề có thế nào ở cho đẹp ý Ngài; vì kẻ đến gần Đức Chúa Trời phải tin rằng có Đức Chúa Trời, và Ngài là Đấng hay thưởng cho kẻ tìm kiếm Ngài\\" Hai điều cần tin: Ngài có thật, và Ngài ban thưởng cho người tìm kiếm Ngài. Chúa không đòi hỏi bạn hiểu hết mọi điều, chỉ cần đến với Ngài bằng lòng tin. Mối quan hệ với Chúa bắt đầu bằng sự tin tưởng. Hôm nay, hãy tìm kiếm Ngài với lòng tin rằng Ngài thấy và đáp lại sự tìm kiếm của bạn, dù nhỏ.","loi_cau_nguyen":"Chúa ơi, con tin Ngài có thật và Ngài thưởng cho người tìm kiếm Ngài. Xin giúp con đến gần Ngài bằng đức tin, và củng cố lòng tin của con khi con còn nghi ngờ hoặc mệt mỏi. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":12,"cau":1,"loi_kinh_thanh":"Thế thì, vì chúng ta được nhiều người chứng kiến vây lấy như đám mây rất lớn, chúng ta cũng nên quăng hết gánh nặng và tội lỗi dễ vấn vương ta, lấy lòng nhịn nhục theo đòi cuộc chạy đua đã bày ra cho ta,","bai_hoc":"Tác giả viết: \\"Thế thì, vì chúng ta được nhiều người chứng kiến vây lấy như đám mây rất lớn, chúng ta cũng nên quăng hết gánh nặng và tội lỗi dễ vấn vương ta, lấy lòng nhịn nhục theo đòi cuộc chạy đua đã bày ra cho ta\\" Hình ảnh một cuộc chạy đường dài: cần bỏ những gánh nặng không cần thiết. Có những điều làm ta chạy chậm: thói quen, nỗi lo, sự so sánh. Hôm nay, hãy hỏi Chúa: điều gì tôi nên đặt xuống để chạy nhẹ nhàng hơn? Rồi hãy xin Ngài giúp bạn buông điều ấy, và tiếp tục chạy với lòng nhẫn nại.","loi_cau_nguyen":"Chúa ơi, xin giúp con cởi bỏ mọi gánh nặng và tội lỗi dễ vấn vương con. Xin cho con lòng nhịn nhục để chạy hết cuộc đua đã đặt ra cho con, và nhớ rằng có nhiều người đã chạy trước con. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":12,"cau":2,"loi_kinh_thanh":"nhìn xem Đức Chúa Jêsus, là cội rễ và cuối cùng của đức tin, tức là Đấng vì sự vui mừng đã đặt trước mặt mình, chịu lấy thập tự giá, khinh điều sỉ nhục, và hiện nay ngồi bên hữu ngai Đức Chúa Trời.","bai_hoc":"Tác giả tiếp tục: Nhìn xem Đức Chúa Jêsus là Đấng khởi đầu và làm trọn đức tin chúng ta, vì sự vui mừng đã đặt trước mặt Ngài, Ngài chịu lấy thập tự giá, khinh điều xấu hổ, và đã ngồi bên hữu ngôi của Đức Chúa Trời. Khi mệt trong cuộc chạy, ta nhìn lên mục tiêu: Chúa Giê-su. Ngài không chỉ khởi đầu mà còn hoàn tất đức tin của ta. Ngài đã đi qua cuộc đua trước ta. Hôm nay, khi bạn cảm thấy nản, hãy dừng lại và nhìn lên Ngài, nhớ điều Ngài đã chịu vì niềm vui dành cho bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con nhìn xem Ngài, Đấng khởi đầu và làm trọn đức tin con. Khi con mệt mỏi và nản lòng, xin cho con nhớ điều Ngài đã chịu vì con, và ban sức để con chạy tiếp. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":13,"cau":5,"loi_kinh_thanh":"Chớ tham tiền; hãy lấy điều mình có làm đủ rồi, vì chính Đức Chúa Trời có phán rằng: Ta sẽ chẳng lìa ngươi đâu, chẳng bỏ ngươi đâu.","bai_hoc":"Tác giả viết: \\"Chớ tham tiền; hãy lấy điều mình có làm đủ rồi, vì chính Đức Chúa Trời có phán rằng: Ta sẽ chẳng lìa ngươi đâu, chẳng bỏ ngươi đâu\\" Điều đáng chú ý là ông đặt lòng biết đủ cạnh lời hứa Chúa ở cùng. Sự thỏa lòng không đến từ có nhiều, mà từ biết Chúa không bao giờ rời bỏ ta. Khi ta có Ngài, ta có điều quan trọng nhất. Hôm nay, hãy nhìn quanh những điều bạn đang có và nói lời cảm ơn, rồi nhắc mình lời hứa này: Chúa không lìa bạn, không bỏ bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa không lìa và không bỏ con. Xin giúp con biết đủ với những gì con có, và tìm sự thỏa lòng trong sự hiện diện của Ngài hơn là trong tiền bạc hay của cải. A-men."},{"sach":"Hê-bơ-rơ","ma":"HEB","chuong":13,"cau":8,"loi_kinh_thanh":"Đức Chúa Jêsus Christ hôm qua, ngày nay, và cho đến đời đời không hề thay đổi.","bai_hoc":"Tác giả viết: \\"Đức Chúa Jêsus Christ hôm qua, ngày nay, và cho đến đời đời không hề thay đổi\\" Giữa một thế giới thay đổi nhanh, đây là điểm tựa vững chắc. Người mà Ngài là ngày hôm qua, Ngài vẫn là như vậy hôm nay: nhân từ, thương xót, đầy quyền năng. Những điều Ngài đã làm trong quá khứ, Ngài vẫn có thể làm hôm nay. Điều đó cho ta hy vọng khi mọi thứ xung quanh chao đảo. Hôm nay, hãy chọn một điều Chúa Giê-su đã làm trong Kinh Thánh, như chữa lành hay tha thứ, và tin rằng Ngài vẫn yêu thương như vậy.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài hôm qua, ngày nay và đời đời không hề thay đổi. Xin giúp con đặt lòng tin vào bản tính vững vàng của Ngài, nhất là khi mọi thứ quanh con thay đổi và bất định. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":1,"cau":2,"loi_kinh_thanh":"Hỡi anh em, hãy coi sự thử thách trăm bề thoạt đến cho anh em như là điều vui mừng trọn vẹn,","bai_hoc":"Gia-cơ viết: Hỡi anh em, hãy coi sự thử thách trăm bề thoạt đến cho anh em như là điều vui mừng trọn vẹn. Ông không bảo ta vui vì đau khổ, mà vui vì biết thử thách có thể sinh ra sự kiên nhẫn và trưởng thành. Điều này đòi hỏi một cách nhìn khác: không chỉ nhìn nỗi đau, mà nhìn điều Chúa có thể làm qua nó. Điều đó không dễ và Chúa hiểu. Hôm nay, nếu bạn đang đi qua thử thách, hãy xin Chúa giúp bạn nhìn thấy điều Ngài đang làm trong bạn, dù chỉ là một điều nhỏ.","loi_cau_nguyen":"Chúa ơi, xin giúp con nhìn thử thách bằng cách nhìn của Ngài. Xin cho con kiên nhẫn và trưởng thành qua những khó khăn, và ban cho con niềm vui sâu hơn hoàn cảnh trong khi con đi qua. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":1,"cau":5,"loi_kinh_thanh":"Ví bằng trong anh em có kẻ kém khôn ngoan, hãy cầu xin Đức Chúa Trời, là Đấng ban cho mọi người cách rộng rãi, không trách móc ai, thì kẻ ấy sẽ được ban cho.","bai_hoc":"Gia-cơ viết: \\"Ví bằng trong anh em có kẻ kém khôn ngoan, hãy cầu xin Đức Chúa Trời, là Đấng ban cho mọi người cách rộng rãi, không trách móc ai, thì kẻ ấy sẽ được ban cho\\" Chúa không chê bạn vì thiếu khôn ngoan, và không trách móc khi bạn hỏi. Ngài ban rộng rãi. Có khi ta ngại hỏi vì sợ bị xem là kém, nhưng Chúa mời ta hỏi. Hôm nay, hãy nói với Ngài một quyết định cần khôn ngoan, và xin: Chúa ơi, xin cho con khôn ngoan. Rồi lắng nghe qua Lời Ngài, qua lời khuyên của người khôn, qua sự bình an.","loi_cau_nguyen":"Chúa ơi, con thiếu khôn ngoan và con xin Ngài. Cảm ơn Ngài ban rộng rãi và không trách móc. Xin dẫn con trong quyết định này, và cho con tai nghe và lòng sẵn sàng để nhận sự dẫn dắt của Ngài. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":1,"cau":17,"loi_kinh_thanh":"mọi ân điển tốt lành cùng sự ban cho trọn vẹn đều đến từ nơi cao và bởi Cha sáng láng mà xuống, trong Ngài chẳng có một sự thay đổi, cũng chẳng có bóng của sự biến cải nào.","bai_hoc":"Gia-cơ viết: \\"mọi ân điển tốt lành cùng sự ban cho trọn vẹn đều đến từ nơi cao và bởi Cha sáng láng mà xuống, trong Ngài chẳng có một sự thay đổi, cũng chẳng có bóng của sự biến cải nào\\" Điều tốt đẹp bạn có đều là ơn Chúa ban, và Ngài không đổi thay như ánh sáng của mặt trời thay đổi bóng. Điều đó làm ta biết ơn hơn và an tâm hơn: Ngài luôn tốt lành. Hôm nay, hãy nhìn quanh và nhận ra một món quà Chúa đã ban, một người, một khoảnh khắc, một bữa ăn, và cảm ơn Ngài từ lòng chân thành.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Cha của các sự sáng và là nguồn của mọi ơn lành. Xin giúp con nhận ra những món quà Ngài ban mỗi ngày, và sống với lòng biết ơn vì Ngài không đổi thay. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":1,"cau":19,"loi_kinh_thanh":"Hỡi anh em yêu dấu, anh em biết điều đó: người nào cũng phải mau nghe mà chậm nói, chậm giận;","bai_hoc":"Gia-cơ viết: \\"Hỡi anh em yêu dấu, anh em biết điều đó: người nào cũng phải mau nghe mà chậm nói, chậm giận\\" Ba điều đơn giản mà thay đổi nhiều mối quan hệ. Mau nghe: thật sự chú ý đến người khác. Chậm nói: suy nghĩ trước khi đáp. Chậm giận: cho mình thời gian trước khi phản ứng. Trong thời đại ai cũng muốn nói, việc lắng nghe là một món quà. Hôm nay, hãy thực hành mau nghe với một người cụ thể: để họ nói xong, đừng cắt ngang, và hỏi thêm một câu quan tâm. Sự chú ý trọn vẹn là một cách yêu thương rất thật, và người đối diện sẽ cảm nhận được điều ấy. Khi bạn lắng nghe, bạn đang trao cho họ giá trị và sự tôn trọng.","loi_cau_nguyen":"Chúa ơi, xin giúp con mau nghe, chậm nói và chậm giận. Xin cho con kiên nhẫn lắng nghe người khác thật sự, và không vội phản ứng, để con trở thành người mang lại bình an trong các cuộc trò chuyện. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":1,"cau":22,"loi_kinh_thanh":"Hãy làm theo lời, chớ lấy nghe làm đủ mà lừa dối mình.","bai_hoc":"Gia-cơ viết: Hãy làm theo lời, chớ lấy nghe làm đủ mà lừa dối mình. Có khi ta nghe nhiều Lời Chúa, bài giảng, đọc nhiều sách mà đời sống không thay đổi, và điều đó là tự dối mình. Chúa muốn ta thực hành. Một hành động nhỏ mỗi ngày có sức mạnh hơn nhiều giờ nghe mà không làm. Hôm nay, hãy chọn một điều bạn đã nghe từ Lời Chúa và biết mình cần làm: tha thứ, giúp đỡ, kiên nhẫn, và làm điều ấy, dù chỉ một bước nhỏ. Đừng chờ đến khi hiểu hết mới làm, vì sự vâng lời thường dẫn đến hiểu biết sâu hơn. Mỗi lần thực hành, Lời Chúa lại ăn sâu thêm vào đời sống bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con không chỉ nghe Lời Ngài mà còn làm theo. Xin cho con chọn một điều nhỏ để thực hành hôm nay, và ban cho con sức mạnh để Lời Ngài thay đổi cách con sống. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":2,"cau":17,"loi_kinh_thanh":"Về đức tin, cũng một lẽ ấy; nếu đức tin không sanh ra việc làm, thì tự mình nó chết.","bai_hoc":"Gia-cơ viết: \\"Về đức tin, cũng một lẽ ấy; nếu đức tin không sanh ra việc làm, thì tự mình nó chết\\" Ông không nói việc làm cứu ta, mà nói đức tin thật sẽ sinh ra việc làm. Một cây sống sẽ ra trái. Nếu không có trái, có lẽ cây chưa sống. Điều này không nhằm tạo gánh nặng, mà là lời mời kiểm tra: đức tin của tôi có hiện ra trong cách tôi sống không? Hôm nay, hãy làm một việc lành cụ thể, bày tỏ đức tin: giúp một người, nói lời tử tế, hoặc tha thứ cho một ai. Đức tin lớn lên mỗi khi ta dám hành động.","loi_cau_nguyen":"Chúa ơi, xin cho đức tin của con sống và sinh ra việc làm. Xin giúp con bày tỏ niềm tin bằng hành động yêu thương cụ thể, và không để đức tin của con chỉ nằm trong lời nói. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":4,"cau":7,"loi_kinh_thanh":"Vậy hãy phục Đức Chúa Trời; hãy chống trả ma quỉ, thì nó sẽ lánh xa anh em.","bai_hoc":"Gia-cơ viết: \\"Vậy hãy phục Đức Chúa Trời; hãy chống trả ma quỉ, thì nó sẽ lánh xa anh em\\" Thứ tự rất quan trọng: phục tùng Chúa trước, rồi mới chống trả. Sức mạnh để chống lại cám dỗ đến từ việc ở dưới quyền Chúa. Khi ta cố chống bằng sức riêng, ta dễ thất bại. Khi ta phục tùng Ngài, ta có sức mạnh của Ngài. Hôm nay, nếu bạn đang chống một cám dỗ, hãy bắt đầu bằng cách thưa với Chúa: Con trao điều này cho Ngài. Rồi dùng Lời Ngài để chống lại. Bạn không cần đánh trận một mình.","loi_cau_nguyen":"Chúa ơi, con phục tùng Ngài. Xin giúp con chống trả cám dỗ bằng sức mạnh của Ngài, không phải sức riêng. Xin cho con dùng Lời Ngài, và cảm ơn Ngài vì kẻ thù phải lánh xa khi con đứng dưới quyền Ngài. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":4,"cau":8,"loi_kinh_thanh":"Hãy đến gần Đức Chúa Trời, thì Ngài sẽ đến gần anh em. Hỡi kẻ có tội, hãy lau tay mình, có ai hai lòng, hãy làm sạch lòng đi;","bai_hoc":"Gia-cơ viết: \\"Hãy đến gần Đức Chúa Trời, thì Ngài sẽ đến gần anh em. Hỡi kẻ có tội, hãy lau tay mình, có ai hai lòng, hãy làm sạch lòng đi\\" Một lời hứa rất dịu dàng: khi ta tiến một bước, Chúa đáp lại. Ngài không đứng xa bắt ta đi hết đường. Ngài chờ đợi, và khi ta quay về, Ngài chạy ra đón. Điều này khích lệ những ai cảm thấy xa Chúa: không cần làm điều lớn lao, chỉ cần một bước nhỏ. Hôm nay, hãy lại gần Chúa bằng một việc đơn giản: một lời cầu nguyện chân thành, một đoạn Kinh Thánh, hoặc một khoảnh khắc yên lặng. Ngài đang chờ bạn, và Ngài vui khi bạn đến.","loi_cau_nguyen":"Chúa ơi, con muốn lại gần Ngài. Cảm ơn Ngài hứa sẽ lại gần con. Xin giúp con bước một bước nhỏ hôm nay, và cảm nhận sự hiện diện của Ngài khi con tìm kiếm Ngài. A-men."},{"sach":"Gia-cơ","ma":"JAS","chuong":5,"cau":16,"loi_kinh_thanh":"Vậy, hãy xưng tội cùng nhau, và cầu nguyện cho nhau, hầu cho anh em được lành bịnh: người công bình lấy lòng sốt sắng cầu nguyện, thật có linh nghiệm nhiều.","bai_hoc":"Gia-cơ viết: \\"Vậy, hãy xưng tội cùng nhau, và cầu nguyện cho nhau, hầu cho anh em được lành bịnh: người công bình lấy lòng sốt sắng cầu nguyện, thật có linh nghiệm nhiều\\" Việc cầu nguyện cho nhau tạo nên mối liên kết thân thiết. Xưng tội cùng nhau, nghĩa là sống thật thà với những người đáng tin. Đó là cách ta được chữa lành. Hôm nay, hãy cầu nguyện cho một người, và nếu bạn có người bạn đáng tin, hãy chia sẻ điều bạn đang gặp khó và xin họ cầu nguyện cho bạn. Sự thật thà ấy mở đường cho sự chữa lành.","loi_cau_nguyen":"Chúa ơi, xin cho con biết cầu nguyện cho người khác và nhờ người khác cầu nguyện cho con. Xin ban cho con can đảm sống thật thà với những người đáng tin, và để Ngài chữa lành qua cộng đoàn. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":2,"cau":9,"loi_kinh_thanh":"Nhưng anh em là dòng giống được lựa chọn, là chức thầy tế lễ nhà vua, là dân thánh là dân thuộc về Đức Chúa Trời, hầu cho anh em rao giảng nhân đức của Đấng đã gọi anh em ra khỏi nơi tối tăm, đến nơi sáng láng lạ lùng của Ngài;","bai_hoc":"Phi-e-rơ viết: \\"Nhưng anh em là dòng giống được lựa chọn, là chức thầy tế lễ nhà vua, là dân thánh là dân thuộc về Đức Chúa Trời, hầu cho anh em rao giảng nhân đức của Đấng đã gọi anh em ra khỏi nơi tối tăm, đến nơi sáng láng lạ lùng của Ngài\\" Bốn danh phận quý giá: được chọn, thuộc về vua, thánh, của riêng Chúa. Bạn được chọn và có giá trị. Và mục đích là để rao truyền những điều tốt đẹp của Ngài. Hôm nay, hãy nhớ danh phận của bạn, và nhẹ nhàng chia sẻ với ai đó điều Chúa đã làm trong đời bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã chọn con, gọi con ra khỏi tối tăm vào sự sáng kỳ diệu của Ngài. Xin giúp con sống đúng danh phận ấy, và có cơ hội chia sẻ điều Ngài đã làm trong đời con. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":2,"cau":24,"loi_kinh_thanh":"Ngài gánh tội lỗi chúng ta trong thân thể Ngài trên cây gỗ, hầu cho chúng ta là kẻ đã chết về tội lỗi, được sống cho sự công bình; lại nhân những lằn đòn của Ngài mà anh em đã được lành bịnh.","bai_hoc":"Phi-e-rơ viết: \\"Ngài gánh tội lỗi chúng ta trong thân thể Ngài trên cây gỗ, hầu cho chúng ta là kẻ đã chết về tội lỗi, được sống cho sự công bình; lại nhân những lằn đòn của Ngài mà anh em đã được lành bịnh\\" Ngài gánh tội chúng ta trong chính thân thể Ngài để ta có thể sống cho sự công bình. Sự cứu chuộc không chỉ là tha thứ mà còn là sự chữa lành và đổi mới. Hôm nay, hãy nhớ điều Ngài đã chịu, và để lòng biết ơn thúc đẩy bạn sống theo đường lối Ngài, với niềm tin rằng Ngài đã chữa lành bạn.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đã gánh tội lỗi con trên thân thể Ngài và chịu lằn roi để con được lành. Xin giúp con sống cho sự công bình, và biết ơn về sự chữa lành Ngài đã ban. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":3,"cau":15,"loi_kinh_thanh":"nhưng hãy tôn Đấng Christ, là Chúa, làm thánh trong lòng mình. Hãy thường thường sẵn sàng để trả lời mọi kẻ hỏi lẽ về sự trông cậy trong anh em, song phải hiền hòa và kính sợ,","bai_hoc":"Phi-e-rơ viết: \\"nhưng hãy tôn Đấng Christ, là Chúa, làm thánh trong lòng mình. Hãy thường thường sẵn sàng để trả lời mọi kẻ hỏi lẽ về sự trông cậy trong anh em, song phải hiền hòa và kính sợ\\" Chúng ta được mời chia sẻ hy vọng khi có người hỏi, với thái độ nhu mì. Điều quan trọng là sự dịu dàng, không phải tranh luận để thắng. Hãy chuẩn bị câu chuyện của bạn: Chúa đã làm gì trong đời bạn. Hôm nay, hãy nghĩ ra vài câu đơn giản để kể về hy vọng của bạn, và cầu xin Chúa cho bạn cơ hội chia sẻ.","loi_cau_nguyen":"Chúa ơi, xin giúp con thờ phượng Chúa Giê-su trong lòng, và sẵn sàng giải thích hy vọng của con với sự mềm mại và kính sợ. Xin ban cho con lời nói đúng lúc khi có người hỏi về đức tin của con. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":4,"cau":8,"loi_kinh_thanh":"Nhất là trong vòng anh em phải có lòng yêu thương sốt sắng; vì sự yêu thương che đậy vô số tội lỗi.","bai_hoc":"Phi-e-rơ viết: \\"Nhất là trong vòng anh em phải có lòng yêu thương sốt sắng; vì sự yêu thương che đậy vô số tội lỗi\\" Yêu thương sốt sắng nghĩa là yêu thương với nỗ lực, không hờ hững. Tình yêu này có sức che đậy: không phô bày lỗi lầm người khác, mà sẵn lòng tha thứ và nâng đỡ. Trong cộng đoàn và gia đình, đây là điều giữ mọi người gắn bó. Hôm nay, hãy chọn yêu thương một cách sốt sắng: một sự quan tâm thật lòng với ai đó, và chọn che đậy một lỗi nhỏ của người khác bằng sự tha thứ.","loi_cau_nguyen":"Chúa ơi, xin cho con lòng yêu thương sốt sắng với những người quanh con. Xin giúp con che đậy lỗi lầm của người khác bằng sự tha thứ, và tạo bầu không khí bình an trong gia đình và cộng đoàn. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":5,"cau":7,"loi_kinh_thanh":"lại hãy trao mọi điều lo lắng mình cho Ngài, vì Ngài hay săn sóc anh em.","bai_hoc":"Phi-e-rơ viết: \\"lại hãy trao mọi điều lo lắng mình cho Ngài, vì Ngài hay săn sóc anh em\\" Hai phần: trao lo lắng, và lý do là Ngài chăm sóc. Chúa không xem nhẹ nỗi lo của bạn. Ngài quan tâm thật sự. Hãy hình dung việc đặt từng nỗi lo vào tay Ngài, thay vì ôm chặt lấy chúng. Có thể bạn cần làm điều này nhiều lần trong ngày, và điều đó không sao. Hôm nay, mỗi khi nỗi lo trỗi dậy, hãy dùng câu Kinh Thánh này như một lời nhắc: Ngài chăm sóc tôi. Đặt nỗi lo xuống không có nghĩa là bạn thiếu trách nhiệm, mà là bạn tin cậy.","loi_cau_nguyen":"Chúa ơi, con trao mọi lo lắng của con cho Ngài, vì Ngài chăm sóc con. Xin giúp con thật sự buông chúng ra thay vì ôm lại, và cho con bình an khi con nhớ rằng Ngài quan tâm đến từng điều nhỏ. A-men."},{"sach":"I Phia-rơ","ma":"1PE","chuong":5,"cau":8,"loi_kinh_thanh":"Hãy tiết độ và tỉnh thức: kẻ thù nghịch anh em là ma quỉ, như sư tử rống, đi rình mò chung quanh anh em, tìm kiếm người nào nó có thể nuốt được.","bai_hoc":"Phi-e-rơ viết: \\"Hãy tiết độ và tỉnh thức: kẻ thù nghịch anh em là ma quỉ, như sư tử rống, đi rình mò chung quanh anh em, tìm kiếm người nào nó có thể nuốt được\\" Đây là lời cảnh tỉnh, không để làm ta sợ mà để ta cẩn thận. Chúng ta có kẻ thù thuộc linh thật, và ta không nên hờ hững. Nhưng ta cũng không cần hoang mang, vì ta có Chúa bảo vệ. Tiết độ và tỉnh thức: sống điều độ, chú ý đến đời sống thuộc linh. Hôm nay, hãy cẩn thận một điều nhỏ có thể làm bạn xa Chúa, và xin Ngài bảo vệ bạn.","loi_cau_nguyen":"Chúa ơi, xin giúp con tiết độ và tỉnh thức, nhận ra những mưu kế của kẻ thù. Xin bảo vệ con, và cho con đứng vững nhờ sức mạnh của Ngài, không sợ hãi vì Ngài ở cùng con. A-men."},{"sach":"II Phia-rơ","ma":"2PE","chuong":3,"cau":9,"loi_kinh_thanh":"Chúa không chậm trễ về lời hứa của Ngài như mấy người kia tưởng đâu, nhưng Ngài lấy lòng nhịn nhục đối với anh em, không muốn cho một người nào chết mất, song muốn cho mọi người đều ăn năn.","bai_hoc":"Phi-e-rơ viết: \\"Chúa không chậm trễ về lời hứa của Ngài như mấy người kia tưởng đâu, nhưng Ngài lấy lòng nhịn nhục đối với anh em, không muốn cho một người nào chết mất, song muốn cho mọi người đều ăn năn\\" Khi ta thấy Chúa dường như chậm, có thể đó là lòng kiên nhẫn đầy thương xót của Ngài. Ngài đang cho mọi người thêm thời gian để quay về. Điều này vừa làm ta kiên nhẫn trong sự chờ đợi, vừa nhắc ta có trách nhiệm với người chưa biết Chúa. Hôm nay, hãy cầu nguyện cho một người bạn mong họ biết Ngài, và biết ơn vì Chúa nhẫn nại với chính bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài nhịn nhục với con và không muốn một ai bị hư mất. Xin giúp con kiên nhẫn trong sự chờ đợi lời hứa của Ngài, và cầu nguyện cho những người con thương được quay về với Ngài. A-men."},{"sach":"II Phia-rơ","ma":"2PE","chuong":3,"cau":18,"loi_kinh_thanh":"Hãy tấn tới trong ân điển và trong sự thông biết Chúa và Cứu Chúa chúng ta là Đức Chúa Jêsus Christ. Nguyền xin vinh hiển về nơi Ngài, từ rày đến đời đời! A-men.","bai_hoc":"Phi-e-rơ kết thúc bức thư: \\"Hãy tấn tới trong ân điển và trong sự thông biết Chúa và Cứu Chúa chúng ta là Đức Chúa Jêsus Christ. Nguyền xin vinh hiển về nơi Ngài, từ rày đến đời đời! A-men\\" Đời sống đức tin là một sự tăng trưởng, không phải một điểm dừng. Lớn lên trong ân điển là hiểu và sống trong ơn Chúa ngày càng sâu hơn. Lớn lên trong hiểu biết là biết Chúa Giê-su nhiều hơn qua Lời Ngài và qua mối quan hệ. Sự tăng trưởng thường chậm và không rõ ràng, như cây lớn từng chút. Hôm nay, hãy chọn một cách nhỏ để biết Chúa hơn: đọc một đoạn Kinh Thánh mới, hoặc cầu nguyện thêm vài phút.","loi_cau_nguyen":"Chúa ơi, xin giúp con lớn lên trong ân điển và trong sự hiểu biết Chúa Giê-su, mỗi ngày một ít. Xin cho con khao khát biết Ngài hơn, và kiên nhẫn với quá trình tăng trưởng chậm rãi nhưng chắc chắn. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":1,"cau":9,"loi_kinh_thanh":"Còn nếu chúng ta xưng tội mình, thì Ngài là thành tín công bình để tha tội cho chúng ta, và làm cho chúng ta sạch mọi điều gian ác.","bai_hoc":"Giăng viết: \\"Còn nếu chúng ta xưng tội mình, thì Ngài là thành tín công bình để tha tội cho chúng ta, và làm cho chúng ta sạch mọi điều gian ác\\" Hai từ đáng chú ý: thành tín và công bình. Ngài tha thứ vì Ngài trung tín với lời hứa và công bình vì Chúa Giê-su đã trả giá. Xưng tội không phải để bị trừng phạt, mà để được làm sạch. Chúa không giữ lại một dấu vết nào. Hôm nay, nếu bạn mang điều gì khiến lòng nặng nề, hãy gọi tên nó trước mặt Chúa cách thật thà. Ngài đã hứa tha thứ và làm sạch.","loi_cau_nguyen":"Chúa ơi, con xưng tội mình với Ngài một cách thành thật. Cảm ơn Ngài thành tín và công bình để tha thứ và làm sạch mọi sự gian ác. Xin giúp con nhận lấy sự tha thứ ấy và sống nhẹ nhàng hơn. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":3,"cau":1,"loi_kinh_thanh":"Hãy xem Đức Chúa Cha đã tỏ cho chúng ta sự yêu thương dường nào, mà cho chúng ta được xưng là con cái Đức Chúa Trời; và chúng ta thật là con cái Ngài. Ấy là vì đó mà thế gian chẳng biết chúng ta, vì họ chẳng từng biết Ngài.","bai_hoc":"Giăng viết: \\"Hãy xem Đức Chúa Cha đã tỏ cho chúng ta sự yêu thương dường nào, mà cho chúng ta được xưng là con cái Đức Chúa Trời; và chúng ta thật là con cái Ngài. Ấy là vì đó mà thế gian chẳng biết chúng ta, vì họ chẳng từng biết Ngài\\" Ông bảo chúng ta hãy nhìn, hãy nhìn kỹ tình yêu ấy. Danh phận làm con cái Chúa không phải một khái niệm xa vời, mà là thực tế đầy tình yêu của Cha. Dù thế gian không hiểu hay đánh giá ta thế nào, ta biết mình là ai trong Ngài. Hôm nay, hãy dừng lại và để lòng bạn nghe lời này như lần đầu: bạn là con của Cha, và bạn được yêu thương.","loi_cau_nguyen":"Cha ơi, cảm ơn Cha đã tỏ cho con tình yêu lớn lao, cho con được gọi là con cái Cha. Xin giúp con sống trong danh phận ấy, và nhớ rằng con luôn được Cha yêu thương, dù người khác nhìn con thế nào. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":4,"cau":4,"loi_kinh_thanh":"Hỡi các con cái bé mọn, phần các con, là thuộc về Đức Chúa Trời, đã thắng được họ rồi, vì Đấng ở trong các con là lớn hơn kẻ ở trong thế gian.","bai_hoc":"Giăng viết: \\"Hỡi các con cái bé mọn, phần các con, là thuộc về Đức Chúa Trời, đã thắng được họ rồi, vì Đấng ở trong các con là lớn hơn kẻ ở trong thế gian\\" Ông viết cho những người đang chịu nhiều ảnh hưởng của sự dạy sai. Lời an ủi là Đấng ở trong ta, tức Thánh Linh, lớn hơn mọi thế lực chống lại. Điều đó không có nghĩa là ta không gặp khó khăn, mà là ta không đối diện với chúng một mình. Hôm nay, khi bạn thấy mình nhỏ bé trước một thử thách, hãy nhắc mình rằng Đấng ở trong bạn lớn hơn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì Đấng ở trong con lớn hơn kẻ ở trong thế gian. Xin giúp con vững lòng trước những tiếng nói sai lạc và khó khăn, và nương cậy vào sự hiện diện của Thánh Linh trong con. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":4,"cau":8,"loi_kinh_thanh":"Ai chẳng yêu, thì không biết Đức Chúa Trời; vì Đức Chúa Trời là sự yêu thương.","bai_hoc":"Giăng viết: Ai không yêu thì không biết Đức Chúa Trời, vì Đức Chúa Trời là sự yêu thương. Đây không chỉ là một đức tính của Chúa, mà là bản chất của Ngài. Mọi điều Ngài làm đều xuất phát từ tình yêu. Khi ta biết Ngài, ta được thay đổi để yêu thương. Nếu bạn thấy khó hiểu Chúa, hãy bắt đầu từ đây: Ngài là tình yêu. Hôm nay, hãy tìm một cách nhỏ để thể hiện tình yêu với một người, và nhận ra rằng khi ta yêu, ta đang phản chiếu một điều về Chúa.","loi_cau_nguyen":"Chúa ơi, Ngài là sự yêu thương. Xin giúp con biết Ngài sâu hơn qua việc học yêu thương. Xin đổ đầy lòng con bằng tình yêu của Ngài, để con có thể yêu người khác và phản chiếu bản tính của Ngài. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":4,"cau":18,"loi_kinh_thanh":"Quyết chẳng có điều sợ hãi trong sự yêu thương, nhưng sự yêu thương trọn vẹn thì cắt bỏ sự sợ hãi; vì sự sợ hãi có hình phạt, và kẻ đã sợ hãi thì không được trọn vẹn trong sự yêu thương.","bai_hoc":"Giăng viết: \\"Quyết chẳng có điều sợ hãi trong sự yêu thương, nhưng sự yêu thương trọn vẹn thì cắt bỏ sự sợ hãi; vì sự sợ hãi có hình phạt, và kẻ đã sợ hãi thì không được trọn vẹn trong sự yêu thương\\" Khi ta hiểu và nhận được tình yêu hoàn hảo của Chúa, sự sợ hãi về sự phán xét và về bị bỏ rơi dần mất đi. Quá trình này diễn ra từ từ khi ta ở trong tình yêu của Ngài. Có những nỗi sợ ăn sâu trong ta, và Chúa kiên nhẫn chữa lành từng chút. Hôm nay, hãy nhớ một nỗi sợ của bạn và đặt nó bên cạnh tình yêu Chúa. Hãy để tình yêu ấy nhỏ giọt vào chỗ sợ hãi, từng ngày.","loi_cau_nguyen":"Chúa ơi, xin để tình yêu trọn vẹn của Ngài cắt bỏ sự sợ hãi trong con. Xin chữa lành những nỗi sợ ăn sâu trong lòng con, và giúp con sống trong sự bảo đảm rằng con được Ngài yêu. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":4,"cau":19,"loi_kinh_thanh":"Chúng ta yêu, vì Chúa đã yêu chúng ta trước.","bai_hoc":"Giăng viết: Chúng ta yêu, vì Chúa đã yêu chúng ta trước. Tình yêu của ta không bắt đầu từ ta, mà là đáp lại. Chúa yêu ta trước, nên ta có thể yêu Ngài và yêu người khác. Điều này giải thoát ta khỏi áp lực phải tự tạo ra tình yêu. Ta chỉ cần nhận và trao đi. Khi bạn thấy mình cạn kiệt tình yêu, hãy quay lại nguồn: để Chúa yêu bạn trước. Hôm nay, hãy dành vài phút ở trong tình yêu của Ngài, và rồi trao một chút tình yêu ấy cho một người bạn gặp.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài đã yêu con trước. Xin giúp con yêu Ngài và yêu người khác từ nguồn tình yêu của Ngài, thay vì cố tạo ra bằng sức riêng, và nhận biết tình yêu ấy mỗi ngày. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":5,"cau":4,"loi_kinh_thanh":"vì hễ sự gì sanh bởi Đức Chúa Trời, thì thắng hơn thế gian; và sự thắng hơn thế gian, ấy là đức tin của chúng ta.","bai_hoc":"Giăng viết: \\"vì hễ sự gì sanh bởi Đức Chúa Trời, thì thắng hơn thế gian; và sự thắng hơn thế gian, ấy là đức tin của chúng ta\\" Đức tin không phải là một cảm giác, mà là sức mạnh chiến thắng. Không phải bởi sức của ta mà bởi Đấng ta tin. Khi ta đặt lòng tin vào Chúa Giê-su, ta cùng chia sẻ chiến thắng của Ngài. Điều này khích lệ ta khi thế gian có vẻ quá lớn. Hôm nay, hãy nhớ rằng đức tin dù nhỏ cũng nối ta với sức mạnh của Chúa, và hãy bước vào ngày với sự tin cậy ấy.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì đức tin của con là sự thắng thế gian. Xin giúp con giữ lòng tin vào Ngài, và nhớ rằng chiến thắng là của Ngài, con chia sẻ trong đó nhờ tin cậy Ngài. A-men."},{"sach":"I Giăng","ma":"1JN","chuong":5,"cau":13,"loi_kinh_thanh":"Ta đã viết những điều nầy cho các con, hầu cho các con biết mình có sự sống đời đời, là kẻ nào tin đến danh Con Đức Chúa Trời.","bai_hoc":"Giăng viết: \\"Ta đã viết những điều nầy cho các con, hầu cho các con biết mình có sự sống đời đời, là kẻ nào tin đến danh Con Đức Chúa Trời\\" Chúa muốn bạn có sự chắc chắn, không phải sống trong nghi ngờ liên tục. Sự sống đời đời không phải là điều ta hy vọng mơ hồ, mà là điều ta có thể biết nhờ tin vào Chúa Giê-su. Hôm nay, nếu bạn hay lo mình có đủ tốt không, hãy đọc câu này chậm và nhận lấy sự chắc chắn Chúa ban cho những ai tin. Nó không phụ thuộc vào cảm giác của bạn hôm nay.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài cho con biết con có sự sống đời đời khi con tin danh Con Ngài. Xin giúp con sống trong sự chắc chắn ấy, và thôi nghi ngờ khi lòng con bất an. A-men."},{"sach":"III Giăng","ma":"3JN","chuong":1,"cau":2,"loi_kinh_thanh":"Hỡi kẻ rất yêu dấu, tôi cầu nguyện cho anh được thạnh vượng trong mọi sự, và được khỏe mạnh phần xác anh cũng như đã được thạnh vượng về phần linh hồn anh vậy.","bai_hoc":"Giăng viết cho người bạn Ga-ius: Hỡi kẻ rất yêu dấu, ta cầu nguyện cho con được thạnh vượng mọi bề và khỏe mạnh, cũng như linh hồn con được thạnh vượng vậy. Đây là lời chúc phước của một người bạn dành cho bạn mình, thể hiện lòng quan tâm chân thành. Cần hiểu đúng đây là lời cầu chúc, không phải lời hứa Chúa chắc chắn ban giàu có hay không bao giờ bệnh. Ông ước điều tốt cho cả thân thể và linh hồn. Hôm nay, hãy gửi một lời chúc phước chân thành cho một người bạn: cầu cho họ khỏe mạnh và bình an trong linh hồn.","loi_cau_nguyen":"Chúa ơi, xin ban phước cho những người con yêu thương, về thân thể và linh hồn. Xin giúp con biết cầu chúc điều tốt cho người khác, và để linh hồn con cũng được mạnh mẽ trong Ngài. A-men."},{"sach":"Giu-đe","ma":"JUD","chuong":1,"cau":24,"loi_kinh_thanh":"Vả, nguyền Đấng có thể gìn giữ anh em khỏi vấp phạm và khiến anh em đứng trước mặt vinh hiển mình cách rất vui mừng, không chỗ trách được,","bai_hoc":"Giu-đe kết thúc bằng một lời ngợi khen: \\"Vả, nguyền Đấng có thể gìn giữ anh em khỏi vấp phạm và khiến anh em đứng trước mặt vinh hiển mình cách rất vui mừng, không chỗ trách được\\" Niềm hy vọng của ta không dựa trên việc tự mình giữ không vấp ngã, mà trên Đấng có thể giữ ta. Ngài sẽ đưa ta đến trước mặt Ngài với niềm vui. Khi bạn lo mình không đủ vững để đi đến cuối, hãy dựa vào lời hứa này. Hôm nay, hãy dâng một lời ngợi khen ngắn cho Đấng có quyền giữ bạn.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài là Đấng có quyền giữ con khỏi vấp ngã và đưa con đến trước mặt Ngài với niềm vui lớn. Xin giữ con vững vàng đến cuối cùng, và giúp con dựa vào sức Ngài hơn sức riêng. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":1,"cau":8,"loi_kinh_thanh":"Chúa là Đức Chúa Trời, Đấng Hiện Có, Đã Có, Và Còn Đến, là Đấng Toàn năng, phán rằng: Ta là An-pha và Ô-mê-ga.","bai_hoc":"Chúa phán trong sách Khải Thị: \\"Chúa là Đức Chúa Trời, Đấng Hiện Có, Đã Có, Và Còn Đến, là Đấng Toàn năng, phán rằng: Ta là An-pha và Ô-mê-ga\\" An-pha và Ô-mê-ga là chữ đầu và chữ cuối của bảng chữ cái Hy Lạp, nghĩa là Ngài là khởi đầu và kết thúc của mọi sự. Ngài vượt qua thời gian: quá khứ, hiện tại, tương lai đều nằm trong tay Ngài. Điều này mang lại bình an khi ta lo lắng về những điều chưa biết. Hôm nay, hãy nhớ rằng Đấng nắm giữ mọi thời gian cũng nắm giữ ngày của bạn. Bạn có thể nghỉ ngơi trong sự chắc chắn ấy ngay bây giờ.","loi_cau_nguyen":"Chúa ơi, Ngài là An-pha và Ô-mê-ga, Đấng hiện có, đã có và còn đến. Xin giúp con yên lòng khi nhớ rằng quá khứ, hiện tại và tương lai của con đều nằm trong tay Ngài, Đấng Toàn Năng. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":2,"cau":10,"loi_kinh_thanh":"Ngươi chớ ngại điều mình sẽ chịu khổ. Nầy, ma quỉ sẽ quăng nhiều kẻ trong các ngươi vào ngục, hầu cho các ngươi bị thử thách; các ngươi sẽ bị hoạn nạn trong mười ngày. Khá giữ trung tín cho đến chết, rồi ta sẽ ban cho ngươi mũ triều thiên của sự sống.","bai_hoc":"Chúa Giê-su nói với Hội Thánh ở Si-miệc-nơ đang chịu bắt bớ: \\"Ngươi chớ ngại điều mình sẽ chịu khổ. Nầy, ma quỉ sẽ quăng nhiều kẻ trong các ngươi vào ngục, hầu cho các ngươi bị thử thách; các ngươi sẽ bị hoạn nạn trong mười ngày. Khá giữ trung tín cho đến chết, rồi ta sẽ ban cho ngươi mũ triều thiên của sự sống\\" Ngài không hứa họ sẽ tránh được khổ nạn, mà hứa phần thưởng cho sự trung tín. Đây là lời khích lệ cho những ai đang chịu khó khăn vì đức tin. Sự trung tín của họ không bị bỏ quên. Hôm nay, nếu bạn đang phải trả giá vì giữ đức tin, dù nhỏ như bị chê cười, hãy nhớ rằng Chúa thấy và sẽ ban thưởng. Hãy giữ lòng trung tín thêm một ngày.","loi_cau_nguyen":"Chúa Giê-su ơi, xin giúp con trung tín với Ngài cho đến cuối cùng, dù có phải trả giá. Xin ban cho con can đảm trong những lúc khó khăn, và cảm ơn Ngài hứa ban mão sự sống cho người trung tín. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":3,"cau":20,"loi_kinh_thanh":"Nầy, ta đứng ngoài cửa mà gõ; nếu ai nghe tiếng ta mà mở cửa cho, thì ta sẽ vào cùng người ấy, ăn bữa tối với người, và người với ta.","bai_hoc":"Chúa Giê-su nói: \\"Nầy, ta đứng ngoài cửa mà gõ; nếu ai nghe tiếng ta mà mở cửa cho, thì ta sẽ vào cùng người ấy, ăn bữa tối với người, và người với ta\\" Ngài đứng ngoài và gõ cửa, không phá cửa mà vào. Ngài tôn trọng sự tự do của ta và mời ta mở cửa. Ăn chung bữa tối là biểu tượng của sự gần gũi và tình bạn. Chúa muốn một mối quan hệ thân mật với bạn. Hôm nay, hãy mở cửa lòng cho Ngài bằng một lời mời đơn giản: Chúa Giê-su ơi, xin vào.","loi_cau_nguyen":"Chúa Giê-su ơi, cảm ơn Ngài đứng ngoài cửa và gõ. Con mở cửa lòng con cho Ngài. Xin vào ở cùng con, ăn cùng con, và cho con một tình bạn thân thiết với Ngài mỗi ngày. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":4,"cau":11,"loi_kinh_thanh":"Lạy Đức Chúa Trời là Chúa chúng tôi, Chúa đáng được vinh hiển, tôn quí và quyền lực; vì Chúa đã dựng nên muôn vật, và ấy là vì ý muốn Chúa mà muôn vật mới có và đã được dựng nên.","bai_hoc":"Các trưởng lão thờ phượng Chúa: Lạy Chúa là Đức Chúa Trời chúng tôi, Ngài đáng được vinh hiển, tôn trọng và quyền phép, vì Ngài đã dựng nên mọi vật, và mọi vật đều tồn tại và được dựng nên bởi ý muốn Ngài. Đây là lời thờ phượng đúng nhất: nhận ra Chúa xứng đáng vì Ngài là Đấng Tạo Hóa. Khi ta tôn vinh Ngài, tâm hồn ta được sắp xếp lại: Ngài lớn, ta nhỏ, và điều đó giải thoát ta. Hôm nay, hãy dành một khoảnh khắc ngắn thờ phượng Ngài bằng chính những lời này.","loi_cau_nguyen":"Chúa ơi, Ngài đáng được vinh hiển, tôn trọng và quyền phép, vì Ngài đã dựng nên mọi vật. Xin giúp con thờ phượng Ngài với lòng chân thành, và nhớ rằng mọi sự đều tồn tại bởi ý muốn Ngài. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":5,"cau":12,"loi_kinh_thanh":"đồng nói lên một tiếng lớn rằng: Chiên Con đã chịu giết đáng được quyền phép, giàu có, khôn ngoan, năng lực, tôn quí, vinh hiển và ngợi khen!","bai_hoc":"Các thiên sứ hát lớn tiếng: Chiên Con đã bị giết đáng được quyền phép, giàu có, khôn ngoan, sức mạnh, tôn trọng, vinh hiển, và ngợi khen. Chúa Giê-su được tôn vinh là Chiên Con đã bị giết, nghĩa là sự hy sinh của Ngài là nền tảng của sự ngợi khen. Ngài xứng đáng vì điều Ngài đã làm vì ta. Đây là hình ảnh của sự thờ phượng trên thiên đàng. Hôm nay, hãy nhớ lại điều Chúa Giê-su đã làm cho bạn, và để lòng biết ơn trào lên thành lời ngợi khen, dù thầm lặng.","loi_cau_nguyen":"Chúa Giê-su ơi, Chiên Con đã bị giết, Ngài xứng đáng nhận quyền phép, giàu có, khôn ngoan, sức mạnh, tôn trọng, vinh hiển và ngợi khen. Xin giúp con biết ơn sâu sắc về sự hy sinh của Ngài, và sống thờ phượng Ngài mỗi ngày. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":12,"cau":11,"loi_kinh_thanh":"Chúng đã thắng nó bởi huyết Chiên Con và bởi lời làm chứng của mình; chúng chẳng tiếc sự sống mình cho đến chết.","bai_hoc":"Kinh Thánh nói về những người đã thắng ma quỷ: \\"Chúng đã thắng nó bởi huyết Chiên Con và bởi lời làm chứng của mình; chúng chẳng tiếc sự sống mình cho đến chết\\" Chiến thắng đến từ hai điều: công việc của Chúa Giê-su trên thập tự giá, và lời chứng của những người tin. Điều đó cho thấy câu chuyện của bạn có sức mạnh. Khi bạn chia sẻ điều Chúa đã làm, bạn đang tham gia vào chiến thắng của Ngài. Hôm nay, hãy nghĩ đến câu chuyện đức tin của bạn, và nếu có thể, kể một phần nhỏ cho một người khác. Câu chuyện chân thật của bạn có thể là điều người ấy đang cần nghe.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài vì chiến thắng bởi huyết Chiên Con và lời làm chứng. Xin cho con can đảm kể câu chuyện về điều Ngài đã làm trong đời con, và dùng lời chứng ấy để khích lệ những người khác. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":19,"cau":16,"loi_kinh_thanh":"Trên áo tơi và trên đùi Ngài, có đề một danh là Vua Của Các Vua Và Chúa Của Các Chúa.","bai_hoc":"Chúa Giê-su được mô tả trong sự vinh hiển của Ngài: Trên áo tơi và trên đùi Ngài có đề tên: Vua của các vua, Chúa của các chúa. Ngài là Vua tối cao, cai trị trên mọi quyền lực. Điều đó cho ta hy vọng trong một thế giới nhiều bất công và hỗn loạn: cuối cùng, Ngài cai trị công bình. Mọi quyền lực khác đều phải cúi đầu trước Ngài. Hôm nay, khi bạn thấy lo vì tin tức hay thế giới, hãy nhớ rằng Vua của các vua đang ngự trị, và để lòng bạn bình an trong sự thật ấy.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là Vua của các vua và Chúa của các chúa. Xin giúp con tin cậy rằng Ngài cai trị công bình, và để lòng con bình an giữa những điều bất định và hỗn loạn trong thế giới này. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":21,"cau":1,"loi_kinh_thanh":"Đoạn, tôi thấy trời mới và đất mới; vì trời thứ nhất và đất thứ nhất đã biến đi mất, và biển cũng không còn nữa.","bai_hoc":"Giăng thấy một sự hiện thấy: Tôi lại thấy một trời mới và đất mới; vì trời thứ nhất và đất thứ nhất đã biến mất. Đây là lời hứa về một sự khởi đầu mới trọn vẹn: mọi sự cũ, kể cả những đau thương, sẽ qua đi. Chúa không chỉ sửa chữa thế giới này, Ngài làm mới tất cả. Hy vọng ấy nâng đỡ ta khi cuộc sống hiện tại còn nhiều đổ vỡ. Hôm nay, hãy để hình ảnh này làm lòng bạn nhẹ nhõm: sẽ có một ngày mọi sự được làm mới, và bạn có chỗ trong đó.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa trời mới đất mới. Xin giúp con giữ hy vọng về ngày Ngài làm mới mọi sự, và sống bây giờ với niềm tin rằng những đổ vỡ của thế giới này sẽ không kéo dài mãi. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":21,"cau":4,"loi_kinh_thanh":"Ngài sẽ lau ráo hết nước mắt khỏi mắt chúng, sẽ không có sự chết, cũng không có than khóc, kêu ca, hay là đau đớn nữa; vì những sự thứ nhất đã qua rồi.","bai_hoc":"Chúa hứa: Ngài sẽ lau ráo hết nước mắt khỏi mắt chúng, sẽ không có sự chết, cũng không có than khóc, kêu ca, hay là đau đớn nữa, vì những sự thứ nhất đã qua rồi. Hãy hình dung Chúa tự tay lau nước mắt cho bạn: một cử chỉ dịu dàng của một người cha. Mỗi giọt nước mắt của bạn quý giá trước mặt Ngài. Có một ngày sẽ không còn nước mắt. Hôm nay, nếu bạn đang buồn, hãy để lời này an ủi bạn và nhớ rằng nỗi đau không phải lời kết thúc. Chúa ở gần bạn ngay bây giờ, và Ngài sẽ không để nước mắt của bạn rơi vô ích.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài hứa lau ráo mọi nước mắt và sẽ không còn sự chết, than khóc hay đau đớn. Xin an ủi những ai đang buồn khổ hôm nay, và giữ lòng con vững vàng trong hy vọng ấy. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":21,"cau":5,"loi_kinh_thanh":"Đấng ngự trên ngôi phán rằng: Nầy, ta làm mới lại hết thảy muôn vật. Đoạn, lại rằng: Hãy chép; vì những lời nầy đều trung tín và chân thật.","bai_hoc":"Đấng ngồi trên ngôi phán: \\"Đấng ngự trên ngôi phán rằng: Nầy, ta làm mới lại hết thảy muôn vật. Đoạn, lại rằng: Hãy chép; vì những lời nầy đều trung tín và chân thật\\" Chúa nói với Giăng: Hãy viết lấy, vì những lời nầy là thành tín và chân thật. Ngài làm mới mọi sự, kể cả những phần trong đời bạn đã cũ kỹ, hư hại. Chúa không chỉ chữa lành, Ngài còn tạo nên điều mới. Lời này là lời hứa đáng tin cậy. Hôm nay, hãy nghĩ đến một điều bạn mong Chúa làm mới: một mối quan hệ, một thói quen, một hy vọng, và thưa với Ngài: Chúa ơi, xin làm mới điều này. Ngài vui lòng bắt đầu từ chỗ bạn đang đứng.","loi_cau_nguyen":"Chúa ơi, Ngài làm nên mọi sự mới. Xin làm mới những phần trong đời con đã cũ kỹ hay tổn thương, và giúp con tin rằng lời hứa của Ngài là thành tín và chân thật. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":22,"cau":13,"loi_kinh_thanh":"Ta là An-pha và Ô-mê-ga, là thứ nhất và là sau chót, là đầu và là rốt.","bai_hoc":"Chúa Giê-su phán: \\"Ta là An-pha và Ô-mê-ga, là thứ nhất và là sau chót, là đầu và là rốt\\" Ngài lặp lại lời tuyên bố ở đầu sách, như một lời đóng dấu: Ngài là khởi đầu và kết thúc của mọi sự, của lịch sử, của đời bạn. Điều đó nghĩa là câu chuyện của bạn nằm trong tay một Đấng biết từ đầu đến cuối. Bạn không cần lo về chương kế tiếp, vì Ngài đã ở đó. Hôm nay, hãy giao câu chuyện của bạn cho Đấng là Đầu và Cuối, và bước đi với sự tin cậy.","loi_cau_nguyen":"Chúa Giê-su ơi, Ngài là An-pha và Ô-mê-ga, Đầu và Cuối. Xin giúp con giao câu chuyện đời con cho Ngài, tin rằng Ngài biết từ đầu đến cuối và đang dẫn dắt con đến nơi Ngài đã chuẩn bị. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":22,"cau":17,"loi_kinh_thanh":"Thánh Linh và vợ mới cùng nói: Hãy đến! Kẻ nào nghe cũng hãy nói rằng: Hãy đến! Ai khát, khá đến. Kẻ nào muốn, khá nhận lấy nước sự sống cách nhưng không.","bai_hoc":"Thánh Linh và Vợ mới cưới đều nói: \\"Thánh Linh và vợ mới cùng nói: Hãy đến! Kẻ nào nghe cũng hãy nói rằng: Hãy đến! Ai khát, khá đến. Kẻ nào muốn, khá nhận lấy nước sự sống cách nhưng không\\" Đây là lời mời cuối cùng của Kinh Thánh, đầy dịu dàng và rộng mở. Không có điều kiện: ai khát, ai muốn. Nước sự sống được ban cho không. Và lời mời này không chỉ dành cho người khác mà cho bạn. Hôm nay, nếu bạn thấy khát, hãy nghe tiếng mời gọi ấy và đến. Rồi hãy mời một người bạn khác cùng đến, vì lời mời này dành cho tất cả. Đây là một lời mời bạn có thể nhận ngay hôm nay.","loi_cau_nguyen":"Chúa ơi, cảm ơn Ngài mời người khát đến uống nước sự sống nhưng không. Con xin đến với Ngài. Xin làm no lòng con, và dùng con để mời người khác cùng đến với Ngài. A-men."},{"sach":"Khải Thị","ma":"REV","chuong":22,"cau":20,"loi_kinh_thanh":"Đấng làm chứng cho những điều ấy, phán rằng: Phải, ta đến mau chóng. A-men, lạy Đức Chúa Jêsus, xin hãy đến!","bai_hoc":"Đấng làm chứng những điều này phán: Phải, Ta đến mau chóng. Giăng đáp: A-men, lạy Chúa Giê-su, xin hãy đến! Đây là lời cầu nguyện cuối cùng của Kinh Thánh, một tiếng thì thầm của hy vọng. Hội Thánh sống trong sự chờ đợi vui mừng, không sợ hãi mà khao khát. Chúa Giê-su đã hứa đến, và Ngài là Đấng giữ lời. Trong khi chờ, ta tiếp tục sống trung tín và yêu thương. Hôm nay, hãy dùng chính lời cầu nguyện này như lời kết ngày của bạn: lạy Chúa Giê-su, xin hãy đến. Hãy để lời ấy kết thúc ngày của bạn trong sự bình an.","loi_cau_nguyen":"Lạy Chúa Giê-su, xin hãy đến. Xin giúp con sống mỗi ngày với lòng trông đợi Ngài, trung tín và yêu thương trong lúc chờ đợi, và giữ con vững vàng cho đến ngày Ngài trở lại. A-men."}]`);export{e as default};